window.EY13={"depUTC":"2026-10-24T05:20:00Z","durMin":925,"taxiOut":25,"aircraft":"Airbus A350-1000 (A35K) on every EY13 rotation FlightAware listed for 8–23 Oct 2026","routeNote":"typical AUH→ATL routing (Gulf, Iraq, Turkey, Balkans, Central Europe, Scotland, North Atlantic, Labrador, NE US); actual tracks vary daily","note":"Schedule from calendar: dep 09:20 Gulf / 01:20 ET Sat 24 Oct, arr 16:45 ET.","waypoints":[[24.433,54.6511],[26.6,51.6],[29.3,47.9],[33.3,44.4],[36.4,43.1],[39.4,37.0],[41.02,31.58],[43.67,28.19],[46.33,24.82],[48.3,20.5],[50.2,14.2],[53.2,9.6],[55.0,3.0],[56.6,-3.8],[57.8,-8.5],[59.0,-20.0],[59.8,-30.0],[59.4,-42.0],[57.0,-52.0],[53.8,-59.0],[49.6,-65.5],[45.8,-70.0],[42.6,-74.2],[40.3,-77.4],[37.6,-80.1],[35.4,-82.4],[33.6367,-84.4281]],"pois":[{"n":"Dubai","lat":25.2697,"lon":55.3094,"s":219,"w":"Dubai","ty":"metropolis|big city|administrative territorial entity|largest city|global city|city","u":0,"b":"Dubai is the most populous city in the United Arab Emirates and the capital of the Emirate of Dubai. It is on a creek on the southeastern coast of the Persian Gulf. As of 2025, its population stands at 4 million, 92% of whom are expatriates."},{"n":"Abu Dhabi","lat":24.4511,"lon":54.3969,"s":185,"w":"Abu Dhabi","ty":"federal capital|metropolis|administrative territorial entity|human settlement|city","u":0,"b":"Abu Dhabi is the capital city of the United Arab Emirates (UAE), and of the Emirate of Abu Dhabi, the seat of the Abu Dhabi Central Capital District and the UAE's second-most populous city, after Dubai. Situated on a T-shaped island, Abu Dhabi extends into the Persian Gulf from the central-western coast of the UAE."},{"n":"Burj Khalifa","lat":25.1972,"lon":55.2742,"s":140,"w":"Burj Khalifa","ty":"skyscraper|architectural landmark","u":0,"b":"The Burj Khalifa (previously known as Burj Dubai prior to inauguration) is a megatall skyscraper in Dubai, United Arab Emirates. Designed by the SOM architectural firm, it is the world's tallest structure, with a total height of 829.8 m (2,722 ft, or just over half a mile) and a roof height (excluding the antenna, but including a 242.6 m spire) of 828 m (2,717 ft)."},{"n":"Emirate of Dubai","lat":25.2644,"lon":55.3117,"s":102,"w":"Emirate of Dubai","ty":"emirate of the United Arab Emirates","u":0,"b":"The Emirate of Dubai is one of the seven emirates of the United Arab Emirates. It is the most populous emirate of the UAE. The capital of the emirate is the eponymous city, Dubai."},{"n":"Emirate of Abu Dhabi","lat":23.6667,"lon":54.0,"s":100,"w":"Emirate of Abu Dhabi","ty":"emirate of the United Arab Emirates","u":0,"b":"The Emirate of Abu Dhabi is one of seven emirates that constitute the United Arab Emirates. It is the largest emirate, accounting for 87% of the nation's total land area or 67,340 km2 (26,000 sq mi). Abu Dhabi is also the second most populous of the seven emirates."},{"n":"Sharjah","lat":25.3375,"lon":55.4119,"s":86,"w":"Sharjah","ty":"big city|city","u":0,"b":"Sharjah is a major port city and the third-most populous city in the United Arab Emirates, after Dubai and Abu Dhabi. It is the capital of the Emirate of Sharjah and forms part of the Dubai-Sharjah-Ajman metropolitan area. The emirate shares legal, political, military and economic functions with the other emirates of the UAE within a federal framework."},{"n":"Emirate of Ajman","lat":25.4,"lon":55.5,"s":84,"w":"Emirate of Ajman","ty":"emirate of the United Arab Emirates","u":0,"b":"The Emirate of Ajman (Arabic: إمارة عجمان ʼImāra(t) ʻAǧmān, pronounced) is one of the seven emirates of the United Arab Emirates. It joined the United Arab Emirates federation on December 2, 1971."},{"n":"Emirate of Fujairah","lat":25.1331,"lon":56.3331,"s":81,"w":"Emirate of Fujairah","ty":"emirate of the United Arab Emirates","u":0,"b":"The Emirate of Fujairah is one of the seven emirates that make up the United Arab Emirates, the only one of the seven with a coastline solely on the Gulf of Oman and none on the Persian Gulf. Its capital is Fujairah."},{"n":"Emirate of Sharjah","lat":25.35,"lon":55.4331,"s":80,"w":"Emirate of Sharjah","ty":"emirate of the United Arab Emirates","u":0,"b":"The Emirate of Sharjah is one of the emirates of the United Arab Emirates. It covers 2,900 square kilometres (1,100 sq mi) and has a population of over 1,800,000 (2022). It comprises the capital city of Sharjah, after which it is named, and other minor towns and exclaves such as Kalba, Al Dhaid, Dibba Al-Hisn and Khor Fakkan."},{"n":"Ras Al Khaimah","lat":25.7833,"lon":55.95,"s":79,"w":"Emirate of Ras Al Khaimah","ty":"emirate of the United Arab Emirates","u":0,"b":"The Emirate of Ras Al Khaimah is the northernmost of the seven emirates that make up the United Arab Emirates. The city of Ras Al Khaimah, abbreviated to RAK or RAK City, is the capital of the emirate and home to most of the emirate's residents. It is linked to the Islamic trading port of Julfar, its predecessor settlement."},{"n":"Al Ain","lat":24.2075,"lon":55.7447,"s":79,"w":"Al Ain","ty":"border city|human settlement|big city|city","u":0,"b":"Al Ain (Arabic: ٱلْعَيْن, romanized: Al-ʿAyn, lit. 'The Spring') is a city in the Emirate of Abu Dhabi, United Arab Emirates, and the seat of the administrative division of the Al Ain Region. The city is bordered to the east by the Omani town of Al-Buraimi."},{"n":"Emirate of Umm Al Quwain","lat":25.55,"lon":55.55,"s":77,"w":"Emirate of Umm Al Quwain","ty":"emirate of the United Arab Emirates","u":0,"b":"The Emirate of Umm Al Quwain is one of the seven constituent emirates of the United Arab Emirates, located in the north of the country. It is the least populous and second smallest emirate in the UAE and borders the Persian Gulf. Umm Al Quwain lies between Ras Al Khaimah and Sharjah/Ajman on the west coast."},{"n":"Ajman","lat":25.3994,"lon":55.4797,"s":62,"w":"Ajman","ty":"big city|city","u":0,"b":"Ajman (Arabic: عجمان 'Aǧmān; Gulf Arabic: عيمان ʿYmān) is the fifth-largest and fifth-most populous city in the United Arab Emirates, after Dubai, Abu Dhabi, Sharjah, and Al Ain. It is the capital of the Emirate of Ajman and forms part of the Dubai–Sharjah–Ajman metropolitan area. It is bounded by the Persian Gulf to the west and surrounded by the Emirate of Sharjah on land."},{"n":"Kish Island","lat":26.535,"lon":53.975,"s":56,"w":"Kish Island","ty":"island","u":0,"b":"Kish (Persian: کیش ) is a 91.5-square-kilometre (35.3 mi2) resort island in Bandar Lengeh County, Hormozgan Province, off the southern coast of Iran in the Persian Gulf. The island's population center is the city of Kish. Owing to its free trade zone status, the island is marketed as a consumers' paradise, offering shopping centers, tourist attractions, and resort hotels."},{"n":"Sheikh Zayed Mosque","lat":24.412,"lon":54.474,"s":56,"w":"Sheikh Zayed Grand Mosque","ty":"mosque","u":0,"b":"The Sheikh Zayed Grand Mosque is a mosque located in Abu Dhabi, the capital city of the United Arab Emirates. It is the country's largest mosque, and is the key place of worship for daily Islamic prayers. There is a smaller replica of this mosque in Surakarta, a city in Indonesia."},{"n":"Ras al-Khaimah","lat":25.7851,"lon":55.9479,"s":52,"w":"Ras Al Khaimah","ty":"city","u":0,"b":"Ras Al Khaimah, often referred to its initials RAK, is an industrial port city and the largest city and capital of the Emirate of Ras Al Khaimah in the United Arab Emirates. The city had a population of 191,753 people in 2025, and is the third-most populous city of the northern UAE after Sharjah and Ajman."},{"n":"Dubai Metro","lat":25.2697,"lon":55.3094,"s":50,"w":"Dubai Metro","ty":"automated rapid transit","u":0,"b":"The Dubai Metro (Arabic: مترو دبي) is an automated rapid transit system in the city of Dubai, United Arab Emirates. The metro system consists of a network of two main lines: the Red Line and the Green Line. A third line, the Blue Line, is scheduled to open in 2029."},{"n":"Musandam Governorate","lat":26.0,"lon":56.3,"s":50,"w":"Musandam Governorate","ty":"governorates of Oman","u":0,"b":"The Musandam Governorate is a governorate of Oman. Except for the exclave of Madha, it is located on the Musandam Peninsula, which juts into the Strait of Hormuz, the narrow entry into the Persian Gulf, from the Arabian Peninsula. The governorate is also an exclave, separated from the rest of Oman by the United Arab Emirates."},{"n":"Fujairah","lat":25.1222,"lon":56.3344,"s":49,"w":"Fujairah","ty":"city","u":0,"b":"Fujairah City (Arabic: الفجيرة) is the capital of the Emirate of Fujairah in the United Arab Emirates. It is the seventh-largest city in UAE, located on the Gulf of Oman (part of the Indian Ocean). It is the only Emirati capital city on the UAE's east coast."},{"n":"Palm Islands","lat":25.1169,"lon":55.1319,"s":48,"w":"Palm Islands","ty":"land reclamation|archipelago","u":0,"b":"The Palm Islands consist of three artificial archipelagos: Palm Jumeirah, Dubai Islands (formerly known as Palm Deira or Deira Islands), and Palm Jebel Ali, off the coast of Dubai, United Arab Emirates. The Palm Islands were constructed around the same time as The World Islands. Nakheel Properties is the Palm Islands real estate developer."},{"n":"The World","lat":25.2356,"lon":55.1645,"s":46,"w":"The World (archipelago)","ty":"artificial archipelago","u":0,"b":"The World Islands (Arabic: جزر العالم, romanized: Juzur al-Ālam) are an archipelago of small artificial islands constructed in the shape of a world map, located in the Persian Gulf, off the coast of Dubai, United Arab Emirates."},{"n":"Abu Musa Island","lat":25.875,"lon":55.03,"s":43,"w":"Abu Musa","ty":"island|disputed territory","u":0,"b":"Abu Musa is a 12.8-square-kilometre (4.9 sq mi) island in the eastern Persian Gulf, near the entrance to the Strait of Hormuz. The island is currently administered by Iran. Due to the depth of the sea, oil tankers and other large ships have to pass between Abu Musa and Greater and Lesser Tunbs, which makes these islands one of the most strategic points in the Persian Gulf."},{"n":"Yas Marina Circuit","lat":24.4702,"lon":54.6061,"s":42,"w":"Yas Marina Circuit","ty":"motorsport racing track","u":0,"b":"The Yas Marina Circuit (Arabic: حلبة مرسى ياس) is a 5.281 km (3.281 mi) motorsport circuit situated on Yas Island in Abu Dhabi, United Arab Emirates. The circuit was designed by Hermann Tilke. It has hosted the season-ending Formula One Abu Dhabi Grand Prix since 2009."},{"n":"Khasab","lat":26.1833,"lon":56.25,"s":42,"w":"Khasab","ty":"human settlement|town|province of Oman","u":0,"b":"Khasab (Arabic: خَصَب, romanized: Ḫaṣab) is a town and capital of the Musandam Governorate which is an exclave of Oman bordering the United Arab Emirates at the tip of the Musandam Peninsula by the Strait of Hormuz. It has been dubbed the \"Norway of Arabia\" because of its extensive fjord-like craggy inlets and desolate mountainscapes."},{"n":"Sohar","lat":24.342,"lon":56.7299,"s":41,"w":"Sohar","ty":"province of Oman|city","u":0,"b":"Sohar (Arabic: صُحَار, romanized: Ṣuḥār), officially: Suhar, is the capital and largest city of the Al Batinah North Governorate in Oman. An ancient capital of the country that once served as an important Islamic port town on the Gulf of Oman, Sohar has also been credited as the mythical birthplace of Sinbad the Sailor. It was historically known as Mazūn (مَزُوْن)."},{"n":"Almas Tower","lat":25.0688,"lon":55.1411,"s":40,"w":"Almas Tower","ty":"skyscraper","u":0,"b":"Almas Tower (Arabic: برج الماس Diamond Tower) is a 68-storey, 360 m (1,180 ft), supertall skyscraper in the Jumeirah Lakes Towers, Dubai, United Arab Emirates. Construction of the office building began in early 2005 and was completed in 2008 with the installation of some remaining cladding panels at the top of the tower."},{"n":"Khor Fakkan","lat":25.3392,"lon":56.3561,"s":39,"w":"Khor Fakkan","ty":"human settlement","u":0,"b":"Khorfakkan is a city and an exclave of the Emirate of Sharjah, located on the east coast of the United Arab Emirates (UAE), facing the Gulf of Oman (Indian Ocean), and geographically surrounded by the Emirate of Fujairah. The city, the second largest on the east coast after Fujairah City, is set on the bay of Khor Fakkan, which means \"Creek of Two Jaws\"."},{"n":"Umm Al Quwain","lat":25.5598,"lon":55.5572,"s":39,"w":"Umm Al Quwain","ty":"human settlement","u":0,"b":"Umm Al Quwain is the capital and largest city of the Emirate of Umm Al Quwain in the United Arab Emirates. The city is situated on the peninsula of Khor Al Bidiyah, with its nearest major cities being Sharjah to the southwest and Ras Al Khaimah to the northeast. The city's economy is primarily based on fishing and tourism, with some industrial activities and trade."},{"n":"Bandar Lengeh","lat":26.5621,"lon":54.8838,"s":38,"w":"Bandar Lengeh","ty":"city of Iran","u":0,"b":"Bandar Lengeh (Persian: بندرلنگه) is a city in the Central District of Bandar Lengeh County, Hormozgan province, Iran, serving as capital of both the county and the district. Bandar Lengeh is a port city on the Persian Gulf, 280 km (170 mi) from Lar, 192 km (119 mi) from Bandar Abbas, and 420 km (260 mi) from Bushehr."},{"n":"Madha","lat":25.2844,"lon":56.3331,"s":37,"w":"Madha","ty":"province of Oman|border city|exclave|enclave","u":0,"b":"Madha (Arabic: مَدْحَاء, romanized: madḥāʾ) is an exclave of Oman entirely surrounded by the United Arab Emirates (UAE). Administratively, it is a province (wilayah) belonging to the Musandam Governorate. The territory is situated halfway between the Musandam Peninsula and the Omani mainland."},{"n":"Palm Jumeirah","lat":25.1172,"lon":55.1344,"s":37,"w":"Palm Jumeirah","ty":"archipelago|land reclamation|artificial island","u":0,"b":"The Palm Jumeirah, also known as the Palm Islands, (Arabic: نخلة جميرا) is an archipelago of artificial islands on the Persian Gulf in Jumeirah, Dubai, United Arab Emirates."},{"n":"Rose Tower","lat":25.2117,"lon":55.2767,"s":37,"w":"Rose Rayhaan by Rotana","ty":"hotel|skyscraper","u":0,"b":"Rose Rayhaan by Rotana, also known as the Rose Tower, is a 72-storey, 333 m (1,093 ft) hotel on Sheikh Zayed Road in Dubai, United Arab Emirates. It is no. 5 on the list of world's tallest hotels."},{"n":"Doha","lat":25.2861,"lon":51.5294,"s":187,"w":"Doha","ty":"largest city|human settlement|national capital","u":0,"b":"Doha is the capital and largest city, and main financial hub of Qatar. Located on the Persian Gulf coast in the east of the country, north of Al Wakrah and south of Al Khor and Lusail, it is home to most of the country's population."},{"n":"Manama","lat":26.2167,"lon":50.5833,"s":169,"w":"Manama","ty":"city|big city","u":0,"b":"Manama is the capital and largest city of Bahrain, with an approximate population of 743,066 as of 2025 estimate. Long an important trading center in the Persian Gulf, Manama is home to a diverse population."},{"n":"Persian Gulf","lat":26.0,"lon":52.0,"s":160,"w":"Persian Gulf","ty":"gulf|sea","u":0,"b":"The Persian Gulf, sometimes called the Arabian Gulf, is a mediterranean sea in West Asia. The body of water is an extension of the Arabian Sea and the larger Indian Ocean located between the Arabian Peninsula and Iran (Persia). It is connected to the Gulf of Oman in the east by the Strait of Hormuz."},{"n":"Al Wakrah","lat":25.18,"lon":51.61,"s":56,"w":"Al Wakrah","ty":"city","u":0,"b":"Al Wakrah (Arabic: الوكرة, romanized: al-Wakra) is the capital city of the Al Wakrah Municipality in Qatar. Al Wakrah's eastern edge touches the shores of the Persian Gulf and Qatar's capital Doha is situated immediately north of the city. Governed by Sheikh Abdulrahman bin Jassim Al Thani, it was originally a small fishing and pearling village."},{"n":"Lusail","lat":25.4175,"lon":51.5075,"s":53,"w":"Lusail","ty":"city","u":0,"b":"Lusail is the third-largest city in Qatar after Doha and Al-Rayyan, and serves as an important economic hub. Located on the coast in the southern part of the municipality of Al Daayen, it lies about 23 kilometres (14 mi) north of the Doha city centre, just north of the West Bay Lagoon, covering over 38 square kilometres (15 sq mi)."},{"n":"Al Khor","lat":25.6839,"lon":51.5058,"s":50,"w":"Al Khor (city)","ty":"human settlement","u":0,"b":"Al Khor (Arabic: الخور, romanised: Al Khawr) is a coastal city in northeast Qatar, located 50 kilometres (31 mi) north of the capital Doha. Considered one of Qatar's largest cities, it is the capital of the municipality of Al Khor and Al Thakhira. Dating back to the 18th century, it is one of Qatar's oldest settlements."},{"n":"Qal’at al Bahrain","lat":26.2336,"lon":50.5206,"s":48,"w":"Qal'at al-Bahrain","ty":"cultural heritage|archaeological site","u":1,"b":"The Qal'at al-Bahrain (also Qala'at al-Bahrain) (Arabic: قلعة البحرين; Portuguese: Forte de Barém), also known as the Bahrain Fort or Portuguese Fort, is an archaeological site located in Bahrain."},{"n":"Al-Muharraq","lat":26.2533,"lon":50.6083,"s":47,"w":"Muharraq","ty":"city|human settlement","u":0,"b":"Muharraq (Arabic: المحرق, romanized: al-Muḥarraq) is Bahrain's third-most populous city and served as its capital until 1932 when it was replaced by Manama. The population of Muharraq in 2020 was 263,373. Muharraq served as the country's capital until 1932."},{"n":"Riffa","lat":26.13,"lon":50.555,"s":46,"w":"Riffa","ty":"big city|city","u":0,"b":"Riffa (Arabic: الرفاع, romanized: Ar-Rifāʿ) is the second-largest city in the Kingdom of Bahrain in terms of area. The city is divided into three parts: East Riffa, West Riffa and North Riffa. All three parts are located in the Southern Governorate."},{"n":"Al Rayyan Municipality","lat":25.3083,"lon":51.3667,"s":45,"w":"Al Rayyan","ty":"municipality of Qatar","u":0,"b":"Al Rayyan (Arabic: الريان; also spelled Ar Rayyan) is the third-largest municipality in Qatar. Its primary settlement is the city of the same name, which occupies the entire eastern section and is a part of the Doha Metropolitan Area. The vast expanse of mostly undeveloped lands in the south-west also falls under the municipality's administration."},{"n":"Bahrain International Circuit","lat":26.0325,"lon":50.5106,"s":44,"w":"Bahrain International Circuit","ty":"motorsport racing track","u":0,"b":"The Bahrain International Circuit is a 5.412 km (3.363 mi) motorsport venue opened in 2004 and used for drag racing, GP2 Series (now FIA Formula 2), and the annual Formula One Bahrain Grand Prix. The 2004 Grand Prix was the first Formula One race held in the Middle East. Beginning in 2006, Australian V8 Supercars raced at the BIC, with the event known as the Desert 400."},{"n":"2011 AFC Asian Cup","lat":25.32,"lon":51.37,"s":44,"w":"2011 AFC Asian Cup","ty":"sports season","u":0,"b":"The 2011 AFC Asian Cup was the 15th edition of the men's AFC Asian Cup, a quadrennial international football tournament organised by the Asian Football Confederation (AFC). The finals were held in Qatar from 7 to 29 January 2011. It was the second time that the tournament was hosted by Qatar, the previous occasion being the 1988 AFC Asian Cup."},{"n":"Bushehr Province","lat":28.9184,"lon":50.8382,"s":89,"w":"Bushehr province","ty":"province of Iran","u":0,"b":"Bushehr Province (Persian: استان بوشهر) is one of the 31 provinces of Iran. It is in the south of the country, with a long coastline on the Persian Gulf. Its capital is the city of Bushehr."},{"n":"Dammam","lat":26.4333,"lon":50.1,"s":84,"w":"Dammam","ty":"port city|big city","u":0,"b":"Dammam (Arabic: الدمام, romanized: ad-Dammām) is the seat and largest city of the Eastern Province of Saudi Arabia. An industrial port city on the coast of the Persian Gulf, it had a population of 1,386,166 as of 2022, making it the country's fifth-largest city after Riyadh, Jeddah, Mecca, and Medina."},{"n":"Bushehr","lat":28.9689,"lon":50.8367,"s":75,"w":"Bushehr","ty":"city of Iran|big city","u":0,"b":"Bushehr (Persian: بوشهر; ) is a port city in the Central District of Bushehr County, Bushehr province, Iran. It is the capital of the province, the county and the district."},{"n":"Kharg Island","lat":29.245,"lon":50.31,"s":57,"w":"Kharg Island","ty":"coral island","u":0,"b":"Kharg Island, also spelled Khark Island and often referred to as the \"Forbidden Island\", is a continental island of Iran in the Persian Gulf. The island is 25 kilometres (16 mi) off the coast of Iran and 660 kilometres (410 mi) northwest of the Strait of Hormuz."},{"n":"Dhahran","lat":26.2667,"lon":50.15,"s":54,"w":"Dhahran","ty":"administrative territorial entity|big city","u":0,"b":"Dhahran is a city located in the Eastern Province, Saudi Arabia. With a total population of 143,936 as of 2022, it is a major administrative center for the Saudi oil industry."},{"n":"Qatif governorate","lat":26.5685,"lon":50.0089,"s":50,"w":"Qatif","ty":"governorate of Saudi Arabia","u":0,"b":"Qatif (Arabic: ٱلْقَطِيف, romanized: al-Qaṭīf) is a governorate located in Eastern Province, Saudi Arabia. It extends from Ras Tanura and Jubail in the north to Dammam in the south, and from the Persian Gulf in the east to King Fahd International Airport in the west."},{"n":"Jubail","lat":27.0,"lon":49.6667,"s":49,"w":"Jubail","ty":"big city","u":0,"b":"Jubail (Arabic: الجبيل, Al Jubayl) is an industrial city in the Eastern province on the Persian Gulf of Saudi Arabia. It is the third most-populous city in the province, after the capital, Dammam, and Al Hofuf. With a total population of 474,679 as of 2022, it is Saudi Arabia’s 11th most-populous city."},{"n":"Firuzabad","lat":28.8436,"lon":52.5706,"s":48,"w":"Firuzabad, Fars","ty":"city of Iran","u":0,"b":"Firuzabad (Persian: فيروزآباد) is a city in the Central District of Firuzabad County, Fars province, Iran, serving as capital of both the county and the district. Firuzabad is south of Shiraz. The city is surrounded by a mud wall and ditch."},{"n":"Hofuf","lat":25.3608,"lon":49.5997,"s":48,"w":"Hofuf","ty":"town","u":0,"b":"Al-Hofuf, also known as Al-Hasa or Al-Ahsa is the seat of the Al-Ahsa Governorate, and the second-largest city in the Eastern Province of Saudi Arabia, after the capital, Dammam. With a population of 729,606 (as of 2022), it is the 6th most-populous city in Saudi Arabia, and the second-largest in the country to not be a provincial capital."},{"n":"Khobar","lat":26.3,"lon":50.2167,"s":45,"w":"Khobar","ty":"big city","u":0,"b":"Al Khobar (Arabic: ٱلْخُبَر, romanized: al-Khobar) is a city and governorate in the Eastern Province of the Kingdom of Saudi Arabia, situated on the coast of the Persian Gulf."},{"n":"Zubarah","lat":25.9834,"lon":51.0272,"s":42,"w":"Zubarah","ty":"World Heritage Site|archaeological site|ancient city","u":1,"b":"Zubarah (Arabic: الزبارة), also referred to as Al Zubarah or Az Zubarah, is a ruined, ancient town located on the northwestern coast of the Qatar peninsula in the Al Shamal municipality, about 65 miles or 105 kilometres from the capital Doha. It was founded by the Bani Utbah tribal confederation who migrated from Kuwait in the mid-eighteenth century."},{"n":"King Fahd Causeway","lat":26.1825,"lon":50.3358,"s":42,"w":"King Fahd Causeway","ty":"causeway|international bridge|bridge–tunnel|road bridge","u":0,"b":"The King Fahd Causeway (Arabic: جسر الملك فهد, romanized: Jisr al-Malik Fahd) is a 25 km (15.5 mi) long series of bridges and causeways connecting Khobar, Saudi Arabia, and Al Jasra, Bahrain across the Gulf of Bahrain. Its five bridges rest on 536 concrete pylons, with seven embankments in the gulf's shallower water."},{"n":"Al-Ahsa Oasis","lat":25.4294,"lon":49.6219,"s":42,"w":"Al-Ahsa Oasis","ty":"big city|cultural landscape","u":1,"b":"Al-Ahsa Oasis (Arabic: الْأَحْسَاء, al-ʾAhsā), also known as al-Ḥasāʾ (الْحَسَا) or Hajar (هَجَر), is an oasis and historical region in eastern Saudi Arabia. Al-Ahsa Governorate, which makes up much of the country's Eastern Province, is named after it. The oasis is located about 60 km (37 miles) inland from the coast of the Persian Gulf."},{"n":"Capital Governorate","lat":26.2361,"lon":50.5831,"s":40,"w":"Capital Governorate, Bahrain","ty":"governorate of Bahrain","u":0,"b":"The Capital Governorate (Arabic: محافظة العاصمة, romanized: Muḥāfaẓat al-ʿĀṣimah) is one of the four governorates of Bahrain. The governorate includes Manama, the capital of Bahrain. It is the most populous administrative region in the country, with a population of over half million people in 2020."},{"n":"Kuwait City","lat":29.375,"lon":47.98,"s":169,"w":"Kuwait City","ty":"big city|city","u":0,"b":"Kuwait City is the capital and largest city of Kuwait. Located at the heart of the country on the south shore of Kuwait Bay on the Persian Gulf, it is the political, cultural and economic primate city of the emirate, being home to the headquarters of most Kuwaiti corporations and the entirety of its banking system."},{"n":"West Asia","lat":29.1667,"lon":47.6,"s":140,"w":"West Asia","ty":"region|subcontinent","u":0,"b":"West Asia (also called Western Asia or Southwest Asia) is the westernmost region of Asia. As defined by most academics, UN bodies and other institutions, the subregion consists of Anatolia, the Arabian Peninsula, Iran, Mesopotamia, the Armenian highlands, the Levant, the Sinai Peninsula and the South Caucasus."},{"n":"Basra","lat":30.515,"lon":47.81,"s":104,"w":"Basra","ty":"big city|port city","u":0,"b":"Basra (Arabic: ٱلْبَصْرَة, romanized: al-Baṣrah) or Basrah is a port city in southern Iraq. It is the capital of the eponymous Basra Governorate, as well as the third largest city in Iraq overall, behind Baghdad and Mosul. Located near the Iran–Iraq border, the city is situated along the banks of the Shatt al-Arab that empties into the Persian Gulf."},{"n":"Abadan","lat":30.3392,"lon":48.3042,"s":83,"w":"Abadan, Iran","ty":"big city|city of Iran|port city","u":0,"b":"Abadan is a city in the Central District of Abadan County, Khuzestan province, Iran, serving as capital of both the county and the district. The city is in the southwest of the county. It lies on Abadan Island (68 km or 42 mi long, 3–19 km or 2–12 miles wide)."},{"n":"Shatt al-Arab","lat":29.9369,"lon":48.6077,"s":78,"w":"Shatt al-Arab","ty":"river","u":0,"b":"The Shatt al-Arab (Arabic: شط العرب, lit. 'River of the Arabs') is a river about 200 kilometres (120 mi) in length that is formed at the confluence of the Euphrates and Tigris rivers in the town of al-Qurnah in the Basra Governorate of southern Iraq. The southern end of the river constitutes the Iran–Iraq border down to its mouth, where it discharges into the Persian Gulf."},{"n":"Basra Governorate","lat":30.3667,"lon":47.3667,"s":59,"w":"Basra Governorate","ty":"governorate of Iraq","u":0,"b":"The Basra Governorate (Arabic: محافظة البصرة‎ Muḥāfaẓa al-Baṣra), also called Basra Province, is a governorate in southern Iraq bordering Kuwait to the south and Iran to the east. The capital is the city of Basra, located in the Basrah district. Other districts of Basra include Al-Qurna, Al-Zubair, Al-Midaina, Shatt Al-Arab, Abu Al-Khaseeb and Al-Faw located on the Persian Gulf."},{"n":"Karun River","lat":30.4275,"lon":48.1653,"s":59,"w":"Karun","ty":"river","u":0,"b":"The Karun is the Iranian river with the highest water flow, and the country's only navigable river. It is 950 km (590 mi) long. The Karun rises in the Zard Kuh mountains of the Bakhtiari district in the Zagros Range, receiving many tributaries, such as the Dez and the Kuhrang."},{"n":"Khorramshahr","lat":30.4408,"lon":48.1842,"s":56,"w":"Khorramshahr","ty":"city of Iran","u":0,"b":"Khorramshahr (Persian: خرمشهر;) is a city in the Central District of Khorramshahr County, Khuzestan province, Iran, serving as capital of both the county and the district. Khorramshahr is an inland port city located approximately 10 kilometres (6.2 mi) north of Abadan."},{"n":"Behbahan","lat":30.5958,"lon":50.2417,"s":44,"w":"Behbahan","ty":"big city|city of Iran","u":0,"b":"Behbahan (Persian: بهبهان) is a city in the Central District of Behbahan County, Khuzestan province, Iran, serving as the capital of both the county and the district."},{"n":"Kazerun","lat":29.6167,"lon":51.65,"s":43,"w":"Kazerun","ty":"city of Iran","u":0,"b":"Kazerun (Persian: کازرون) is a city in the northwest of Fars Province in Iran and the center of Kazerun County. This city has an ancient history, with numerous historical monuments and tourist attractions. Kazerun is the fifth most populous city in Fars Province."},{"n":"Battle of the Camel","lat":30.5,"lon":47.8167,"s":43,"w":"Battle of the Camel","ty":"battle","u":0,"b":"The Battle of the Camel, also known as the Battle of Basra (Arabic: معركة الجمل, romanized: Maʿrakat al-Jamal), took place in 656 CE outside of Basra in Iraq. It was fought between the partisans of the fourth Rashidun caliph Ali and the Uthmaniyya led by Aisha, Talha, and Zubayr."},{"n":"Umm Qasr","lat":30.0342,"lon":47.9294,"s":43,"w":"Umm Qasr","ty":"big city|city","u":0,"b":"Umm Qasr is a port city in southern Iraq. It stands on the canalised Khawr az-Zubayr, part of the Khawr Abd Allah estuary which leads to the Persian Gulf. It is separated from the border of Kuwait by a small inlet."},{"n":"Mahshahr","lat":30.5567,"lon":49.1886,"s":41,"w":"Bandar-e Mahshahr","ty":"city of Iran","u":0,"b":"Bandar-e Mahshahr (Persian: بندرماهشهر) is a city in the Central District of Bandar Mahshahr County, Khuzestan province, Iran, serving as capital of both the county and the district."},{"n":"Al Hamra Tower","lat":29.3786,"lon":47.9928,"s":38,"w":"Al Hamra Tower","ty":"tower block|skyscraper","u":0,"b":"The Al Hamra Tower is a skyscraper in Kuwait City, Kuwait. It is the tallest building in Kuwait. Construction of the skyscraper started in 2005."},{"n":"Bandar Imam Khomeini","lat":30.5491,"lon":49.0586,"s":37,"w":"Bandar-e Emam Khomeini","ty":"city of Iran","u":0,"b":"Bandar-e Emam Khomeyni (Persian: بندر امام خمینی) is the capital city Bandar-e Emam Khomeyni District of Bandar Mahshahr County, Khuzestan province, Iran. It also serves as the administrative center for Bandar-e Emam Khomeyni Rural District. Bandar-e Imam Khomeyni is a port city on the Persian Gulf."},{"n":"Al Ahmadi Governorate","lat":29.077,"lon":48.084,"s":37,"w":"Ahmadi Governorate","ty":"governorate of Kuwait","u":0,"b":"The Ahmadi Governorate is a governorate in southern Kuwait. It is the second most populated governorate in Kuwait, behind Farwaniya Governorate. Many oil and petroleum companies such as KOC and KNPC have their headquarters here."},{"n":"Capital Governorate","lat":29.366,"lon":47.978,"s":36,"w":"Capital Governorate (Kuwait)","ty":"governorate of Kuwait","u":0,"b":"The Asimah Governorate or Capital Governorate, sometimes referred to as Al Kuwayt, is one of the six governorates of Kuwait. It comprises the historic core of Kuwait City, industrial and port areas such as Shuwaikh Port and Doha Port, and several offshore islands. The governorate houses most of Kuwait's financial and business centres such as the Kuwait Stock Exchange."},{"n":"Kuwait Towers","lat":29.39,"lon":48.0031,"s":36,"w":"Kuwait Towers","ty":"architectural landmark|building complex","u":0,"b":"The Kuwait Towers are a group of three thin towers in Kuwait City, standing on a promontory into the Persian Gulf. They were the sixth, and last, group in the larger Kuwait Water Towers system of 34 towers (33 store water; one stores equipment), and were built in a style considerably different from the other five groups."},{"n":"Al Shamal","lat":26.14,"lon":51.22,"s":36,"w":"Al Shamal","ty":"municipality of Qatar","u":0,"b":"Al Shamal is a municipality in Qatar. Its seat is Madinat ash Shamal and it is considered to be one of the major cities in Qatar, although its population is barely over 7,000. The seat's name translates to \"city of the north\"."},{"n":"Muharraq Governorate","lat":26.25,"lon":50.6167,"s":36,"w":"Muharraq Governorate","ty":"governorate of Bahrain","u":0,"b":"The Muharraq Governorate (Arabic: محافظة المحرق, romanized: Muḥāfaẓat al-Muḥarraq) is one of the four governorates of Bahrain. It is now co-extensive with the municipality of Al Muharraq and with Muharraq Island together with outlying islets. It includes the former municipality of Al Hadd at the southern end of that island."},{"n":"Northern Governorate","lat":26.1167,"lon":50.4833,"s":36,"w":"Northern Governorate","ty":"governorate of Bahrain","u":0,"b":"The Northern Governorate is one of the four governorates of Bahrain. It includes parts of the former municipalities of Al Mintaqah al Gharbiyah, Al Mintaqah al Wusta, Al Mintaqah al Shamaliyah, Jidd Haffs and Madinat Hamad. It also includes the island of Umm an Nasan."},{"n":"Hawalli","lat":29.333,"lon":48.029,"s":36,"w":"Hawalli Governorate","ty":"governorate of Kuwait","u":0,"b":"Hawalli Governorate (Arabic: محافظة حولي Muḥāfaẓat Ḥawalli) is one of the six governorates of Kuwait. Nawaf Al-Ahmad Al-Jaber Al-Sabah became governor in 1962. A more recent governor of the Hawalli governorate is Ahmad Nawaf Al-Ahmad Al-Sabah, who later became prime minister."},{"n":"Al Jahra Governorate","lat":29.4631,"lon":47.635,"s":35,"w":"Jahra Governorate","ty":"governorate of Kuwait","u":0,"b":"Jahra Governorate (Arabic: محافظة الجهراء Muḥāfaẓat al-Ǧahrāʾ) is one of the six governorates of Kuwait. It is the largest Governorate in Kuwait accounting for 63 percent of its land area. It includes the town of Al Jahra, most of the northern and western parts of Kuwait, several islands (among them Bubiyan Island)."},{"n":"Euphrates","lat":31.0043,"lon":47.442,"s":142,"w":"Euphrates","ty":"river","u":0,"b":"The Euphrates is the longest and one of the most historically important rivers of West Asia. Together with the Tigris, it is one of the two defining rivers of Mesopotamia (lit. 'the land between the rivers'). Originating in Turkey, the Euphrates flows through Syria and Iraq to join the Tigris in the Shatt al-Arab in Iraq, which empties into the Persian Gulf."},{"n":"Sumer","lat":32.0,"lon":45.5,"s":140,"w":"Sumer","ty":"culture|historical region|cultural region|style|archaeological culture|former or current s","u":0,"b":"Sumer is the earliest known civilization, located in the historical region of southern Mesopotamia (now south-central Iraq), emerging during the Chalcolithic and early Bronze Ages between the 5th and 4th millennium BC."},{"n":"Tigris","lat":31.0043,"lon":47.4421,"s":130,"w":"Tigris","ty":"river","u":0,"b":"The Tigris is the eastern of the two great rivers that define Mesopotamia, the other being the Euphrates. The river flows south from the mountains of the Armenian Highlands through the Syrian and Arabian Deserts, before merging with the Euphrates and reaching to the Persian Gulf. The Tigris passes through historical cities such as Mosul, Tikrit, Samarra and Baghdad."},{"n":"Khuzestan Province","lat":31.3273,"lon":48.694,"s":97,"w":"Khuzestan province","ty":"province of Iran","u":0,"b":"Khuzestan province is one of the 31 provinces of Iran. An extension of the Mesopotamian Plain, it is located in the southwest of the country, bordering Iraq and the Persian Gulf, and covering an area of 64,055 square kilometres (24,732 mi2). Its capital is the city of Ahvaz."},{"n":"Ahvaz","lat":31.3189,"lon":48.6842,"s":94,"w":"Ahvaz","ty":"big city|city of Iran","u":0,"b":"Ahvaz (Persian: اهواز; ) is a city in the Central District of Ahvaz County, Khuzestan province, Iran, serving as capital of the province, the county, and the district."},{"n":"Ur","lat":30.9622,"lon":46.1044,"s":86,"w":"Ur","ty":"ancient city|archaeological site","u":1,"b":"Ur ( or ) was a major Sumerian city-state in ancient Mesopotamia, located at the site of modern Tell el-Muqayyar (Arabic: تَلّ ٱلْمُقَيَّر, lit. 'mound of bitumen') in Dhi Qar Governorate, Iraq."},{"n":"Susa","lat":32.1894,"lon":48.2561,"s":79,"w":"Susa","ty":"ancient city|architectural landmark|archaeological site","u":1,"b":"Susa was an ancient city in the lower Zagros Mountains about 250 km (160 mi) east of the Tigris, between the Karkheh and Dez Rivers in Iran. It represents the current city of Shush, located on the site of ancient Susa."},{"n":"Uruk","lat":31.3259,"lon":45.6374,"s":75,"w":"Uruk","ty":"ancient city|type site|archaeological site|city-state|human settlement","u":1,"b":"Uruk, the archeological site known today as Warka, was an ancient city in the Near East or West Asia, located east of the current bed of the Euphrates River, on an ancient, now-dried channel of the river in Muthanna Governorate, Iraq."},{"n":"Nippur","lat":32.1261,"lon":45.2308,"s":69,"w":"Nippur","ty":"ancient city|archaeological site","u":0,"b":"Nippur was an ancient Sumerian city. It was the special seat of the worship of the Sumerian god Enlil, the \"Lord Wind\", ruler of the cosmos, subject to An alone. Nippur was located in modern Nuffar 8 kilometers north of modern Afak, Al-Qādisiyyah Governorate, Iraq."},{"n":"Chogha Zanbil","lat":32.0083,"lon":48.5208,"s":66,"w":"Chogha Zanbil","ty":"archaeological site|ancient city","u":1,"b":"Chogha Zanbil is an ancient Elamite complex in the Khuzestan province of Iran. It is one of the few existing ziggurats outside Mesopotamia. It lies approximately 30 km (19 mi) southeast of Susa and 80 km (50 mi) north of Ahvaz."},{"n":"Nasiriyah","lat":31.0439,"lon":46.2575,"s":64,"w":"Nasiriyah","ty":"big city|city","u":0,"b":"Nasiriyah, also spelled Nassiriya or Nasiriya, is a city in Iraq, the capital of the Dhi Qar Governorate. It lies on the lower Euphrates, about 360 km (225 miles) south-southeast of Baghdad, near the ruins of the ancient city of Ur, as well as the recently established Ur Tourist City located adjacent to the archaeological site."},{"n":"Lagash","lat":31.4114,"lon":46.4072,"s":61,"w":"Lagash","ty":"historical country|city-state","u":0,"b":"Lagash was an ancient city-state located northwest of the junction of the Euphrates and Tigris rivers and east of Uruk, about 22 kilometres (14 mi) east of the modern town of Al-Shatrah, Iraq. Lagash (modern Al-Hiba in Dhi Qar Governorate) was one of the oldest cities of the Ancient Near East, and the Lagash state incorporated the cities of Lagash, Girsu, and Nina."},{"n":"Al Muthanna Governorate","lat":30.2,"lon":45.35,"s":55,"w":"Muthanna Governorate","ty":"governorate of Iraq","u":0,"b":"Muthanna Governorate (Arabic: المثنى Al Muthannā) or Al Muthanna Province, is a province in Iraq, named after the 7th-century Arab general al-Muthanna ibn Haritha. It is in the south of the country, bordering Saudi Arabia and Kuwait. The provincial capital is the city of Samawah."},{"n":"Maysan Governorate","lat":31.9,"lon":47.0333,"s":55,"w":"Maysan Governorate","ty":"governorate of Iraq","u":0,"b":"Maysan Governorate (Arabic: ميسان, romanized: Maysān or Mīsān) is a governorate in southeastern Iraq, bordering Iran. Its administrative centre is the city of Amarah, and it is composed of six districts. Before 1976, it was named Amara Province."},{"n":"Dhi Qar Governorate","lat":31.2333,"lon":46.3167,"s":54,"w":"Dhi Qar Governorate","ty":"governorate of Iraq","u":0,"b":"Thi Qar Governorate is a governorate in southern Iraq, in the Arabian Peninsula. The provincial capital is Nasiriyah. Prior to 1976 the governorate was known as Muntafiq Governorate."},{"n":"Eridu","lat":30.826,"lon":45.9946,"s":54,"w":"Eridu","ty":"archaeological site|ancient city","u":1,"b":"Eridu was a Sumerian city located at Tell Abu Shahrain (Arabic: تل أبو شهرين), also Abu Shahrein or Tell Abu Shahrayn, an archaeological site in Lower Mesopotamia. It is located in Dhi Qar Governorate, Iraq, near the modern city of Basra. Eridu is traditionally considered the earliest city in southern Mesopotamia based on the Sumerian King List."},{"n":"Al-Qādisiyyah Governorate","lat":31.85,"lon":45.05,"s":54,"w":"Al-Qādisiyyah Governorate","ty":"governorate of Iraq","u":0,"b":"Al-Qadisiyah Governorate (Arabic: القادسية, al-Qādisiyah), also known as the Al-Diwaniyah Governorate (Arabic: ٱلدِّيوَانِيَّة, ad-Dīwānīyah), is one of the governorates of Iraq. It is in the southern part of the center of the country. The estimated population of the province is about a million and a half million people, according to the census of 2014."},{"n":"Shushtar","lat":32.0497,"lon":48.8483,"s":51,"w":"Shoushtar","ty":"big city|city of Iran","u":0,"b":"Shoushtar (Persian: شوشتر, romanized: Shūshtar) is a city in the Central District of Shoushtar County, Khuzestan province, Iran, serving as capital of both the county and the district. Shoushtar is an ancient fortress city, approximately 92 kilometres (57 mi) from Ahvaz, the centre of the province."},{"n":"Amarah","lat":31.8333,"lon":47.15,"s":50,"w":"Amarah","ty":"city|big city","u":0,"b":"Amarah (Arabic: ٱلْعَمَارَة, romanized: al-ʿAmārah), also spelled Amara, is a city in south-eastern Iraq, located on a low ridge next to the Tigris River waterway south of Baghdad about 50 km (31 mi) from the border with Iran. It lies at the northern tip of the marshlands between the Tigris and Euphrates. It had a population of about 340,000 in 2002 and 720,000 in 2024."},{"n":"Ubaid period","lat":30.9722,"lon":46.0306,"s":48,"w":"Ubaid period","ty":"archaeological culture|archaeological period","u":0,"b":"The Ubaid period (c. 6500–3800 BC) is a prehistoric period of Mesopotamia. The name derives from Tell al-'Ubaid where the earliest large excavation of Ubaid period material was conducted initially by Henry Hall in 1919, Leonard Woolley in 1922–1923, and later by Pinhas Delougaz in 1937."},{"n":"Isin","lat":31.9335,"lon":45.2852,"s":47,"w":"Isin","ty":"archaeological site|human settlement|city-state","u":0,"b":"Isin is an archaeological site in Al-Qādisiyyah Governorate, Iraq which was the location of the Ancient Near East city of Isin, occupied from the late 4th millennium BC Uruk period up until at least the late 1st millennium BC Neo-Babylonian period. It lies about 40 km (25 mi) southeast of the modern city of Al Diwaniyah."},{"n":"Al Diwaniyah","lat":31.9892,"lon":44.9247,"s":47,"w":"Al Diwaniyah","ty":"big city|city","u":0,"b":"Al Diwaniyah (Arabic: ٱلدِّيوَانِيَّة ad-Dīwānīyah), also spelt Diwaniya, is the capital city of Iraq's Al-Qādisiyyah Governorate. In 2014 the population was estimated at 700,000. The city was founded by the rulers of the Khaza'il Dynasty (Banu Khuza'ah) and formally known as Khuza'ahs Diwaniyah - Khuza'ahs Guest House."},{"n":"Larsa","lat":31.2833,"lon":45.8498,"s":47,"w":"Larsa","ty":"archaeological site|hill|city-state|human settlement","u":0,"b":"Larsa (Sumerian: 𒌓𒀕𒆠, romanized: UD.UNUGKI, read Larsamki), also referred to as Larancha/Laranchon (Gk. Λαραγχων) by Berossos and connected with the biblical Ellasar, was an important city-state of ancient Sumer, the center of the cult of the sun god Utu with his temple E-babbar."},{"n":"Umma","lat":31.6674,"lon":45.8877,"s":44,"w":"Umma","ty":"human settlement|archaeological site|city-state","u":0,"b":"Umma (Sumerian: 𒄑𒆵𒆠 = GIŠ.KUŠU2KI) in modern Dhi Qar Province in Iraq, was an ancient city in Sumer. There is some scholarly debate about the Sumerian and Akkadian names for this site. Traditionally, Umma was identified with Tell Jokha."},{"n":"Ziggurat of Ur","lat":30.9625,"lon":46.1025,"s":43,"w":"Ziggurat of Ur","ty":"ziggurat","u":0,"b":"The Ziggurat (or Great Ziggurat) of Ur is a Neo-Sumerian ziggurat in what was the city of Ur near Nasiriyah, in present-day Dhi Qar Province, Iraq. The structure was built during the Early Bronze Age (21st century BC) by King Ur-Nammu of the Third Dynasty of Ur. It had crumbled to ruins by the 6th century BC of the Neo-Babylonian period, when it was restored by King Nabonidus."},{"n":"Samawah","lat":31.3167,"lon":45.2833,"s":41,"w":"Samawah","ty":"big city|city","u":0,"b":"Samawah or As-Samawah (Arabic: ٱلسَّمَاوَة, romanized: as-Samāwah) is a city in Iraq, 280 kilometres (174 mi) southeast of Baghdad. The city of Samawah is the modern capital of the Al Muthanna Governorate. The city is located midway between Baghdad and Basra, at the northern edge of the governorate."},{"n":"Baghdad","lat":33.3153,"lon":44.3661,"s":251,"w":"Baghdad","ty":"largest city|federal capital|big city","u":0,"b":"Baghdad is the capital and largest city in Iraq. It is located on the banks of the Tigris in central Iraq. With an estimated population of 8 million, it ranks among the most populous and largest cities in the Middle East and the Arab world and constitutes 22% of Iraq's population."},{"n":"Mesopotamia","lat":33.7,"lon":43.5,"s":176,"w":"Mesopotamia","ty":"historical region|cultural region|ancient civilization|cultural landscape","u":0,"b":"Mesopotamia is a historical region of West Asia situated within the Tigris–Euphrates river system, in the northern part of the Fertile Crescent. It corresponds roughly to the territory of modern Iraq. Just beyond it lies southwestern Iran, where the region transitions into the Iranian plateau, marking the shift from the Arab world to Iran."},{"n":"Babylon","lat":32.5229,"lon":44.4241,"s":127,"w":"Babylon","ty":"archaeological site|ancient city|city-state","u":0,"b":"Babylon was an ancient city located on the lower Euphrates river in southern Mesopotamia, within modern-day Hillah, Iraq, about 85 kilometres (53 miles) south of modern-day Baghdad. Babylon functioned as the main cultural and political centre of the Akkadian-speaking region of Babylonia."},{"n":"Abbasid Caliphate","lat":33.3153,"lon":44.3661,"s":125,"w":"Abbasid Caliphate","ty":"historical country","u":0,"b":"The Abbasid Caliphate or Abbasid Empire was the third Islamic caliphate, ruled by the Abbasid dynasty. The dynasty was descended from Muhammad's uncle, Abbas ibn Abd al-Muttalib (d. 653), after whom it is named."},{"n":"Achaemenid Empire","lat":32.5364,"lon":44.4208,"s":112,"w":"Achaemenid Empire","ty":"historical period|historical country","u":0,"b":"The Achaemenid Empire was an ancient Iranian empire founded by Cyrus the Great of the Achaemenid dynasty in 550 BC. At peak, its territorial extent was roughly 5.5 million square kilometres (2.1 million square miles), making it the largest empire of its time."},{"n":"Babylonia","lat":32.5,"lon":44.5,"s":100,"w":"Babylonia","ty":"ancient civilization|historical country","u":0,"b":"Babylonia was an ancient Akkadian-speaking state and cultural area based on the city of Babylon in central-southern Mesopotamia (present-day Iraq and parts of Syria). It emerged as an Akkadian-populated but Amorite-ruled state c. 1894 BC."},{"n":"Hanging Gardens of Babylon","lat":32.5355,"lon":44.4275,"s":100,"w":"Hanging Gardens of Babylon","ty":"hanging garden|destroyed building or structure|Wonder of the Ancient World","u":0,"b":"The Hanging Gardens of Babylon were one of the Seven Wonders of the Ancient World listed by Hellenic culture. They were described as a remarkable feat of engineering with an ascending series of tiered gardens containing a wide variety of trees, shrubs, and vines, resembling a large green mountain constructed of mud bricks."},{"n":"Parthian Empire","lat":33.0936,"lon":44.5808,"s":99,"w":"Parthian Empire","ty":"historical country","u":0,"b":"The Parthian Empire, also known as the Arsacid Empire, was a major Iranian political and cultural power centered in ancient Iran from 247 BC to 224 AD. Its latter name comes from its founder, Arsaces I, who led the Parni tribe in conquering the region of Parthia in Iran's northeast, then a satrapy (province) under Andragoras, who was rebelling against the Seleucid Empire."},{"n":"Seleucid Empire","lat":33.0944,"lon":44.5222,"s":95,"w":"Seleucid Empire","ty":"Hellenistic kingdom|empire|historical country|rump state","u":0,"b":"The Seleucid Empire was a Greek state in West Asia during the Hellenistic period. It was founded by the Macedonian general Seleucus I Nicator in 312 BC, following the division of Alexander the Great's Empire, and was ruled by the Seleucid dynasty from Seleucia and later Antioch until its annexation by the Roman Republic under Pompey in 63 BC."},{"n":"Karbala","lat":32.6167,"lon":44.0333,"s":92,"w":"Karbala","ty":"city|big city","u":0,"b":"Karbala is a major city in Iraq, and the capital of Karbala Governorate. With a population of around 800,000 people in 2024, Karbala is the second-largest city in central Iraq, after Baghdad. The city is located a few miles east of Lake Milh, also known as Razzaza Lake."},{"n":"Akkadian Empire","lat":33.1,"lon":44.1,"s":91,"w":"Akkadian Empire","ty":"historical country","u":0,"b":"The Akkadian Empire or the Kingdom of Akkad/Agade was an ancient kingdom established around 2300 BCE, often seen as the first empire in world history, succeeding and unifying the long-lived city-states of the Early Dynastic period."},{"n":"Umayyad Caliphate","lat":33.3153,"lon":44.3661,"s":90,"w":"Umayyad Caliphate","ty":"historical country","u":0,"b":"The Umayyad Caliphate, or the Umayyad Empire, was the second Islamic caliphate, ruled by the Umayyad dynasty from 661 to 750. It succeeded the Rashidun Caliphate, whose third caliph, Uthman ibn Affan (r. 644–656), was also a member of the Umayyad clan."},{"n":"Najaf","lat":32.029,"lon":44.3396,"s":89,"w":"Najaf","ty":"big city|city","u":0,"b":"Najaf is the capital city of the eponymous Najaf Governorate in central Iraq, about 160 km (99 mi) south of Baghdad. Its estimated population in 2024 was about 1.41 million people. It is widely considered amongst the holiest cities of Shia Islam and one of its spiritual capitals, as well as the center of Shia political power in Iraq."},{"n":"Zagros Mountains","lat":33.6667,"lon":47.0,"s":88,"w":"Zagros Mountains","ty":"mountain range","u":0,"b":"The Zagros Mountains are a mountain range in West Asia spanning Iran, northern Iraq, and southeastern Turkey. The range has a total length of 1,600 km (990 miles). The Zagros range begins in northwestern Iran and roughly follows Iran's western border while covering much of southeastern Turkey and northeastern Iraq."},{"n":"Ilam Province","lat":33.6384,"lon":46.4226,"s":88,"w":"Ilam province","ty":"province of Iran","u":0,"b":"Ilam Province (Persian: استان ایلام) is one of the 31 provinces of Iran. Its capital is the city of Ilam. The province is in the western part of the country in Region 4 and covers 20,164.11 km2 (7,785.41 mi2)."},{"n":"Kufa","lat":32.03,"lon":44.4,"s":77,"w":"Kufa","ty":"big city|city","u":0,"b":"Kufa (Arabic: الْكُوفَة \"al-Kūfah\"), also spelled Kufah, is a city in Iraq, about 170 kilometres (110 mi) south of Baghdad, and 10 kilometres (6.2 mi) northeast of Najaf. It is located on the banks of the Euphrates River. The estimated population in 2003 was 110,000."},{"n":"Ilkhanate","lat":33.3153,"lon":44.3661,"s":76,"w":"Ilkhanate","ty":"historical country","u":0,"b":"The Ilkhanate or Il-khanate was a Mongol khanate founded in the southwestern territories of the Mongol Empire. It was ruled by the Il-Khans or Ilkhanids (Persian: ایلخانان, romanized: Īlkhānān), and was known to the Mongols as Hülegü Ulus (lit. 'people / state of Hülegü'). The Ilkhanid realm was officially known as the Land of Iran (Irānzamin) or simply Iran."},{"n":"Ctesiphon","lat":33.0936,"lon":44.5806,"s":75,"w":"Ctesiphon","ty":"archaeological site|ancient city","u":0,"b":"Ctesiphon was an ancient city in modern Iraq, on the eastern bank of the Tigris, about 35 kilometres (22 mi) (22 mi) southeast of Baghdad. Ctesiphon served as a royal capital of the Iranian empires for over eight hundred years, in the Parthian and Sasanian periods. It fell in 637, during the Muslim conquest of Persia."},{"n":"Battle of Karbala","lat":32.6153,"lon":44.0314,"s":62,"w":"Battle of Karbala","ty":"battle","u":0,"b":"The Battle of Karbala was fought on 10 October 680 (10 Muharram in the year 61 AH of the Islamic calendar) between the forces of the second Umayyad caliph Yazid I (r. 680–683), and a small army led by Husayn ibn Ali, second son of Ali and grandson of the Islamic prophet Muhammad, at Karbala, in modern-day southern Iraq. Prior to his death, the Umayyad caliph Mu'awiya I (r."},{"n":"Ramadi","lat":33.4258,"lon":43.2992,"s":61,"w":"Ramadi","ty":"city|big city","u":0,"b":"Ramadi is a city in central Iraq, about 110 kilometers (68 mi) west of Baghdad and 50 kilometers (31 mi) west of Fallujah. It is the capital and largest city of Al Anbar Governorate which shares borders with Syria, Jordan, and Saudi Arabia. The city extends along the Euphrates which bisects Al Anbar."},{"n":"Babylon Governorate","lat":32.6167,"lon":44.55,"s":59,"w":"Babylon Governorate","ty":"governorate of Iraq","u":0,"b":"Babylon Governorate or Babil Province (Arabic: محافظة بابل Muḥāfaẓa Bābil) is a governorate in central Iraq. It has an area of 5,119 square kilometres (1,976 sq mi), The population in Babil for 2023 is 1,820,700. The provincial capital is the city of Hillah, which lies opposite the ancient city of Babylon (بابل), on the Euphrates river."},{"n":"Samarra","lat":34.1959,"lon":43.8857,"s":92,"w":"Samarra","ty":"archaeological site|big city","u":1,"b":"Samarra (Arabic: سَامَرَّاء, Sāmarrāʾ) is a city in Iraq. It stands on the east bank of the Tigris in the Saladin Governorate, 125 kilometers (78 mi) north of Baghdad. Due to the presence of Al-Askari Shrine, the city is considered a holy site in Shia Islam."},{"n":"Kirkuk","lat":35.4667,"lon":44.4,"s":89,"w":"Kirkuk","ty":"city|big city","u":0,"b":"Kirkuk is a major city in northern Iraq, serving as the capital of the Kirkuk Governorate. The city is home to a diverse population of Kurds, Iraqi Turkmens and Arabs, as well as smaller numbers of Assyrians. Kirkuk sits on the ruins of the original Kirkuk Citadel which sits near the Khasa River."},{"n":"Tikrit","lat":34.6,"lon":43.6833,"s":87,"w":"Tikrit","ty":"city|big city|markaz","u":0,"b":"Tikrit (Arabic: تِكْرِيت, romanized: Tikrīt), historically romanized as Tekrit, is a city in Iraq, located 140 kilometers (87 mi) northwest of Baghdad and 220 kilometers (140 mi) southeast of Mosul on the Tigris River. It is the administrative center of the Saladin Governorate. In 2012, it had a population of approximately 160,000."},{"n":"Assur","lat":35.4567,"lon":43.2625,"s":79,"w":"Assur","ty":"ancient city|archaeological site|human settlement","u":1,"b":"Aššur, also known as Ashur and Qal'at Sherqat, was the capital of the Middle Assyrian Empire for a time, of the Neo-Assyrian Empire (911–609 BC) and a semi-independent state during the Parthian Empire between the 2nd century BC and mid 3rd century AD."},{"n":"Sulaymaniyah","lat":35.55,"lon":45.4333,"s":75,"w":"Sulaymaniyah","ty":"big city|city","u":0,"b":"Sulaymaniyah (Arabic: السليمانية, romanized: as-Sulaymāniyyah) or Slemani (Kurdish: سلێمانی, romanized: Silêmanî), is a city in the east of the Kurdistan Region of Iraq and is the capital of the Sulaymaniyah Governorate. It is surrounded by the Azmar, Goizha and Qaiwan Mountains in the northeast, Baranan Mountain in the south and the Tasluja Hills in the west."},{"n":"Saladin Governorate","lat":34.45,"lon":43.5833,"s":62,"w":"Saladin Governorate","ty":"governorate of Iraq","u":0,"b":"The Saladin, Salah ad Din, or Salah Al-Din Governorate (Arabic: محافظة صلاح الدين, Muḥāfaẓat Ṣalāḥ al-Dīn) is one of Iraq's 19 governorates, north of Baghdad. It has an area of 24,363 square kilometres (9,407 sq mi), with a population of 1,774,542 people in 2024. It is made up of 8 districts, with the capital being Tikrit."},{"n":"Hatra","lat":35.5881,"lon":42.7183,"s":62,"w":"Hatra","ty":"city-state|archaeological site|ancient city","u":1,"b":"Hatra was an ancient city in Upper Mesopotamia located in present-day eastern Nineveh Governorate in northern Iraq. The ruins of the city lie 290 km (180 mi) northwest of Baghdad and 110 km (68 mi) southwest of Mosul. It was a strongly fortified caravan city and capital of the Arab Kingdom of Hatra, located between the Roman and Parthian/Sasanian Empires."},{"n":"Neo-Assyrian Empire","lat":35.4567,"lon":43.2625,"s":61,"w":"Neo-Assyrian Empire","ty":"empire|historical period|historical country|style","u":0,"b":"The Neo-Assyrian Empire was the fourth and penultimate stage of ancient Assyrian history."},{"n":"Ilam","lat":33.6375,"lon":46.4228,"s":59,"w":"Ilam, Iran","ty":"big city|city of Iran","u":0,"b":"Ilam (Persian: ايلام;, Kurdish: ئیلام/Îlam) is a city in the Central District of Ilam County, Ilam province, Iran, serving as capital of the province, the county, and the district. The Kabir Kuh mountain range lies east of the city. To the west, it borders Iraq."},{"n":"Kish","lat":32.5403,"lon":44.6047,"s":58,"w":"Kish (Sumer)","ty":"ancient city|city-state","u":0,"b":"Kish is an important archaeological site in Babil Governorate (Iraq), located 80 km (50 mi) south of Baghdad and 12 km (7.5 mi) east of the ancient city of Babylon. The Ubaid period site of Ras al-Amiyah is 8 km (5.0 mi) away. It was occupied from the Ubaid period to the Hellenistic period."},{"n":"Hillah","lat":32.4833,"lon":44.4333,"s":58,"w":"Hillah","ty":"big city|city","u":0,"b":"Hillah (Arabic: ٱلْحِلَّة al-Ḥillah), also spelled Hilla, is a city in central Iraq. On the Hilla branch of the Euphrates River, it is 100 km (62 mi) south of Baghdad. The population was estimated to be about 455,700 in 2018."},{"n":"Fallujah","lat":33.35,"lon":43.7833,"s":58,"w":"Fallujah","ty":"city|big city","u":0,"b":"Fallujah (Arabic: ٱلْفَلُّوجَة al-Fallūjah) is a city in Al Anbar Governorate, Iraq. Situated on the Euphrates River, it is located roughly 69 kilometres (43 mi) to the west of the capital city of Baghdad and 50 kilometres (31 mi) from the neighboring city of Ramadi."},{"n":"Sulaymaniyah Governorate","lat":35.5167,"lon":45.3167,"s":57,"w":"Sulaymaniyah Governorate","ty":"governorate of Iraq","u":0,"b":"Sulaymaniyah Governorate or Sulaymaniyah Province is a governorate in the Kurdistan Region of Iraq. Its capital and largest city is Sulaymaniyah. Halabja Governorate was formerly the Halabja District of Sulaymaniyah, until it became a separate governorate in 2014."},{"n":"Kurdistan","lat":37.5585,"lon":43.5498,"s":152,"w":"Kurdistan","ty":"region|cultural region|great homeland|Kurdish-inhabited area","u":0,"b":"Kurdistan, or Greater Kurdistan, is a roughly defined geo-cultural region and stateless nation in West Asia wherein the Kurds form a prominent majority population and the Kurdish culture, languages, and national identity have historically been based. Geographically, Kurdistan roughly encompasses the northwestern Zagros and the eastern Taurus mountain ranges."},{"n":"Mosul","lat":36.3417,"lon":43.1292,"s":119,"w":"Mosul","ty":"city|big city","u":0,"b":"Mosul is a major city in northern Iraq, serving as the capital of Nineveh Governorate. It is the second largest city in Iraq overall after the capital Baghdad. Mosul is situated on the banks of Tigris and the ruins of the ancient Assyrian city of Nineveh, once the largest city in the world, are on the east side of the city."},{"n":"Assyrian Empire","lat":36.0,"lon":43.3,"s":116,"w":"Assyria","ty":"historical country","u":0,"b":"Assyria was a major ancient Mesopotamian civilization that existed from the 21st to the 7th century BCE which conquered and administered most of West Asia from the Assyrian heartland in Upper Mesopotamia."},{"n":"Erbil","lat":36.1911,"lon":44.0094,"s":104,"w":"Erbil","ty":"big city|city","u":0,"b":"Erbil, also called Hawler (Kurdish: هەولێر, romanized: Hewlêr), is the capital and most populated city in the Kurdistan Region of Iraq and the capital of the Erbil Governorate. Erbil is described as the region's cultural, economic, industrial, educational and medical hub. Erbil is one of the oldest continuously inhabited cities in the world."},{"n":"Kurdistan Region of Iraq","lat":36.1833,"lon":44.0,"s":102,"w":"Kurdistan Region","ty":"Kurdish-inhabited area|autonomous region","u":0,"b":"The Kurdistan Region (KRI) is a semi-autonomous federal region of the Republic of Iraq. It comprises four Kurdish-majority governorates of Arab-majority Iraq: Erbil Governorate, Sulaymaniyah Governorate, Duhok Governorate, and Halabja Governorate. It is located in northern Iraq, which shares borders with Iran to the east, Turkey to the north, and Syria to the west."},{"n":"Syriac","lat":37.05,"lon":41.25,"s":93,"w":"Syriac language","ty":"sacred language|natural language|historical language","u":0,"b":"The Syriac language, also known natively in its spoken form in early Syriac literature as Edessan (Urhāyā), the Mesopotamian language (Nahrāyā) and Aramaic (Aramāyā), is an Eastern Middle Aramaic dialect based on the Aramaic dialect of Edessa."},{"n":"West Azarbaijan Province","lat":37.5528,"lon":45.0759,"s":89,"w":"West Azerbaijan province","ty":"province of Iran","u":0,"b":"West Azerbaijan province (Persian: استان آذربایجان غربی) is one of the 31 provinces of Iran, whose capital and largest city is Urmia."},{"n":"Nineveh","lat":36.3594,"lon":43.1528,"s":87,"w":"Nineveh","ty":"archaeological site|tell|ancient city|type site","u":0,"b":"Nineveh was an ancient Near Eastern city of Upper Mesopotamia, located in the modern-day city of Mosul in northern Iraq. It is located on the eastern bank of the Tigris River and was the capital and largest city of the Neo-Assyrian Empire, and potentially the wealthiest city in the ancient world."},{"n":"Urmia","lat":37.5486,"lon":45.0675,"s":85,"w":"Urmia","ty":"city of Iran|big city","u":0,"b":"Urmia is the largest city in West Azerbaijan Province of Iran. In the Central District of Urmia County, it is capital of the province, the county, and the district. The city is situated near the borders of Iran with Turkey and Iraq."},{"n":"Urmia Lake","lat":37.662,"lon":45.405,"s":82,"w":"Lake Urmia","ty":"endorheic lake|hypersaline lake|biosphere reserve","u":0,"b":"Lake Urmia is an endorheic salt lake in Iran. The lake is located in the Iranian region of Azerbaijan, near the Armenian border and south of the Caspian Sea. At its greatest extent, it was the largest lake in West Asia."},{"n":"Hakkâri Province","lat":37.4661,"lon":44.0644,"s":81,"w":"Hakkâri Province","ty":"province of Turkey","u":0,"b":"Hakkâri Province, is a province in the southeast of Turkey. It borders Van Province to the north, and Şırnak Province to the west. The administrative centre is the city of Hakkâri."},{"n":"Democratic Autonomous Administration of North and East Syria","lat":37.05,"lon":41.25,"s":79,"w":"Democratic Autonomous Administration of North and East Syria","ty":"de facto regime|autonomous region|administrative territorial entity","u":0,"b":"The Democratic Autonomous Administration of North and East Syria (DAANES), also known as Rojava, was a de facto autonomous region in northeastern Syria from 2012 until its integration into the Syrian state in 2026. At various points during its existence, it consisted of the self-governing sub-regions of Afrin, Jazira, Euphrates, Raqqa, Tabqa, Manbij, and Deir ez-Zor."},{"n":"Mardin Province","lat":37.3177,"lon":40.7153,"s":79,"w":"Mardin Province","ty":"province of Turkey","u":0,"b":"Mardin Province is a province and metropolitan municipality in Turkey. Its area is 8,780 km2, and its population is 870,374 (2022). The largest city in the province is Kızıltepe, while the capital Mardin is the second largest city."},{"n":"Mardin","lat":37.3131,"lon":40.735,"s":78,"w":"Mardin","ty":"big city|metropolitan municipality in Turkey|city","u":0,"b":"Mardin is a city and seat of the Artuklu District of Mardin Province in Turkey. It is known for the Artuqid architecture of its old city, and for its strategic location on a rocky hill near the Tigris River. In February 2000, the Turkish Ministry of Culture placed Mardin and its surrounding cultural landscape on the country’s Tentative List for UNESCO World Heritage nomination."},{"n":"Şırnak Province","lat":37.5192,"lon":42.4542,"s":78,"w":"Şırnak Province","ty":"province of Turkey","u":0,"b":"Şırnak Province (Turkish: Şırnak ili, Kurdish: Parêzgeha Şirnex) is a province in Turkey in the Southeastern Anatolia Region. Şırnak Province was created in 1990, with areas that were formerly part of the Siirt, Hakkâri and Mardin Provinces. It borders both Kurdistan Region of Iraq and Syria."},{"n":"Siirt","lat":37.8417,"lon":41.9458,"s":76,"w":"Siirt","ty":"city|municipality|big city","u":0,"b":"Siirt is a city in the Siirt District of Siirt Province in Turkey. It had a population of 160,340 in 2021. The city is predominantly inhabited by Kurds."},{"n":"Hakkâri","lat":37.5744,"lon":43.7408,"s":74,"w":"Hakkâri (city)","ty":"municipality|city","u":0,"b":"Hakkâri, formerly known as Julamerk, is a city and the seat of Hakkâri District in the Hakkâri Province of Turkey. The city is populated by Kurds and had a population of 58,470 in 2023."},{"n":"Şırnak","lat":37.5164,"lon":42.4611,"s":66,"w":"Şırnak","ty":"municipality|city","u":0,"b":"Şırnak (Kurdish: Şirnex) is a city in Şırnak District and the capital of Şırnak Province in Turkey. The city is located near the Ibrahim Khalil border crossing with Iraq, which is one of the main links from Turkey to the Kurdistan Region of Iraq. The city is mainly populated by Kurds of the Şirnexî tribe and had a population of 75,932 in 2023."},{"n":"Piranshahr","lat":36.6944,"lon":45.1417,"s":66,"w":"Piranshahr","ty":"big city|city of Iran","u":0,"b":"Piranshahr (Persian: پيرانشهر, Kurdish: Pîranşar or Khane) is a city in the Central District of Piranshahr County, West Azerbaijan province, Iran, serving as capital of both the county and the district."},{"n":"Battle of Gaugamela","lat":36.36,"lon":43.25,"s":64,"w":"Battle of Gaugamela","ty":"battle","u":0,"b":"The Battle of Gaugamela, also called the Battle of Arbela (Ἄρβηλα, Árbēla), took place in 331 BC between the forces of the Army of Macedon under Alexander the Great and the Persian Army under King Darius III. It was the second and final battle between the two kings, and is considered to be the final blow to the Achaemenid Empire, resulting in its complete conquest by Alexander."},{"n":"Hasakah","lat":36.5117,"lon":40.7422,"s":62,"w":"Hasakah","ty":"populated place in Syria|big city|city","u":0,"b":"Hasakah is a city in northeastern Syria and the capital of the Hasakah Governorate. With a 2023 estimated population of 422,445, Hasakah is populated by Arabs, Kurds, Assyrians and a smaller number of Armenians and Chechens. Hasakah is 80 kilometres (50 miles) south of the city of Qamishli."},{"n":"Duhok Governorate","lat":37.05,"lon":43.15,"s":62,"w":"Duhok Governorate","ty":"governorate of Iraq","u":0,"b":"Duhok Governorate is a governorate in the semi-autonomous Kurdistan Region of Iraq. Its capital is the city of Duhok. It includes Zakho, near the Ibrahim Khalil border crossing with Şırnak Province, Turkey."},{"n":"Erbil Governorate","lat":36.1833,"lon":44.0333,"s":62,"w":"Erbil Governorate","ty":"governorate of Iraq","u":0,"b":"Erbil Governorate is a governorate of Iraq in the semi-autonomous Kurdistan Region. Its administrative centre is Erbil, which is its most important city. Erbil is also the most populated and one of the oldest continuously inhabited cities in the world, with the citadel being recognized as a UNESCO World Heritage Site."},{"n":"Nimrud","lat":36.0981,"lon":43.3289,"s":61,"w":"Nimrud","ty":"ancient city|archaeological site","u":0,"b":"Nimrud is an ancient Assyrian city (original Assyrian name Kalḫu, biblical name Calah) located in Iraq, 30 kilometres (20 mi) south of the city of Mosul, and 5 kilometres (3 mi) south of the village of Selamiyah (Arabic: السلامية), in the Nineveh Plains in Upper Mesopotamia. It was a major Assyrian city between approximately 1350 BC and 610 BC."},{"n":"Qamishli","lat":37.05,"lon":41.2167,"s":60,"w":"Qamishli","ty":"border city|city|populated place in Syria","u":0,"b":"Qamishli is a city in northeastern Syria on the Syria–Turkey border, adjoining the city of Nusaybin in Turkey. The Jaghjagh River flows through the city. With a 2004 census population of 184,231, it is the ninth most-populous city in Syria and the second-largest in Al-Hasakah Governorate after Al-Hasakah."},{"n":"Zazaki","lat":38.6,"lon":40.7,"s":122,"w":"Zaza language","ty":"modern language|macrolanguage|language","u":0,"b":"Zaza, also known by its endonym Zazaki, is an Iranic language or group of languages belonging to the Northwestern Iranian branch and spoken in various regions of Turkey by the Zaza people."},{"n":"Diyarbakır","lat":37.9158,"lon":40.2189,"s":101,"w":"Diyarbakır","ty":"big city|city|metropolitan municipality in Turkey","u":0,"b":"Diyarbakır is the largest Kurdish-majority city in Turkey. It is the administrative center of Diyarbakır Province. It is considered one of the oldest continually inhabited cities in the world, having been continually inhabited since c."},{"n":"Van","lat":38.5019,"lon":43.4167,"s":94,"w":"Van, Turkey","ty":"big city|metropolitan municipality in Turkey|city","u":0,"b":"Van is a city in eastern Turkey's Van Province, on the eastern shore of Lake Van. It is the capital and largest city of Van Province. Van has a long history as a major urban area."},{"n":"Lake Van","lat":38.6333,"lon":42.8167,"s":90,"w":"Lake Van","ty":"salt lake|tectonic lake|soda lake","u":0,"b":"Lake Van is the largest lake in Turkey. It lies in the Eastern Anatolia region of Turkey in the provinces of Van and Bitlis, in the Armenian highlands. It is a saline soda lake, receiving water from many small streams that descend from the surrounding mountains."},{"n":"Batman","lat":37.8833,"lon":41.1333,"s":89,"w":"Batman, Turkey","ty":"city|big city|municipality","u":0,"b":"Batman (Kurdish: Êlih; Syriac: Elīḥā) is a city and capital of Batman District in Batman Province, Turkey. It lies on a plateau, 540 meters (1,772 feet) above sea level, near the confluence of the Batman River and the Tigris and had a population of 452,157 in 2021. It is populated by Kurds and considered to be part of Turkish Kurdistan."},{"n":"Bingöl Province","lat":39.0411,"lon":40.6758,"s":87,"w":"Bingöl Province","ty":"province of Turkey","u":0,"b":"Bingöl Province is a province of Turkey. The province was known as Çapakçur Province (Armenian: Ճապաղջուր, lit. 'spread out water') before 1945 when it was renamed as Bingöl Province. Its area is 8,003 km2, and its population is 282,556 (2022)."},{"n":"Van Province","lat":38.5011,"lon":43.3731,"s":86,"w":"Van Province","ty":"province of Turkey","u":0,"b":"Van Province is a province and metropolitan municipality in the Eastern Anatolian region of Turkey, between Lake Van and the Iranian border. Its area is 20,921 km2, and its population is 1,128,749 (2022). Its adjacent provinces are Bitlis to the west, Siirt to the southwest, Şırnak and Hakkâri to the south, and Ağrı to the north."},{"n":"Batman Province","lat":38.0819,"lon":41.4072,"s":85,"w":"Batman Province","ty":"province of Turkey","u":0,"b":"Batman Province is a province in the Southeastern Anatolia Region of Turkey. It was created in May 1990 with Law No. 3647, incorporating districts from the eastern Siirt Province and the southern Mardin Province."},{"n":"Fertile Crescent","lat":36.0,"lon":40.0,"s":84,"w":"Fertile Crescent","ty":"region","u":0,"b":"The Fertile Crescent (Arabic: الهلال الخصيب, al-hilāl al-ḵhaṣīb) is a crescent-shaped region in the Middle East, spanning modern-day Iraq, Israel, Jordan, Lebanon, Palestine, and Syria, together with northern Kuwait, south-eastern Turkey, and western Iran. Some authors also include Cyprus and northern Egypt."},{"n":"Bitlis Province","lat":38.5258,"lon":42.3878,"s":84,"w":"Bitlis Province","ty":"province of Turkey","u":0,"b":"Bitlis Province is a province of eastern Turkey, located to the west of Lake Van. It takes its name from the central city, Bitlis. Its area is 8,294 km2, and its population is 353,988 (2022)."},{"n":"Raqqa","lat":35.95,"lon":39.01,"s":83,"w":"Raqqa","ty":"populated place in Syria|big city|city","u":0,"b":"Raqqa (Arabic: ٱلرَّقَّة, romanized: ar-Raqqah, also al-Raḳḳa) is a city in Syria on the north bank of the Euphrates River, about 160 kilometres (99 miles) east of Aleppo. It is located 40 kilometres (25 miles) east of the Euphrates Dam, Syria's largest dam."},{"n":"Elazığ","lat":38.6667,"lon":39.2167,"s":82,"w":"Elazığ","ty":"city|municipality|large city","u":0,"b":"Elazığ is a city in the Eastern Anatolia region of Turkey, and the administrative centre of Elazığ Province and Elazığ District. Founded in and around the former city of Harput, it is located in the uppermost Euphrates valley. The plain on which the city extends has an altitude of 1,067 metres (3,501 ft)."},{"n":"Diyarbakır Province","lat":38.1422,"lon":40.2711,"s":82,"w":"Diyarbakır Province","ty":"province of Turkey","u":0,"b":"Diyarbakır Province is a province and metropolitan municipality in southeastern Turkey. Its area is 15,101 km2, and its population is 1,804,880 (2022). The provincial capital is the city of Diyarbakır."},{"n":"Bingöl","lat":38.8861,"lon":40.5017,"s":81,"w":"Bingöl","ty":"municipality|city|big city","u":0,"b":"Bingöl, known as Çapakçur before 1944, is a city in Turkey. It is the seat of Bingöl Province and Bingöl District, and has a population of 133,423 (2022). The city has a Kurdish and Zaza (Kird) population."},{"n":"Aras River","lat":39.3379,"lon":41.3282,"s":81,"w":"Aras River","ty":"river","u":0,"b":"The Aras is a transboundary river in the Caucasus. It rises in eastern Turkey and flows along the borders between Turkey and Armenia, between Turkey and the Nakhchivan exclave of Azerbaijan, between Iran and both Azerbaijan and Armenia, and, finally, through Azerbaijan where it flows into the Kura river as a right tributary."},{"n":"Urartu","lat":38.5,"lon":43.3425,"s":80,"w":"Urartu","ty":"historical country|ancient civilization","u":0,"b":"Urartu was an ancient civilization and Iron Age kingdom centered on the Armenian highlands between Lake Van, Lake Urmia, and Lake Sevan. The territory of the ancient kingdom of Urartu extended over the modern frontiers of Turkey, Iran, Iraq, and Armenia. Its kings left behind cuneiform inscriptions in the Urartian language, a member of the Hurro-Urartian language family."},{"n":"Muş Province","lat":39.0006,"lon":41.8272,"s":80,"w":"Muş Province","ty":"province of Turkey","u":0,"b":"Muş Province is a province in the east Anatolia region of Turkey (Türkiye). Its area is 8,718 km2, and its population is 399,202 (2022), down from 453,654 in 2000. The provincial capital is the city of Muş."},{"n":"Muş","lat":38.7333,"lon":41.4911,"s":79,"w":"Muş","ty":"city|big city|municipality","u":0,"b":"Muş is a city in eastern Turkey and one of the principal cities of the predominantly Kurdish-inhabited region of eastern Anatolia. It is the seat of Muş Province and Muş District. Its population is 120,699 (2022)."},{"n":"Mitanni","lat":37.6496,"lon":39.8919,"s":79,"w":"Mitanni","ty":"kingdom|historical country","u":0,"b":"Mitanni or Mittani (c. 1550–1260 BC), earlier called Ḫabigalbat in old Babylonian texts, c. 1600 BC; Ḫanigalbat or Ḫani-Rabbat in Assyrian records, or Naharin in Egyptian and some Akkadian texts, was a Hurrian-speaking kingdom in northern Syria and southeast Anatolia (modern-day Turkey) with Indo-Aryan linguistic and political influences."},{"n":"Şanlıurfa Province","lat":37.2542,"lon":39.0425,"s":79,"w":"Şanlıurfa Province","ty":"province of Turkey","u":0,"b":"Şanlıurfa Province (Turkish: Şanlıurfa ili; Kurdish: Parêzgeha Rihayê), also known as Urfa Province, is a province and metropolitan municipality in southeastern Turkey. The city of Şanlıurfa is the capital of the province which bears its name. Its area is 19,242 km2, and its population is 2,170,110 (2022)."},{"n":"Elazığ Province","lat":38.6675,"lon":39.3597,"s":79,"w":"Elazığ Province","ty":"province of Turkey","u":0,"b":"Elazığ Province is a province of Turkey with its seat in the city of Elazığ. Its area is 9,383 km2, and its population is 591,497 (2022). The population of the province was 569,616 in 2000 and 498,225 in 1990."},{"n":"Tunceli Province","lat":39.2147,"lon":39.4714,"s":78,"w":"Tunceli Province","ty":"province of Turkey","u":0,"b":"Tunceli Province (Turkish: Tunceli ili), formerly Dersim Province, is a province in the Eastern Anatolia region of Turkey. Its central city is Tunceli. The province has a Kurdish majority."},{"n":"Siirt Province","lat":37.93,"lon":42.2703,"s":77,"w":"Siirt Province","ty":"province of Turkey","u":0,"b":"Siirt Province, (Turkish: Siirt ili, Kurdish: Parêzgeha Sêrtê; is a province of Turkey, located in the southeast. The province borders Bitlis to the north, Batman to the west, Mardin to the southwest, Şırnak to the south, and Van to the east. Its area is 5,717 km2, and its population is 331,311 (2022)."},{"n":"Gaziantep","lat":37.0628,"lon":37.3792,"s":120,"w":"Gaziantep","ty":"city|big city|metropolitan municipality in Turkey","u":0,"b":"Gaziantep, historically Aintab and still informally called Antep, is a major city in south-central Turkey. It is the capital of the Gaziantep Province, in the westernmost part of Turkey's Southeastern Anatolia Region and partially in the Mediterranean Region."},{"n":"Şanlıurfa","lat":37.1583,"lon":38.7917,"s":99,"w":"Urfa","ty":"metropolitan municipality in Turkey|city|big city","u":0,"b":"Urfa, officially called Şanlıurfa, is a city in southeastern Turkey and the capital of Şanlıurfa Province. Urfa is situated on a plain about 80 km (50 mi) east of the Euphrates. Its climate features extremely hot, dry summers and cool, moist winters."},{"n":"Erzurum","lat":39.9097,"lon":41.2756,"s":94,"w":"Erzurum","ty":"city|big city|metropolitan municipality in Turkey","u":0,"b":"Erzurum (Armenian: Կարին, romanized: Karin; Kurdish: Erzîrom) is a city in eastern Turkey. It is the largest city and capital of Erzurum Province and is 1,900 meters (6,233 feet) above sea level. Erzurum had a population of 367,250 in 2010."},{"n":"Sivas","lat":39.75,"lon":37.0167,"s":91,"w":"Sivas","ty":"city|large city|municipality","u":0,"b":"Sivas is a city in central Turkey. It is the seat of Sivas Province and Sivas District. Its population is 365,274 (2022)."},{"n":"Adıyaman Province","lat":37.76,"lon":38.2786,"s":91,"w":"Adıyaman Province","ty":"province of Turkey","u":0,"b":"Adıyaman Province is a province in the Southeastern Anatolia Region of Turkey. The capital is Adıyaman. Its area is 7,337 km2, and its population is 635,169 (2022)."},{"n":"2023 Turkey–Syria earthquakes","lat":37.174,"lon":37.032,"s":90,"w":"2023 Turkey–Syria earthquakes","ty":"earthquake sequence","u":0,"b":"On 6 February 2023, two earthquakes devastated southern and central Turkey and northern and western Syria. The first earthquake occurred at 04:17:35 TRT (01:17:35 UTC), measuring moment magnitude (Mw) of 7.8. The epicenter was 37 km (23 mi) west–northwest of Gaziantep."},{"n":"Kahramanmaraş","lat":37.5875,"lon":36.9453,"s":89,"w":"Kahramanmaraş","ty":"big city|metropolitan municipality in Turkey|city","u":0,"b":"Kahramanmaraş, historically Marash (Turkish: Maraş; Armenian: Մարաշ) and Germanicea (Greek: Γερμανίκεια), is a city in the Mediterranean region of Turkey and the administrative centre of Kahramanmaraş province. After 1973, Maraş was officially named Kahramanmaraş with the prefix kahraman (Turkish word meaning \"heroic\") to commemorate the Battle of Marash."},{"n":"Malatya","lat":38.3506,"lon":38.3094,"s":85,"w":"Malatya","ty":"city|metropolitan municipality in Turkey","u":0,"b":"Malatya is a metropolitan municipality and the capital of Malatya Province in the Eastern Anatolia Region of Turkey. It is a major regional center for industry, healthcare, education, and agriculture, and is the global hub for apricot production and export. The name of the city is thought to derive from the Hittite word melid or milit, meaning \"honey\"."},{"n":"Adıyaman","lat":37.7634,"lon":38.2771,"s":84,"w":"Adıyaman","ty":"big city|city|municipality","u":0,"b":"Adıyaman (Kurdish: Semsûr) is a city in southeastern Turkey. It is the administrative centre of Adıyaman Province and Adıyaman District. Its population is 290,883 (2024)."},{"n":"Bayburt Province","lat":40.2367,"lon":40.2236,"s":83,"w":"Bayburt Province","ty":"province of Turkey","u":0,"b":"Bayburt Province (Turkish: Bayburt ili) is a province of Turkey. Located in the Northeast Anatolia region of the country, the capital city is Bayburt. Its area is 3,746 km2, and its population is 84,241 (2022), making it the least-populous province in Turkey."},{"n":"Tokat","lat":40.3097,"lon":36.5542,"s":83,"w":"Tokat","ty":"municipality|big city|city","u":0,"b":"Tokat is a city of Turkey in the mid-Black Sea region of Anatolia. It is the seat of Tokat Province and Tokat District. Its population is 163,405 (2022)."},{"n":"Erzincan","lat":39.7464,"lon":39.4914,"s":82,"w":"Erzincan","ty":"big city|municipality|city","u":0,"b":"Erzincan, historically Yerznka (Armenian: Երզնկա), is the capital of Erzincan Province in eastern Turkey. Nearby cities include Erzurum, Sivas, Tunceli, Bingöl, Elazığ, Malatya, Gümüşhane, Bayburt, and Giresun. The city is majority Turkish Sunni with a Kurdish Alevi minority."},{"n":"Giresun Province","lat":40.5797,"lon":38.5944,"s":82,"w":"Giresun Province","ty":"province of Turkey","u":0,"b":"Giresun Province (Turkish: Giresun ili) is a province of Turkey on the Black Sea coast. Its adjacent provinces are Trabzon to the east, Gümüşhane to the southeast, Erzincan to the south, Sivas to the southwest, and Ordu to the west. Its area is 6,972 km2, and its population is 450,862 (2022)."},{"n":"Gaziantep Province","lat":37.0833,"lon":37.3333,"s":80,"w":"Gaziantep Province","ty":"province of Turkey","u":0,"b":"Gaziantep Province (Turkish: Gaziantep ili) is a province and metropolitan municipality in south-central Turkey. It is located in the westernmost part of Turkey's Southeastern Anatolia Region and partially in the Mediterranean Region. Its area is 6,803 km2, and its population is 2,154,051 (2022)."},{"n":"Erzincan Province","lat":39.6783,"lon":39.33,"s":80,"w":"Erzincan Province","ty":"province of Turkey","u":0,"b":"Erzincan Province (Turkish: Erzincan ili); is a province in the Eastern Anatolia region of Turkey. In Turkey, its capital is also called Erzincan. Its area is 11,815 km2, and its population is 239,223 (2022)."},{"n":"Tokat Province","lat":40.3528,"lon":36.5644,"s":80,"w":"Tokat Province","ty":"province of Turkey","u":0,"b":"Tokat Province (Turkish: Tokat ili) is a province in northern Turkey. Its area is 10,042 km2, and its population is 596,454 (2022). Its adjacent provinces are Amasya to the northwest, Yozgat to the southwest, Sivas to the southeast, and Ordu to the northeast."},{"n":"Kahramanmaraş Province","lat":37.8983,"lon":36.9711,"s":80,"w":"Kahramanmaraş Province","ty":"province of Turkey","u":0,"b":"Kahramanmaraş Province (Turkish: Kahramanmaraş ili) is a province and metropolitan municipality of Turkey. Its area is 14,520 km2, and its population is 1,177,436 (2022). Its provincial capital is the city of Kahramanmaraş, and the traffic code is 46."},{"n":"Malatya Province","lat":38.3481,"lon":38.3178,"s":80,"w":"Malatya Province","ty":"province of Turkey","u":0,"b":"Malatya Province (Turkish: Malatya ili) is a province and metropolitan municipality of Turkey. Its area is 12,259 km2, and its population is 812,580 (2022). It is part of a larger mountainous area."},{"n":"Gümüşhane Province","lat":40.3881,"lon":39.4186,"s":79,"w":"Gümüşhane Province","ty":"province of Turkey","u":0,"b":"Gümüşhane Province (Turkish: Gümüşhane ili) is a province in northern Turkey, bordering Bayburt to the east, Trabzon to the north, Giresun and Erzincan to the west. Its area is 6,668 km2, and its population is 144,544 (2022). The population was 186,953 in 2000."},{"n":"Anatolia","lat":39.0,"lon":35.0,"s":146,"w":"Anatolia","ty":"peninsula","u":0,"b":"Anatolia (Greek: Ανατολή, Turkish: Anadolu), also known as Asia Minor, is a peninsula in West Asia that makes up the majority of the land area of Turkey."},{"n":"Kayseri","lat":38.7225,"lon":35.4875,"s":117,"w":"Kayseri","ty":"big city|metropolitan municipality in Turkey|city","u":0,"b":"Kayseri is a large city in Central Anatolia, Turkey, and the capital of Kayseri province. Historically known as Caesarea, it has been the historical capital of Cappadocia since ancient times. The Kayseri Metropolitan Municipality area is composed of five districts: the two central districts of Kocasinan and Melikgazi, and since 2004, also outlying Hacılar, İncesu, and Talas."},{"n":"Cappadocia","lat":38.6706,"lon":34.8392,"s":106,"w":"Cappadocia","ty":"historical region|region","u":0,"b":"Cappadocia is a historical region in Central Anatolia region, Turkey. It is largely in the provinces of Nevşehir, Kayseri, Aksaray, Kırşehir, Sivas and Niğde. Today, the touristic Cappadocia Region is located in Nevşehir province."},{"n":"Adana Province","lat":37.3683,"lon":35.7061,"s":95,"w":"Adana Province","ty":"province of Turkey","u":0,"b":"Adana Province (Turkish: Adana ili) is a province and metropolitan municipality of Turkey located in central Cilicia. The administrative seat of the province is the city of Adana, home to 78.25% of the residents of the province. Its area is 13,844 km2, and its population is 2,274,106 (2022)."},{"n":"Amasya","lat":40.65,"lon":35.8333,"s":95,"w":"Amasya","ty":"municipality|city|big city","u":0,"b":"Amasya is a city in northern Turkey, in the Black Sea Region. It was called Amaseia or Amasia in antiquity. It is the seat of Amasya Province and Amasya District."},{"n":"Samsun","lat":41.2867,"lon":36.33,"s":92,"w":"Samsun","ty":"city|big city|metropolitan municipality in Turkey","u":0,"b":"Samsun is a city on the north coast of Turkey and a major Black Sea port. The urban area recorded a population of 738,692 in 2022. The city is the capital of Samsun Province which has a population of 1,382,376."},{"n":"Amasya Province","lat":40.6503,"lon":35.8328,"s":90,"w":"Amasya Province","ty":"province of Turkey","u":0,"b":"Amasya Province (Turkish: Amasya ili) is a province of Turkey, situated on the Yeşil River in the Black Sea Region to the north of the country. Its area is 5,628 km2, and its population is 338,267 (2022). The provincial capital is Amasya, the antique Amaseia mentioned in documents from the era of Alexander the Great and the birthplace of the geographer and historian Strabo."},{"n":"Trabzon Province","lat":40.7806,"lon":39.8122,"s":83,"w":"Trabzon Province","ty":"province of Turkey","u":0,"b":"Trabzon Province (Turkish: Trabzon ili) is a province and metropolitan municipality of Turkey on the Black Sea coast. Its area is 4,628 km2, and its population is 818,023 (2022). Located in a strategically important region, Trabzon is one of the oldest trade port cities in Anatolia."},{"n":"Samsun Province","lat":41.2044,"lon":36.0072,"s":82,"w":"Samsun Province","ty":"province of Turkey","u":0,"b":"Samsun Province (Turkish: Samsun ili) is a province and metropolitan municipality of Turkey on the Black Sea coast. Its area is 9,725 km2, and its population is 1,368,488 (2022). Its adjacent provinces are Sinop on the northwest, Çorum on the west, Amasya on the south, Tokat on the southeast on the east."},{"n":"Çorum Province","lat":40.5522,"lon":34.9539,"s":81,"w":"Çorum Province","ty":"province of Turkey","u":0,"b":"Çorum Province (Turkish: Çorum İli) is a province in the Black Sea Region of Turkey, but lying inland and having more characteristics of Central Anatolia than the Black Sea coast. Its area is 12,428 km2, and its population is 524,130 (2022). Its provincial capital is the city of Çorum, the traffic code is 19."},{"n":"Yozgat Province","lat":39.6694,"lon":35.2692,"s":80,"w":"Yozgat Province","ty":"province of Turkey","u":0,"b":"Yozgat Province (Turkish: Yozgat ili) is a province in central Turkey. Its area is 13,690 km2, and its population is 418,442 (2022). Its adjacent provinces are Çorum to the northwest, Kırıkkale to the west, Kırşehir to the southwest, Nevşehir to the south, Kayseri to the southeast, Sivas to the east, Tokat to the northeast, and Amasya to the north."},{"n":"Çorum","lat":40.5489,"lon":34.9533,"s":80,"w":"Çorum","ty":"municipality|city|large city","u":0,"b":"Çorum is a northern Anatolian city in Turkey. Çorum is located inland in the central Black Sea Region of Turkey and is approximately 244 km (152 mi) from Ankara and 608 km (378 mi) from Istanbul. It is the seat of Çorum Province and of Çorum District."},{"n":"Aksaray","lat":38.3686,"lon":34.0297,"s":80,"w":"Aksaray","ty":"city|municipality","u":0,"b":"Aksaray is a city in the Central Anatolia region of Turkey. It is the seat of Aksaray Province and Aksaray District. Its population is 247,147 (2021)."},{"n":"Ordu Province","lat":40.8114,"lon":37.5406,"s":80,"w":"Ordu Province","ty":"province of Turkey","u":0,"b":"Ordu Province (Turkish: Ordu ili) is a province and metropolitan municipality of Turkey, located on the Black Sea coast. Its area is 5,914 km2, and its population is 763,190 (2022). Its adjacent provinces are Samsun to the northwest, Tokat to the southwest, Sivas to the south, and Giresun to the east."},{"n":"Sivas Province","lat":39.7503,"lon":37.0161,"s":79,"w":"Sivas Province","ty":"province of Turkey","u":0,"b":"Sivas Province (Turkish: Sivas ili) is a province of Turkey. It is located in the eastern part of the Central Anatolia region of Turkey. Its area is 28,164 km2 (the second largest province after Konya), and its population is 634,924 (2022)."},{"n":"Osmaniye Province","lat":37.2281,"lon":36.2125,"s":78,"w":"Osmaniye Province","ty":"province of Turkey","u":0,"b":"Osmaniye Province (Turkish: Osmaniye ili) is a province in south-central Turkey. It was named Cebel-i Bereket (lit. 'Fertile Mountain') in the early republic until 1933, when it was incorporated into Adana Province. It was made a province again in 1996."},{"n":"Ankara","lat":39.9358,"lon":32.8387,"s":241,"w":"Ankara","ty":"city|metropolitan municipality in Turkey","u":0,"b":"Ankara is the capital city of Turkey. Located in the central part of Anatolia, the city has a population of over 5.3 million residents in its urban center, out of 6 million residents in Ankara Province. Ankara is Turkey's second-largest city by population after Istanbul."},{"n":"Bolu Province","lat":40.6792,"lon":31.5583,"s":89,"w":"Bolu Province","ty":"province of Turkey","u":0,"b":"Bolu Province (Turkish: Bolu ili) is a province in north-western Turkey, between the capital, Ankara, and the largest city in the country, Istanbul. Its area is 8,313 square kilometres (3,210 sq mi), and its population is 320,824 (2022). The capital city of the province is Bolu."},{"n":"Ankara Province","lat":39.9264,"lon":32.8561,"s":88,"w":"Ankara Province","ty":"province of Turkey","u":0,"b":"Ankara Province is a province and metropolitan municipality of Turkey with the capital city Ankara. Its area is 25,632 km2, and its population is 5,782,285 (2022)."},{"n":"Sinop","lat":42.0267,"lon":35.1511,"s":87,"w":"Sinop, Turkey","ty":"city|municipality|big city","u":0,"b":"Sinop is a city on the isthmus of İnce Burun (İnceburun, Cape Ince) and on the Boztepe Peninsula, near Cape Sinope (Sinop Burnu, Boztepe Cape, Boztepe Burnu) which is situated on the northernmost edge of the Turkish side of the Black Sea coast, in the ancient region of Paphlagonia, in modern-day northern Turkey. It is the seat of Sinop Province and Sinop District."},{"n":"Aksaray Province","lat":38.4308,"lon":33.8622,"s":83,"w":"Aksaray Province","ty":"province of Turkey","u":0,"b":"Aksaray Province (Turkish: Aksaray ili) is a province in central Turkey. Its adjacent provinces are Konya along the west and south, Ankara to the northwest, Niğde to the southeast, Nevşehir to the east, and Kırşehir to the north. Its area is 7,659 km2, and its population is 439.474 (2022)."},{"n":"Bartın Province","lat":41.6044,"lon":32.5111,"s":82,"w":"Bartın Province","ty":"province of Turkey","u":0,"b":"Bartın Province (Turkish: Bartın ili) is a small province in northern Turkey on the Black Sea, surrounding the city of Bartın. Its area is 2,330 km2, and its population is 203,351 (2022). It lies to the east of Zonguldak Province."},{"n":"Kastamonu Province","lat":41.5194,"lon":33.6897,"s":78,"w":"Kastamonu Province","ty":"province of Turkey","u":0,"b":"Kastamonu Province (Turkish: Kastamonu ili) is a province of Turkey, in the Black Sea region in the north of the country. It is surrounded by Sinop to the east, Bartın, Karabük to the west, Çankırı to the south, Çorum to the southeast and the Black Sea to the north. Its area is 13,064 km2, and its population is 378,115 (2022)."},{"n":"Zonguldak Province","lat":41.3206,"lon":31.7336,"s":78,"w":"Zonguldak Province","ty":"administrative territorial entity type of Turkey|province of Turkey","u":0,"b":"Zonguldak Province (Turkish: Zonguldak ili) is a province along the western Black Sea coast region of Turkey. Its area is 3,342 km2, and its population is 588,510 (2022). Its adjacent provinces are Düzce to the southwest, Bolu to the south, Karabük to the southeast, and Bartın to the east."},{"n":"Çankırı Province","lat":40.7356,"lon":33.3661,"s":78,"w":"Çankırı Province","ty":"province of Turkey","u":0,"b":"Çankırı Province (Turkish: Çankırı ili) is a province of Turkey, which lies close to the capital, Ankara. The provincial capital is Çankırı. Its area is 7,542 km2, and its population is 195,766 (2022)."},{"n":"Karabük Province","lat":41.2236,"lon":32.6403,"s":77,"w":"Karabük Province","ty":"province of Turkey","u":0,"b":"Karabük Province (Turkish: Karabük ili) is a landlocked province in the northern part of Anatolia (northern central Turkey), located about 200 km (124 mi) north of Ankara, 115 km (71 mi) away from Zonguldak and 113 km (70 mi) away from Kastamonu. Its area is 4,142 km2, and its population is 252,058 (2022)."},{"n":"Nevşehir Province","lat":38.7817,"lon":34.6881,"s":77,"w":"Nevşehir Province","ty":"province of Turkey","u":0,"b":"Nevşehir Province (Turkish: Nevşehir ili) is a province in central Turkey with its capital in Nevşehir. Its area is 5,485 km2, and its population is 317,952 (2024). Its adjacent provinces are Kırşehir to the northwest, Aksaray to the southwest, Niğde to the south, Kayseri to the southeast, and Yozgat to the northeast."},{"n":"Kayseri Province","lat":38.737,"lon":35.4968,"s":77,"w":"Kayseri Province","ty":"province of Turkey","u":0,"b":"Kayseri Province (Turkish: Kayseri ili) is a province and metropolitan municipality in central Turkey. Its area is 16,970 km2, and its population is 1,441,523 (2022). It borders with Sivas, Adana, Niğde, Kahramanmaraş, Yozgat and Nevşehir provinces."},{"n":"Kırıkkale Province","lat":39.8697,"lon":33.7161,"s":76,"w":"Kırıkkale Province","ty":"province of Turkey","u":0,"b":"Kırıkkale Province (Turkish: Kırıkkale ili) is a province of Turkey. It is located on the crossroads of major highways east of Ankara leading east to the Black Sea region. Its area is 4,791 km2, and its population is 277,046 (2022)."},{"n":"Bolu","lat":40.7333,"lon":31.6,"s":76,"w":"Bolu","ty":"municipality|big city|city","u":0,"b":"Bolu is a city in northern Turkey, and administrative center of the Bolu Province and of Bolu District, located on the highway between Istanbul and Ankara. Its population as of 2021 was 184,682. The city has been governed by mayor Tanju Özcan (CHP) since local elections in 2019."},{"n":"Niğde Province","lat":37.9158,"lon":34.6936,"s":75,"w":"Niğde Province","ty":"province of Turkey","u":0,"b":"Niğde Province (Turkish: Niğde ili) is a province in the southern part of Central Anatolia, Turkey. Its area is 7,234 km2, and its population is 365,419 (2022) of which 170,511 live in the city of Niğde. The population was 348,081 in 2000 and 305,861 in 1990."},{"n":"Sinop Province","lat":41.6092,"lon":34.9019,"s":74,"w":"Sinop Province","ty":"province of Turkey","u":0,"b":"Sinop Province (Turkish: Sinop ili) is a province of Turkey, along the Black Sea. It is located between 41 and 42 degrees North latitude and between 34 and 35 degrees East longitude. Its area is 5,717 km2, equivalent to 0.73% of Turkey's total area, and its population is 220,799 (2022)."},{"n":"Kırşehir Province","lat":39.3239,"lon":34.1292,"s":74,"w":"Kırşehir Province","ty":"province of Turkey","u":0,"b":"Kırşehir Province (Turkish: Kırşehir ili) is a province in central Turkey, forming part of the Central Anatolia Region. Its area is 6,584 km2, and its population is 244,519 (2022). The average elevation is approximately 985 meters above sea level."},{"n":"Zonguldak","lat":41.45,"lon":31.7833,"s":73,"w":"Zonguldak","ty":"city|municipality|big city","u":0,"b":"Zonguldak is a city of about 100,000 people in the Black Sea region of Turkey. It is the seat of Zonguldak Province and Zonguldak District. It was established in 1849 as a port town for the nearby coal mines in Ereğli."},{"n":"Nevşehir","lat":38.625,"lon":34.7122,"s":73,"w":"Nevşehir","ty":"big city|city|municipality","u":0,"b":"Nevşehir is a city in the Central Anatolia Region of Turkey. It is the seat of Nevşehir Province and Nevşehir District. Its population is 128,290 (2024)."},{"n":"Kırşehir","lat":39.145,"lon":34.1608,"s":72,"w":"Kırşehir","ty":"municipality|city|big city","u":0,"b":"Kırşehir is a city in Turkey. It is the seat of Kırşehir Province and Kırşehir District. Its population is 162,989 (2023)."},{"n":"Hattusa","lat":40.0197,"lon":34.6153,"s":71,"w":"Hattusa","ty":"archaeological site","u":1,"b":"Hattusa, also Hattuşa, Ḫattuša, Hattusas, or Hattusha, was the capital of the Hittite Empire in the late Bronze Age during two distinct periods. Its ruins lie near to modern Boğazkale, Turkey (originally Boğazköy), within the great loop of the Kızılırmak River (Hittite: Marashantiya; Greek: Halys)."},{"n":"Kastamonu","lat":41.3833,"lon":33.7833,"s":70,"w":"Kastamonu","ty":"big city|city|municipality","u":0,"b":"Kastamonu is a city in northern Turkey. It is the seat of Kastamonu Province and Kastamonu District. Its population is 125,622 (2021)."},{"n":"Kızılırmak River","lat":41.7342,"lon":35.9564,"s":70,"w":"Kızılırmak River","ty":"river","u":0,"b":"The Kızılırmak, historically known as the Halys River (Ancient Greek: Ἅλυς), is the longest river flowing entirely within Turkey. It is a source of hydroelectric power and is not used for navigation."},{"n":"Istanbul","lat":41.01,"lon":28.9603,"s":290,"w":"Istanbul","ty":"largest city|metropolitan municipality in Turkey|megacity|port city|former capital|big cit","u":0,"b":"Istanbul is the largest city in Turkey, a megacity, constituting the country's economic, cultural, and historical center. With a population of over 15 million, it is home to 18% of the population of Turkey. Istanbul is among the largest cities in Europe and in the world by population."},{"n":"Turkish","lat":40.0,"lon":30.0,"s":249,"w":"Turkish language","ty":"natural language|modern language","u":0,"b":"Turkish is the most widely spoken of the Turkic languages, with around 90 million speakers. It is the national language of Turkey and one of two official languages of Cyprus. Significant smaller groups of Turkish speakers also exist in Germany, Austria, Bulgaria, North Macedonia, Greece, other parts of Europe, the South Caucasus, and some parts of Central Asia, Iraq, and Syria."},{"n":"Ottoman Empire","lat":41.0,"lon":29.0,"s":211,"w":"Ottoman Empire","ty":"historical country|sultanate|empire","u":0,"b":"The Ottoman Empire, also known historically as Turkey or the Turkish Empire, was a state that spanned much of Southeastern Europe, West Asia, and North Africa from the 14th century to the early 20th century, centred in modern-day Turkey. It also controlled parts of southeastern Central Europe between the early 16th and early 18th centuries."},{"n":"Byzantine Empire","lat":41.0125,"lon":28.98,"s":191,"w":"Byzantine Empire","ty":"historical country|historical period","u":0,"b":"The Byzantine Empire, also known as the Eastern Roman Empire, was the continuation of the Eastern part of the Roman Empire centred on Constantinople during late antiquity and the Middle Ages. Having survived the fall of the Western Roman Empire in the 5th century AD, it endured until the fall of Constantinople to the Ottoman Empire in 1453."},{"n":"Hagia Sophia","lat":41.0083,"lon":28.98,"s":152,"w":"Hagia Sophia","ty":"museum|mosque","u":1,"b":"Hagia Sophia, officially the Hagia Sophia Grand Mosque, is a mosque and a major cultural and historical site in Istanbul, Turkey. It was formerly a church (360–1453) and a museum (1935–2020)."},{"n":"Bursa","lat":40.1913,"lon":29.0805,"s":137,"w":"Bursa","ty":"metropolitan municipality in Turkey|big city|metropolitan municipality|city","u":0,"b":"Bursa is a city in northwestern Turkey and the administrative center of Bursa Province. It is the fourth-most populous city in Turkey and second-most populous in the Marmara Region after Istanbul. According to 2025 end of year estimate, the province has a population of 3,263,011 while Bursa city has a population of around 2.5 million."},{"n":"Bosporus Strait","lat":41.12,"lon":29.08,"s":131,"w":"Bosporus","ty":"strait","u":0,"b":"The Bosporus or Bosphorus Strait is a natural strait and an internationally significant waterway located in Turkey which is straddled by the city of Istanbul. The Bosporus connects the Black Sea to the Sea of Marmara and forms one of the continental boundaries between Asia and Europe. It also divides Turkey by separating Asia Minor from Thrace."},{"n":"Constantinople","lat":41.0122,"lon":28.976,"s":128,"w":"Constantinople","ty":"city|administrative territorial entity|ancient city","u":0,"b":"Constantinople, the modern Istanbul, was the capital of the Roman Empire and Byzantine Empire from 330 until its takeover by the Ottoman Empire in 1453. After this, it continued to function as the Ottoman capital until the abolition of the Ottoman sultanate in 1922."},{"n":"Bursa Province","lat":40.15,"lon":29.0208,"s":95,"w":"Bursa Province","ty":"province of Turkey","u":0,"b":"Bursa Province (Turkish: Bursa ili) is a province and metropolitan municipality in Turkey along the Sea of Marmara coast in northwestern Anatolia. It borders Balıkesir to the west, Kütahya to the south, Bilecik and Sakarya to the east, Kocaeli to the northeast and Yalova to the north. Its area is 10,813 km2, and its population is 3,194,720 (2022)."},{"n":"Eskişehir","lat":39.7767,"lon":30.5206,"s":95,"w":"Eskişehir","ty":"college town|metropolitan municipality|city|metropolitan municipality in Turkey|big city","u":0,"b":"Eskişehir is a city in northwestern Turkey and the capital of the Eskişehir Province. The urban population of the city is 821,315 (Odunpazarı + Tepebaşı), with a metropolitan population of 921,630. The city is located on the banks of the Porsuk River, 792 m above sea level, where it overlooks the fertile Phrygian Valley."},{"n":"İzmit","lat":40.7719,"lon":29.9498,"s":89,"w":"İzmit","ty":"district|town|city","u":0,"b":"İzmit is a municipality and the capital district of Kocaeli Province, Turkey. Its area is 480 km2, and its population is 376,056 (2022). The capital of Kocaeli Province, it is located at the Gulf of İzmit in the Sea of Marmara, about 100 km (62 mi) east of Istanbul, on the northwestern part of Anatolia."},{"n":"Sultan Ahmed Mosque","lat":41.0054,"lon":28.9768,"s":89,"w":"Blue Mosque, Istanbul","ty":"mosque|historic building","u":0,"b":"The Sultan Ahmed Mosque (Turkish: Sultanahmet Camii), popularly known as the Blue Mosque, is an Ottoman-era historical imperial mosque located in Istanbul, Turkey. It was constructed between 1609 and 1617 during the rule of Ahmed I. It attracts a large number of tourists and is one of the most iconic and popular monuments of Ottoman architecture."},{"n":"Bilecik Province","lat":40.0,"lon":30.1667,"s":87,"w":"Bilecik Province","ty":"province of Turkey","u":0,"b":"Bilecik Province (Turkish: Bilecik ili) is a province in midwest Turkey, neighboring Bursa to the west, Kocaeli and Sakarya to the north, Bolu to the east, Eskişehir to the southeast and Kütahya to the south. Its area is 4,179 km2, and its population is 228,673 (2022)."},{"n":"Istanbul Province","lat":41.0122,"lon":28.9761,"s":87,"w":"Istanbul Province","ty":"province of Turkey","u":0,"b":"Istanbul is the largest city in Turkey, a megacity, constituting the country's economic, cultural, and historical center. With a population of over 15 million, it is home to 18% of the population of Turkey. Istanbul is among the largest cities in Europe and in the world by population."},{"n":"Kütahya","lat":39.4242,"lon":29.9833,"s":86,"w":"Kütahya","ty":"municipality|city|large city","u":0,"b":"Kütahya is a city in western Turkey which lies on the Porsuk River, at 969 metres above sea level. It is the seat of Kütahya Province and Kütahya District. Its population is 263,863 (2022)."},{"n":"Kocaeli Province","lat":40.7644,"lon":29.945,"s":86,"w":"Kocaeli Province","ty":"metropolitan municipality in Turkey|province of Turkey","u":0,"b":"Kocaeli Province is a province and metropolitan municipality of Turkey and one of only three not to have the same official name as its capital, İzmit, which is thus also sometimes called Kocaeli. Its area is 3,397 km2 (1,312 sq mi), and its population is 2,102,907 (2023). The province is the successor of the Ottoman-era Sanjak of Kocaeli."},{"n":"Sakarya Province","lat":40.6972,"lon":30.4567,"s":85,"w":"Sakarya Province","ty":"province of Turkey","u":0,"b":"Sakarya (Turkish: Sakarya ili) is a province and metropolitan municipality in Turkey, located on the coast of the Black Sea. Its area is 4,824 km2 (1,863 sq mi), and its population is 1,110,735 (2024). The Sakarya River creates a webbing of estuaries in the province, which is in the Marmara Region."},{"n":"Lydia","lat":40.0,"lon":30.0,"s":85,"w":"Lydia","ty":"realm|historical country|cultural region|historical region","u":0,"b":"Lydia (Ancient Greek: Λυδία, romanized: Ludía; Latin: Lȳdia) was a powerful Iron Age civilization prominent in western Anatolia in the 8th to 6th centuries BCE. Its capital and only city at Sardis. They are known in part for the world's first coinage, and rapid expansion based on their immense wealth in gold."},{"n":"First Council of Nicaea","lat":40.43,"lon":29.72,"s":85,"w":"First Council of Nicaea","ty":"ecumenical council","u":0,"b":"The First Council of Nicaea was a council of Christian bishops convened in the Bithynian city of Nicaea (now İznik, Turkey) by the Roman Emperor Constantine I, also known as the First Ecumenical Council. It met from May until the end of July 325."},{"n":"Kütahya Province","lat":39.3047,"lon":29.59,"s":82,"w":"Kütahya Province","ty":"province of Turkey","u":0,"b":"Kütahya Province (Turkish: Kütahya ili) is a province in the Aegean region of Turkey. Its area is 11,634 km2, and its population is 580,701 (2022). In 1990, Kütahya had a population of 578,000."},{"n":"Adapazarı","lat":40.7762,"lon":30.4026,"s":82,"w":"Adapazarı","ty":"district of Turkey|big city","u":0,"b":"Adapazarı is a municipality and the capital district of Sakarya Province, Turkey. Its area is 324 km2, and its population 281,489 (2022). It covers the central and northern part of the agglomeration of Adapazarı and the adjacent countryside."},{"n":"Yalova Province","lat":40.6442,"lon":29.1936,"s":81,"w":"Yalova Province","ty":"province of Turkey","u":0,"b":"Yalova Province (Turkish: Yalova ili) is a province in northwestern Turkey, on the eastern coast of the Sea of Marmara. Its adjacent provinces are Bursa to the south and Kocaeli to the east. Its area is 798 km2 (making it the smallest province of Turkey), and its population is 296,333 (2022)."},{"n":"Fall of Constantinople","lat":41.03,"lon":28.935,"s":80,"w":"Fall of Constantinople","ty":"battle|siege|conquest","u":0,"b":"Constantinople, the capital city of the Byzantine Empire, was captured by the Ottoman Empire on 29 May 1453 as part of the culmination of a 53-day siege which had begun on 6 April."},{"n":"Düzce Province","lat":40.9469,"lon":31.2381,"s":80,"w":"Düzce Province","ty":"province of Turkey","u":0,"b":"Düzce Province (Turkish: Düzce ili) is a province in northwestern Turkey. The province is on the coastline of the Black Sea and is traversed by the main highway between Istanbul and Ankara. The primary town is Düzce, located in the center of the province."},{"n":"Topkapı Palace","lat":41.013,"lon":28.984,"s":79,"w":"Topkapı Palace","ty":"palace|building or structure under construction|museum","u":0,"b":"The Topkapı Palace or the Seraglio, is a large museum and library in the east of the Fatih district of Istanbul in Turkey. From the 1460s to the completion of Dolmabahçe Palace in 1853, it served as the administrative center of the Ottoman Empire, and was the main residence of its sultans."},{"n":"Byzantium","lat":41.0134,"lon":28.9836,"s":78,"w":"Byzantium","ty":"polis|ancient city","u":0,"b":"Byzantium or Byzantion (Ancient Greek: Βυζάντιον) was an ancient Greek city in classical antiquity that became known as Constantinople in late antiquity and Istanbul in modern times."},{"n":"Eskişehir Province","lat":39.6825,"lon":31.0725,"s":77,"w":"Eskişehir Province","ty":"province of Turkey","u":0,"b":"Eskişehir Province (Turkish: Eskişehir ili) is a province and metropolitan municipality in northwestern Turkey. Its area is 13,960 km2, and its population is 906,617 (2022). Its adjacent provinces are Bilecik to the northwest, Kütahya to the west, Afyon to the southwest, Konya to the south, Ankara to the east, and Bolu to the north."},{"n":"Phrygia","lat":39.0,"lon":31.0,"s":77,"w":"Phrygia","ty":"historical region|area|kingdom","u":0,"b":"In classical antiquity, Phrygia was a civilization and kingdom in the west-central part of Anatolia, in what is now Asian Turkey, centered on the Sangarios River."},{"n":"Edirne","lat":41.673,"lon":26.5736,"s":284,"w":"Edirne","ty":"city|municipality|big city","u":0,"b":"Edirne, historically known as Orestias, Orestiada, Adrianople, or Adriana, is a city in Turkey, in the northwestern part of the province of Edirne in Eastern Thrace. Situated 7 km (4.3 mi) from the Greek and 20 km (12 mi) from the Bulgarian borders, Edirne was the second capital city of the Ottoman Empire from the 1360s to 1453, before Constantinople became its capital."},{"n":"Sea of Marmara","lat":40.75,"lon":28.0,"s":126,"w":"Sea of Marmara","ty":"adjacent sea","u":0,"b":"The Sea of Marmara, also known as the Sea of Marmora, the Marmara Sea, or Propontis, is a small inland sea entirely within the borders of Turkey. It links the Black Sea and the Aegean Sea via the Bosporus and Dardanelles straits, separating Turkey's European and Asian sides."},{"n":"Varna","lat":43.2114,"lon":27.9111,"s":121,"w":"Varna, Bulgaria","ty":"municipality seat|large city|city in Bulgaria|oblast seat","u":0,"b":"Varna is the third-largest city in Bulgaria and the largest city and seaside resort on the Bulgarian Black Sea Coast and in the Northern Bulgaria region. Situated strategically in the Gulf of Varna, the city has been a major economic, social, and cultural centre for almost three millennia."},{"n":"Troy","lat":39.9575,"lon":26.2389,"s":121,"w":"Troy","ty":"polis|Bronze Age settlement|city-state|settlement site","u":1,"b":"Troy or Ilion was an ancient city located in present-day Çanakkale, Turkey. It is best known as the setting for the Greek myth of the Trojan War. The modern-day archaeological site, also known as Hisarlık, is open to the public as a tourist destination, and was added to the UNESCO World Heritage list in 1998."},{"n":"Dardanelles","lat":40.2,"lon":26.4,"s":108,"w":"Dardanelles","ty":"strait","u":0,"b":"The Dardanelles, also known as the Strait of Gallipoli (after the Gallipoli peninsula), is a narrow, natural strait and internationally significant waterway in northwestern Turkey that forms part of the continental boundary between Asia and Europe and separates Asian Turkey from European Turkey. Together with the Bosporus, the Dardanelles forms the Turkish Straits."},{"n":"Burgas","lat":42.503,"lon":27.4702,"s":106,"w":"Burgas","ty":"municipality seat|oblast seat|big city|city in Bulgaria","u":0,"b":"Burgas, sometimes transliterated as Bourgas, is the second largest city on the Bulgarian Black Sea Coast in the region of Northern Thrace and the fourth-largest city in Bulgaria after Sofia, Plovdiv, and Varna, with a population of 210,382 inhabitants, while 225,945 live in its urban area."},{"n":"Çanakkale","lat":40.15,"lon":26.4,"s":92,"w":"Çanakkale","ty":"municipality|city|big city","u":0,"b":"Çanakkale, formerly known in English as Dardanelles, is a city and seaport in Turkey on the southern shore of the Dardanelles at their narrowest point. It is the seat of Çanakkale Province and Çanakkale District. Its population is 143,622 (2021)."},{"n":"Balıkesir Province","lat":39.7408,"lon":27.8192,"s":92,"w":"Balıkesir Province","ty":"province of Turkey","u":0,"b":"Balıkesir Province (Turkish: Balıkesir ili) is a province and metropolitan municipality in northwestern Turkey with coastlines on both the Sea of Marmara and the Aegean. Its area is 14,583 km2, and its population is 1,276,096 (2024). Its adjacent provinces are Çanakkale to the west, İzmir to the southwest, Manisa to the south, Kütahya to the southeast, and Bursa to the east."},{"n":"Çanakkale Province","lat":40.1506,"lon":26.4111,"s":88,"w":"Çanakkale Province","ty":"province of Turkey","u":0,"b":"Çanakkale Province (Turkish: Çanakkale ili) is a province of Turkey, located in the northwestern part of the country. It takes its name from the city of Çanakkale. Its area is 9,817 km2, and its population is 559,383 (2022)."},{"n":"Edirne Province","lat":41.12,"lon":26.5206,"s":85,"w":"Edirne Province","ty":"province of Turkey","u":0,"b":"Edirne Province (Turkish: Edirne ili) is a Turkish province located in East Thrace. Part of European Turkey, it is one of only three provinces located entirely within continental Europe. Its area is 6,145 km2, and its population is 414,714 (2022)."},{"n":"Tekirdağ Province","lat":40.9778,"lon":27.5183,"s":84,"w":"Tekirdağ Province","ty":"province of Turkey","u":0,"b":"Tekirdağ Province is a province and metropolitan municipality of Turkey. Its area is 6,190 km2, and its population is 1,142,451 (2022). It is located in the East Thrace region of the country, also known as European Turkey, one of only three provinces entirely within continental Europe."},{"n":"Dobrich","lat":43.5667,"lon":27.8333,"s":81,"w":"Dobrich","ty":"city in Bulgaria|oblast seat|average city|municipality seat","u":0,"b":"Dobrich (Bulgarian: Добрич) is the 9th-largest city in Bulgaria, the administrative centre of Dobrich Province and the capital of the region of Southern Dobrudzha. It is located in the northeastern part of the country, 30 km west of the Bulgarian Black Sea Coast, not far from resorts such as Albena, Balchik, and Golden Sands."},{"n":"Kırklareli Province","lat":41.6811,"lon":27.4714,"s":80,"w":"Kırklareli Province","ty":"province of Turkey","u":0,"b":"Kırklareli Province (Turkish: Kırklareli ili) is a province in northwestern Turkey on the west coast of the Black Sea. The province neighbours Bulgaria to the north along a 180-kilometre (110 mi) long border. It borders the province of Edirne to the west, the province of Tekirdağ to the south, and the province of Istanbul to the southeast."},{"n":"Marmara Region","lat":40.6307,"lon":28.1264,"s":79,"w":"Marmara region","ty":"human-geographic territorial entity|region of Turkey|statistical territorial entity","u":0,"b":"The Marmara region (Turkish: Marmara Bölgesi) is a geographical region of Turkey. It is bordered by Greece and the Aegean Sea to the west, Bulgaria and the Black Sea to the north, the Black Sea Region to the east, and the Aegean Region to the south. At the center of the region is the Sea of Marmara, which gives the region its name."},{"n":"Bucharest","lat":44.4134,"lon":26.0978,"s":237,"w":"Bucharest","ty":"municipality of Romania","u":0,"b":"Bucharest (Romanian: București ) is the capital and largest city of Romania. The metropolis stands on the River Dâmbovița in south-eastern Romania. Its population is officially estimated at 1.71 million residents within a greater metropolitan area of 2.33 million residents, which makes Bucharest the fifteenth-largest city in Europe."},{"n":"Bulgarian","lat":42.75,"lon":25.5,"s":196,"w":"Bulgarian language","ty":"language|modern language","u":0,"b":"Bulgarian is an Eastern South Slavic language spoken in Southeast Europe, primarily in Bulgaria. It is the language of the Bulgarians. Along with the closely related Macedonian language (collectively forming Macedo-Bulgarian), it is a member of the Balkan sprachbund and South Slavic dialect continuum of the Indo-European language family."},{"n":"Veliko Tarnovo","lat":43.0787,"lon":25.6283,"s":196,"w":"Veliko Tarnovo","ty":"city in Bulgaria|municipality seat|oblast seat","u":0,"b":"Veliko Tarnovo is a city in north central Bulgaria and the administrative centre of Veliko Tarnovo Province. It is the historical and spiritual capital of Bulgaria."},{"n":"Plovdiv","lat":42.1421,"lon":24.7415,"s":119,"w":"Plovdiv","ty":"oblast seat|municipality seat|city in Bulgaria|large city","u":0,"b":"Plovdiv is the second-largest city in Bulgaria and the most populous city in the Bulgarian part of the historic region of Thrace, located 144 km (93 miles) southeast of the capital Sofia. It is considered the oldest European continually inhabited city, having been inhabited since c. 6,000 BCE."},{"n":"Thrace","lat":42.0,"lon":26.0,"s":101,"w":"Thrace","ty":"ancient civilization|historical region","u":0,"b":"Thrace is a geographical and historical region in Southeast Europe roughly corresponding to the province of Thrace in the Roman Empire."},{"n":"Craiova","lat":44.3333,"lon":23.8167,"s":95,"w":"Craiova","ty":"border city|county seat in Romania|border area|cross-border region|municipality of Romania","u":0,"b":"Craiova is the largest city in southwestern Romania, the seventh largest city in the country and the capital of Dolj County, situated near the east bank of the river Jiu in central Oltenia. It is a longstanding political center, and is located at approximately equal distances from the Southern Carpathians (north) and the River Danube (south)."},{"n":"Ruse","lat":43.8445,"lon":25.9539,"s":93,"w":"Ruse, Bulgaria","ty":"oblast seat|city in Bulgaria|municipality seat|big city|border city","u":0,"b":"Ruse is the sixth-largest city in Bulgaria. Ruse is in the northeastern part of the country, on the right bank of the Danube, opposite the Romanian city of Giurgiu, approximately 67 km (42 mi) south of Bucharest, Romania's capital, 172 km (107 mi) from Varna, and 249 km (155 mi) from the capital Sofia."},{"n":"Wallachia","lat":44.43,"lon":26.1,"s":86,"w":"Wallachia","ty":"historical region","u":0,"b":"Wallachia is a geographical region of modern-day Romania, as well as one of the two historical Romanian principalities that laid the foundation for the establishment of the modern Romanian state. It is situated north of the Lower Danube and south of the Southern Carpathians."},{"n":"Pleven","lat":43.4132,"lon":24.6169,"s":83,"w":"Pleven","ty":"oblast seat|big city|city in Bulgaria|municipality seat","u":0,"b":"Pleven is the seventh most populous city in Bulgaria. Located in the northern part of the country, it is the administrative centre of Pleven Province, as well as of the subordinate Pleven municipality. It is the biggest economic center in Northwestern Bulgaria."},{"n":"Balkan Mountains","lat":42.7842,"lon":24.9763,"s":83,"w":"Balkan Mountains","ty":"mountain range","u":0,"b":"The Balkan mountain range is located in the eastern part of the Balkan Peninsula in Southeastern Europe. It is conventionally taken to begin at the peak of Vrashka Chuka on the border between Bulgaria and Serbia."},{"n":"Stara Zagora","lat":42.4257,"lon":25.6346,"s":83,"w":"Stara Zagora","ty":"city in Bulgaria|municipality seat|big city|oblast seat","u":0,"b":"Stara Zagora is a city in Bulgaria, and the administrative capital of Stara Zagora Province. It is located in the Upper Thracian Plain, near the cities of Kazanlak, Plovdiv, and Sliven. Its population is 121,582 making it the fifth largest city of Bulgaria."},{"n":"Tekirdağ","lat":40.9833,"lon":27.5167,"s":78,"w":"Tekirdağ","ty":"city|big city","u":0,"b":"Tekirdağ is a city in northwestern Turkey. It is the seat of Tekirdağ Province and Süleymanpaşa District. It is located on the north coast of the Sea of Marmara, in the region of East Thrace."},{"n":"Sofia","lat":42.6979,"lon":23.3217,"s":228,"w":"Sofia","ty":"oblast seat|seat of government|city in Bulgaria|metropolis|municipality seat|largest city","u":0,"b":"Sofia is the capital and largest city of Bulgaria. It is situated in the Sofia Valley at the foot of the Vitosha mountain, in the western part of the country. The city is built west of the Iskar river and has many mineral springs, such as the Sofia Central Mineral Baths."},{"n":"Romanian","lat":45.0,"lon":26.0,"s":210,"w":"Romanian language","ty":"natural language|modern language","u":0,"b":"Romanian is the official and main language of Romania and Moldova. Romanian is part of the Eastern Romance sub-branch of Romance languages, a linguistic group that evolved from several dialects of Vulgar Latin which separated from the Western Romance languages in the course of the period from the 5th to the 8th centuries."},{"n":"Timișoara","lat":45.7597,"lon":21.23,"s":115,"w":"Timișoara","ty":"municipality of Romania|tourist destination|economic region|conurbation|border city|metrop","u":0,"b":"Timișoara (UK:, US:, Romanian:; see other names), officially the Municipality of Timișoara, is the capital city of Timiș County, Banat, and the main economic, social and cultural center in western Romania. Located on the Bega River, Timișoara is considered the informal capital city of the historical Banat region."},{"n":"Sibiu","lat":45.8,"lon":24.15,"s":106,"w":"Sibiu","ty":"municipality of Romania|big city|county seat in Romania","u":0,"b":"Sibiu is a city in central Romania, situated in the historical region of Transylvania. Located some 275 km (171 mi) north-west of Bucharest, the city straddles the Cibin River, a tributary of the Olt River. Now the seat of Sibiu County, between 1692 and 1791 and 1849–65, Sibiu was the capital of the Principality of Transylvania."},{"n":"Brașov","lat":45.6522,"lon":25.6106,"s":102,"w":"Brașov","ty":"big city|county seat in Romania|municipality of Romania","u":0,"b":"Brașov is a city in Transylvania, Romania and the county seat (i.e. administrative centre) of Brașov County. According to the 2021 census, with 237,589 inhabitants, Brașov is the 6th most populous city in Romania."},{"n":"Niš","lat":43.3192,"lon":21.8961,"s":99,"w":"Niš","ty":"big city|Serbian city|administrative territorial entity","u":0,"b":"Niš, less often spelled in English as Nish, is the third largest city in Serbia and the administrative center of the Nišava District. It is located in the southern part of Serbia. According to the 2022 census, the city proper has a population of 178,976, while its administrative area has a population of 249,501 inhabitants."},{"n":"Ploiești","lat":44.9411,"lon":26.0225,"s":85,"w":"Ploiești","ty":"county seat in Romania|municipality of Romania|big city","u":0,"b":"Ploiești, formerly spelled Ploești, is a city and the county seat of Prahova County, Romania. Situated in the historical region of Muntenia, it lies on the Wallachian Plain, approximately 56 km (35 mi) north of Bucharest. With a population of 180,540 according to the 2021 census, it is the tenth-most populous city in the country and a major urban centre in southern Romania."},{"n":"Pitești","lat":44.8667,"lon":24.8833,"s":78,"w":"Pitești","ty":"county seat in Romania|big city|municipality of Romania","u":0,"b":"Pitești is a city in Romania, located on the river Argeș. The capital and largest city of Argeș County, it is an important commercial and industrial center, as well as the home of two universities. Pitești is situated in the historical region of Muntenia."},{"n":"Blagoevgrad","lat":41.75,"lon":23.25,"s":76,"w":"Blagoevgrad Province","ty":"oblast of Bulgaria","u":0,"b":"Blagoevgrad Province, also known as Pirin Macedonia or Bulgarian Macedonia (Bulgarian: Пиринска Македония; Българска Македония), (Pirinska Makedoniya or Bulgarska Makedoniya) is a province (oblast) of southwestern Bulgaria. It borders four other Bulgarian provinces to the north and east, the Greek region of Macedonia to the south, and North Macedonia to the west."},{"n":"Burgas","lat":42.5,"lon":27.25,"s":75,"w":"Burgas Province","ty":"oblast of Bulgaria","u":0,"b":"Burgas is a province in southeastern Bulgaria on the southern Bulgarian Black Sea Coast. The province is named after its administrative and industrial centre, the city of Burgas, the fourth biggest town in the country. It is the largest province by area, with a territory of 7,748.1 km2 (2,991.6 sq mi) that is divided into 13 municipalities."},{"n":"Sliven","lat":42.6781,"lon":26.326,"s":75,"w":"Sliven","ty":"city in Bulgaria|municipality seat|oblast seat|big city","u":0,"b":"Sliven (Bulgarian: Сливен) is the eighth-largest city in Bulgaria and the administrative and industrial centre of Sliven Province and municipality in Northern Thrace. It is situated in the Sliven Valley at the foothills of the Balkan Mountains."},{"n":"Ruse","lat":43.75,"lon":26.0,"s":74,"w":"Ruse Province","ty":"oblast of Bulgaria","u":0,"b":"Ruse Province (Bulgarian: Област Русе, romanized: Oblast Ruse), or Rusenska Oblast (Bulgarian: Русенска област, former name Ruse okrug) is a province in northern Bulgaria, named after its main city, Ruse, neighbouring Romania via the Danube. It is divided into eight municipalities with a total population, as of February 2011, of 235,252 inhabitants."},{"n":"Plovdiv","lat":42.2667,"lon":24.8333,"s":74,"w":"Plovdiv Province","ty":"oblast of Bulgaria","u":0,"b":"Plovdiv Province is a province in central southern Bulgaria. It comprises 18 municipalities (общини, obshtini, sing. общинa, obshtina) on a territory of 5,972.9 km2 (2,306.1 sq mi) with a population, as of February 2011, of 683,027 inhabitants."},{"n":"Vidin","lat":43.8,"lon":22.6833,"s":74,"w":"Vidin Province","ty":"oblast of Bulgaria","u":0,"b":"Vidin Province (Bulgarian: Област Видин) is the northwesternmost province of Bulgaria. It borders Serbia to the west and Romania to the northeast, and its administrative centre is the city of Vidin on the Danube river. The area is divided into 11 municipalities."},{"n":"Brașov County","lat":45.79,"lon":25.28,"s":74,"w":"Brașov County","ty":"county of Romania","u":0,"b":"Brașov County is a county (județ) of Transylvania, Romania. Its capital city is Brașov. The county incorporates within its boundaries most of the Medieval \"lands\" (țări) Burzenland and Făgăraș."},{"n":"Gabrovo","lat":42.9167,"lon":25.25,"s":73,"w":"Gabrovo Province","ty":"oblast of Bulgaria","u":0,"b":"Gabrovo Province is a small province lying at the geographical centre of Bulgaria. It is named after its main town – Gabrovo. In 2009 the total population of the area was 130,001."},{"n":"Varna","lat":43.2,"lon":27.6,"s":73,"w":"Varna Province","ty":"oblast of Bulgaria","u":0,"b":"Varna Province (Bulgarian: Област Варна, romanized: Oblast Varna), formerly known as Varna okrug, is a province in eastern Bulgaria, one of the 28 Bulgarian provinces. It comprises 12 municipalities with a population of 494,216 as of April 2016. The province is named after its administrative centre, Varna."},{"n":"Shumen","lat":43.2746,"lon":26.9349,"s":72,"w":"Shumen","ty":"oblast seat|city in Bulgaria|municipality seat","u":0,"b":"Shumen is the tenth-largest city in Bulgaria and the administrative and economic capital of Shumen Province."},{"n":"Blagoevgrad","lat":42.0119,"lon":23.0897,"s":72,"w":"Blagoevgrad","ty":"municipality seat|oblast seat|city in Bulgaria","u":0,"b":"Blagoevgrad (Bulgarian: Благоевград) is а town in Southwestern Bulgaria, the administrative centre of Blagoevgrad Municipality and of Blagoevgrad Province. With a population of almost 70,000 inhabitants, it is the economic and cultural centre of Southwestern Bulgaria."},{"n":"Pleven","lat":43.4167,"lon":24.6667,"s":72,"w":"Pleven Province","ty":"oblast of Bulgaria","u":0,"b":"Pleven Province (Bulgarian: Област Плевен or Плевенска Област) is a province located in central northern Bulgaria, bordering the Danube river, Romania and the Bulgarian provinces of Vratsa, Veliko Tarnovo and Lovech."},{"n":"Smolyan","lat":41.6667,"lon":24.5833,"s":72,"w":"Smolyan Province","ty":"oblast of Bulgaria","u":0,"b":"Smolyan Province is a province in Southern-central Bulgaria, located in the Rhodope Mountains, neighbouring Greece to the south. It is named after its administrative and industrial centre — the city of Smolyan. The province embraces a territory of 3,192.8 km2 (1,232.7 sq mi)."},{"n":"Kardzhali","lat":41.65,"lon":25.3667,"s":71,"w":"Kardzhali Province","ty":"oblast of Bulgaria","u":0,"b":"Kardzhali Province (Bulgarian: Област Кърджали, romanized: Oblast Kărdžali) is a province of southern Bulgaria, neighbouring Greece with the Greek regional units of Xanthi, Rhodope, and Evros to the south and east. It is 3,209.1 km2 in area. Its main city is Kardzhali."},{"n":"Razgrad","lat":43.5,"lon":26.5833,"s":71,"w":"Razgrad Province","ty":"oblast of Bulgaria","u":0,"b":"Razgrad Province (Bulgarian: Област Разград (Oblast Razgrad), former name Razgrad okrug) is a province in Northeastern Bulgaria, geographically part of the Ludogorie region. It is named after its administrative and industrial centre: the town of Razgrad."},{"n":"Vratsa","lat":43.5167,"lon":23.6,"s":71,"w":"Vratsa Province","ty":"oblast of Bulgaria","u":0,"b":"Vratsa Province is a Bulgarian province located in the northwestern part of the country, between Danube river in the north and Stara Planina mountain in the south. It is named after its main town: Vratsa. As of 2016, the province had a population of 170 367, on territory of 3,619.7 km2 (1,397.6 sq mi)."},{"n":"Kyustendil","lat":42.25,"lon":23.0,"s":71,"w":"Kyustendil Province","ty":"oblast of Bulgaria","u":0,"b":"Kyustendil Province (Bulgarian: Област Кюстендил, romanized: Oblast Kyustendil) is a province in southwestern Bulgaria, extending over an area of 3,084.3 km2 (1,190.9 sq mi), and with a population of 106 131."},{"n":"Budapest","lat":47.4983,"lon":19.0408,"s":260,"w":"Budapest","ty":"commercial capital city|global city|big city|town in Hungary|largest city|metropolis|encla","u":0,"b":"Budapest is the capital and largest city of Hungary. It is Hungary's primate city with 1.7 million inhabitants and its greater metro area has a population of about 3.3 million, representing one-third of the country's population and producing more than 40% of the country's economic output."},{"n":"Belgrade","lat":44.8178,"lon":20.4569,"s":230,"w":"Belgrade","ty":"primate city|metropolis|largest city|global city|city|capital city|tourist destination|big","u":0,"b":"Belgrade is the capital and largest city of Serbia. It is located at the confluence of the Sava and Danube rivers and at the crossroads of the Pannonian Plain and the Balkan Peninsula."},{"n":"Yugoslavia","lat":44.82,"lon":20.4275,"s":182,"w":"Yugoslavia","ty":"historical country","u":0,"b":"Yugoslavia was a country in Central Europe and the Balkans that existed from 1918 to 1992."},{"n":"Serbian","lat":44.0,"lon":21.0,"s":175,"w":"Serbian language","ty":"pluricentric language variant|language|standard variety","u":0,"b":"Serbian is the standard variety of the Serbo-Croatian language mainly used by Serbs. It is the national official language and literary standard of Serbia, one of the official languages in Bosnia-Herzegovina and Kosovo, and a recognized minority language in numerous countries."},{"n":"Cluj-Napoca","lat":46.7689,"lon":23.5907,"s":123,"w":"Cluj-Napoca","ty":"municipality|county seat in Romania|municipality of Romania|big city|city","u":0,"b":"Cluj-Napoca, or simply Cluj (Hungarian: Kolozsvár; German: Klausenburg), is a city in northwestern Romania. It is the second-most populous city in the country and the seat of Cluj County. Geographically, it is roughly equidistant from Bucharest (445 km; 277 mi), Budapest (461 km; 286 mi) and Belgrade (483 km; 300 mi)."},{"n":"Debrecen","lat":47.53,"lon":21.6392,"s":122,"w":"Debrecen","ty":"city with county rights","u":0,"b":"Debrecen is Hungary's second-largest city, after Budapest, the regional centre of the Northern Great Plain region and the seat of Hajdú-Bihar County. A city with county rights, it was the largest Hungarian city in the 18th century and it is one of the Hungarian people's most important cultural centres."},{"n":"Transylvania","lat":46.7667,"lon":23.5833,"s":120,"w":"Transylvania","ty":"historical region","u":0,"b":"Transylvania is a historical and cultural region in Central Europe, encompassing central Romania. The region's natural border to the east and south is the Carpathian Mountains, and to the west it is the Apuseni Mountains. Broader definitions of Transylvania also include the western and northwestern Romanian regions of Crișana and Maramureș, and occasionally Banat."},{"n":"Serbo-Croatian","lat":44.86,"lon":19.02,"s":120,"w":"Serbo-Croatian","ty":"macrolanguage|natural language|pluricentric language|modern language","u":0,"b":"Serbo-Croatian, also known as Bosnian-Croatian-Montenegrin-Serbian (BCMS), is a Western South Slavic language and the primary language of Serbia, Croatia, Bosnia and Herzegovina, and Montenegro. It is a pluricentric language with four mutually intelligible standard varieties, namely Serbian, Croatian, Bosnian, and Montenegrin."},{"n":"Szeged","lat":46.25,"lon":20.1667,"s":113,"w":"Szeged","ty":"County city (council system)|city with municipal rights|administrative centre|county town|","u":0,"b":"Szeged is the third largest city of Hungary, the largest city and regional centre of the Southern Great Plain and the county seat of Csongrád-Csanád county. The University of Szeged is one of the most distinguished universities in Hungary."},{"n":"Novi Sad","lat":45.2644,"lon":19.8317,"s":110,"w":"Novi Sad","ty":"administrative centre|metropolitan area|tourist destination|cultural capital|Serbian city|","u":0,"b":"Novi Sad is the second-largest city in Serbia and the administrative center of the autonomous province of Vojvodina. It is located in the southern portion of the Pannonian Plain on the border of the Bačka and Syrmia geographical regions, lying on the banks of the Danube river, and facing the northern slopes of Fruška Gora."},{"n":"Romani","lat":46.8,"lon":21.7,"s":109,"w":"Romani language","ty":"language subfamily|modern language|macrolanguage|natural language","u":0,"b":"Romani is an Indo-Aryan macrolanguage of the Romani people. Most Roma speak one of its dialects. Its largest dialects are Balkan Romani (about 600,000 speakers), Vlax Romani (500,000), and Sinte Romani (300,000)."},{"n":"Vojvodina","lat":45.25,"lon":19.85,"s":105,"w":"Vojvodina","ty":"autonomous province of Serbia","u":0,"b":"Vojvodina, officially the Autonomous Province of Vojvodina, is an autonomous province in northern Serbia. It encompasses the historical and geographical regions of Bačka, Banat, Syrmia, and northernmost part of Mačva, lying to the north of the national capital Belgrade and the Sava and Danube rivers."},{"n":"Ecser","lat":47.4444,"lon":19.326,"s":103,"w":"Ecser","ty":"municipality of Hungary|large village of Hungary","u":0,"b":"Ecser (Hungarian:; Slovak: Ečer) is a village in Pest county, Budapest metropolitan area, Hungary."},{"n":"Oradea","lat":47.0722,"lon":21.9211,"s":100,"w":"Oradea","ty":"municipality of Romania|big city|county seat in Romania","u":0,"b":"Oradea is the capital of the Crișana region in Romania. It serves as the administrative centre of Bihor County. The city is situated on both banks of the Crișul Repede River."},{"n":"Kecskemét","lat":46.9075,"lon":19.6917,"s":94,"w":"Kecskemét","ty":"town in Hungary|city with county rights|big city|city with municipal rights|County city (c","u":0,"b":"Kecskemét is a city with county rights in central Hungary. It is the eighth-largest city in the country, and the county seat of Bács-Kiskun. Kecskemét lies halfway between the capital Budapest and the country's third-largest city, Szeged, 86 kilometres (53 miles) from both of them and almost equal distance from the two big rivers of the country, the Danube and the Tisza."},{"n":"Socialist Federal Republic of Yugoslavia","lat":44.82,"lon":20.4275,"s":92,"w":"Socialist Federal Republic of Yugoslavia","ty":"historical country","u":0,"b":"The Socialist Federal Republic of Yugoslavia, known from 1945 to 1963 as the Federal People's Republic of Yugoslavia, and commonly referred to as Yugoslavia, was a country in Central and Southeast Europe. It was established in 1945, following World War II, and lasted until 1992, dissolving amid the onset of the Yugoslav Wars."},{"n":"Arad","lat":46.1667,"lon":21.3167,"s":89,"w":"Arad, Romania","ty":"border area|urban area|big city|municipality of Romania|border city|conurbation|cross-bord","u":0,"b":"Arad is the capital city of Arad County, at the border of Crișana and Banat. No villages are administered by the city. It is the third largest city in Western Romania, behind Timișoara and Oradea, and the 12th largest in Romania, with a population of 145,078."},{"n":"Tisza","lat":45.1358,"lon":20.2722,"s":88,"w":"Tisza","ty":"transboundary river|river","u":0,"b":"The Tisza, Tysa, Tisa, or Theiss (see below) is one of the major rivers of Central and Eastern Europe. It was once called \"the most Hungarian river\" because it flowed entirely within the territory of the Kingdom of Hungary. Today, it crosses several national borders."},{"n":"Kragujevac","lat":44.0101,"lon":20.9172,"s":87,"w":"Kragujevac","ty":"big city|Serbian city","u":0,"b":"Kragujevac is the fourth largest city in Serbia and the administrative centre of the Šumadija District. It is the historical centre of the geographical region of Šumadija in central Serbia, and is situated on the banks of the Lepenica River. According to the 2022 census, the city itself has a population of 146,318 while the city administrative area has 171,186 inhabitants."},{"n":"Szolnok","lat":47.1747,"lon":20.1764,"s":85,"w":"Szolnok","ty":"town in Hungary|city with county rights","u":0,"b":"Szolnok is the county seat of Jász-Nagykun-Szolnok county in central Hungary. A city with county rights, it is located on the banks of the Tisza river, in the heart of the Great Hungarian Plain, which has made it an important cultural and economic crossroads for centuries. Szolnok also has one of Hungary’s best water polo teams."},{"n":"Sava","lat":44.8317,"lon":20.4497,"s":83,"w":"Sava","ty":"river","u":0,"b":"The Sava is a river in Central and Southeast Europe, a right-bank and the longest tributary of the Danube. From its source in Slovenia, it flows through Croatia and along its border with Bosnia and Herzegovina, and finally reaches Serbia, feeding into the Danube in its capital, Belgrade."},{"n":"Vukovar","lat":45.35,"lon":19.0033,"s":80,"w":"Vukovar","ty":"town in Croatia|city","u":0,"b":"Vukovar is a city in Croatia, in the eastern regions of Syrmia and Slavonia. It contains Croatia's largest river port, located at the confluence of the Vuka and the Danube. Vukovar is the seat of Vukovar-Syrmia County and the second-largest city in the county after Vinkovci."},{"n":"Kingdom of Yugoslavia","lat":44.8097,"lon":20.4631,"s":78,"w":"Kingdom of Yugoslavia","ty":"historical country","u":0,"b":"The Kingdom of Yugoslavia was a country in Southeast and Central Europe that existed from 1918 until 1941. From 1918 to 1929, it was officially called the Kingdom of Serbs, Croats, and Slovenes and was colloquially known as Yugoslavia (lit. 'Land of the South Slavs') due to its origins."},{"n":"Subotica","lat":46.1002,"lon":19.6653,"s":77,"w":"Subotica","ty":"Serbian city|big city","u":0,"b":"Subotica is a city in Central Europe and the administrative center of the North Bačka District in the autonomous province of Vojvodina, Serbia. Formerly the largest city of Vojvodina region, contemporary Subotica is now the second largest city in the province, as well as in the Serbian part of the Bačka geographical region, following the city of Novi Sad."},{"n":"Békéscsaba","lat":46.6833,"lon":21.0833,"s":77,"w":"Békéscsaba","ty":"city with municipal rights|city with county rights|town in Hungary","u":0,"b":"Békéscsaba is a city with county rights in southeast Hungary, the capital of Békés County."},{"n":"Sighișoara","lat":46.2169,"lon":24.7911,"s":75,"w":"Sighișoara","ty":"municipality of Romania","u":0,"b":"Sighișoara is a city on the Târnava Mare River in Mureș County, central Romania. Located in the historic region of Transylvania, Sighișoara had a population of 23,927 according to the 2021 census. It is a popular tourist destination for its well-preserved old town, which is listed by UNESCO as a World Heritage Site since 1999."},{"n":"Giurtelecu Șimleului","lat":47.2944,"lon":22.7917,"s":75,"w":"Giurtelecu Șimleului","ty":"village","u":0,"b":"Măeriște (Hungarian: Krasznahídvég; German: Bruckend) is a commune located in Sălaj County, Crișana, Romania. It is composed of six villages: Criștelec (Kerestelek), Doh (Doh), Giurtelecu Șimleului (Somlyógyőrtelek), Măeriște, Mălădia (Maladé), and Uileacu Șimleului (Somlyóújlak)."},{"n":"Târgu Mureș","lat":46.5497,"lon":24.5597,"s":74,"w":"Târgu Mureș","ty":"county seat in Romania|big city|municipality of Romania","u":0,"b":"Târgu Mureș is the seat of Mureș County in the historical region of Transylvania, Romania. It is the 16th-largest city in Romania, with 116,033 inhabitants as of the 2021 census. It lies on the Mureș River, the second-longest river in Romania (after the Danube)."},{"n":"Alba Iulia","lat":46.0764,"lon":23.5728,"s":74,"w":"Alba Iulia","ty":"municipality of Romania|county seat in Romania","u":0,"b":"Alba Iulia is a city that serves as the seat of Alba County in the west-central part of Romania. Located on the river Mureș in the historical region of Transylvania, it has a population of 64,227 (as of 2021). During ancient times, the site was the location of the Roman camp Apulum."},{"n":"Banat","lat":45.7,"lon":20.9,"s":74,"w":"Banat","ty":"historical region","u":0,"b":"Banat is a geographical and historical region located in the Pannonian or Carpathian Basin that straddles Central and Eastern Europe. It is divided among three countries: the eastern part lies in western Romania; the western part of Banat is in northeastern Serbia; and a small northern part lies within southeastern Hungary (Csongrád-Csanád County)."},{"n":"Bratislava","lat":48.1517,"lon":17.1093,"s":226,"w":"Bratislava","ty":"big city|municipality of Slovakia|city","u":0,"b":"Bratislava (Hungarian: Pozsony; German: Pressburg) is the capital and largest city of Slovakia and the fourth largest of all cities on the river Danube. Officially, the population of the city proper is about 479,000, with the wider Bratislava Region exceeding 732,000 inhabitants. The metropolitan area has a population of approximately 1.3 million."},{"n":"Hungarian","lat":47.0,"lon":19.0,"s":208,"w":"Hungarian language","ty":"modern language|language|natural language","u":0,"b":"Hungarian, or Magyar, is a Ugric language of the Uralic language family spoken in Hungary and parts of several neighboring countries. It is the official language of Hungary and one of the 24 official languages of the European Union."},{"n":"Slovak","lat":49.0,"lon":19.0,"s":182,"w":"Slovak language","ty":"language|modern language","u":0,"b":"Slovak ( SLOH-va(h)k; endonym: slovenčina or slovenský jazyk ), is a West Slavic language of the Czech–Slovak group, written in Latin script. It is part of the Indo-European language family, and is one of the Slavic languages, which are part of the larger Balto-Slavic branch."},{"n":"Pécs","lat":46.0708,"lon":18.2331,"s":110,"w":"Pécs","ty":"town in Hungary|big city|city with county rights|city with municipal rights|county town|Co","u":0,"b":"Pécs is the fifth largest city in Hungary, on the slopes of the Mecsek mountains in the country's southwest, close to the border with Croatia. It is the administrative and economic centre of Baranya County, and the seat of the Roman Catholic Diocese of Pécs."},{"n":"Košice","lat":48.7167,"lon":21.25,"s":108,"w":"Košice","ty":"municipality of Slovakia|big city|city","u":0,"b":"Košice is the largest city in eastern Slovakia. It is situated on the river Hornád at the eastern reaches of the Slovak Ore Mountains, near the border with Hungary and Ukraine. With a population of approximately 230,000, Košice is the second-largest city in Slovakia, after the capital Bratislava."},{"n":"Miskolc","lat":48.1,"lon":20.7833,"s":108,"w":"Miskolc","ty":"city with county rights|big city|town in Hungary|city with municipal rights|County city (c","u":0,"b":"Miskolc is a city in northeastern Hungary, known for its heavy industry. With a population of 143,502 as of 2024, Miskolc is the fourth largest city in Hungary, behind Budapest, Debrecen, and Szeged. It is also the county capital of Borsod-Abaúj-Zemplén and the regional centre of Northern Hungary."},{"n":"Győr","lat":47.6842,"lon":17.6344,"s":105,"w":"Győr","ty":"town in Hungary","u":0,"b":"Győr is the main city of northwest Hungary, the capital of Győr-Moson-Sopron County and Western Transdanubia region, and – halfway between Budapest and Vienna – situated on one of the important roads of Central Europe. It is the sixth largest city in Hungary, and one of its seven main regional centres. The city has county rights."},{"n":"Zichyújfalu","lat":47.1299,"lon":18.67,"s":103,"w":"Zichyújfalu","ty":"municipality of Hungary","u":0,"b":"Zichyújfalu is a village in Fejér county, Hungary, about 10 km from Lake Velencei, which is more or less easy to reach on road and on railway (Pusztaszabolcs-Székesfehérvár line). The settlement used to be a part of Gárdony but declared its independence in December 1997."},{"n":"Lake Balaton","lat":46.85,"lon":17.72,"s":97,"w":"Lake Balaton","ty":"lake|rift lake|geographical small region of Hungary|Natura 2000 site","u":0,"b":"Lake Balaton is a freshwater rift lake in the Transdanubian region of Hungary. It is the largest lake in Central Europe, and one of the region's foremost tourist destinations. The Zala River provides the largest inflow of water to the lake, and the canalized Sió is the only outflow."},{"n":"Székesfehérvár","lat":47.191,"lon":18.4108,"s":97,"w":"Székesfehérvár","ty":"city with municipal rights|County city (council system)|city with county rights|city|town ","u":0,"b":"Székesfehérvár, known colloquially as Fehérvár (lit. 'white castle'), is a city in central Hungary, and the country's ninth-largest city. It is the regional capital of Central Transdanubia, and the centre of Fejér County and Székesfehérvár District. The area is an important rail and road junction between Lake Balaton and Lake Velence."},{"n":"Mošovce","lat":48.9095,"lon":18.8876,"s":97,"w":"Mošovce","ty":"municipality of Slovakia","u":0,"b":"Mošovce (Hungarian: Mosóc, German: Moschotz) is one of the largest villages in the historical region of Turiec, currently in the Turčianske Teplice District in the Žilina Region of northern Slovakia."},{"n":"Banská Bystrica","lat":48.7353,"lon":19.1453,"s":93,"w":"Banská Bystrica","ty":"city|municipality of Slovakia","u":0,"b":"Banská Bystrica is a city in central Slovakia, located on the Hron River in a long and wide valley encircled by the mountain chains of the Low Tatras, the Veľká Fatra, and the Kremnica Mountains. With approximately 76,000 inhabitants, Banská Bystrica is the sixth most populous municipality in Slovakia."},{"n":"Osijek","lat":45.5603,"lon":18.6703,"s":90,"w":"Osijek","ty":"town in Croatia|city","u":0,"b":"Osijek is the largest city and the economic and cultural hub of the eastern Croatian region of Slavonia, as well as the administrative seat of Osijek-Baranja County. It is the fourth-largest city in Croatia, with a population of 96,313 recorded in the 2021 census."},{"n":"Nyíregyháza","lat":47.95,"lon":21.7167,"s":90,"w":"Nyíregyháza","ty":"town in Hungary|city with county rights|County city (council system)|city|big city","u":0,"b":"Nyíregyháza is a city with county rights in northeastern Hungary and the county capital of Szabolcs-Szatmár-Bereg. With a population of 118,001, it is the seventh-largest city in Hungary and the second largest in the Northern Great Plain region. Its development has been ongoing since the 18th century, making it the economic and cultural center of the region."},{"n":"Eger","lat":47.8989,"lon":20.3747,"s":90,"w":"Eger","ty":"city with county rights|town in Hungary","u":0,"b":"Eger is the county seat of Heves County, and the second largest city in Northern Hungary (after Miskolc). A city with county rights, Eger is best known for its medieval castle, thermal baths, baroque buildings, the northernmost Ottoman minaret, and red wines."},{"n":"Prešov","lat":49.0,"lon":21.2333,"s":89,"w":"Prešov","ty":"city|municipality of Slovakia","u":0,"b":"Prešov is a city in eastern Slovakia. It is the seat of administrative Prešov Region (Slovak: Prešovský kraj) and Šariš. With a population of approximately 85,000 for the city, and in total more than 100,000 with the urban area, it is the second-largest city in eastern Slovakia and the third-largest city in all of Slovakia, after the nearby city of Košice."},{"n":"Trnava","lat":48.3777,"lon":17.5862,"s":88,"w":"Trnava","ty":"municipality of Slovakia|city","u":0,"b":"Trnava is a city in western Slovakia, 47 km (29 mi) to the northeast of Bratislava, on the Trnávka river. It is the capital of the Trnava Region and the Trnava District. It is the seat of a Roman Catholic archbishopric (1541–1820 and then again since 1977)."},{"n":"Nitra","lat":48.3147,"lon":18.0875,"s":86,"w":"Nitra","ty":"city|municipality of Slovakia","u":0,"b":"Nitra (Hungarian: Nyitra) is a city in southwestern Slovakia, situated at the foot of the Zobor Mountain in the Nitra River Valley about 90 km (56 mi) northeast of the country's capital, Bratislava. With a population of about 78,353, it is the fifth-largest city in Slovakia."},{"n":"Esztergom","lat":47.7856,"lon":18.7403,"s":86,"w":"Esztergom","ty":"city with county rights","u":0,"b":"Esztergom is a city with county rights in northern Hungary, 46 kilometres (29 miles) northwest of the capital Budapest. It lies in Komárom-Esztergom County, on the right bank of the river Danube, which forms the border with Slovakia there."},{"n":"Veszprém","lat":47.1,"lon":17.9167,"s":86,"w":"Veszprém","ty":"town in Hungary|city with county rights","u":0,"b":"Veszprém is one of the oldest urban areas in Hungary, and a city with county rights. It lies approximately 15 km (9 mi) north of the Lake Balaton. It is the administrative center of the county of the same name."},{"n":"Tuzla","lat":44.5391,"lon":18.6752,"s":85,"w":"Tuzla","ty":"human settlement|city|big city","u":0,"b":"Tuzla is the third-largest city of Bosnia and Herzegovina and the administrative center of Tuzla Canton of the Federation of Bosnia and Herzegovina. As of 2013, it has a population of 110,979 inhabitants. Tuzla is the economic, cultural, educational, health, and tourist center of northeast Bosnia."},{"n":"Trenčín","lat":48.8942,"lon":18.0406,"s":80,"w":"Trenčín","ty":"municipality of Slovakia|city","u":0,"b":"Trenčín is a city in western Slovakia of the central Váh River valley near the Czech border, around 95 km (59 mi) from Bratislava. It has a population of more than 55,000, which makes it the eighth largest municipality of the country and is the seat of the Trenčín Region and the Trenčín District. It has a medieval castle, Trenčín Castle, on a rock above the city."},{"n":"Vienna","lat":48.2083,"lon":16.3725,"s":294,"w":"Vienna","ty":"municipality of Austria|city-state|federal capital|place with town rights and privileges|s","u":0,"b":"Vienna is the capital, most populous city, and one of the nine states of Austria. It is Austria's primate city, with just over two million inhabitants. Its larger metropolitan area has a population of nearly 2.9 million, representing nearly one-third of the country's population."},{"n":"Prague","lat":50.0875,"lon":14.4214,"s":267,"w":"Prague","ty":"district town|municipality of the Czech Republic|national capital|electoral unit|big city|","u":0,"b":"Prague ( PRAHG; Czech: Praha ) is the capital and largest city of the Czech Republic and the historical capital of Bohemia. Located on the Vltava River, the city has a population of about 1.4 million, making it the twelfth-largest city in the European Union. Its metropolitan area is home to approximately 2.3 million people."},{"n":"Czech","lat":50.0,"lon":15.0,"s":222,"w":"Czech language","ty":"language|modern language|spoken language|natural language","u":0,"b":"Czech ( CHEK; endonym: čeština ), historically known as Bohemian, is a West Slavic language of the Czech–Slovak group, written in Latin script. Spoken by over 12 million people including second-language speakers, it serves as the official language of the Czech Republic."},{"n":"Czechoslovakia","lat":50.0833,"lon":14.4167,"s":168,"w":"Czechoslovakia","ty":"historical country","u":0,"b":"Czechoslovakia was a country in Central Europe. The country was bordered by Austria and Hungary to the south, Germany to the west and northwest, Poland to the northeast, and Ukraine to the southeast. Czechoslovakia had a hilly and mostly mountainous landscape that covered an area of 127,906 square kilometers (49,385 sq mi) with a mostly temperate continental and oceanic climate."},{"n":"Katowice","lat":50.25,"lon":19.0,"s":163,"w":"Katowice","ty":"place with town rights and privileges|city with powiat rights in Poland|city|tourist desti","u":0,"b":"Katowice is the capital city of the Silesian Voivodeship in southern Poland and the central city of the Katowice urban area. As of 2021, Katowice has an official population of 286,960, and a resident population estimate of around 315,000."},{"n":"Graz","lat":47.0708,"lon":15.4386,"s":155,"w":"Graz","ty":"municipality of Austria|place with town rights and privileges|big city|statutory city of A","u":0,"b":"Graz is the capital of the Austrian state of Styria and the second-largest city in Austria, after Vienna. On 1 January 2026, Graz had a population of around 307,912 to 345,391 including residents with a secondary residence. In 2023, the population of the Graz functional urban area was 660,238."},{"n":"Austria–Hungary","lat":48.2075,"lon":16.365,"s":148,"w":"Austria-Hungary","ty":"historical country","u":0,"b":"Austria-Hungary, also referred to as the Austro-Hungarian Empire and officially as the Austro-Hungarian Monarchy, was a multi-national empire in Central Europe under a constitutional dual monarchy that existed between 1867 and 1918."},{"n":"Brno","lat":49.1953,"lon":16.6083,"s":147,"w":"Brno","ty":"statutory city in the Czech Republic|capital of region|municipality with town privileges i","u":0,"b":"Brno is a city in the South Moravian Region of the Czech Republic. Located at the confluence of the Svitava and Svratka rivers, Brno has about 404,000 inhabitants, making it the second-largest city in the Czech Republic after the capital, Prague, and one of the 100 largest cities in the European Union. The Brno metropolitan area has approximately 730,000 inhabitants."},{"n":"Auschwitz","lat":50.0358,"lon":19.1783,"s":128,"w":"Auschwitz concentration camp","ty":"extermination camp|museum|architectural ensemble|Nazi concentration camp","u":1,"b":"Auschwitz, also known as Oświęcim, was a complex of over 40 concentration and extermination camps operated by Nazi Germany in occupied Poland (in a portion annexed into Germany in 1939) during World War II and the Holocaust."},{"n":"Styria","lat":47.25,"lon":15.1667,"s":120,"w":"Styria","ty":"federal state of Austria|region","u":0,"b":"Styria is an Austrian state in the southeast of the country. With an area of approximately 16,399 km2 (6,332 sq mi), it is Austria's second-largest state by area, after Lower Austria. Styria borders Slovenia to the south and, clockwise from the southwest, the Austrian states of Carinthia, Salzburg, Upper Austria, Lower Austria and Burgenland."},{"n":"Vistula","lat":49.6058,"lon":19.0036,"s":118,"w":"Vistula","ty":"main stem|river","u":0,"b":"The Vistula is the longest river in Poland and the longest river draining into the Baltic Sea, at 1,047 kilometres (651 miles) in length. Its drainage basin, extending into three other countries apart from Poland, covers 193,960 km2 (74,890 sq mi), of which 168,868 km2 (65,200 sq mi) is in Poland."},{"n":"Lower Austria","lat":48.3333,"lon":15.75,"s":117,"w":"Lower Austria","ty":"historical region|federal state of Austria","u":0,"b":"Lower Austria is one of the nine states of Austria, located in the northeastern corner of the country. Major cities are Amstetten, Krems an der Donau, Wiener Neustadt and Sankt Pölten, which has been the capital of Lower Austria since 1986, replacing Vienna, which became a separate state in 1921."},{"n":"Burgenland","lat":47.5,"lon":16.4167,"s":116,"w":"Burgenland","ty":"federal state of Austria","u":0,"b":"Burgenland is the easternmost and least populous state of Austria. It consists of two statutory cities and seven rural districts, with a total of 171 municipalities. It is 166 km (103 mi) long from north to south but much narrower from west to east ( as little as 5 km or 3 mi wide at Sieggraben)."},{"n":"Ostrava","lat":49.8356,"lon":18.2925,"s":116,"w":"Ostrava","ty":"district town|Czech municipality with expanded powers|big city|statutory city in the Czech","u":0,"b":"Ostrava is a city in the north-east of the Czech Republic and the capital of the Moravian-Silesian Region. It has about 281,000 inhabitants. It lies near the border with Poland, at the confluences of four rivers: Oder, Opava, Ostravice and Lučina."},{"n":"Oder","lat":49.6133,"lon":17.5208,"s":107,"w":"Oder","ty":"main stem|river","u":0,"b":"The Oder is a river in Central Europe. It is Poland's second-longest river and third-longest within its borders after the Vistula and its largest tributary the Warta. The Oder rises in the Czech Republic and flows 742 kilometres (461 mi) through western Poland, later forming 187 kilometres (116 mi) of the border between Poland and Germany as part of the Oder–Neisse line."},{"n":"Silesian Voivodeship","lat":50.3333,"lon":19.0,"s":107,"w":"Silesian Voivodeship","ty":"voivodeship of Poland","u":0,"b":"Silesian Voivodeship (Polish: województwo śląskie ) is an administrative province in southern Poland. With over 4.2 million residents and an area of 12,300 square kilometers, it is the second-most populous, and the most-densely populated and most-urbanized region of Poland."},{"n":"Maribor","lat":46.55,"lon":15.6333,"s":105,"w":"Maribor","ty":"big city","u":0,"b":"Maribor is the second-largest city in Slovenia and the largest city of the traditional region of Lower Styria. It is the seat of the Urban Municipality of Maribor and the Drava Statistical Region. Maribor is also the economic, administrative, educational, and cultural centre of eastern Slovenia."},{"n":"Austrian Empire","lat":48.2,"lon":16.35,"s":104,"w":"Austrian Empire","ty":"historical country","u":0,"b":"The Austrian Empire, officially known as the Empire of Austria, was a multinational European great power from 1804 to 1867, created by proclamation out of the realms of the Habsburgs."},{"n":"Vrahovice","lat":49.4808,"lon":17.1483,"s":104,"w":"Vrahovice","ty":"municipal part of the Czech Republic|cadastral area in the Czech Republic","u":0,"b":"Vrahovice is a village and administrative part of Prostějov in the Olomouc Region of the Czech Republic. It has about 3,300 inhabitants."},{"n":"Racibórz","lat":50.0919,"lon":18.2192,"s":103,"w":"Racibórz","ty":"urban municipality of Poland","u":0,"b":"Racibórz is a city in Silesian Voivodeship in southern Poland. It is the administrative seat of Racibórz County. With Opole, Racibórz is one of the historic capitals of Upper Silesia, being the residence of the Dukes of Racibórz from 1172 to 1521."},{"n":"Benetice","lat":49.6836,"lon":15.3553,"s":102,"w":"Benetice (Světlá nad Sázavou)","ty":"municipal part of the Czech Republic","u":0,"b":"Benetice (German: Benetitz) is a village and administrative part of Světlá nad Sázavou in the Vysočina Region of the Czech Republic. As of 2021, it had 18 inhabitants."},{"n":"Moravia","lat":49.5,"lon":17.0,"s":102,"w":"Moravia","ty":"historical region|Czech lands|region","u":0,"b":"Moravia is a historical region in the east of the Czech Republic and one of three historical Czech lands, with Bohemia and Czech Silesia."},{"n":"Olomouc","lat":49.5939,"lon":17.2508,"s":102,"w":"Olomouc","ty":"municipality with town privileges in the Czech Republic|district town|statutory city in th","u":0,"b":"Olomouc is a city in the Czech Republic. It has about 105,000 inhabitants, making it the sixth largest city in the country. It is the administrative centre of the Olomouc Region."},{"n":"St. Pölten","lat":48.2,"lon":15.6167,"s":101,"w":"St. Pölten","ty":"statutory city of Austria|municipality of Austria|city|place with town rights and privileg","u":0,"b":"Sankt Pölten, mostly abbreviated to the official name St. Pölten, is the capital and largest city of the State of Lower Austria in northeast Austria, with 59,767 inhabitants as of 1 January 2025. St."},{"n":"Eisenstadt","lat":47.8456,"lon":16.5233,"s":101,"w":"Eisenstadt","ty":"municipality of Austria|district of Austria|town|statutory city of Austria|place with town","u":0,"b":"Eisenstadt is the capital city of the Austrian state of Burgenland. With a population of 16,118 (as of 2025), it is the smallest state capital and the 38th-largest city in Austria overall. It lies at the foot of the Leitha Mountains."},{"n":"Dresden","lat":51.0493,"lon":13.7381,"s":183,"w":"Dresden","ty":"major regional center|urban municipality in Germany|big city|urban district in Saxony","u":0,"b":"Dresden is the capital city of the German state of Saxony and its second most populous city after Leipzig. It is the 12th most populous city of Germany, the fourth largest by area (after Berlin, Hamburg, and Cologne), and the third-most populous city in the area of former East Germany, after Berlin and Leipzig."},{"n":"Saxony","lat":51.0269,"lon":13.3589,"s":179,"w":"Saxony","ty":"federated state of Germany","u":0,"b":"Saxony, officially the Free State of Saxony, is a landlocked state of Germany, bordering the states of Brandenburg, Saxony-Anhalt, Thuringia, and Bavaria, as well as the countries of the Czech Republic and Poland. Its capital is Dresden, and its largest city is Leipzig."},{"n":"Leipzig","lat":51.3406,"lon":12.3747,"s":170,"w":"Leipzig","ty":"urban district in Saxony|big city|city|urban municipality in Germany|major regional center","u":0,"b":"Leipzig is the most populous city in the German state of Saxony. The city has a population of 633,592 residents as of 31 December 2025. It is the eighth-largest city in Germany and is part of the Central German Metropolitan Region."},{"n":"Salzburg","lat":47.8,"lon":13.045,"s":161,"w":"Salzburg","ty":"big city|place with town rights and privileges|district of Austria|border city|municipalit","u":0,"b":"Salzburg is the fourth-largest city in Austria. In 2026 its population was 157,994. The city lies on the Salzach River, near the border with Germany and at the foot of the Alps mountains."},{"n":"Wrocław","lat":51.11,"lon":17.0325,"s":159,"w":"Wrocław","ty":"city with powiat rights in Poland","u":0,"b":"Wrocław is a city in southwestern Poland, and the capital of the Lower Silesian Voivodeship. It is the largest city and historical capital of the regions of Silesia and Lower Silesia. It lies on the banks of the Oder (Odra) River in the Silesian Lowlands."},{"n":"Linz","lat":48.3058,"lon":14.2864,"s":143,"w":"Linz","ty":"big city|municipality of Austria|statutory city of Austria|district of Austria|place with ","u":0,"b":"Linz is the capital of Upper Austria and third-largest city in Austria. Located on the river Danube, the city is in the far north of Austria, 30 km (19 mi) south of the border with Czechia. As of 1 January 2024, the city has a population of 214,064."},{"n":"Silesian","lat":50.5,"lon":18.5,"s":126,"w":"Silesian language","ty":"language|modern language","u":0,"b":"Silesian, occasionally called Upper Silesian, is an ethnolect of the Lechitic group spoken in Upper Silesia."},{"n":"Elbe","lat":50.8875,"lon":14.2331,"s":122,"w":"Elbe","ty":"national waterways in Germany|river","u":0,"b":"The Elbe (Czech: Labe) is one of the major rivers of Central Europe. It rises in the Giant Mountains of the northern Czech Republic before traversing much of Bohemia (western half of the Czech Republic), then Germany before flowing into the North Sea at Cuxhaven, 110 kilometres (68 miles) northwest of Hamburg. Its total length is 1,094 km (680 mi)."},{"n":"Halle (Saale)","lat":51.4828,"lon":11.9697,"s":122,"w":"Halle (Saale)","ty":"big city|independent city of Saxony-Anhalt|college town|Hanseatic city|urban municipality ","u":0,"b":"Halle (Saale), or simply Halle, is the second largest city of the German state of Saxony-Anhalt. It is the sixth-most populous city in the area of former East Germany after (East) Berlin, Leipzig, Dresden, Chemnitz, and Magdeburg, and is Germany's 31st-largest city. With around 226,000 inhabitants, Halle is less populous than the state capital, Magdeburg."},{"n":"Regensburg","lat":49.0167,"lon":12.0833,"s":121,"w":"Regensburg","ty":"big city|district capital|urban municipality in Germany|compact city|urban district of Bav","u":0,"b":"Regensburg is a city in eastern Bavaria, at the confluence of the rivers Danube, Naab and Regen, Danube's northernmost point. It is the capital of the Upper Palatinate subregion of the state."},{"n":"Chemnitz","lat":50.8324,"lon":12.9189,"s":121,"w":"Chemnitz","ty":"urban municipality in Germany|big city|urban district in Saxony|major regional center","u":0,"b":"Chemnitz, known as Karl-Marx-Stadt from 1953 to 1990, is the third-largest city in the German state of Saxony after Leipzig and Dresden, and the fourth-largest city in the area of the former East Germany after (East) Berlin, Leipzig, and Dresden."},{"n":"Plzeň","lat":49.7414,"lon":13.3825,"s":120,"w":"Plzeň","ty":"big city|municipality with town privileges in the Czech Republic|statutory city in the Cze","u":0,"b":"Plzeň, also known in English and German as Pilsen, is a city in the Czech Republic. It is the fourth most populous city in the Czech Republic with about 188,000 inhabitants. It is located about 78 kilometres (48 miles) west of Prague, at the confluence of four rivers: Mže, Úhlava, Úslava and Radbuza, together forming the Berounka River."},{"n":"Upper Austria","lat":48.2,"lon":14.0,"s":115,"w":"Upper Austria","ty":"federal state of Austria","u":0,"b":"Upper Austria (German: Oberösterreich; Bavarian: Obaöstareich; Czech: Horní Rakousy) is one of the nine states of Austria. Its capital is Linz. Upper Austria borders Germany and the Czech Republic, as well as the other Austrian states of Lower Austria, Styria, and Salzburg."},{"n":"Bohemia","lat":49.8333,"lon":14.3333,"s":107,"w":"Bohemia","ty":"historical region","u":0,"b":"Bohemia is the westernmost and largest historical region of the Czech Republic. Bohemia can also refer to a wider area consisting of the historical Lands of the Bohemian Crown ruled by the Bohemian kings, including Moravia and Czech Silesia, in which case the term refers to the historical cultural and political space of the Czech people."},{"n":"Lower Silesian Voivodeship","lat":51.0833,"lon":16.3833,"s":103,"w":"Lower Silesian Voivodeship","ty":"voivodeship of Poland","u":0,"b":"The Lower Silesian Voivodeship, simply known as Lower Silesia is one of the 16 voivodeships into which Poland is divided. Located in the southwestern part of the country, it covers an area of 19,946 square kilometres (7,701 sq mi), and as of 2024 has a total population of 2,868,242. Its capital and largest city is Wrocław, situated on the Oder."},{"n":"Opole Voivodeship","lat":50.6333,"lon":17.9,"s":102,"w":"Opole Voivodeship","ty":"voivodeship of Poland","u":0,"b":"Opole Voivodeship is the smallest and least populated voivodeship (province) of Poland. The province's name derives from that of the region's capital and largest city, Opole. It is part of Silesia."},{"n":"Cottbus","lat":51.7608,"lon":14.3319,"s":102,"w":"Cottbus","ty":"big city|district independent city of Brandenburg|major regional center|urban municipality","u":0,"b":"Cottbus or Chóśebuz is a university city and the second-largest city in the German state of Brandenburg after the state capital, Potsdam. With around 100,000 inhabitants, Cottbus is the most populous city in Lusatia."},{"n":"Karlovy Vary","lat":50.2306,"lon":12.8725,"s":99,"w":"Karlovy Vary","ty":"city|municipality of the Czech Republic|capital of region|municipality with authorized mun","u":0,"b":"Karlovy Vary is a spa city in the Karlovy Vary Region of the Czech Republic. It has about 49,000 inhabitants. It is located at the confluence of the Ohře and Teplá rivers."},{"n":"German","lat":50.0,"lon":10.0,"s":356,"w":"German language","ty":"modern language","u":0,"b":"German is a West Germanic language in the Indo-European language family, mainly spoken in Western and Central Europe. It is the majority and official (or co-official) language in Germany, Austria, Switzerland, and Liechtenstein."},{"n":"Berlin","lat":52.5167,"lon":13.3833,"s":334,"w":"Berlin","ty":"town divided by border|city-state|Unitary municipality in Germany|integrated municipality|","u":0,"b":"Berlin is the capital and largest city of Germany. With 3.7 million inhabitants, it has the highest population within its city limits of any city in the European Union (EU). The metropolis is also one of the states of Germany, being the third-smallest state in the country by area."},{"n":"Hamburg","lat":53.55,"lon":10.0,"s":230,"w":"Hamburg","ty":"federated state of Germany|Hanseatic city|free imperial city|urban municipality in Germany","u":0,"b":"Hamburg, officially the Free and Hanseatic City of Hamburg, is the second-largest city in Germany after Berlin and sixth-largest city in the European Union, with a population of over 1.9 million. The Hamburg Metropolitan Region has a population of over 5.1 million and is the tenth-largest metropolitan region by GDP in the European Union."},{"n":"Bavaria","lat":49.0786,"lon":11.3856,"s":206,"w":"Bavaria","ty":"federated state of Germany","u":0,"b":"Bavaria, officially the Free State of Bavaria, is a landlocked state of Germany. It borders the states of Baden-Württemberg to the west, Hesse to the north-west, and Thuringia and Saxony to the north, as well as the countries of Switzerland and Austria to the south and the Czech Republic to the east."},{"n":"Hesse","lat":50.608,"lon":9.0285,"s":182,"w":"Hesse","ty":"federated state of Germany","u":0,"b":"Hesse or Hessen, officially the State of Hesse (German: Land Hessen), is a landlocked state in Germany. Its capital city is Wiesbaden, and the largest urban area is Frankfurt am Main, which is also the country's principal financial centre. Two other major historic cities are Darmstadt and Kassel."},{"n":"Holy Roman Empire","lat":50.0,"lon":10.0,"s":180,"w":"Holy Roman Empire","ty":"historical country","u":0,"b":"The Holy Roman Empire, also known as the Holy Roman Empire of the German Nation after 1512, was a polity comprising and controlling much of Central Europe and Western Europe, headed by the Holy Roman Emperor and characterized by a decentralized political structure."},{"n":"Nazi Germany","lat":52.5111,"lon":13.3797,"s":179,"w":"Nazi Germany","ty":"historical country","u":0,"b":"Nazi Germany, officially the German Reich and later the Greater German Reich, was the German state between 1933 and 1945, when Adolf Hitler and the Nazi Party controlled the country, transforming it into a totalitarian dictatorship."},{"n":"Brandenburg","lat":52.3946,"lon":13.0603,"s":174,"w":"Brandenburg","ty":"federated state of Germany","u":0,"b":"Brandenburg, officially the State of Brandenburg (see Names), is a landlocked state in northeastern Germany. Brandenburg borders Poland and the states of Berlin, Mecklenburg-Vorpommern, Lower Saxony, Saxony-Anhalt, and Saxony. It is the fifth-largest German state by area and the tenth-most populous, with 2.5 million residents."},{"n":"Hanover","lat":52.3744,"lon":9.7386,"s":172,"w":"Hanover","ty":"district capital|state capital in Germany|urban municipality in Germany|big city","u":0,"b":"Hanover (German: Hannover ) is the capital and largest city of the German state of Lower Saxony. Its population of 535,932 (2021) makes it the 13th-largest city in Germany as well as the fourth-largest in northern Germany after Berlin, Hamburg and Bremen. Hanover's urban area comprises the towns of Garbsen, Langenhagen and Laatzen and has a population of about 791,000 (2018)."},{"n":"Thuringia","lat":51.0,"lon":11.0,"s":169,"w":"Thuringia","ty":"federated state of Germany","u":0,"b":"Thuringia is a landlocked state in central Germany. With 2.1 million people, it is 12th-largest by population, and with 16,171 square kilometers, it is 11th-largest in area. It is the country's centermost state."},{"n":"Lower Saxony","lat":52.7561,"lon":9.3931,"s":167,"w":"Lower Saxony","ty":"federated state of Germany","u":0,"b":"Lower Saxony is a coastal state (Land) in northwestern Germany. It is the second-largest state by land area, with 47,614 km2 (18,384 sq mi), and fourth-largest in population (8 million in 2021) among the 16 Länder of the Federal Republic of Germany. In rural areas, Northern Low Saxon and Saterland Frisian are spoken to varying degrees."},{"n":"Central Europe","lat":51.0,"lon":10.0,"s":165,"w":"Central Europe","ty":"region","u":0,"b":"Central Europe is a geographical region of Europe between Eastern, Southern, Western and Northern Europe. Central Europe is known for its cultural diversity; however, countries in this region also share certain historical and cultural similarities."},{"n":"Saxony-Anhalt","lat":52.0,"lon":11.7,"s":162,"w":"Saxony-Anhalt","ty":"federated state of Germany","u":0,"b":"Saxony-Anhalt is a landlocked state of Germany. It covers an area of 20,555 square kilometres (7,936 sq mi) and has a population of about 2.14 million inhabitants, making it the 8th-largest state in Germany by area and the 11th-largest by population."},{"n":"East Germany","lat":52.052,"lon":12.389,"s":158,"w":"East Germany","ty":"historical country","u":0,"b":"East Germany, officially the German Democratic Republic (GDR), was a country in Central Europe from its formation on 7 October 1949 until its reunification with West Germany (Federal Republic of Germany) on 3 October 1990. Until 1989, it was generally viewed as a communist state and described itself as a socialist workers' and peasants' state."},{"n":"Nuremberg","lat":49.4539,"lon":11.0775,"s":157,"w":"Nuremberg","ty":"urban municipality in Germany|big city|urban district of Bavaria","u":0,"b":"Nuremberg is the second-largest city in the German state of Bavaria and the largest city in the cultural region of Franconia. Its 546,397 (2024) inhabitants make it the 13th-largest city in Germany."},{"n":"Potsdam","lat":52.4009,"lon":13.0591,"s":152,"w":"Potsdam","ty":"state capital in Germany|urban municipality in Germany|district independent city of Brande","u":0,"b":"Potsdam is the capital and largest city of the German state of Brandenburg. It is part of the Berlin/Brandenburg Metropolitan Region. Potsdam sits on the River Havel, a tributary of the Elbe, downstream of Berlin, and lies embedded in a hilly morainic landscape dotted with many lakes, around 20 of which are located within Potsdam's city limits."},{"n":"Szczecin","lat":53.4247,"lon":14.5553,"s":146,"w":"Szczecin","ty":"city|city with powiat rights in Poland|tourist destination|big city|Hanseatic city|border ","u":0,"b":"Szczecin, historically known in English as Stettin, is the capital and largest city of the West Pomeranian Voivodeship in northwestern Poland. Located near the Baltic Sea and the German border, it is a major seaport, the largest city of northwestern Poland, and seventh-largest city of Poland. As of 31 December 2022, the population was 391,566."},{"n":"Erfurt","lat":50.9781,"lon":11.0289,"s":144,"w":"Erfurt","ty":"big city|state capital in Germany|urban district of Thuringia|Lutherstadt|urban municipali","u":0,"b":"Erfurt is the capital and largest city of the Central German state of Thuringia, with a population of around 216,000."},{"n":"Magdeburg","lat":52.1316,"lon":11.64,"s":141,"w":"Magdeburg","ty":"Lutherstadt|college town|state capital in Germany|Hanseatic city|city|big city|independent","u":0,"b":"Magdeburg is the capital and most populous city of the German state of Saxony-Anhalt. The city is on the Elbe river. The city was mentioned for the first time in a documentary record as \"Magadoburg\" in the Capitulary of Diedenhofen by Charlemagne in 805."},{"n":"Berlin Wall","lat":52.5044,"lon":13.4411,"s":140,"w":"Berlin Wall","ty":"destroyed building or structure|separation barrier|defense line|cordon","u":0,"b":"The Berlin Wall was a guarded concrete barrier that encircled West Berlin from 1961 to 1989, separating it from East Berlin and the German Democratic Republic (GDR; East Germany). Construction of the Berlin Wall was commenced by the government of the GDR on 13 August 1961."},{"n":"German Empire","lat":52.5186,"lon":13.3761,"s":129,"w":"German Empire","ty":"historical country|historical period","u":0,"b":"The German Empire (German: Deutsches Reich), also referred to as Imperial Germany or the Second Reich, was the period of the German Reich from the unification of Germany in 1871 until the November Revolution in 1918, when Germany changed its form of government to a republic."},{"n":"Weimar","lat":50.9811,"lon":11.3294,"s":126,"w":"Weimar","ty":"urban district of Thuringia|college town|urban municipality in Germany|medium regional cen","u":0,"b":"Weimar is a city in the German state of Thuringia, in Central Germany between Erfurt to the west and Jena to the east, 80 km (50 mi) southwest of Leipzig, 170 km (106 mi) north of Nuremberg and 170 km (106 mi) west of Dresden. Together with the neighbouring cities of Erfurt and Jena, it forms the central metropolitan area of Thuringia, with approximately 500,000 inhabitants."},{"n":"Göttingen","lat":51.5339,"lon":9.9356,"s":125,"w":"Göttingen","ty":"Einheitsgemeinde of Lower Saxony|major regional center|urban district of Lower Saxony|spec","u":0,"b":"Göttingen is a university city in Lower Saxony, central Germany, the capital of the eponymous district. The River Leine runs through it. According to the 2022 German census, the population of Göttingen was 124,548."},{"n":"Würzburg","lat":49.7944,"lon":9.9294,"s":120,"w":"Würzburg","ty":"district capital|major regional center|urban district of Bavaria|city|big city|college tow","u":0,"b":"Würzburg is the second-largest city in Franconia after Nuremberg and is located in the north of Bavaria. Würzburg is the administrative seat of the Regierungsbezirk Lower Franconia."},{"n":"Kassel","lat":51.3158,"lon":9.4979,"s":119,"w":"Kassel","ty":"residenz|urban municipality in Germany|big city|district capital|major regional center|urb","u":0,"b":"Kassel is a city on the Fulda River in northern Hesse, in central Germany. It is the administrative seat of the Regierungsbezirk Kassel and the district of the same name, and had 201,048 inhabitants in December 2020. The former capital of the state of Hesse-Kassel, it has many palaces and parks, including the Bergpark Wilhelmshöhe, which is a UNESCO World Heritage Site."},{"n":"Brunswick","lat":52.2692,"lon":10.5211,"s":117,"w":"Braunschweig","ty":"urban district of Lower Saxony|urban municipality in Germany|big city|Hanseatic city|Einhe","u":0,"b":"Braunschweig or Brunswick is a city in Lower Saxony, Germany, north of the Harz Mountains at the farthest navigable point of the river Oker, which connects it to the North Sea via the rivers Aller and Weser. In 2025, it had a population of 255,500. The Braunschweig-Wolfsburg-Salzgitter region had 1.02 million residents including the cities Wolfsburg and Salzgitter."},{"n":"Jena","lat":50.9272,"lon":11.5864,"s":115,"w":"Jena","ty":"urban municipality in Germany|college town|Option municipality|major regional center|big c","u":0,"b":"Jena is a city in Germany and the second largest city in Thuringia. Together with the nearby cities of Erfurt and Weimar, it forms the central metropolitan area of Thuringia with approximately 500,000 inhabitants, while the city itself has a population of about 110,000. Jena is a centre of education and research."},{"n":"Uetersen","lat":53.6872,"lon":9.6692,"s":226,"w":"Uetersen","ty":"urban municipality in Germany","u":0,"b":"Uetersen (German pronunciation:, formerly known as Ütersen (Holstein)) is a town in the district of Pinneberg, in Schleswig-Holstein, Germany. It is situated approximately 7 km (4.3 mi) south of Elmshorn, and 30 km (19 mi) northwest of Hamburg at the small Pinnau River, close to the Elbe river."},{"n":"North Rhine-Westphalia","lat":51.4667,"lon":7.55,"s":184,"w":"North Rhine-Westphalia","ty":"federated state of Germany","u":0,"b":"North Rhine-Westphalia or North-Rhine/Westphalia (German: Nordrhein-Westfalen ), commonly shortened to NRW, is a landlocked state (Land) in Western Germany. With more than 18 million inhabitants, it is the most populous state in Germany. Apart from the city-states (Berlin, Hamburg and Bremen), it is also the most densely populated state in Germany."},{"n":"Schleswig-Holstein","lat":54.47,"lon":9.5142,"s":166,"w":"Schleswig-Holstein","ty":"federated state of Germany","u":0,"b":"Schleswig-Holstein is a coastal state that is the northernmost of the sixteen states of Germany, comprising most of the historical Duchy of Holstein and the southern part of the former Duchy of Schleswig. It borders Denmark, Mecklenburg-Vorpommern, Lower Saxony and the city-state of Hamburg. Its capital city is Kiel; other notable cities are Lübeck and Flensburg."},{"n":"Mecklenburg-Vorpommern","lat":53.75,"lon":12.5,"s":166,"w":"Mecklenburg-Vorpommern","ty":"federated state of Germany","u":0,"b":"Mecklenburg-Vorpommern, often known by its anglicised name Mecklenburg–West Pomerania, is a coastal state in the north-east of Germany. Of the country's sixteen states, Mecklenburg-Vorpommern ranks 14th in population; it covers an area of 23,300 km2 (9,000 sq mi), making it the sixth largest German state in area; and it is 16th in population density."},{"n":"Bremen","lat":53.0758,"lon":8.8072,"s":164,"w":"Bremen","ty":"urban municipality in Germany|urban district of Bremen|big city|college town|Hanseatic cit","u":0,"b":"Bremen, officially the City Municipality of Bremen, is the capital and most populous city of the German state of the Free Hanseatic City of Bremen (Freie Hansestadt Bremen), a two-city-state consisting of the city of Bremen itself, and Bremerhaven."},{"n":"Dortmund","lat":51.5139,"lon":7.4653,"s":153,"w":"Dortmund","ty":"major regional center|Hanseatic city|urban municipality in Germany|urban district of North","u":0,"b":"Dortmund (German:; Westphalian: Düörpm) is the third-largest city in North Rhine-Westphalia, after Cologne and Düsseldorf, and the ninth-largest city in Germany. With a population of 614,495 inhabitants, it is the largest city (by area and population) of the Ruhr as well as the largest city of Westphalia."},{"n":"Kiel","lat":54.3233,"lon":10.1394,"s":142,"w":"Kiel","ty":"urban district in Schleswig-Holstein|big city|state capital in Germany|Hanseatic city|majo","u":0,"b":"Kiel is the capital and most populous city in the northern German state of Schleswig-Holstein. With a population of around 250,000, it is Germany's largest city on the Baltic Sea."},{"n":"Lübeck","lat":53.8697,"lon":10.6864,"s":135,"w":"Lübeck","ty":"urban district in Schleswig-Holstein|major regional center|big city|urban municipality in ","u":0,"b":"Lübeck, officially the Hanseatic City of Lübeck (German: Hansestadt Lübeck), is a city in Northern Germany. With around 220,000 inhabitants, it is the second-largest city on the German Baltic coast and the second-largest city in the state of Schleswig-Holstein, after its capital, Kiel. It is the 36th-largest city in Germany."},{"n":"Essen","lat":51.4508,"lon":7.0131,"s":134,"w":"Essen","ty":"urban municipality in Germany|Option municipality|big city|Hanseatic city|urban district o","u":0,"b":"Essen is the central and, after Dortmund, second-largest city of the Ruhr, the largest urban area in Germany. Its population of 573,618 makes it the fourth-largest city of North Rhine-Westphalia after Cologne, Düsseldorf and Dortmund, as well as the tenth-largest city of Germany."},{"n":"Bremen","lat":53.1333,"lon":8.7333,"s":132,"w":"Bremen (state)","ty":"federated state of Germany|city-state|state of the German Confederation 1815–1848 & 1850–1","u":0,"b":"Bremen, officially the Free Hanseatic City of Bremen, is the smallest and least populous of Germany's 16 states. It is informally called Land Bremen ('State of Bremen'), although the term is sometimes used in official contexts."},{"n":"Münster","lat":51.9625,"lon":7.6256,"s":125,"w":"Münster","ty":"college town|big city|urban municipality in Germany|Hanseatic city|cycling city|urban dist","u":0,"b":"Münster (German:; Westphalian: Mönster) is an independent city (Kreisfreie Stadt) in North Rhine-Westphalia, Germany. It is in the northern part of the state and the historic capital of the Westphalia region, as well being the centre of a state district. During the Protestant Reformation, Münster was the location of the Anabaptist rebellion."},{"n":"Schwerin","lat":53.6289,"lon":11.415,"s":122,"w":"Schwerin","ty":"city|residenz|big city|state capital in Germany|major regional center|urban district of Me","u":0,"b":"Schwerin is the capital and second-largest city of the northeastern German state of Mecklenburg-Vorpommern as well as of the region of Mecklenburg, after Rostock. It has around 96,000 inhabitants, and is thus the least populous of all German state capitals."},{"n":"Rostock","lat":54.0833,"lon":12.1333,"s":120,"w":"Rostock","ty":"urban municipality in Germany|urban district of Mecklenburg-Vorpommern","u":0,"b":"Rostock, officially the Hanseatic and University City of Rostock (German: Hanse- und Universitätsstadt Rostock), is the largest city in the German state of Mecklenburg-Western Pomerania and lies in the Mecklenburgian part of the state, close to the border with Pomerania."},{"n":"Amsterdam","lat":52.3667,"lon":4.8833,"s":284,"w":"Amsterdam","ty":"city|big city|place with town rights and privileges|largest city|port city|national capita","u":0,"b":"Amsterdam (Dutch:; lit. 'Dam in the Amstel') is the capital and largest city of the Netherlands. As of 1 January 2026, it had a population of 941,873 within the city proper, 1,457,018 in the urban area and 2,480,394 in the metropolitan area."},{"n":"Dutch","lat":52.0001,"lon":5.0001,"s":257,"w":"Dutch language","ty":"modern natural language","u":0,"b":"Dutch (Endonym: Nederlands, Nederlandse taal) is a West Germanic language of the Indo-European language family, spoken by about 25 million people as a first language and 5 million as a second language and is the third most spoken Germanic language."},{"n":"Danish","lat":56.0,"lon":9.0,"s":213,"w":"Danish language","ty":"natural language|modern language|language|spoken language","u":0,"b":"Danish is a North Germanic language from the Indo-European language family spoken by about 5.5 million people, principally in and around Denmark. Communities of Danish speakers are also found in Greenland, the Faroe Islands, Iceland and the northern German region of Southern Schleswig, where it has minority language status."},{"n":"Ido","lat":52.36,"lon":4.9,"s":143,"w":"Ido","ty":"constructed language|Esperantido|international auxiliary language|planned language","u":0,"b":"Ido is a constructed language derived from a reformed version of Esperanto, and designed similarly with the goal of being an international auxiliary language (or universal second language) for people of diverse languages."},{"n":"Utrecht","lat":52.0908,"lon":5.1217,"s":137,"w":"Utrecht","ty":"municipality of the Netherlands|cycling city","u":0,"b":"Utrecht ( YOO-trekt; Dutch:; Utrecht dialect: Ut(e)reg) is the fourth-largest city of the Netherlands, as well as the capital and the most populous city of the province of Utrecht. The municipality of Utrecht is located in the eastern part of the Randstad conurbation, in the very centre of mainland Netherlands, and includes Haarzuilens, Vleuten and De Meern."},{"n":"Friesland","lat":53.2014,"lon":5.8,"s":128,"w":"Friesland","ty":"province of the Netherlands","u":0,"b":"Friesland, historically and traditionally known as Frisia, is a province of the Netherlands located in the north of the country. As of January 2023, the province had a population of about 660,000, and a total area of 5,753 km2 (2,221 sq mi). The land is mostly made up of grassland and has numerous lakes."},{"n":"North Holland","lat":52.6667,"lon":4.8333,"s":124,"w":"North Holland","ty":"province of the Netherlands","u":0,"b":"North Holland is a province of the Netherlands in the northwestern part of the country. It is located on the North Sea, north of South Holland and Utrecht, and west of Friesland and Flevoland. As of January 2023, it had a population of about 2,952,000 and a total area of 4,092 km2 (1,580 sq mi), of which 1,429 km2 (552 sq mi) is water."},{"n":"Gelderland","lat":52.0833,"lon":5.9167,"s":118,"w":"Gelderland","ty":"province of the Netherlands","u":0,"b":"Gelderland, also known as Guelders in English, is a province of the Netherlands, located in the centre-east of the country. With a total area of 5,136 km2 (1,983 sq mi) of which 176 km2 (68 sq mi) is water, it is the largest province of the Netherlands by land area, and second by total area."},{"n":"Bielefeld","lat":52.0167,"lon":8.5333,"s":118,"w":"Bielefeld","ty":"big city|urban district of North Rhine-Westphalia|urban municipality in Germany|college to","u":0,"b":"Bielefeld is a city in the Ostwestfalen-Lippe region in the north-east of North Rhine-Westphalia, Germany. With a population of 342,952, it is also the most populous city in the administrative region (Regierungsbezirk) of Detmold and the 18th largest city in Germany."},{"n":"Arnhem","lat":51.9833,"lon":5.9167,"s":117,"w":"Arnhem","ty":"municipality of the Netherlands|Hanseatic city|place with town rights and privileges|cadas","u":0,"b":"Arnhem (Dutch: or; German: Arnheim; Ernems: Èrnem) is a city and municipality situated in the eastern part of the Netherlands, near the German border. It is the capital of the province of Gelderland and its second-most populous municipality (after Nijmegen), located on both banks of the rivers Nederrijn and Sint-Jansbeek, which was the source of the city's development."},{"n":"Drenthe","lat":52.9167,"lon":6.5833,"s":115,"w":"Drenthe","ty":"province of the Netherlands","u":0,"b":"Drenthe is a province of the Netherlands located in the northeastern part of the country. It is bordered by Overijssel to the south, Friesland to the west, Groningen to the north, and the German state of Lower Saxony to the east. As of January 2023, Drenthe had a population of about 502,000, and a total area of 2,680 km2 (1,030 sq mi)."},{"n":"Groningen","lat":53.2189,"lon":6.5675,"s":115,"w":"Groningen","ty":"city|cycling city|place with town rights and privileges|fortified town|big city|cadastral ","u":0,"b":"Groningen is the capital city and main municipality of Groningen province in the Netherlands."},{"n":"Groningen","lat":53.2581,"lon":6.7378,"s":115,"w":"Groningen (province)","ty":"province of the Netherlands","u":0,"b":"Groningen is the northeasternmost province of the Netherlands. It borders on Friesland to the west, Drenthe to the south, the German state of Lower Saxony to the east, and the Wadden Sea to the north. As of January 2023, Groningen had a population of about 596,000, and a total area of 2,955 km2 (1,141 sq mi)."},{"n":"Odense","lat":55.4,"lon":10.3833,"s":115,"w":"Odense","ty":"big city","u":0,"b":"Odense is the third largest city in Denmark (after Copenhagen and Aarhus) and the largest city on the island of Funen. As of 1 January 2026, the city proper had a population of 187,558 while Odense Municipality had a population of 213,168, making it the fourth largest municipality in Denmark (behind Copenhagen, Aarhus and Aalborg municipalities)."},{"n":"Flevoland","lat":52.5333,"lon":5.6667,"s":114,"w":"Flevoland","ty":"province of the Netherlands","u":0,"b":"Flevoland is the twelfth and newest province of the Netherlands, established in 1986, when the southern and eastern Flevopolders, together with the Noordoostpolder, were merged into one provincial entity. It is in the centre of the country in the former Zuiderzee, which was turned into the freshwater IJsselmeer by the closure of the Afsluitdijk in 1932."},{"n":"Utrecht","lat":52.1033,"lon":5.1792,"s":112,"w":"Utrecht (province)","ty":"province of the Netherlands","u":0,"b":"Utrecht, officially the Province of Utrecht (Dutch: Provincie Utrecht), is a province of the Netherlands. It is located in the centre of the country, bordering the Eemmeer in the north-east, the province of Gelderland in the east and south-east, the province of South Holland in the west and south-west and the province of North Holland in the north-west and north."},{"n":"Overijssel","lat":52.5,"lon":6.5,"s":111,"w":"Overijssel","ty":"province of the Netherlands","u":0,"b":"Overijssel is a province of the Netherlands located in the eastern part of the country. The province borders Drenthe to the north, Friesland to the north-west, Flevoland (and a small part of the IJsselmeer) to the west, Gelderland to the south and west, and Germany's states of Lower Saxony and North Rhine-Westphalia to the east."},{"n":"Gelsenkirchen","lat":51.5103,"lon":7.0942,"s":111,"w":"Gelsenkirchen","ty":"urban municipality in Germany|urban district of North Rhine-Westphalia|big city","u":0,"b":"Gelsenkirchen is the 26th-most populous city of Germany and the 12th-most populous in the state of North Rhine-Westphalia with a population of 266,199 as of 2025. On the Emscher River (a tributary of the Rhine), it lies at the centre of the Ruhr area, the largest urban area of Germany, of which it is the fifth-largest city after Dortmund, Essen, Duisburg and Bochum."},{"n":"Leiden","lat":52.16,"lon":4.49,"s":111,"w":"Leiden","ty":"city|municipality of the Netherlands|place with town rights and privileges|cadastral popul","u":0,"b":"Leiden is a city and municipality in the province of South Holland, Netherlands. The municipality of Leiden has a population of 127,046 (31 January 2023), but the city forms one densely connected agglomeration with its suburbs Oegstgeest, Leiderdorp, Voorschoten and Zoeterwoude with 215,602 inhabitants."},{"n":"Nijmegen","lat":51.8475,"lon":5.8625,"s":110,"w":"Nijmegen","ty":"municipality of the Netherlands","u":0,"b":"Nijmegen is the largest city in the Dutch province of Gelderland and the ninth largest of the Netherlands as a whole. Located on the Waal River close to the German border, Nijmegen is one of the oldest cities in the Netherlands and the first to be recognized as such in Roman times. In 2005, it celebrated 2,000 years of existence."},{"n":"Wolfsburg","lat":52.4231,"lon":10.7872,"s":110,"w":"Wolfsburg","ty":"major regional center|big city|planned community|urban municipality in Germany|urban distr","u":0,"b":"Wolfsburg (German:; Eastphalian: Wulfsborg) is the fifth-largest city in the German state of Lower Saxony. It lies on the river Aller, 75 kilometres (47 mi) east of Hanover and 230 kilometres (143 mi) west of Berlin. Wolfsburg is famous as the location of Volkswagen AG's headquarters and, until it was overtaken by Tesla Gigafactory Texas in 2022, the world's biggest car plant."},{"n":"Haarlem","lat":52.3814,"lon":4.6356,"s":109,"w":"Haarlem","ty":"place with town rights and privileges|cadastral populated place in the Netherlands|big cit","u":0,"b":"Haarlem is a city and municipality in the Netherlands. It is the capital of the province of North Holland. Haarlem is situated at the northern edge of the Randstad, one of the most populated metropolitan areas in Europe; it is also part of the Amsterdam metropolitan area."},{"n":"Leeuwarden","lat":53.2,"lon":5.7833,"s":107,"w":"Leeuwarden","ty":"city|cadastral populated place in the Netherlands|place with town rights and privileges","u":0,"b":"Leeuwarden (Dutch:; West Frisian: Ljouwert; Stadsfries Dutch: Liwwadden; Leeuwarder dialect: Leewarden) is a city and municipality in Friesland, Netherlands, with a population of 130,162 (2026). It is the provincial capital and seat of the Provincial Council of Friesland. The region has been continuously inhabited since the 10th century."},{"n":"Osnabrück","lat":52.2789,"lon":8.0431,"s":106,"w":"Osnabrück","ty":"independent city of Germany|urban district of Lower Saxony|college town|Hanseatic city|Ein","u":0,"b":"Osnabrück is a city in Lower Saxony in western Germany. It is situated on the river Hase in a valley penned between the Wiehen Hills and the northern tip of the Teutoburg Forest. With a population of 166,057 Osnabrück is the fourth largest city in Lower Saxony."},{"n":"Zwolle","lat":52.5167,"lon":6.1,"s":103,"w":"Zwolle","ty":"municipality of the Netherlands|big city|Hanseatic city|place with town rights and privile","u":0,"b":"Zwolle is a city and municipality in the Northeastern Netherlands. It is the capital of the province of Overijssel and the province's second-largest municipality, after Enschede, and has a population of 132,441 as of December 2023. Zwolle borders the province of Gelderland and lies on the eastern side of the River IJssel."},{"n":"North Sea","lat":55.0,"lon":3.0,"s":194,"w":"North Sea","ty":"sea","u":0,"b":"The North Sea lies between Great Britain, Denmark, Norway, Germany, the Netherlands, Belgium, and France. A sea on the European continental shelf, it connects to the Atlantic Ocean through the English Channel in the south and the Norwegian Sea in the north."},{"n":"Assen","lat":52.9953,"lon":6.5606,"s":100,"w":"Assen","ty":"municipality of the Netherlands|city","u":0,"b":"Assen is a city and municipality in the Northeastern Netherlands, and is the capital of the province of Drenthe. It received city rights in 1809. Assen is known for TT Circuit Assen, the motorcycle racing circuit, where on the last Sunday in June the Dutch TT is run; and also for the annual Assen Dance Festival."},{"n":"Lelystad","lat":52.5167,"lon":5.4833,"s":93,"w":"Lelystad","ty":"municipality of the Netherlands","u":0,"b":"Lelystad is a Dutch municipality and the capital city of the province of Flevoland in the central Netherlands. The city, built on reclaimed land, was founded in 1967 and was named after Cornelis Lely, who engineered the Afsluitdijk that made the reclamation possible. Lelystad is situated approximately three metres (10 feet) below sea level."},{"n":"Alkmaar","lat":52.6289,"lon":4.744,"s":92,"w":"Alkmaar","ty":"municipality of the Netherlands","u":0,"b":"Alkmaar is a city and municipality in the Netherlands, located in the province of North Holland. Alkmaar is well known for its traditional cheese market. For tourists, it is a popular cultural destination."},{"n":"Heligoland","lat":54.1825,"lon":7.8853,"s":88,"w":"Heligoland","ty":"coastal spa|archipelago|car-free place|municipality without town privileges in Germany","u":0,"b":"Heligoland is a small archipelago in the North Sea, administratively part of the German state of Schleswig-Holstein."},{"n":"Wilhelmshaven","lat":53.5286,"lon":8.1056,"s":83,"w":"Wilhelmshaven","ty":"urban district of Lower Saxony|Einheitsgemeinde of Lower Saxony|major regional center|urba","u":0,"b":"Wilhelmshaven is a coastal town in Lower Saxony, Germany. It is situated on the western side of the Jade Bight, a bay of the North Sea, and has a population of 76,089. Wilhelmshaven is the centre of the \"Jade Buse\" business region (which has around 330,000 inhabitants) and is Germany's main military port."},{"n":"Emden","lat":53.3669,"lon":7.2061,"s":83,"w":"Emden","ty":"urban district of Lower Saxony","u":0,"b":"Emden is an independent town and seaport in Lower Saxony in the north-west of Germany and lies on the River Ems, close to the Netherlands border. It is the main town in the region of East Frisia and had a total population of 50,535 in 2022."},{"n":"Texel","lat":53.0667,"lon":4.8,"s":82,"w":"Texel","ty":"place with town rights and privileges|municipality of the Netherlands","u":0,"b":"Texel is a municipality and an island with a population of 13,846 in North Holland, Netherlands. It is the largest and most populated island of the West Frisian Islands in the Wadden Sea. The island is situated north of Den Helder, northeast of Noorderhaaks, and southwest of Vlieland."},{"n":"Hoorn","lat":52.6533,"lon":5.0733,"s":81,"w":"Hoorn","ty":"municipality of the Netherlands","u":0,"b":"Hoorn is a city and municipality in the northwest of the Netherlands, in the province of North Holland. It is the largest town and the traditional capital of the region of West Friesland. Hoorn is located on the Markermeer, 20 kilometers (12 mi) east of Alkmaar and 35 kilometers (22 mi) north of Amsterdam."},{"n":"West Frisian","lat":53.0,"lon":5.6,"s":79,"w":"West Frisian language","ty":"modern language|natural language","u":0,"b":"West Frisian (Westerlauwersk Frysk; Dutch: Westerlauwers Fries), or simply Frisian (Frysk; Dutch: Fries), is a West Germanic language spoken mostly in the province of Friesland (Fryslân) in the north of the Netherlands, mostly by those of Frisian ancestry. It is the most widely spoken of the Frisian languages."},{"n":"Wadden Sea","lat":53.5333,"lon":6.8833,"s":75,"w":"Wadden Sea","ty":"geotope|marginal sea|biotope","u":0,"b":"The Wadden Sea (Dutch: Waddenzee; German: Wattenmeer; Low German: Wattensee or Waddenzee; Danish: Vadehavet; West Frisian: Waadsee; North Frisian: di Heef) is an intertidal zone in the southeastern part of the North Sea."},{"n":"Den Helder","lat":52.9583,"lon":4.7589,"s":72,"w":"Den Helder","ty":"municipality of the Netherlands","u":0,"b":"Den Helder is an industrial port town in the Netherlands, in the province of North Holland. Den Helder occupies the northernmost point of the North Holland peninsula. It is home to the country's main naval base."},{"n":"Zaanstad","lat":52.4697,"lon":4.7767,"s":70,"w":"Zaanstad","ty":"municipality of the Netherlands","u":0,"b":"Zaanstad is a Dutch municipality in the province of North Holland, situated northwest of Amsterdam. Its main settlement is Zaandam. It is part of the conurbation and metropolitan area of Amsterdam."},{"n":"Emmen","lat":52.7833,"lon":6.9,"s":69,"w":"Emmen, Netherlands","ty":"municipality of the Netherlands","u":0,"b":"Emmen is a municipality and city of the province of Drenthe in the northeastern Netherlands."},{"n":"Heerenveen","lat":52.9658,"lon":6.0503,"s":67,"w":"Heerenveen","ty":"municipality of the Netherlands","u":0,"b":"Heerenveen is a town and municipality in the province of Friesland (Fryslân), in the Northern Netherlands. In 2021, the town had a population of 29,790 (1 January) while the municipality in 2026 had a population of 51,955. The town itself is located southeast of Sneek and southwest of Drachten."},{"n":"Saterland Frisian","lat":53.0333,"lon":7.7167,"s":66,"w":"Saterland Frisian language","ty":"natural language|dialect|modern language","u":0,"b":"Saterland Frisian, also known as Sater Frisian, Saterfrisian or Saterlandic (Seeltersk), spoken in the Saterland municipality of Lower Saxony in Germany, is the last living dialect of the East Frisian language. It is closely related to the other Frisian languages: North Frisian, spoken in Germany as well, and West Frisian, spoken in the Dutch province of Friesland."},{"n":"Borkum","lat":53.5881,"lon":6.6697,"s":66,"w":"Borkum","ty":"coastal spa|border city|urban municipality in Germany|Einheitsgemeinde of Lower Saxony","u":0,"b":"Borkum is an island and a town in the Leer District in Lower Saxony, northwestern Germany. It is situated in the Wadden Sea, to the east of Rottumeroog and west of Juist. In 2025 a tradition where boys would chase girls to beat their buttocks each 5 December was discontinued."},{"n":"Battle of the Teutoburg Forest","lat":52.4075,"lon":8.1258,"s":65,"w":"Battle of the Teutoburg Forest","ty":"battle","u":0,"b":"The Battle of the Teutoburg Forest, also called the Varian Disaster (Latin: Clades Variana) by Roman historians, was a major battle fought between an alliance of Germanic peoples and the Roman Empire between 8 and 11 September 9 AD, possibly near modern Kalkriese."},{"n":"Aurich","lat":53.4714,"lon":7.4836,"s":65,"w":"Aurich","ty":"urban municipality in Germany|independent community|district capital|port city|Einheitsgem","u":0,"b":"Aurich is a town in the East Frisian region of Lower Saxony, Germany. It is the capital of the district of Aurich and is the second largest City in East Frisia, both in population, after Emden, and in area, after Wittmund."},{"n":"Norderney","lat":53.7072,"lon":7.1469,"s":64,"w":"Norderney","ty":"urban municipality in Germany|Einheitsgemeinde of Lower Saxony|coastal spa","u":0,"b":"Norderney is one of the seven populated East Frisian Islands off the North Sea coast of Germany. The island is 14 by 2.5 kilometres (8.7 by 1.6 mi), having a total area of about 26.3 square kilometres (10.2 sq mi) and is therefore Germany's ninth-largest island. Norderney's population amounts to about 5,850 people."},{"n":"Purmerend","lat":52.505,"lon":4.9639,"s":63,"w":"Purmerend","ty":"city|cadastral populated place in the Netherlands|place with town rights and privileges","u":0,"b":"Purmerend is a city and municipality in the west of the Netherlands, in the province of North Holland. The city is surrounded by polders, such as the Purmer, Beemster and the Wormer. Purmerend's population grew relatively slowly until the 1960s, when it increased from around 10,000 to over 80,000 by 2020."},{"n":"Schiermonnikoog","lat":53.49,"lon":6.225,"s":63,"w":"Schiermonnikoog","ty":"island|car-free place|municipality of the Netherlands|cadastral populated place in the Net","u":0,"b":"Schiermonnikoog is an island, a municipality and national park in the Northern Netherlands. Schiermonnikoog is one of the West Frisian Islands, and is part of the province of Friesland. It is situated between the islands of Ameland and Rottumerplaat."},{"n":"Leer","lat":53.2308,"lon":7.4528,"s":61,"w":"Leer, Lower Saxony","ty":"independent community|Einheitsgemeinde of Lower Saxony|urban municipality in Germany|distr","u":0,"b":"Leer is a town in the district of Leer in the region of East Frisia, in the northwestern part of Lower Saxony, Germany. It is situated on the river Leda, a tributary of the river Ems, near the border with the Netherlands. With 34,958 inhabitants (2021), it is the third-largest city in East Frisia after Emden and Aurich."},{"n":"Hoogeveen","lat":52.7167,"lon":6.4667,"s":61,"w":"Hoogeveen","ty":"municipality of the Netherlands","u":0,"b":"Hoogeveen is a municipality and town in the Dutch province of Drenthe. It is located in the south of the province and shares a provincial border with Overijssel. The municipality has a population of 56,897 (2025), of which 40,560 reside in the town of Hoogeveen itself."},{"n":"Delfzijl","lat":53.3333,"lon":6.9167,"s":60,"w":"Delfzijl","ty":"place with town rights and privileges|cadastral populated place in the Netherlands|city","u":0,"b":"Delfzijl (Dutch:; Gronings: Delfziel) is a city and former municipality (which now belongs to the municipality of Eemsdelta) with a population of 25,651 in the province of Groningen in the northeast of the Netherlands. Delfzijl was a sluice between the Delf and the Ems, which became fortified settlement in the 16th century."},{"n":"Ems","lat":53.3256,"lon":7.2447,"s":60,"w":"Ems (river)","ty":"river","u":0,"b":"The Ems (German: Ems; Dutch: Eems ) is a river in northwestern Germany. It runs through the states of North Rhine-Westphalia and Lower Saxony, and discharges into the Dollart Bay which is part of the Wadden Sea. Its total length is 362.4 kilometres (225.2 mi)."},{"n":"Urk","lat":52.6631,"lon":5.5986,"s":60,"w":"Urk","ty":"municipality of the Netherlands|cadastral populated place in the Netherlands|town","u":0,"b":"Urk (Dutch:; Urkers: Urrek; Dutch Low Saxon: Ürrek) is a municipality and a town in the Flevoland province in the center-north of the Netherlands with a population of 22,173 as of 2025. It is surrounded by the Noordoostpolder on land and is on the coast of the IJsselmeer."},{"n":"Meppel","lat":52.7033,"lon":6.1917,"s":60,"w":"Meppel","ty":"municipality of the Netherlands","u":0,"b":"Meppel is a city and municipality in the Northeastern Netherlands. It constitutes the southwestern part of the province of Drenthe. Meppel is the smallest municipality in Drenthe, with a total area of about 57 km2 (22 sq mi)."},{"n":"Dronten","lat":52.5242,"lon":5.7125,"s":60,"w":"Dronten","ty":"municipality of the Netherlands","u":0,"b":"Dronten is a municipality and a town in the central Netherlands, in the province of Flevoland. It had a population of 42,011 in 2021."},{"n":"Enkhuizen","lat":52.7,"lon":5.2833,"s":60,"w":"Enkhuizen","ty":"municipality of the Netherlands|city|cadastral populated place in the Netherlands|place wi","u":0,"b":"Enkhuizen is a historic city and municipality in the Netherlands. Located in the region of West Friesland in the province of North Holland, the city developed as an important fishing and trading port during the Middle Ages and the Dutch Golden Age, when it was one of the wealthiest and most influential cities in the country."},{"n":"Edinburgh","lat":55.9533,"lon":-3.1892,"s":192,"w":"Edinburgh","ty":"big city|lieutenancy area of Scotland|college town|city of the United Kingdom","u":0,"b":"Edinburgh is the capital city of Scotland and one of its 32 council areas. It is located in southeast Scotland and is bounded to the north by the Firth of Forth and to the south by the Pentland Hills. Edinburgh had a population of 506,520 in 2020, making it the second-most-populous city in Scotland (behind Glasgow) and the seventh-most-populous in the United Kingdom."},{"n":"Great Britain","lat":53.8333,"lon":-2.4167,"s":174,"w":"Great Britain","ty":"island","u":0,"b":"Great Britain is an island in the North Atlantic Ocean off the north-west coast of continental Europe, consisting of the countries England, Scotland and Wales, which comprise most of the United Kingdom. With an area of 209,331 km2 (80,823 sq mi), it is the largest of the British Isles, the largest European island, and the ninth-largest island in the world."},{"n":"Leeds","lat":53.7975,"lon":-1.5436,"s":136,"w":"Leeds","ty":"city|big city|college town|unparished area","u":0,"b":"Leeds is a city in West Yorkshire, England. It is the largest settlement in Yorkshire and the administrative centre of the City of Leeds Metropolitan Borough, which is the second most populous district in the United Kingdom. It is built around the River Aire and is in the eastern foothills of the Pennines."},{"n":"York","lat":53.95,"lon":-1.0833,"s":129,"w":"York","ty":"big city|county town|unparished area|city","u":0,"b":"York is a cathedral city in North Yorkshire, England, with Roman origins, sited at the confluence of the rivers Ouse and Foss. It has many historic buildings and other structures, including the minster, castle and city walls, all of which are Grade I listed. It is the traditional county town of Yorkshire, and the administrative centre of the City of York district."},{"n":"Aberdeen","lat":57.15,"lon":-2.1,"s":129,"w":"Aberdeen","ty":"human settlement|city|big city","u":0,"b":"Aberdeen is a port city in North East Scotland, and is the third most populous Scottish city. Historically, Aberdeen was within the historic county of Aberdeenshire, but is now separate from the council area of Aberdeenshire. Aberdeen City Council is one of Scotland's 32 local authorities (commonly referred to as councils)."},{"n":"Scots","lat":57.0,"lon":-3.0,"s":120,"w":"Scots language","ty":"modern language|natural language","u":0,"b":"Scots is an Anglic language variety of West Germanic origin descended from Early Middle English. Thus, Modern Scots is a sister language of Modern English. Scots is classified as an official language of Scotland, a regional or minority language of Europe, and a vulnerable language by UNESCO."},{"n":"Newcastle upon Tyne","lat":54.9778,"lon":-1.6133,"s":119,"w":"Newcastle upon Tyne","ty":"unparished area|big city|civil parish|city","u":0,"b":"Newcastle upon Tyne, or simply Newcastle, is a city and metropolitan borough, in Tyne and Wear, England. While the hyphenated form of the name, Newcastle-upon-Tyne, is seen sometimes, correct usage is generally unhyphenated. It is England's northernmost city, sited on the river Tyne's northern bank opposite Gateshead to the south."},{"n":"Dundee","lat":56.4606,"lon":-2.97,"s":100,"w":"Dundee","ty":"city|big city|lieutenancy area of Scotland","u":0,"b":"Dundee is the fourth-largest city in Scotland. The 2020 mid-year population estimate for the locality was 148,210. It lies within the eastern central Lowlands on the north bank of the Firth of Tay, which feeds into the North Sea."},{"n":"Northumberland","lat":55.1667,"lon":-2.0,"s":92,"w":"Northumberland","ty":"ceremonial county of England|unitary authority area|non-metropolitan county","u":0,"b":"Northumberland is a ceremonial county in North East England, on the border with Scotland. It is bordered by the North Sea to the east, Tyne and Wear and County Durham to the south, Cumbria to the west, and the Scottish Borders council area to the north. The town of Blyth is the largest settlement."},{"n":"Cumbria","lat":54.5,"lon":-3.25,"s":91,"w":"Cumbria","ty":"non-metropolitan county|ceremonial county of England","u":0,"b":"Cumbria is a ceremonial county in North West England. It borders the Scottish council areas of Dumfries and Galloway and Scottish Borders to the north; the English ceremonial counties of Northumberland and County Durham to the east, North Yorkshire to the south-east, and Lancashire to the south; and the Irish Sea to the west. Its largest settlement is the city of Carlisle."},{"n":"Kingston upon Hull","lat":53.7444,"lon":-0.3325,"s":90,"w":"Kingston upon Hull","ty":"city","u":0,"b":"Kingston upon Hull, or simply Hull, is a port city and unitary authority area in the East Riding of Yorkshire, England. It lies upon the River Hull at its confluence with the Humber Estuary, 25 miles (40 km) inland from the North Sea."},{"n":"Yorkshire","lat":53.9583,"lon":-1.0833,"s":89,"w":"Yorkshire","ty":"historical region|historic county of England","u":0,"b":"Yorkshire is an area of Northern England which was historically a county. Despite no longer being used for administration, Yorkshire retains a strong regional identity. The county was named after the city of York."},{"n":"Durham","lat":54.7833,"lon":-1.5667,"s":86,"w":"Durham, England","ty":"county town|city","u":0,"b":"Durham is a cathedral city and civil parish in County Durham, England. It is the county town and contains the headquarters of Durham County Council, the unitary authority which governs the district of County Durham. The built-up area had a population of 50,510 at the 2021 Census."},{"n":"County Durham","lat":54.6667,"lon":-1.8333,"s":84,"w":"County Durham","ty":"ceremonial county of England","u":0,"b":"County Durham, also called simply Durham, is a ceremonial county in North East England. The county borders Northumberland and Tyne and Wear to the north, the North Sea to the east, North Yorkshire to the south, and Cumbria to the west. The largest settlement is Darlington."},{"n":"Middlesbrough","lat":54.5739,"lon":-1.2333,"s":84,"w":"Middlesbrough","ty":"unparished area|big city|town","u":0,"b":"Middlesbrough, colloquially known as Boro, is a port town and unitary authority of North Yorkshire, located in North East England. Situated on the southern bank of the River Tees, Middlesbrough forms part of the Borough of Middlesbrough, the Teesside built-up area and the Tees Valley."},{"n":"North Yorkshire","lat":54.1,"lon":-1.35,"s":83,"w":"North Yorkshire","ty":"ceremonial county of England","u":0,"b":"North Yorkshire is a ceremonial county in Northern England. It is bordered by County Durham to the north, the North Sea to the east, the East Riding of Yorkshire to the south-east, South Yorkshire to the south, West Yorkshire to the south-west, and Cumbria and Lancashire to the west."},{"n":"Hadrian's Wall","lat":55.0242,"lon":-2.2925,"s":82,"w":"Hadrian's Wall","ty":"Roman limes|Roman archaeological site|cordon|international border","u":1,"b":"Hadrian's Wall is a former defensive fortification of the Roman province of Britannia, begun in AD 122 in the reign of the Emperor Hadrian."},{"n":"Sunderland","lat":54.9044,"lon":-1.3811,"s":81,"w":"Sunderland","ty":"city|big city|unparished area","u":0,"b":"Sunderland is a port city in the county of Tyne and Wear in North East England. It is a port at the mouth of the River Wear on the North Sea, approximately 10 miles (16 km) south-east of Newcastle upon Tyne. It is the most populous settlement in the Wearside conurbation and the second-most populous settlement, after Newcastle."},{"n":"West Yorkshire","lat":53.75,"lon":-1.6667,"s":81,"w":"West Yorkshire","ty":"metropolitan county|ceremonial county of England","u":0,"b":"West Yorkshire is a metropolitan and ceremonial county in the Yorkshire and the Humber region of England. It borders North Yorkshire to the north and east, South Yorkshire and Derbyshire to the south, Greater Manchester to the south-west, and Lancashire to the west. The city of Leeds is the largest settlement."},{"n":"Tyne and Wear","lat":54.974,"lon":-1.6132,"s":80,"w":"Tyne and Wear","ty":"metropolitan county|ceremonial county of England","u":0,"b":"Tyne and Wear is a ceremonial county in North East England. It borders Northumberland to the north and County Durham to the south, and the largest settlement is the city of Newcastle upon Tyne. The county is largely urbanised, with an area of 540 square kilometres (210 sq mi) and an estimated population of 1,178,389 in 2024."},{"n":"East Riding of Yorkshire","lat":53.9167,"lon":-0.5,"s":79,"w":"East Riding of Yorkshire","ty":"ceremonial county of England","u":0,"b":"The East Riding of Yorkshire, often abbreviated to the East Riding or East Yorkshire, is a ceremonial county in the Yorkshire and the Humber region of England. It borders North Yorkshire to the north and west, South Yorkshire to the south-west, and Lincolnshire to the south across the Humber Estuary. The city of Kingston upon Hull is the largest settlement."},{"n":"Battle of Britain","lat":54.0,"lon":-2.0,"s":77,"w":"Battle of Britain","ty":"dogfight","u":0,"b":"The Battle of Britain was a military campaign of the Second World War, in which the Royal Air Force (RAF) and the Fleet Air Arm (FAA) of the Royal Navy defended the United Kingdom against large-scale attacks by Nazi Germany's air force, the Luftwaffe. It was the first major military campaign fought entirely by air forces."},{"n":"North West England","lat":54.075,"lon":-2.75,"s":77,"w":"North West England","ty":"region of England|ITL 1 statistical regions of England","u":0,"b":"North West England is one of nine official regions of England and consists of the ceremonial counties of Cheshire, Cumbria, Greater Manchester, Lancashire and Merseyside. The North West had a population of 7,417,397 in 2021. It is the third-most-populated region in the United Kingdom, after the South East and Greater London."},{"n":"Carlisle","lat":54.8947,"lon":-2.9364,"s":77,"w":"Carlisle","ty":"city|unparished area|civil parish|county town|city of United Kingdom","u":0,"b":"Carlisle is a city located in the Cumberland district of Cumbria, England. It is the largest settlement and only city in Cumbria. In 2021, it had a population of 77,730."},{"n":"Lancaster","lat":54.0489,"lon":-2.8014,"s":73,"w":"Lancaster, Lancashire","ty":"city|unparished area|county town","u":0,"b":"Lancaster is a city in Lancashire, England, and the main cultural, economic and commercial centre of City of Lancaster district. The city is on the River Lune, directly inland from Morecambe Bay. Lancaster is the county town, although Lancashire County Council has been based at County Hall in Preston since its formation in 1889."},{"n":"North East England","lat":55.0,"lon":-1.8667,"s":73,"w":"North East England","ty":"ITL 1 statistical regions of England|region of England","u":0,"b":"North East England is one of nine official regions of England. It consists of County Durham, Northumberland, Tyne and Wear and part of North Yorkshire. With 2.6 million residents in 2022, it is the least populous region of England."},{"n":"Aberdeenshire","lat":57.151,"lon":-2.123,"s":71,"w":"Aberdeenshire","ty":"council area","u":0,"b":"Aberdeenshire is one of the 32 council areas of Scotland. It takes its name from the historic county of Aberdeenshire, which had substantially different boundaries. The Aberdeenshire Council area includes all of the areas of the historic counties of Aberdeenshire and Kincardineshire except the area making up Aberdeen City Council area, as well as part of Banffshire."},{"n":"Yorkshire and the Humber","lat":53.5667,"lon":-1.2,"s":67,"w":"Yorkshire and the Humber","ty":"ITL 1 statistical regions of England|region of England","u":0,"b":"Yorkshire and the Humber is one of the nine official regions of England at the first level of ITL for statistical purposes. It is one of the three regions covering Northern England, alongside the North West England and North East England regions, and covers the historic and cultural Yorkshire area."},{"n":"Doncaster","lat":53.5228,"lon":-1.1325,"s":65,"w":"Doncaster","ty":"unparished area|city","u":0,"b":"Doncaster is a city in South Yorkshire, England. Named after the River Don, it is the administrative centre of the City of Doncaster metropolitan borough, and is the second largest settlement in South Yorkshire after Sheffield. Noted for its racing and railway history, it is situated in the Don Valley on the western edge of the Humberhead Levels and east of the Pennines."},{"n":"Fife","lat":56.25,"lon":-3.2,"s":64,"w":"Fife","ty":"Scottish region|council area|registration county|peninsula|lieutenancy area of Scotland","u":0,"b":"Fife is a council area and lieutenancy area in Scotland. A peninsula, it is bordered by the Firth of Tay to the north, the North Sea to the east, the Firth of Forth to the south, Clackmannanshire to the south-west, and Perth and Kinross to the west. The largest settlement is the city of Dunfermline, and the administrative centre is Glenrothes."},{"n":"Balmoral Castle","lat":57.0407,"lon":-3.2302,"s":62,"w":"Balmoral Castle","ty":"museum|Residence of the British Royal Family|estate|garden|country house|château","u":0,"b":"Balmoral Castle is a large estate house in Aberdeenshire, Scotland, and a residence of the British royal family. It is near the village of Crathie, 9 miles (14 km) west of Ballater and 50 miles (80 km) west of Aberdeen. The estate and its original castle were bought from the Farquharson family in 1852 by Prince Albert, the husband of Queen Victoria."},{"n":"Kingdom of Northumbria","lat":55.0,"lon":-2.5,"s":61,"w":"Northumbria","ty":"historical country","u":0,"b":"Northumbria was an early medieval English kingdom, existing between 654 and 1066 AD, at its height spanning modern-day Northern England and Southern Scotland. The name derives from the Old English Norþhymbre meaning \"the people or province north of the Humber\", as opposed to the people south of the Humber Estuary."},{"n":"Pennines","lat":54.7028,"lon":-2.4867,"s":60,"w":"Pennines","ty":"mountain range","u":0,"b":"The Pennines, also known as the Pennine Chain or Pennine Hills, are an upland range mainly located in Northern England. Sometimes described as the \"backbone of England\" because of its length and position, the range runs from Derbyshire and Staffordshire in the north of the Midlands to Northumberland in North East England."},{"n":"Lake District","lat":54.5,"lon":-3.1667,"s":59,"w":"Lake District","ty":"mountain range|lake area|region","u":1,"b":"The Lake District, also known as the Lakes or Lakeland, is a mountainous region and national park in Cumbria, North West England. It is famous for its landscape, including its lakes, coast, and mountains, and for its literary associations with Beatrix Potter, John Ruskin, Arthur Ransome, and the Lake Poets."},{"n":"Scotland","lat":57.0,"lon":-5.0,"s":278,"w":"Scotland","ty":"constituent country of the United Kingdom","u":0,"b":"Scotland (Scots: Scotland; Scottish Gaelic: Alba) is a country that is part of the United Kingdom, consisting of the northern part of the island of Great Britain and adjacent islands, principally in the archipelagos of the Hebrides and the Northern Isles. In 2022 the country's population was about 5.4 million."},{"n":"Glasgow","lat":55.8611,"lon":-4.25,"s":175,"w":"Glasgow","ty":"lieutenancy area of Scotland|city|largest city|big city","u":0,"b":"Glasgow is the most populous city in Scotland, located on the banks of the River Clyde in west central Scotland. It is the third-most populous city in the United Kingdom and comprises 23 wards which represent the areas within the city boundaries."},{"n":"Belfast","lat":54.5967,"lon":-5.93,"s":162,"w":"Belfast","ty":"largest city|big city|city","u":0,"b":"Belfast is the capital, largest city and main port of Northern Ireland. It stands on the banks of the river Lagan, and is connected to the open sea through Belfast Lough and the North Channel."},{"n":"Scottish Gaelic","lat":58.1,"lon":-6.6,"s":139,"w":"Scottish Gaelic","ty":"natural language|modern language","u":0,"b":"Scottish Gaelic, also known as Scots Gaelic or simply Gaelic, is a Celtic language native to the Gaels of Scotland. As a member of the Goidelic branch of Celtic, Scottish Gaelic, alongside both Irish and Manx, developed out of Old Irish."},{"n":"Inverness","lat":57.4839,"lon":-4.2258,"s":93,"w":"Inverness","ty":"large burgh|city","u":0,"b":"Inverness is a city in the Scottish Highlands in the north of Scotland. Long regarded as the de facto capital of the Scottish Highlands, it is the administrative centre for The Highland Council region whose headquarters are located close to the city centre."},{"n":"Stirling","lat":56.1166,"lon":-3.9369,"s":79,"w":"Stirling","ty":"large burgh|city","u":0,"b":"Stirling is a city in central Scotland, 26 miles (42 km) north-east of Glasgow and 37 miles (60 km) north-west of Edinburgh. The city is surrounded by rich farmland and had a royal citadel, the medieval old town with its merchants and tradesmen, the Old Bridge and the port are all linked to its history."},{"n":"Loch Ness","lat":57.3,"lon":-4.45,"s":79,"w":"Loch Ness","ty":"lake","u":0,"b":"Loch Ness is a large freshwater loch in the Scottish Highlands. It takes its name from the River Ness, which flows from the northern end. Loch Ness is best known for claimed sightings of the cryptozoological Loch Ness Monster, also known affectionately as \"Nessie\" (Scottish Gaelic: Niseag)."},{"n":"Ben Nevis","lat":56.7969,"lon":-5.0037,"s":78,"w":"Ben Nevis","ty":"mountain","u":0,"b":"Ben Nevis is the highest mountain in Scotland, the United Kingdom, and the British Isles. Ben Nevis stands at the western end of the Grampian Mountains in the Highland region of Lochaber, close to the town of Fort William. The mountain is a popular destination, attracting an estimated 150,000 visitors a year, around three-quarters of whom use the Mountain Track from Glen Nevis."},{"n":"Loch Ness Monster","lat":57.2144,"lon":-4.5706,"s":76,"w":"Loch Ness Monster","ty":"mythical creature|legendary figure|standing wave|comics character|lake monster","u":0,"b":"The Loch Ness Monster (Scottish Gaelic: Uilebheist Loch Nis), known affectionately as Nessie, is a mythical creature in Scottish folklore that is said to inhabit Loch Ness in the Scottish Highlands. It is often described as large, long-necked, and with one or more humps protruding from the water."},{"n":"Giant's Causeway","lat":55.2408,"lon":-6.5117,"s":75,"w":"Giant's Causeway","ty":"columnar basalt|landform","u":1,"b":"The Giant's Causeway (Irish: Clochán an Aifir or Clochán na bhFomhórach) is an area of approximately 40,000 interlocking basalt columns, the result of an ancient volcanic fissure eruption, part of the North Atlantic Igneous Province active in the region during the Paleogene period."},{"n":"Kingdom of Scotland","lat":57.0,"lon":-5.0,"s":75,"w":"Kingdom of Scotland","ty":"historical country","u":0,"b":"The Kingdom of Scotland was a sovereign state in northwest Europe, traditionally said to have been founded in 843. Its territories expanded and shrank, but it came to occupy the northern third of the island of Great Britain, sharing a land border to the south with the Kingdom of England."},{"n":"Scottish Highlands","lat":57.12,"lon":-4.71,"s":74,"w":"Scottish Highlands","ty":"historical region","u":0,"b":"The Highlands is a historical region of Scotland, comprising the northernmost mountain ranges on the island of Great Britain, divided by the Great Glen between the Grampian Mountains to the southeast and the Northwest Highlands, divided from the islands of the Hebrides by the Minch."},{"n":"Isle of Skye","lat":57.35,"lon":-6.3,"s":73,"w":"Isle of Skye","ty":"island","u":0,"b":"The Isle of Skye, or simply Skye, is the largest and northernmost of the major islands in the Inner Hebrides of Scotland. The island's peninsulas radiate from a mountainous hub dominated by the Cuillin, the rocky slopes of which provide some of the most dramatic mountain scenery in the country."},{"n":"Perth","lat":56.3958,"lon":-3.4333,"s":70,"w":"Perth, Scotland","ty":"city|large burgh","u":0,"b":"Perth is a central Scottish city located on the banks of the River Tay. It is the administrative centre of Perth and Kinross council area and is the historic county town of Perthshire. It had a population of 47,893 in 2022."},{"n":"Argyll and Bute","lat":55.9833,"lon":-5.45,"s":67,"w":"Argyll and Bute","ty":"council area|lieutenancy area of Scotland","u":0,"b":"Argyll and Bute is one of 32 unitary council areas in Scotland and a lieutenancy area. The current lord-lieutenant for Argyll and Bute is Jane Margaret MacLeod (14 July 2020). The administrative centre for the council area is the town of Lochgilphead."},{"n":"House of Stuart","lat":56.0664,"lon":-4.7697,"s":67,"w":"House of Stuart","ty":"dynasty|royal house","u":0,"b":"The House of Stuart, originally spelled Stewart, also known as the Stuart dynasty, was a royal house of Scotland, England, Ireland and later Great Britain. The family name comes from the office of High Steward of Scotland, first held by the family progenitor Walter fitz Alan (c. 1150)."},{"n":"River Clyde","lat":55.4064,"lon":-3.6522,"s":62,"w":"River Clyde","ty":"river","u":0,"b":"The River Clyde is a major river of western Scotland and the second-longest in the country at about 170 kilometres (110 mi) in length. Its river network extends to 4,244 km and drains a basin of 1,903 km2, expanding to 3,854 km2 when the Clyde estuary system with the Kelvin, White Cart, Black Cart and Leven is included."},{"n":"Orkney Islands","lat":59.0,"lon":-3.0,"s":92,"w":"Orkney","ty":"council area|shire of Scotland|registration county|lieutenancy area of Scotland|historic c","u":0,"b":"Orkney, also known as the Orkney Islands, is an archipelago off the north coast of mainland Scotland. The plural name the Orkneys, though heavily disliked by Orcadians, is also sometimes used. Part of the Northern Isles along with Shetland, Orkney is 10 miles (16 km) north of Caithness and has about 70 islands, of which 20 are inhabited."},{"n":"Derry","lat":54.9917,"lon":-7.3417,"s":89,"w":"Derry","ty":"Capital of Culture (designation)|border city|city","u":0,"b":"Derry, officially Londonderry, is a cathedral city in Northern Ireland. Located in County Londonderry, the city now covers both banks of the River Foyle. Cityside and the old walled city are on the west bank and Waterside is on the east, with two road bridges and one footbridge crossing the river in between."},{"n":"Hebrides","lat":58.0,"lon":-7.0,"s":82,"w":"Hebrides","ty":"archipelago","u":0,"b":"The Hebrides are the largest archipelago in Scotland and the British Isles, off the west coast of the Scottish mainland. The islands fall into two main groups, based on their proximity to the mainland: the Inner and Outer Hebrides."},{"n":"Outer Hebrides","lat":57.76,"lon":-7.02,"s":70,"w":"Outer Hebrides","ty":"archipelago|council area|Scottish islands area|lieutenancy area of Scotland","u":0,"b":"The Outer Hebrides or Western Isles, sometimes known as the Long Isle or Long Island, is an island chain off the west coast of mainland Scotland. It is the longest archipelago in the British Isles."},{"n":"Dunfermline","lat":56.0714,"lon":-3.4617,"s":61,"w":"Dunfermline","ty":"city|large burgh","u":0,"b":"Dunfermline is a city, parish, and former royal burgh in Fife, Scotland, 3 miles (5 km) from the northern shore of the Firth of Forth. Dunfermline was the de facto capital of the Kingdom of Scotland between the 11th and 15th centuries. The earliest known settlements around Dunfermline probably date to the Neolithic period, growing by the Bronze Age."},{"n":"Perth and Kinross","lat":56.4167,"lon":-3.4833,"s":60,"w":"Perth and Kinross","ty":"council area|lieutenancy area of Scotland","u":0,"b":"Perth and Kinross is one of the 32 council areas of Scotland, and a lieutenancy area. It is bordered by Highland and Aberdeenshire to the north, Angus, Dundee, and Fife to the east, Clackmannanshire to the south, and Stirling and Argyll and Bute to the west."},{"n":"Highland","lat":57.5,"lon":-5.0,"s":60,"w":"Highland (council area)","ty":"council area","u":0,"b":"The Highland council area is a council area in the Scottish Highlands and is the largest local government area in both Scotland and the United Kingdom. It was the 7th most populous council area in Scotland at the 2011 census. It has land borders with the council areas of Aberdeenshire, Argyll and Bute, Moray and Perth and Kinross."},{"n":"Ayr","lat":55.4639,"lon":-4.6278,"s":60,"w":"Ayr","ty":"county town|town|large burgh|seaport","u":0,"b":"Ayr is a town situated on the southwest coast of Scotland. A former royal burgh, today it is the administrative centre of South Ayrshire Council, and the historic county town of Ayrshire. With a population of 46,182 in 2022, Ayr is the 15th largest settlement in Scotland and second largest town in Ayrshire by population."},{"n":"Inner Hebrides","lat":56.5,"lon":-6.0,"s":58,"w":"Inner Hebrides","ty":"island group|archipelago","u":0,"b":"The Inner Hebrides is an archipelago off the west coast of mainland Scotland, to the south east of the Outer Hebrides. Together these two island chains form the Hebrides, which experience a mild oceanic climate. The Inner Hebrides comprise 35 inhabited islands as well as 44 uninhabited islands with an area greater than 30 hectares (74 acres)."},{"n":"Islay","lat":55.7667,"lon":-6.15,"s":54,"w":"Islay","ty":"island","u":0,"b":"Islay is the southernmost island of the Inner Hebrides of Scotland. Known as \"The Queen of the Hebrides\", it lies in Argyll and Bute just south west of Jura and around 40 kilometres (22 nautical miles) north of the Northern Irish coast. The island's capital is Bowmore where the distinctive round Kilarrow Parish Church and a distillery are located."},{"n":"Isle of Mull","lat":56.45,"lon":-6.0,"s":53,"w":"Isle of Mull","ty":"island","u":0,"b":"The Isle of Mull, or simply Mull, is the second-largest island of the Inner Hebrides of the west coast of Scotland."},{"n":"St Kilda","lat":57.815,"lon":-8.5875,"s":53,"w":"St Kilda, Scotland","ty":"archipelago|World Heritage Site|National Scenic Area|national nature reserve","u":1,"b":"St Kilda (Scottish Gaelic: Hiort) is a remote archipelago situated 35 nautical miles (65 kilometres) west-northwest of North Uist in the North Atlantic Ocean. It contains the westernmost islands of the Outer Hebrides of Scotland."},{"n":"Rockall","lat":57.5963,"lon":-13.6873,"s":50,"w":"Rockall","ty":"rock","u":0,"b":"Rockall is a 17.15-metre-high (56 ft 3 in), uninhabitable granite islet in the North Atlantic Ocean. It is 301 kilometres (187 statute miles; 163 nautical miles) west of Soay, St Kilda, Scotland; 423 kilometres (263 statute miles; 228 nautical miles) north-west of Tory Island, Ireland; and 700 kilometres (430 statute miles; 380 nautical miles) south of Iceland."},{"n":"Iona","lat":56.33,"lon":-6.41,"s":50,"w":"Iona","ty":"island","u":0,"b":"Iona is an island in the Inner Hebrides, off the Ross of Mull on the western coast of Scotland. It is mainly known for Iona Abbey, though there are other buildings on the island. Iona Abbey was a centre of Gaelic monasticism for three centuries, and is today known for its relative tranquillity and natural environment as well as for its importance to pilgrims."},{"n":"Jura","lat":56.0833,"lon":-5.75,"s":49,"w":"Jura, Scotland","ty":"island","u":0,"b":"Jura is an island in the Inner Hebrides of Scotland, adjacent to and northeast of Islay."},{"n":"Dál Riata","lat":56.0861,"lon":-5.4783,"s":49,"w":"Dál Riata","ty":"historical country","u":0,"b":"Dál Riata or Dál Riada (also Dalriada) was a Gaelic kingdom that encompassed the western seaboard of Scotland and northeastern Ireland, on each side of the North Channel. At its height in the 6th and 7th centuries, it covered what is now Argyll (\"Coast of the Gaels\") in Scotland and part of County Antrim in Northern Ireland."},{"n":"Oban","lat":56.4097,"lon":-5.4725,"s":44,"w":"Oban","ty":"small burgh|town","u":0,"b":"Oban is a resort town and seaport in the west of Scotland, within the Argyll and Bute council area. Although small, it is the largest town between Helensburgh and Fort William. Oban has a population of 8,000 (2022), which rises to over 24,000 during the tourist season."},{"n":"Stornoway","lat":58.209,"lon":-6.387,"s":44,"w":"Stornoway","ty":"district|small burgh|town","u":0,"b":"Stornoway (Scottish Gaelic: Steòrnabhagh) is a port town in Scotland, the main town, and by far the largest, of the Outer Hebrides and the capital of both the Isle of Lewis and encompassing island of Lewis and Harris in Scotland. Stornoway is the third-largest island town in Scotland's islands after Kirkwall in Orkney and Lerwick in Shetland."},{"n":"Lewis and Harris","lat":58.25,"lon":-6.6667,"s":42,"w":"Lewis and Harris","ty":"island","u":0,"b":"Lewis and Harris, or Lewis with Harris, is the largest island in Scotland. It is the main island of the Outer Hebrides, around 24 miles (39 km) from the Scottish mainland. The island has an area of 841 square miles (2,178 km2), which is approximately 1% the size of Great Britain)."},{"n":"Sea of the Hebrides","lat":57.0,"lon":-7.0,"s":42,"w":"Sea of the Hebrides","ty":"sea","u":0,"b":"The Sea of the Hebrides is a small and partly sheltered section of the North Atlantic Ocean, indirectly off the southern part of the north-west coast of Scotland. To the east are the mainland of Scotland and the northern Inner Hebrides (including Skye and the Small Isles); to the west are the southern Outer Hebrides islands, principally South Uist, Eriskay, and Barra."},{"n":"Isle of Lewis","lat":58.2,"lon":-6.6,"s":40,"w":"Isle of Lewis","ty":"peninsula","u":0,"b":"The Isle of Lewis or simply Lewis is the northern part of Lewis and Harris, the largest island of the Western Isles or Outer Hebrides archipelago in Scotland. The two parts are frequently referred to as if they were separate islands. The total area of Lewis is 683 square miles (1,770 km2)."},{"n":"South Uist","lat":57.2667,"lon":-7.3167,"s":40,"w":"South Uist","ty":"island","u":0,"b":"South Uist is the second-largest island of the Outer Hebrides in Scotland. At the 2022 census it had a usually resident population of 1,650, a decrease of 104 since 2011. The island, in common with the rest of the Hebrides, is one of the last remaining strongholds of the Gaelic language in Scotland."},{"n":"Barra","lat":56.9833,"lon":-7.4667,"s":40,"w":"Barra","ty":"island","u":0,"b":"Barra is an island in the Outer Hebrides, Scotland, and the second southernmost inhabited island there, after the adjacent island of Vatersay to which it is connected by the Vatersay Causeway. In 2022, the population was 1,209, an increase of 35 since the 2011 census. English and Gaelic are widely spoken, and at the 2011 Census, there were 761 Gaelic speakers."},{"n":"Benbecula","lat":57.4458,"lon":-7.3196,"s":39,"w":"Benbecula","ty":"island","u":0,"b":"The Isle of Benbecula is an island of the Outer Hebrides in the Atlantic Ocean off the west coast of Scotland. In the 2022 census it had a resident population of 1,255 including a sizable percentage of Roman Catholics. It is in a zone administered by Comhairle nan Eilean Siar or the Western Isles Council."},{"n":"North Uist","lat":57.6,"lon":-7.3333,"s":38,"w":"North Uist","ty":"island","u":0,"b":"North Uist (Scottish Gaelic: Uibhist a Tuath) is an island and community in the Outer Hebrides of Scotland."},{"n":"Rùm","lat":57.0,"lon":-6.35,"s":37,"w":"Rùm","ty":"island","u":0,"b":"Rùm, a Scottish Gaelic name often anglicised to Rum ( rum), is one of the Small Isles of the Inner Hebrides, off the west coast of Scotland, in the district of Lochaber. For much of the 20th century the name became Rhum, a spelling invented by the former owner, Sir George Bullough, because he did not relish the idea of having the title \"Laird of Rum\"."},{"n":"Tiree","lat":56.5056,"lon":-6.8781,"s":37,"w":"Tiree","ty":"island","u":0,"b":"Tiree is the most westerly island in the Inner Hebrides of Scotland. The low-lying island, southwest of Coll, has an area of 7,834 hectares (30+1⁄4 square miles) and a population of around 700. The land is highly fertile, and crofting, alongside tourism, and fishing are the main sources of employment for the islanders."},{"n":"Fingal's Cave","lat":56.4314,"lon":-6.3414,"s":36,"w":"Fingal's Cave","ty":"sea cave|show cave","u":0,"b":"Fingal's Cave is a sea cave on the uninhabited island of Staffa, in the Inner Hebrides of Scotland, known for its natural acoustics. The National Trust for Scotland owns the cave as part of a national nature reserve. It became known as Fingal's Cave after the eponymous hero of an epic poem by 18th-century Scots poet-historian James Macpherson."},{"n":"Eilean Donan","lat":57.2742,"lon":-5.5161,"s":35,"w":"Eilean Donan","ty":"tidal island","u":0,"b":"Eilean Donan (Scottish Gaelic: Eilean Donnain) is a small tidal island situated at the confluence of three sea lochs (Loch Duich, Loch Long and Loch Alsh) in the western Highlands of Scotland, about one kilometre (5⁄8 mi) from the village of Dornie."},{"n":"Staffa","lat":56.4361,"lon":-6.3403,"s":35,"w":"Staffa","ty":"island","u":0,"b":"Staffa is an island of the Inner Hebrides in Argyll and Bute, Scotland. The Vikings gave it the name because its columnar basalt reminded them of their houses, which were constructed using vertical logs. Staffa lies about 10 kilometres (6 miles) west of the Isle of Mull."},{"n":"U-47","lat":60.0,"lon":-13.0,"s":31,"w":"German submarine U-47 (1938)","ty":"U-boat","u":0,"b":"German submarine U-47 was a Type VIIB U-boat of Nazi Germany's Kriegsmarine during World War II. She was laid down on 25 February 1937 at Friedrich Krupp Germaniawerft in Kiel as yard number 582 and went into service on 17 December 1938 under the command of Günther Prien."},{"n":"SS Athenia","lat":56.7333,"lon":-14.0833,"s":21,"w":"SS Athenia (1922)","ty":"ocean liner","u":0,"b":"SS Athenia was a steam turbine transatlantic passenger liner built in Glasgow, Scotland, in 1923 for the Anchor-Donaldson Line, which later became the Donaldson Atlantic Line. She worked between the United Kingdom and the east coast of Canada until 3 September 1939, when a torpedo from the German submarine U-30 sank her in the Western Approaches."},{"n":"U-39","lat":58.5333,"lon":-11.8167,"s":20,"w":"German submarine U-39 (1938)","ty":"U-boat|shipwreck","u":0,"b":"German submarine U-39 was a Type IXA U-boat of the Kriegsmarine that operated from 1938 to the first few days of World War II. She was ordered by the Kriegsmarine on 29 July 1936 as part of the re-armament program (Aufrüstung) in Germany, which was illegal under the terms of the Treaty of Versailles."},{"n":"U-31","lat":56.4333,"lon":-10.3,"s":18,"w":"German submarine U-31 (1936)","ty":"U-boat","u":0,"b":"German submarine U-31 was a Type VIIA U-boat of Nazi Germany's Kriegsmarine during World War II. She was laid down on 1 March 1936 as yard number 912, launched on 25 September and commissioned on 28 December 1936."},{"n":"SS Norge","lat":57.5967,"lon":-13.6886,"s":15,"w":"SS Norge","ty":"steamship","u":0,"b":"SS Norge was a transatlantic ocean liner that was launched in 1881 in Scotland, and was lost in 1904 off Rockall with great loss of life. Her final voyage was from Copenhagen, Kristiania and Kristiansand, bound for New York, carrying passengers many of whom were emigrants."},{"n":"U-70","lat":60.25,"lon":-14.0,"s":14,"w":"German submarine U-70 (1940)","ty":"U-boat","u":0,"b":"German submarine U-70 was a Type VIIC submarine of Nazi Germany's Kriegsmarine during World War II."},{"n":"U-249","lat":56.1667,"lon":-10.0833,"s":13,"w":"German submarine U-249","ty":"shipwreck|U-boat","u":0,"b":"German submarine U-249 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine during World War II. The submarine was laid down on 23 January 1943 at the Friedrich Krupp Germaniawerft yard at Kiel as yard number 683, launched on 23 October 1943 and commissioned on 20 November under the command of Oberleutnant zur See Rolf Lindschau. In two patrols, she sank no ships."},{"n":"U-261","lat":59.8333,"lon":-9.4667,"s":11,"w":"German submarine U-261","ty":"U-boat","u":0,"b":"German submarine U-261 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine during World War II. The submarine was laid down on 17 May 1941 at the Bremer Vulkan yard at Bremen-Vegesack as yard number 26, launched on 16 February 1942 and commissioned on 28 March under the command of Kapitänleutnant Hans Lange."},{"n":"U-65","lat":59.51,"lon":-15.3,"s":11,"w":"German submarine U-65 (1939)","ty":"U-boat","u":0,"b":"German submarine U-65 was a Type IXB U-boat of Nazi Germany's Kriegsmarine during World War II. Over the course of six war patrols between 9 April 1940 and 28 April 1941, she sank twelve ships and damaged three others for a total loss of 88,664 gross register tons (GRT)."},{"n":"U-481","lat":56.1833,"lon":-10.0,"s":10,"w":"German submarine U-481","ty":"U-boat","u":0,"b":"German submarine U-481 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine during World War II. The submarine was laid down on 6 February 1943 at the Deutsche Werke yard in Kiel, launched on 25 September 1943, and commissioned on 10 November 1943 under the command of Oberleutnant zur See Ewald Pick."},{"n":"U-773","lat":56.1667,"lon":-10.0833,"s":10,"w":"German submarine U-773","ty":"U-boat","u":0,"b":"German submarine U-773 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine during World War II. She was ordered on 21 November 1940, and was laid down on 13 October 1942, at Kriegsmarinewerft, Wilhelmshaven, as yard number 156. She was launched on 8 December 1943, and commissioned under the command of Oberleutnant zur See Richard Lange on 20 January 1944."},{"n":"U-368","lat":56.2333,"lon":-10.6167,"s":10,"w":"German submarine U-368","ty":"U-boat","u":0,"b":"German submarine U-368 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine during World War II. She carried out no patrols. She did not sink or damage any ships. She was sunk after Germany's surrender as part of Operation Deadlight on 17 December 1945."},{"n":"U-1002","lat":56.1667,"lon":-10.0833,"s":9,"w":"German submarine U-1002","ty":"U-boat","u":0,"b":"German submarine U-1002 was a Type VIIC/41 U-boat of Nazi Germany's Kriegsmarine during World War II. She was ordered on 14 October 1941, and was laid down on 4 January 1943, at Blohm & Voss, Hamburg, as yard number 202. She was launched on 6 October 1943, and commissioned under the command of Oberleutnant zur See Albrecht Schubart on 30 November 1943."},{"n":"U-357","lat":57.1667,"lon":-15.6667,"s":9,"w":"German submarine U-357","ty":"U-boat","u":0,"b":"German submarine U-357 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine during World War II and was sunk by British warships northwest of Ireland on 26 December 1942 on her first operational patrol."},{"n":"U-283","lat":60.75,"lon":-12.8333,"s":9,"w":"German submarine U-283","ty":"U-boat","u":0,"b":"German submarine U-283 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine during World War II. The submarine was laid down on 10 June 1942 at the Bremer Vulkan yard at Bremen-Vegesack as yard number 48. She was launched on 17 February 1943 and commissioned on 31 March under the command of Oberleutnant zur See Heinz-Günther Scholz."},{"n":"U-739","lat":56.1667,"lon":-10.0833,"s":9,"w":"German submarine U-739","ty":"U-boat","u":0,"b":"German submarine U-739 was a Type VIIC U-boat built for Nazi Germany's Kriegsmarine for service during World War II. She was laid down on 17 April 1942 by Schichau-Werke, Danzig as yard number 1536, launched on 23 December 1942 and commissioned on 6 March 1943 under Leutnant zur See Ernst Mangold."},{"n":"U-826","lat":56.1667,"lon":-10.0833,"s":9,"w":"German submarine U-826","ty":"U-boat","u":0,"b":"German submarine U-826 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine during World War II. She was ordered on 8 June 1942, and was laid down on 6 August 1943 at F Schichau GmbH, Danzig, as yard number 1589. She was launched on 9 March 1944 and commissioned under the command of Oberleutnant zur See Olaf Lübcke on 11 May 1944."},{"n":"U-992","lat":56.1667,"lon":-10.0833,"s":9,"w":"German submarine U-992","ty":"U-boat","u":0,"b":"German submarine U-992 was a Type VIIC U-boat built for Nazi Germany's Kriegsmarine for service during World War II. She was laid down on 30 October 1942 by Blohm & Voss, Hamburg as yard number 192, launched on 24 June 1943 and commissioned on 2 August 1943 under Oberleutnant zur See Hans Falke."},{"n":"U-1198","lat":56.2333,"lon":-10.6167,"s":8,"w":"German submarine U-1198","ty":"U-boat","u":0,"b":"German submarine U-1198 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine during World War II. She was ordered on 25 August 1941, and was laid down on 13 March 1943 at F Schichau GmbH, Danzig, as yard number 1568. She was launched on 30 September 1943 and commissioned under the command of Oberleutnant zur See Gerhard Peters on 9 December 1943."},{"n":"U-1004","lat":56.1667,"lon":-10.0833,"s":8,"w":"German submarine U-1004","ty":"U-boat","u":0,"b":"German submarine U-1004 was a Type VIIC/41 U-boat built for Nazi Germany's Kriegsmarine for service during World War II. She was laid down on 15 January 1943 by Blohm & Voss, Hamburg as yard number 204, launched on 27 October 1943 and commissioned on 16 December 1943 under Oberleutnant zur See Hartmuth Schimmelpfennig."},{"n":"SS Vaderland","lat":56.1667,"lon":-12.2333,"s":8,"w":"SS Vaderland (1900)","ty":"ocean liner","u":0,"b":"SS Vaderland was an ocean liner launched in July 1900 for the Red Star Line service between Antwerp and New York. During her passenger career, the ship initially sailed under British registry, but was re-registered in Antwerp in 1903. Vaderland was a sister ship to Zeeland and a near sister ship to Kroonland and Finland."},{"n":"U-2361","lat":56.1667,"lon":-10.0833,"s":6,"w":"German submarine U-2361","ty":"U-boat","u":0,"b":"German submarine U-2361 was a Type XXIII U-boat of Nazi Germany's Kriegsmarine during World War II. She was ordered on 20 September 1944, and was laid down on 12 November 1944 at Deutsche Werft AG, Hamburg, as yard number 515. She was launched on 3 January 1945 and commissioned under the command of Oberleutnant zur See Heinz von Henning on 3 February 1945."},{"n":"Hasselwood Rock","lat":57.5978,"lon":-13.6875,"s":6,"w":"Hasselwood Rock","ty":"reef|rock formation|island","u":0,"b":"Hasselwood Rock is a 1-metre-high (3 ft 3 in) uninhabitable skerry 200 metres North of Rockall in the North-east Atlantic Ocean."},{"n":"U-2334","lat":56.1667,"lon":-10.0833,"s":6,"w":"German submarine U-2334","ty":"U-boat","u":0,"b":"German submarine U-2334 was a Type XXIII U-boat of Nazi Germany's Kriegsmarine during World War II. She was ordered on 20 September 1943, and was laid down on 14 July 1944 at Deutsche Werft, Hamburg, as yard number 488. She was launched on 26 August 1944 and commissioned under the command of Leutnant zur See Walter Angermann on 21 September 1944."},{"n":"SM U-70","lat":56.1667,"lon":-12.2333,"s":6,"w":"SM U-70","ty":"U-boat","u":0,"b":"SM U-70 was a Type U 66 submarine or U-boat for the German Imperial Navy (German: Kaiserliche Marine) during World War I. She had been laid down in February 1914 as U-11 the final boat of the U-7 class for the Austro-Hungarian Navy but was sold to Germany, along with the others in her class, in November 1914."},{"n":"U-556","lat":60.4,"lon":-20.0,"s":14,"w":"German submarine U-556","ty":"U-boat","u":0,"b":"German submarine U-556 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine during World War II."},{"n":"U-76","lat":58.5833,"lon":-20.3333,"s":11,"w":"German submarine U-76 (1940)","ty":"U-boat","u":0,"b":"German submarine U-76 was a Type VIIB U-boat of Nazi Germany's Kriegsmarine during World War II. She played a minor role in the Battle of the Atlantic, but was destroyed south of Iceland."},{"n":"U-651","lat":59.8667,"lon":-18.6,"s":9,"w":"German submarine U-651","ty":"U-boat","u":0,"b":"German submarine U-651 was a German Type VIIC U-boat built for Nazi Germany's Kriegsmarine for service during World War II. She was ordered just after the war started in 1939, laid down on 16 January 1940, launched on 21 December that year and commissioned the following 21 February. She was commanded by Kapitänleutnant Peter Lohmeyer. Her career was a short one."},{"n":"U-633","lat":58.85,"lon":-19.9167,"s":8,"w":"German submarine U-633","ty":"U-boat","u":0,"b":"German submarine U-633 was a Type VIIC U-boat built for Nazi Germany's Kriegsmarine for service during World War II. She was laid down on 22 September 1941 by Blohm & Voss, Hamburg as yard number 609, launched on 10 June 1942 and commissioned on 30 July 1942 under Oberleutnant zur See Bernhard Müller."},{"n":"USS Mason","lat":57.0167,"lon":-19.1333,"s":8,"w":"USS Mason (DD-191)","ty":"destroyer|shipwreck","u":0,"b":"USS Mason (DD-191) was a Clemson-class destroyer in the United States Navy during World War II. She was later transferred to the Royal Navy as HMS Broadwater (H81)."},{"n":"HMS Dundee","lat":56.75,"lon":-14.2333,"s":5,"w":"HMS Dundee (L84)","ty":"sloop-of-war|shipwreck","u":0,"b":"HMS Dundee was a Shoreham-class sloop of the Royal Navy. The ship was built at Chatham Dockyard, entering service in 1933. The ship saw service primarily as a convoy escort in the Atlantic."},{"n":"SS Tregenna","lat":58.3667,"lon":-15.7,"s":3,"w":"SS Tregenna","ty":"ship","u":0,"b":"SS Tregenna was a cargo steamship that was launched in England in 1919 and sunk by a U-boat in the Battle of the Atlantic in 1940 with the loss of 33 of her 37 crew. She was laid down as War Bulldog, but the Hain Steam Ship Co bought her before she was completed and renamed her Tregenna."},{"n":"George Bligh Bank","lat":58.9167,"lon":-14.75,"s":2,"w":"George Bligh Bank","ty":"seamount","u":0,"b":"George Bligh Bank is a seamount that lies in the Rockall Trough in the northeast Atlantic, west of Scotland, centred at approximately 59°N, 14°W at the northern end of both the Hatton and Rockall Banks."},{"n":"Hatton Basin","lat":57.0,"lon":-19.0,"s":2,"w":"Hatton Basin","ty":"undersea landform","u":0,"b":"The Hatton Basin or Hatton-Rockall Basin is a ca. 600 km long SW–NE trending sedimentary basin, located off the west coast of Ireland, within the Rockall–Porcupine margin. It lies between the Hatton and Edoras Banks to the west and the Rockall Bank to the east."},{"n":"MV Languedoc","lat":59.2333,"lon":-17.85,"s":2,"w":"MV Languedoc","ty":"ship","u":0,"b":"MV Languedoc was a motor tanker that sailed under the French flag until World War II. She was taken over by the UK after the fall of France in 1940, sailed in a number of convoys, and was sunk by a German U-boat later that year."},{"n":"MV Seaforth (1938)","lat":58.8,"lon":-18.2833,"s":2,"w":"MV Seaforth (1938)","ty":"motor ship","u":0,"b":"MV Seaforth was an Elder Dempster Lines cargo motor ship that traded between Liverpool and West Africa. She was launched in 1938 in Scotland and sunk in 1941 in the North Atlantic."},{"n":"SS Crown Arun","lat":58.0333,"lon":-14.3,"s":2,"w":"SS Crown Arun","ty":"steamship","u":0,"b":"SS Crown Arun was a cargo steamship. She was built in Germany for Johann MK Blumenthal, and completed in 1938 as Hannah Böge. In 1939 the Royal Navy captured her, and she was declared a war prize."},{"n":"SS Fanad Head","lat":56.7167,"lon":-15.35,"s":2,"w":"SS Fanad Head","ty":"steamship","u":0,"b":"SS Fanad Head was a UK cargo steamship. She was built during the First World War and torpedoed and sunk ten days after the UK entered the Second World War."},{"n":"SS Manistee","lat":58.2167,"lon":-21.55,"s":2,"w":"SS Manistee (1920)","ty":"ship","u":0,"b":"SS Manistee was an Elders & Fyffes Ltd banana boat that was launched in 1920. She was one of a numerous class of similar banana boats built for Elders & Fyffes in the 1920s. In 1940 the British Admiralty requisitioned Manistee and had her converted into an ocean boarding vessel."},{"n":"SS Scoresby","lat":59.2333,"lon":-17.85,"s":2,"w":"SS Scoresby","ty":"steamship","u":0,"b":"SS Scoresby was a British cargo steamship that was built in 1923, sailed in a number of transatlantic convoys in 1940, and was sunk by a U-boat that October."},{"n":"SS West Pocasset","lat":58.5,"lon":-19.6667,"s":2,"w":"SS West Pocasset","ty":"ship","u":0,"b":"West Pocasset was a steam cargo ship built in 1919 by Northwest Steel Company of Portland for the United States Shipping Board as part of the wartime shipbuilding program of the Emergency Fleet Corporation (EFC) to restore the nation's Merchant Marine."},{"n":"U-279","lat":60.6667,"lon":-26.5,"s":12,"w":"German submarine U-279","ty":"U-boat","u":0,"b":"German submarine U-279 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine during World War II. The submarine was laid down on 31 March 1942 at the Bremer Vulkan yard at Bremen-Vegesack as yard number 44. She was launched on 16 December 1942 and commissioned on 3 February 1943 under the command of Kapitänleutnant Otto Franke."},{"n":"U-341","lat":58.5667,"lon":-25.5,"s":12,"w":"German submarine U-341","ty":"U-boat","u":0,"b":"German submarine U-341 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine during World War II. She did not sink or damage any ships."},{"n":"U-273","lat":59.4167,"lon":-24.55,"s":11,"w":"German submarine U-273","ty":"U-boat","u":0,"b":"German submarine U-273 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine during World War II. The submarine was laid down on 5 December 1941 at the Bremer Vulkan yard at Bremen-Vegesack as yard number 38, she was launched on 2 September 1942 and commissioned on 21 October under the command of Oberleutnant zur See Hans-Adolf Engel."},{"n":"U-194","lat":59.0,"lon":-26.3,"s":10,"w":"German submarine U-194","ty":"U-boat","u":0,"b":"German submarine U-194 was a Type IXC/40 U-boat of Nazi Germany's Kriegsmarine built during World War II for service in the Atlantic Ocean. Notable for having been fitted with the new Balkon sonar, she was a short-lived vessel, being sunk on her first and only operational war patrol."},{"n":"U-200","lat":58.25,"lon":-25.4167,"s":10,"w":"German submarine U-200","ty":"U-boat","u":0,"b":"German submarine U-200 was a Type IXD2 U-boat of Nazi Germany's Kriegsmarine during World War II. The submarine was laid down on 3 November 1941 at the AG Weser yard at Bremen as yard number 1046, launched on 10 August 1942 and commissioned on 22 December 1942 under the command of Korvettenkapitän Heinrich Schonder."},{"n":"U-619","lat":58.6833,"lon":-22.9667,"s":10,"w":"German submarine U-619","ty":"U-boat","u":0,"b":"German submarine U-619 was a Type VIIC U-boat built for Nazi Germany's Kriegsmarine for service during World War II. She was laid down on 19 June 1941 by Blohm & Voss, Hamburg as yard number 595, launched on 9 March 1942 and commissioned on 23 April 1942 under Oberleutnant zur See Kurt Makowski."},{"n":"U-710","lat":61.25,"lon":-19.48,"s":8,"w":"German submarine U-710","ty":"U-boat","u":0,"b":"German submarine U-710 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine during World War II. She had an extremely short career, only conducting one patrol in April 1943 and attacking no ships. Just nine days after starting her first patrol, she was sunk by a B-17 Flying Fortress with the loss of all hands."},{"n":"solar eclipse of August 31, 1913","lat":61.5,"lon":-26.8,"s":7,"w":"Solar eclipse of August 31, 1913","ty":"partial solar eclipse|solar eclipse","u":0,"b":"A partial solar eclipse occurred at the Moon's descending node of orbit on Sunday, August 31, 1913, with a magnitude of 0.1513. A solar eclipse occurs when the Moon passes between Earth and the Sun, thereby totally or partly obscuring the image of the Sun for a viewer on Earth."},{"n":"Soviet destroyer Smetlivy","lat":59.6833,"lon":-24.1667,"s":4,"w":"Soviet destroyer Smetlivy (1937)","ty":"destroyer","u":0,"b":"Smetlivy (Russian: Сметливый, lit. 'Sly') was one of 29 Gnevny-class destroyers (officially known as Project 7) built for the Soviet Navy during the late 1930s. Completed in 1938, she was assigned to the Baltic Fleet and played a minor role in the 1939–1940 Winter War against Finland."},{"n":"SS Wahehe","lat":58.2,"lon":-23.3667,"s":4,"w":"SS Wahehe (1922)","ty":"steamship","u":0,"b":"Wahehe was a 4,690 GRT cargo ship which was built in 1922 as Wadigo by Reiherstieg Schiffswerfte und Maschinenfabrik, Hamburg for Woermann Linie AG. She was converted to a refrigerated cargo liner in about 1934. At sea when war was declared in 1939, she sought refuge at Vigo, Spain."},{"n":"SS Somersby","lat":60.65,"lon":-26.2167,"s":2,"w":"SS Somersby","ty":"ship","u":0,"b":"SS Somersby was a British cargo steamship that was built in 1930, sailed in a number of convoys in the Second World War and was sunk by a U-boat in 1941."},{"n":"Reykjanes Ridge","lat":61.0,"lon":-28.0,"s":13,"w":"Reykjanes Ridge","ty":"mid-ocean ridge","u":0,"b":"The Mid-Atlantic Ridge is a mid-ocean ridge (a divergent or constructive plate boundary) located along the floor of the Atlantic Ocean, and part of the longest mountain range in the world. In the North Atlantic, the ridge separates North America from the Eurasian plate and the African plate, north and south of the Azores triple junction."},{"n":"U-334","lat":58.2667,"lon":-28.3333,"s":10,"w":"German submarine U-334","ty":"U-boat","u":0,"b":"German submarine U-334 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine during World War II. The submarine was laid down on 16 March 1940 at the Nordseewerke yard at Emden as yard number 206, launched on 15 August 1941 and commissioned on 9 October under the command of Kapitänleutnant Hilmar Siemon."},{"n":"U-389","lat":60.85,"lon":-28.4333,"s":10,"w":"German submarine U-389","ty":"U-boat","u":0,"b":"German submarine U-389 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine during World War II. She carried out one patrol. She did not sink or damage any ships. She was sunk by a British aircraft southwest of Iceland on 4 October 1943."},{"n":"U-844","lat":58.5,"lon":-27.2667,"s":10,"w":"German submarine U-844","ty":"U-boat","u":0,"b":"German submarine U-844 was a Type IXC/40 U-boat of Nazi Germany's Kriegsmarine, built for service during the Second World War. An extremely short-lived boat, U-844 served just ten days on her only patrol and was sunk with two other boats whilst preparing for a failed attack on a well-defended convoy within range of allied air support."},{"n":"U-342","lat":60.5333,"lon":-29.3333,"s":9,"w":"German submarine U-342","ty":"U-boat","u":0,"b":"German submarine U-342 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine during World War II. She was on her first patrol when she was sunk by a Canadian aircraft, Canso patrol flying boats, on 17 April 1944, with 51 casualties, lost with all hands. She did not sink or damage any ships."},{"n":"U-964","lat":57.45,"lon":-28.2833,"s":9,"w":"German submarine U-964","ty":"U-boat","u":0,"b":"German submarine U-964 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine built for service during World War II. A short-lived boat, U-964 is most noted for being one of three new boats ordered by the Kriegsmarine to attack Convoy ON 206 in the Western Approaches."},{"n":"U-756","lat":58.1333,"lon":-27.55,"s":8,"w":"German submarine U-756","ty":"U-boat","u":0,"b":"German submarine U-756 was a Type VIIC U-boat built for Nazi Germany's Kriegsmarine for service during World War II. Laid down as yard number 139 at the Kriegsmarinewerft (KMW) in Wilhelmshaven, she served with 6th U-boat flotilla from 30 December 1941 until 1 September 1942 under the command of Kapitänleutnant Klaus Harney."},{"n":"Irminger Sea","lat":62.0,"lon":-35.0,"s":42,"w":"Irminger Sea","ty":"sea","u":0,"b":"The Irminger Sea is a marginal sea of the North Atlantic Ocean. It is bordered to the west by southern Greenland, to the north by Iceland and the Denmark Strait, to the east by the Reykjanes Ridge (a northern part of the Mid-Atlantic Ridge), and to the south by open waters of the North Atlantic."},{"n":"U-110","lat":60.3667,"lon":-33.2,"s":18,"w":"German submarine U-110 (1940)","ty":"U-boat","u":0,"b":"German submarine U-110 was a Type IXB U-boat of Nazi Germany's Kriegsmarine that operated during World War II. She was captured by the Royal Navy on 9 May 1941 and provided a number of secret cipher documents to the British. U-110's capture, later given the code name \"Operation Primrose\", was one of the biggest secrets of the war, remaining so for seven months."},{"n":"U-540","lat":58.6333,"lon":-31.9333,"s":10,"w":"German submarine U-540","ty":"U-boat","u":0,"b":"German submarine U-540 was a Type IXC U-boat of Nazi Germany's Kriegsmarine during World War II. She was laid down at the Deutsche Werft (yard) in Hamburg as yard number 361 on 12 May 1942, launched on 18 December and commissioned on 10 March 1943 with Kapitänleutnant Lorenz Kasch in command."},{"n":"U-841","lat":59.95,"lon":-31.1,"s":10,"w":"German submarine U-841","ty":"U-boat","u":0,"b":"German submarine U-841 was a Type IXC/40 U-boat built for Nazi Germany's Kriegsmarine during World War II. U-841 was ordered on 20 January 1941 from DeSchiMAG AG Weser in Bremen under the yard number 1047. Her keel was laid down on 21 March 1942 and after seven months of construction the U-boat was launched on 21 October 1942."},{"n":"U-388","lat":57.6,"lon":-31.3333,"s":9,"w":"German submarine U-388","ty":"U-boat","u":0,"b":"German submarine U-388 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine during World War II. The submarine was laid down on 12 September 1941 at the Howaldtswerke yard in Kiel, launched on 12 November 1942 and commissioned on 31 December 1942 under the command of Oberleutnant zur See Peter Sues."},{"n":"U-631","lat":58.2167,"lon":-32.4833,"s":9,"w":"German submarine U-631","ty":"U-boat","u":0,"b":"German submarine U-631 was a Type VIIC U-boat built for Nazi Germany's Kriegsmarine for service during World War II. She was laid down on 5 September 1941 by Blohm & Voss, Hamburg as yard number 607, launched on 27 May 1942 and commissioned on 16 July 1942 under Oberleutnant zur See Jürgen Krüger."},{"n":"U-640","lat":60.5333,"lon":-31.0833,"s":8,"w":"German submarine U-640","ty":"U-boat","u":0,"b":"German submarine U-640 was a Type VIIC U-boat built for Nazi Germany's Kriegsmarine for service during World War II. She was laid down on 30 October 1941 by Blohm & Voss, Hamburg as yard number 616, launched on 23 July 1942 and commissioned on 17 September 1942 under Oberleutnant zur See Karl-Heinz Nagel."},{"n":"solar eclipse of February 25, 1971","lat":61.4,"lon":-33.5,"s":8,"w":"Solar eclipse of February 25, 1971","ty":"partial solar eclipse|solar eclipse","u":0,"b":"A partial solar eclipse occurred at the Moon's ascending node of orbit on Thursday, February 25, 1971, with a magnitude of 0.7872. A solar eclipse occurs when the Moon passes between Earth and the Sun, thereby totally or partly obscuring the image of the Sun for a viewer on Earth."},{"n":"U-635","lat":58.3333,"lon":-31.8667,"s":7,"w":"German submarine U-635","ty":"U-boat","u":0,"b":"German submarine U-635 was a Type VIIC U-boat built for Nazi Germany's Kriegsmarine for service during World War II. She was laid down on 3 October 1941 by Blohm & Voss, Hamburg as yard number 611, launched on 24 June 1942 and commissioned on 13 August 1942 under Oberleutnant zur See Heinz Eckelmann."},{"n":"solar eclipse of October 3, 1986","lat":59.9,"lon":-37.1,"s":7,"w":"Solar eclipse of October 3, 1986","ty":"hybrid solar eclipse|solar eclipse","u":0,"b":"A total solar eclipse occurred at the Moon's descending node of orbit on Friday, October 3, 1986, with a magnitude of 1. It was a hybrid event, with only a fraction of its path as total, and longer sections at the start and end as an annular eclipse."},{"n":"HMS Byard","lat":59.95,"lon":-31.1,"s":3,"w":"HMS Byard","ty":"destroyer escort|shipwreck","u":0,"b":"HMS Byard was a Captain-class frigate of the Royal Navy during World War II. She was named for Sir Thomas Byard, who commanded HMS Bedford at the Battle of Camperdown in 1797 during the French Revolutionary Wars."},{"n":"HMCS Levis","lat":60.1167,"lon":-38.6167,"s":2,"w":"HMCS Lévis (K115)","ty":"corvette","u":0,"b":"HMCS Lévis was a Royal Canadian Navy Flower-class corvette which took part in convoy escort duties during the Second World War. She was sunk in 1941. She was named for Lévis, Quebec."},{"n":"SS Burgondier","lat":58.3,"lon":-38.2,"s":2,"w":"SS Burgondier","ty":"steamship","u":0,"b":"SS Burgondier was a 5,297-ton cargo steamship built to a First World War standard design by Caird & Company at Greenock on the Firth of Clyde. She changed owners and names several times, becoming the Azul, David Dawson, Penteli and finally Brockley Hill. She was sunk by enemy action in 1941."},{"n":"SS Pink Star","lat":61.6,"lon":-35.1167,"s":2,"w":"SS Pink Star","ty":"ship","u":0,"b":"SS Pink Star, the former Danish ship Lundby taken over as an idle foreign vessel in United States ports, was an American-owned ship flying under the Panamanian flag. Pink Star was the seventh American ship sunk by a German U-boat prior the United States entry into World War II. On September 20, 1941, she was torpedoed by U-552."},{"n":"Cape Farewell","lat":59.7731,"lon":-43.9225,"s":40,"w":"Cape Farewell, Greenland","ty":"cape|headland","u":0,"b":"Cape Farewell (Greenlandic: Nunap Isua; Danish: Kap Farvel) is a headland on the southern shore of Egger Island, Nunap Isua Archipelago, Greenland. As the southernmost point of the country, it is one of the important landmarks of Greenland."},{"n":"MS Hans Hedtoft","lat":59.5,"lon":-43.0,"s":14,"w":"MS Hans Hedtoft","ty":"shipwreck|passenger-cargo ship","u":0,"b":"MS Hans Hedtoft was a Danish cargo passenger liner that struck an iceberg and sank on 30 January 1959 on her maiden voyage off the coast of Western Greenland. The only piece of the wreckage found was a lifebelt."},{"n":"solar eclipse of September 23, 2090","lat":60.7,"lon":-40.5,"s":12,"w":"Solar eclipse of September 23, 2090","ty":"total solar eclipse","u":0,"b":"A total solar eclipse will occur at the Moon's ascending node of orbit on Saturday, September 23, 2090, with a magnitude of 1.0562. A solar eclipse occurs when the Moon passes between Earth and the Sun, thereby totally or partly obscuring the image of the Sun for a viewer on Earth."},{"n":"Prince Christian Sound","lat":60.15,"lon":-43.8833,"s":11,"w":"Prince Christian Sound","ty":"sound","u":0,"b":"The Prince Christian Sound (Kalaallisut: Ikerasassuaq; Danish: Prins Christians Sund) is a waterway in Southern Greenland. It separates the mainland from Sammisoq (Christian IV Island) and other islands of the Cape Farewell Archipelago near the southernmost tip of Greenland. The name was given in honour of the prince, later king Christian VIII of Denmark."},{"n":"Eggers Island","lat":59.89,"lon":-43.9,"s":10,"w":"Egger Island","ty":"island","u":0,"b":"Egger Island is Greenland's southernmost island. It is located in the Kujalleq municipality and is uninhabited."},{"n":"Sangmissoq","lat":60.0528,"lon":-43.6867,"s":9,"w":"Sammisoq","ty":"island","u":0,"b":"Sammisoq is an island in the Kujalleq municipality in southern Greenland, located northeast of Uummannarsuaq cape. It is the largest island of the Cape Farewell Archipelago (Nunap Isua)."},{"n":"U-657","lat":58.9,"lon":-42.55,"s":8,"w":"German submarine U-657","ty":"U-boat","u":0,"b":"German submarine U-657 was a Type VIIC U-boat built for Nazi Germany's Kriegsmarine for service during World War II. She was laid down on 5 October 1940 by Howaldtswerke, Hamburg as yard number 806, launched on 12 August 1941 and commissioned on 8 October 1941 under Oberleutnant zur See Hans-Jürgen Radke."},{"n":"Lindenow Fjord","lat":60.5333,"lon":-43.6667,"s":5,"w":"Lindenow Fjord","ty":"fjord","u":0,"b":"Lindenow Fjord or Kangerlussuatsiaq, is a fjord in the King Frederick VI Coast, Kujalleq municipality, southern Greenland."},{"n":"Kangerluluk Bjerge","lat":61.1333,"lon":-42.9167,"s":4,"w":"Kangerluluk Range","ty":"mountain range","u":0,"b":"The Kangerluluk Range (Danish: Kangerluluk Bjerge) is a mountain range in the King Frederick VI Coast, southeastern Greenland. Administratively this range is part of the Kujalleq municipality. This mountain group was named after Kangerluluk, the fjord flanking the range on the southern side."},{"n":"Qulleq","lat":61.55,"lon":-42.2667,"s":4,"w":"Qulleq","ty":"island","u":0,"b":"Qulleq, Qutdleq or Kutdlek is an uninhabited island in the King Frederick VI Coast, Sermersooq municipality in southern Greenland."},{"n":"Paatusoq","lat":60.7833,"lon":-43.0,"s":4,"w":"Paatusoq","ty":"body of water","u":0,"b":"Paatusoq, mentioned as 'Patursok' by Wilhelm August Graah, is a fjord in the King Frederick VI Coast, Kujalleq municipality, southeastern Greenland. Its name means \"The one with the big mouth\" in Greenlandic."},{"n":"Igutsaat Fjord","lat":61.1333,"lon":-42.6,"s":4,"w":"Igutsaat Fjord","ty":"fjord","u":0,"b":"Igutsaat Fjord, also known as Igutsait Fjord, is a fjord in the King Frederick VI Coast, Kujalleq municipality, southern Greenland. Deposits of rare minerals have been found in this fjord, as well as in neighbouring Kangerluluk."},{"n":"Iluileq Fjord","lat":60.8667,"lon":-43.0667,"s":4,"w":"Iluileq Fjord","ty":"fjord","u":0,"b":"Iluileq (Danish: Danell Fjord) is a fjord in the King Frederick VI Coast, Kujalleq municipality, southern Greenland. This fjord was named by Wilhelm August Graah after David Danell, a Dutchman who made three expeditions to Greenland in 1652-54 sent by King Frederick III of Denmark."},{"n":"Aluk Island","lat":60.1572,"lon":-43.08,"s":3,"w":"Aluk Island","ty":"island","u":0,"b":"Aluk Island or Aluk Avalleq is an island off Prins Christian Sound, in Kujalleq municipality in southern Greenland. It is located to the east of Aluk Tunorleq island. This island is the type locality for allanite a member of the epidote mineral group."},{"n":"Kangerluk Fjord","lat":60.9833,"lon":-42.7667,"s":3,"w":"Kangerluk Fjord","ty":"fjord","u":0,"b":"Kangerluk, also known as Kangerluluarak, is a fjord in the King Frederick VI Coast, Kujalleq municipality, southern Greenland."},{"n":"Kangerluluk","lat":61.1,"lon":-43.0833,"s":3,"w":"Kangerluluk","ty":"body of water","u":0,"b":"Kangerluluk, meaning 'the awful fjord', is a fjord in the King Frederick VI Coast, Kujalleq municipality, southern Greenland. Deposits of rare minerals have been found in this fjord, as well as in neighbouring Igutsaat Fjord."},{"n":"Kangerluaraq","lat":60.5833,"lon":-42.9833,"s":3,"w":"Kangerluaraq","ty":"fjord","u":0,"b":"Kangerluaraq, old spelling Kangerdluaraq, is a fjord in the King Frederick VI Coast, Kujalleq municipality, southern Greenland."},{"n":"Kuutseq","lat":60.6333,"lon":-42.9,"s":3,"w":"Kuutseq","ty":"fjord","u":0,"b":"Kuutseq is a fjord in the King Frederick VI Coast, Kujalleq municipality, southern Greenland."},{"n":"Iluileq","lat":60.8667,"lon":-42.8,"s":3,"w":"Iluileq","ty":"island","u":0,"b":"Iluileq (named 'Ilivilik' in old maps) is an uninhabited island in the Kujalleq municipality in southern Greenland."},{"n":"Nanuuseq Fjord","lat":60.5167,"lon":-43.25,"s":3,"w":"Nanuuseq Fjord","ty":"body of water","u":0,"b":"Nanuuseq Fjord, old spelling Nanûseq, is a fjord in the King Frederick VI Coast, Kujalleq municipality, southern Greenland."},{"n":"Napasorsuaq Fjord","lat":61.7167,"lon":-42.5833,"s":3,"w":"Napasorsuaq Fjord","ty":"body of water","u":0,"b":"Napasorsuaq Fjord or Napasorsuup Kangerlua is a fjord of the King Frederick VI Coast in the Sermersooq municipality, southeastern Greenland."},{"n":"Nattoralik","lat":60.5167,"lon":-43.05,"s":3,"w":"Nattoralik","ty":"body of water","u":0,"b":"Nattoralik, old spelling Nagtoralik, is a fjord in the King Frederick VI Coast, Kujalleq municipality, southern Greenland. There is a Paleo-Eskimo archaeological site on the northern shore of the fjord."},{"n":"Graah Fjelde","lat":61.05,"lon":-42.9667,"s":3,"w":"Graah Mountains","ty":"nunatak","u":0,"b":"The Graah Mountains (Danish: Graah Fjelde or Graah Bjerge) are a mountain range in southeastern Greenland. Administratively this range is part of the Kujalleq municipality."},{"n":"Cape Walløe","lat":60.5833,"lon":-42.8333,"s":3,"w":"Cape Walløe","ty":"peninsula","u":0,"b":"Cape Walløe (Danish: Kap Walløe), also known as Kangeq and Kangerssiuasik, is a headland in the North Atlantic Ocean, southeast Greenland, Kujalleq municipality."},{"n":"Kap Discord","lat":60.8833,"lon":-42.6333,"s":3,"w":"Cape Discord","ty":"peninsula","u":0,"b":"Cape Discord (Danish: Kap Discord), also known as Kangeq, is a headland in the North Atlantic Ocean, southeast Greenland, Kujalleq municipality."},{"n":"Avaqqat Kangerluat","lat":61.2833,"lon":-42.8,"s":3,"w":"Avaqqat Kangerluat","ty":"fjord","u":0,"b":"Avaqqat Kangerluat, also known as Avarqqat Kangerluat, Avaqqat Kangerlua and Puiagtoq Fjord, is a fjord in the King Frederick VI Coast, Kujalleq municipality, southern Greenland."},{"n":"Avatdlerssuaq","lat":59.8167,"lon":-43.5833,"s":3,"w":"Avallersuaq","ty":"island","u":0,"b":"Avallersuaq, old spelling Avatdlerssuaq, is an uninhabited island of the Cape Farewell Archipelago in Kujalleq municipality of southern Greenland. It is a small and rocky island located east of Itilleq Island (Egger). It has an elevation of 491 metres (1,611 ft)."},{"n":"Anorituup Kangerlua","lat":61.5333,"lon":-42.7667,"s":3,"w":"Anorituup Kangerlua","ty":"body of water","u":0,"b":"Anorituup Kangerlua, also known as Anoritoq or Anortek Fjord, is a fjord in King Frederick VI Coast, southern Greenland."},{"n":"Tiningnertok","lat":60.5983,"lon":-43.8203,"s":3,"w":"Tiningnertok","ty":"mountain","u":0,"b":"Tiningnertok is a mountain in King Frederick VI Coast, Kujalleq municipality, southern Greenland. This mountain is popular among mountaineers, especially its Northeast Face, but it is of difficult access for it lies in an isolated area where climatic conditions are often rough. Its granite walls are similar to Ketil's."},{"n":"Pyramiden","lat":61.6475,"lon":-43.0175,"s":2,"w":"Pyramiden (Greenland)","ty":"mountain","u":0,"b":"Pyramiden is a mountain in King Frederick VI Coast, Kujalleq municipality, southern Greenland."},{"n":"Qaqortoq","lat":60.7167,"lon":-46.0333,"s":54,"w":"Qaqortoq","ty":"human settlement","u":0,"b":"Qaqortoq, also known as Julianehåb, is the capital city of the Kujalleq municipality in southern Greenland, located near Cape Thorvaldsen. With a population of 3,069 in 2025, it is the most populous town in Kujalleq and the fourth most in Greenland."},{"n":"Kujalleq","lat":61.0,"lon":-45.0,"s":48,"w":"Kujalleq","ty":"electoral unit|municipality of Greenland","u":0,"b":"Kujalleq is a municipality on the southern tip of Greenland, operational from 1 January 2009. The administrative center of the municipality is in Qaqortoq (formerly called Julianehåb)."},{"n":"Narsaq","lat":60.9122,"lon":-46.0486,"s":42,"w":"Narsaq","ty":"city","u":0,"b":"Narsaq (Greenlandic, lit. 'Plain' or 'Field'; Danish), formerly Nordprøven (Danish, lit. 'The North Test' or 'The North Trial'), is a town in Kujalleq, Greenland, Kingdom of Denmark on the shores of Tunulliarfik Fjord."},{"n":"Nanortalik","lat":60.1417,"lon":-45.2431,"s":32,"w":"Nanortalik","ty":"town","u":0,"b":"Nanortalik, formerly Nennortalik, is a town in Nanortalik Island, Kujalleq municipality, southern Greenland. With 1,072 inhabitants as of 2024, it is the eleventh-largest town in the country. The name Nanortalik means \"Place of Polar Bears\" or \"Place Where the Polar Bears Go\" (from nanoq)."},{"n":"Narsarsuaq","lat":61.1458,"lon":-45.4347,"s":31,"w":"Narsarsuaq","ty":"rural area","u":0,"b":"Narsarsuaq (lit. Great Plain; old spelling: Narssarssuaq) is a settlement in the Kujalleq municipality in southern Greenland. The settlement's economy and population of 123 inhabitants was almost entirely reliant on Narsarsuaq Airport, an old U.S. military base (Bluie West One)."},{"n":"Kujataa","lat":61.1644,"lon":-45.5981,"s":29,"w":"Kujataa","ty":"group|region","u":1,"b":"Kujataa is a sub-arctic farming landscape in Kujalleq, Greenland. It is the first known example of agriculture in the Arctic, and the oldest evidence of the Old Norse culture spreading outside Europe."},{"n":"Aappilattoq","lat":60.1503,"lon":-44.285,"s":24,"w":"Aappilattoq, Kujalleq","ty":"village","u":0,"b":"Aappilattoq or Rødførde is a village in the Kujalleq municipality in southern Greenland. The name means \"red\", after the red mountain rising above the settlement in the Greenlandic language. The settlement had 86 inhabitants in 2025."},{"n":"Eastern Settlement","lat":61.0,"lon":-45.4167,"s":24,"w":"Eastern Settlement","ty":"human settlement","u":0,"b":"The Eastern Settlement was the first and by far the larger of the two main areas of Norse Greenland, settled c. AD 985 – c. AD 1000 by Norsemen from Iceland. At its peak, it contained approximately 4,000 inhabitants."},{"n":"Qassiarsuk","lat":61.15,"lon":-45.5167,"s":24,"w":"Qassiarsuk","ty":"human settlement","u":0,"b":"Qassiarsuk is a settlement in the Kujalleq municipality, in southern Greenland. Its population was 39 in 2020. Qassiarsuk is part of the Kujataa World Heritage Site, due to its historical importance as the homestead of Erik the Red and its unique testimony to Greenlandic farming."},{"n":"Igaliku","lat":60.9878,"lon":-45.4208,"s":23,"w":"Igaliku","ty":"rural area","u":0,"b":"Igaliku is a settlement in the Kujalleq municipality in southern Greenland. The town was founded as Igaliko in 1783 by the trader and colonial administrator Anders Olsen and his Greenlandic wife, Tuperna. In 2020, Igaliku had 21 inhabitants."},{"n":"Brattahlíð","lat":61.156,"lon":-45.516,"s":22,"w":"Brattahlíð","ty":"ruins","u":0,"b":"Brattahlíð, often anglicised as Brattahlid, was Erik the Red's estate in the Eastern Settlement Viking colony he established in south-western Greenland toward the end of the 10th century. The present settlement of Qassiarsuk is now located on the former estate."},{"n":"Alluitsup Paa","lat":60.4625,"lon":-45.5694,"s":22,"w":"Alluitsup Paa","ty":"rural area","u":0,"b":"Alluitsup Paa is a village in the Kujalleq municipality in southern Greenland. Alluitsup Paa had 136 residents in 2025. Presently, the community's religious activities take place in Qaqortoq."},{"n":"Hvalsey","lat":60.8282,"lon":-45.7815,"s":20,"w":"Hvalsey","ty":"rural area|archaeological site","u":1,"b":"Hvalseyjarfjord (\"Whale Island fjord\"; Greenlandic Qaqortukulooq) is located at the back of Qaqortoq, Greenland and is the site of Greenland's largest, best-preserved Norse ruins in the area known as the Eastern Settlement. In 2017, it was inscribed on the UNESCO World Heritage List and part of the Kujataa Greenland site."},{"n":"Eqalugaarsuit","lat":60.6222,"lon":-45.9097,"s":20,"w":"Eqalugaarsuit","ty":"rural area","u":0,"b":"Eqalugaarsuit (old spelling: Eqalugârssuit) is a settlement in the Kujalleq municipality in southern Greenland, located southeast of Qaqortoq and northwest of Alluitsup Paa. It had a population of 49 in 2020. Until January 2009, the settlement — along Qassimiut and Saarloq, as well as 13 sheep farms — belonged to the Qaqortoq municipality."},{"n":"Narsarmijit","lat":60.0047,"lon":-44.6653,"s":20,"w":"Narsarmijit, Greenland","ty":"village","u":0,"b":"Narsarmijit, formerly Narsaq Kujalleq and Frederiksdal (Anglicised: Frederiksthal), is a settlement in southern Greenland. It is located in the Kujalleq municipality near Cape Thorvaldsen. Its population was 62 in 2024."},{"n":"Ammassivik","lat":60.5967,"lon":-45.3846,"s":20,"w":"Ammassivik","ty":"rural area","u":0,"b":"Ammassivik (old spelling: Angmagssivik) is a settlement in the Kujalleq municipality in southern Greenland. The modern name is the Kalaallisut for \"where you catch ammassaat (capelin)\". Its population was 74 in 2010."},{"n":"Qassimiut","lat":60.7814,"lon":-47.1597,"s":20,"w":"Qassimiut","ty":"rural area|human settlement","u":0,"b":"Qassimiut, also known by its Danish name Bødker, is a settlement in the Kujalleq municipality in southern Greenland. The settlement was founded in 1835 as a trading station. With a population of 14 in 2024, it is the smallest organised, permanent settlement in Greenland."},{"n":"Saarloq","lat":60.5376,"lon":-46.0269,"s":19,"w":"Saarloq","ty":"human settlement|island","u":0,"b":"Saarloq is a settlement in the Kujalleq municipality in southern Greenland. Its population was 21 in 2020. It is located on a small island with the same name off the Labrador Sea coast, at the mouth of the Qaqortoq Fjord, west of Alluitsup Paa and 20 km south of Qaqortoq."},{"n":"Terra Nova","lat":60.2542,"lon":-45.9292,"s":19,"w":"Terra Nova (ship)","ty":"shipwreck|ship","u":0,"b":"Terra Nova was a whaler and polar expedition ship. The ship carried the 1910 British Antarctic Expedition, Robert Falcon Scott's last expedition."},{"n":"Church of Hvalsey","lat":60.8281,"lon":-45.7804,"s":18,"w":"Hvalsey Church","ty":"church ruin","u":0,"b":"Hvalsey Church was a Catholic church at the abandoned Greenlandic Norse homestead of Hvalseyjarfjord (near modern-day Qaqortoq). The best preserved Norse ruins in Greenland, the church was also the location of the last written record of the Greenlandic Norse, a wedding in September 1408."},{"n":"Garðar","lat":60.9871,"lon":-45.4229,"s":17,"w":"Garðar, Greenland","ty":"deserted medieval village|archaeological site","u":0,"b":"Garðar was the seat of the bishop in the Norse settlements in Greenland. It was the first Catholic diocese established in the Americas and is now a Latin Catholic titular see."},{"n":"Tasiusaq","lat":60.1931,"lon":-44.8197,"s":16,"w":"Tasiusaq, Kujalleq","ty":"human settlement","u":0,"b":"Tasiusaq is a settlement in the Kujalleq municipality in southern Greenland, founded in 1933. It is located at the Tasermiut Fjord (Danish: Ketils Fjord), east of Nanortalik. Its population was 42 in 2025."},{"n":"Qinngua Valley","lat":60.3019,"lon":-44.475,"s":14,"w":"Qinngua Valley","ty":"valley","u":0,"b":"Qinngua Valley, also called Qinnguadalen, Kanginsap Qinngua and Paradisdalen, is a valley in southern Greenland, about 15 kilometres (9.3 mi) from the nearest settlement of Tasiusaq, Kujalleq. The valley has the only natural forest in Greenland and is about 15 kilometres (9.3 mi) long, running roughly north to south and terminating at Tasersuaq Lake."},{"n":"Alluitsoq","lat":60.5072,"lon":-45.5378,"s":13,"w":"Alluitsoq","ty":"rural area","u":0,"b":"Alluitsoq, formerly spelled Agdluitsoĸ, is a former settlement in southern Greenland, located on the Alluitsoq or Lichtenau Fjord near Cape Farewell. It is about 13 kilometers from Ammassivik (Sletten), located on the opposite side of the same fjord. It was founded as Lichtenau (German: \"Light Meadow\") by the Moravian missionary Gotfried Grillich and five families in 1774."},{"n":"Herjolfsnes","lat":59.9937,"lon":-44.723,"s":10,"w":"Herjolfsnes","ty":"abandoned hamlet","u":0,"b":"Herjólfsnes was a Norse Icelandic settlement in Greenland, 50 km northwest of Cape Farewell. It was established by Herjólfr Bardsson in the late 10th century and is believed to have lasted some 500 years. The fate of its inhabitants, along with all the other Norse Greenlanders, is unknown."},{"n":"Napasorsuaq","lat":60.35,"lon":-44.7333,"s":9,"w":"Napasorsuaq","ty":"mountain","u":0,"b":"The Napasorsuaq (Danish: Kirkespiret) is a 1,590m–high mountain in southern Greenland, in the Kujalleq municipality."},{"n":"Ketil (mountain)","lat":60.4167,"lon":-44.5167,"s":7,"w":"Ketil (mountain)","ty":"mountain","u":0,"b":"The Ketil (Greenlandic: Uiluit Qaqqaa, meaning \"Shell Mountain\") is a 2,010 m–high mountain in southern Greenland, in the Kujalleq municipality. Ketil's granite walls are similar to Tiningnertok's (Apostelen Tommelfinger), another massive peak in the east coast."},{"n":"Narsaq Municipality","lat":60.55,"lon":-46.0,"s":7,"w":"Narsaq Municipality","ty":"former municipality of Greenland","u":0,"b":"Narsaq Municipality was a municipality in south Greenland until 31 December 2008. The municipality consisted of Narsaq, and the settlements Qassiarsuk, Igaliku, and Narsarsuaq. Its administrative center was the town of Narsaq."},{"n":"Tasermiut Fjord","lat":60.27,"lon":-44.78,"s":7,"w":"Tasermiut Fjord","ty":"fjord","u":0,"b":"Tasermiut Fjord is a 70-kilometre-long fjord in southwestern Greenland. Administratively it is part of the Kujalleq municipality. Nanortalik Island is located near the mouth of the fjord."},{"n":"Nanortalik Church","lat":60.1377,"lon":-45.2438,"s":6,"w":"Nanortalik Church","ty":"church building","u":0,"b":"Nanortalik Church is a wooden, Danish Lutheran church in the town of Nanortalik in southern Greenland in the Arctic. The church was built and consecrated in 1916, and is currently the only church serving the Nanortalik congregation. The church is located in the old colonial quarter of the town."},{"n":"Ulamertorsuaq","lat":60.375,"lon":-44.525,"s":6,"w":"Ulamertorsuaq","ty":"mountain","u":0,"b":"The Ulamertorsuaq is a 1,858 m–high mountain in southern Greenland, in the Kujalleq municipality."},{"n":"USAT Dorchester","lat":59.3667,"lon":-48.7,"s":3,"w":"SS Dorchester","ty":"ship","u":0,"b":"Dorchester was a coastal passenger steamship requisitioned and operated by the War Shipping Administration (WSA) in January 1942 for wartime use as a troop ship allocated to United States Army requirements. The ship was operated for WSA by its agent Atlantic, Gulf & West Indies Steamship Lines (Agwilines)."},{"n":"Gannet Islands Ecological Reserve","lat":53.934,"lon":-56.505,"s":5,"w":"Gannet Islands Ecological Reserve","ty":"ecological reserve of Newfoundland and Labrador","u":0,"b":"The Gannet Islands Ecological Reserve is a remote wildlife refuge in the Labrador Sea. The Gannet Islands are a group of islands approximately 40 km northeast of Cartwright. The islands are named after the British survey ship HMS Gannet."},{"n":"Groswater Bay","lat":54.3333,"lon":-57.6658,"s":2,"w":"Groswater Bay","ty":"bay","u":0,"b":"Groswater Bay (Inuttitut: Kangerliorsoak), also known by other names, is a bay in south central Labrador, Canada. Its Hamilton Inlet and Melville Lake extensions stretch 140 km (87 mi) inland."},{"n":"Newfoundland and Labrador","lat":53.0,"lon":-60.0,"s":148,"w":"Newfoundland and Labrador","ty":"province of Canada","u":0,"b":"Newfoundland and Labrador is the easternmost province of Canada, in the country's Atlantic region. It comprises the island of Newfoundland and the continental region of Labrador, with an area of 405,212 km2 (156,453 sq mi) and a population of 552,462 in 2026."},{"n":"Churchill River","lat":53.3603,"lon":-60.1708,"s":25,"w":"Churchill River (Atlantic)","ty":"waterfall|river","u":0,"b":"The Churchill River, formerly known by other names, is a river in Newfoundland and Labrador, Canada. It flows east from the Smallwood Reservoir into the Atlantic Ocean via Lake Melville. The river is 856 km (532 mi) long and drains an area of 79,800 km2 (30,800 sq mi), making it the longest river in Atlantic Canada."},{"n":"Happy Valley-Goose Bay","lat":53.3019,"lon":-60.4167,"s":23,"w":"Happy Valley-Goose Bay","ty":"town of Newfoundland and Labrador","u":0,"b":"Happy Valley-Goose Bay (Inuit: Vâli) is a town in the province of Newfoundland and Labrador, Canada. Located in central Labrador on the coast of Lake Melville and the Churchill River, Happy Valley-Goose Bay is the largest population centre in the region with an estimated 8,040 residents in 2021."},{"n":"Lake Melville","lat":53.6822,"lon":-59.7486,"s":19,"w":"Lake Melville","ty":"lake","u":0,"b":"Lake Melville is an estuary of Hamilton Inlet (itself an extension of Groswater Bay) on the Labrador coast of the Canadian province of Newfoundland and Labrador."},{"n":"Hopedale","lat":55.4674,"lon":-60.2032,"s":16,"w":"Hopedale, Newfoundland and Labrador","ty":"town of Newfoundland and Labrador","u":0,"b":"Hopedale (Inuit language: Agvituk) is a town located in the north of Labrador, the mainland portion of the Canadian province of Newfoundland and Labrador. Hopedale is the legislative capital of the Inuit Land Claims Area Nunatsiavut, and where the Nunatsiavut Assembly meets. As of the 2021 census, it has a population of 596."},{"n":"Akami-Uapishkᵘ-KakKasuak-Mealy Mountains National Park Reserve","lat":53.4,"lon":-59.3667,"s":13,"w":"Akami−Uapishkᵘ−KakKasuak−Mealy Mountains National Park Reserve","ty":"national park|national park of Canada","u":0,"b":"Akami−Uapishkᵘ−KakKasuak−Mealy Mountains National Park Reserve is a national park reserve in the Labrador region of Newfoundland and Labrador. Established in 2015, its area covers approximately 10,700 square kilometres (4,131 sq mi)."},{"n":"Port Hope Simpson","lat":52.5333,"lon":-56.3,"s":11,"w":"Port Hope Simpson","ty":"town of Newfoundland and Labrador","u":0,"b":"Port Hope Simpson is a town located on the southeastern Labrador coast, 215 km (134 mi) from the Quebec/Southern Labrador border in Canada. In 1944 it was named after John Hope Simpson as a company town. With the completion of the Trans-Labrador Highway that crosses the region, the town has benefitted from an increase in tourism."},{"n":"Makkovik","lat":55.0904,"lon":-59.1762,"s":10,"w":"Makkovik","ty":"town of Newfoundland and Labrador","u":0,"b":"Makkovik is a town in Labrador in eastern Canada. It had 365 residents in 2021. The main industry is snow crabbing and there is a fishing cooperative."},{"n":"Postville","lat":54.9083,"lon":-59.7725,"s":10,"w":"Postville, Newfoundland and Labrador","ty":"town of Newfoundland and Labrador","u":0,"b":"Postville is an Inuit town in the north of Labrador, Canada. It had a population of 188 as of 2021. It is located about 40 km (25 mi) inside Kaipokok Bay, 180 km (110 mi) NNE of Happy Valley-Goose Bay."},{"n":"Cartwright","lat":53.7078,"lon":-57.0161,"s":10,"w":"Cartwright, Newfoundland and Labrador","ty":"town of Newfoundland and Labrador","u":0,"b":"Cartwright is a community located on the eastern side of the entrance to Sandwich Bay, along the southern coast of Labrador in the province of Newfoundland and Labrador, Canada. It was incorporated in 1956. Sandwich Bay is an area with a longstanding Inuit presence known to resident Inuit as Natsiktok or place of the ring seals."},{"n":"North West River","lat":53.5356,"lon":-60.1439,"s":9,"w":"North West River","ty":"town of Newfoundland and Labrador","u":0,"b":"North West River is a small town located in central Labrador. Established in 1743 as a trading post by French Fur Trader Louis Fornel, the community later went on to become a hub for the Hudson's Bay Company and home to a hospital and school serving the needs of coastal Labrador. North West River is the oldest modern settlement in Labrador."},{"n":"Rigolet","lat":54.1667,"lon":-58.4333,"s":9,"w":"Rigolet","ty":"town of Newfoundland and Labrador","u":0,"b":"Rigolet (Inuttitut: Tikigâksuagusik) (population 327) is a remote, coastal Labrador community established in 1735 by French-Canadian trader Louis Fornel. The town is the southernmost officially recognized Inuit community in the world."},{"n":"Hamilton Inlet","lat":53.8381,"lon":-59.1378,"s":8,"w":"Hamilton Inlet","ty":"inlet","u":0,"b":"Hamilton Inlet is a fjord-like inlet of Groswater Bay on the Labrador coast of the Canadian province of Newfoundland and Labrador. Together with Lake Melville, it forms its province's largest estuary, extending over 140 km (87 mi) inland to Happy Valley-Goose Bay and primarily draining the Churchill River and Naskaupi River watersheds."},{"n":"Quest","lat":53.1667,"lon":-54.45,"s":8,"w":"Quest (ship)","ty":"shipwreck|schooner|steamship","u":0,"b":"Quest was a low-powered, schooner-rigged steamship that sailed from 1917 until sinking in 1962, best known as the polar exploration vessel of the Shackleton–Rowett Expedition of 1921–1922. It was aboard this vessel that Sir Ernest Shackleton died on 5 January 1922 while in harbour in South Georgia."},{"n":"Saint-Augustin River","lat":52.596,"lon":-59.472,"s":7,"w":"Saint-Augustin River","ty":"river","u":0,"b":"The Saint-Augustin River is a salmon river in the Côte-Nord region of Quebec, Canada. It empties into the Gulf of Saint Lawrence."},{"n":"Mealy Mountains","lat":53.38,"lon":-59.47,"s":7,"w":"Mealy Mountains","ty":"mountain range","u":0,"b":"The Mealy Mountains is a mountain range in the southern portion of Labrador in the Canadian province of Newfoundland and Labrador. The mountains lie south of Lake Melville and cover an area of approximately 26,495 km2 (10,231 mi2)."},{"n":"Hawke Island","lat":53.0667,"lon":-55.8323,"s":6,"w":"Hawke Island","ty":"island","u":0,"b":"Hawke Island is a small island off of the coast of Labrador. There is a harbour on the east side of the island named Hawke Harbour, or sometimes Hawke Bay. The Newfoundland Whaling Company operated a whaling station in Hawke Harbour in the late 1930s."},{"n":"Newfoundland expedition","lat":52.6244,"lon":-59.685,"s":6,"w":"Newfoundland expedition","ty":"military expedition","u":0,"b":"The Newfoundland expedition was a series of fleet manoeuvres and amphibious landings in the coasts of Newfoundland, Labrador and Saint Pierre and Miquelon carried out by the combined French and Spanish fleets during the French Revolutionary Wars."},{"n":"St. Paul River","lat":52.6408,"lon":-58.5015,"s":6,"w":"Saint-Paul River","ty":"river","u":0,"b":"The Saint-Paul River is a river on the Labrador Peninsula of eastern Canada. Its source is located in the province of Newfoundland and Labrador and it empties into the Gulf of Saint Lawrence in the Côte-Nord region of Quebec. The Saint-Paul River is a salmon river that flows in a southerly direction."},{"n":"Labrador","lat":54.0,"lon":-62.0,"s":52,"w":"Labrador","ty":"region","u":0,"b":"Labrador is a geographic and cultural region within the Canadian province of Newfoundland and Labrador. It is the primarily continental portion of the province and constitutes 71% of the province's area but is home to only 6% of its population. It is separated from the island of Newfoundland by the Strait of Belle Isle."},{"n":"Bonne-Espérance","lat":51.4719,"lon":-57.7081,"s":15,"w":"Bonne-Espérance, Quebec","ty":"municipality","u":0,"b":"Bonne-Espérance is a municipality in the Côte-Nord region of the province of Quebec in Canada. The municipality is made up of the fishing villages of St. Paul's River (Rivière-Saint-Paul), Middle Bay (Baie du Milieu), and Old Fort (Old Fort Bay), and was incorporated as a municipality on January 1, 1990."},{"n":"Saint-Augustin","lat":51.2167,"lon":-58.65,"s":12,"w":"Saint-Augustin, Côte-Nord, Quebec","ty":"municipality","u":0,"b":"Saint-Augustin is a municipality and settlement in Le Golfe-du-Saint-Laurent Regional County Municipality in the Côte-Nord region of Quebec, Canada, known by its large English-speaking population as St. Augustine."},{"n":"Petit-Mécatina","lat":51.5,"lon":-60.0,"s":6,"w":"Petit-Mécatina","ty":"unorganized area in Quebec","u":0,"b":"Petit-Mécatina is an unorganized territory in the Côte-Nord region of Quebec, Canada, part of Le Golfe-du-Saint-Laurent Regional County Municipality. It was formerly part of the Minganie Regional County Municipality, but transferred to the current MRC in July 2010."},{"n":"Pakuashipi","lat":51.2303,"lon":-58.6717,"s":6,"w":"Pakuashipi","ty":"Indian reservation of Canada|Native settlement","u":0,"b":"Pakuashipi is an Innu community in the Canadian province of Quebec, located on the north shore of the Gulf of Saint Lawrence in the Côte-Nord region. It is on the western shore of the mouth of the Saint-Augustin River, opposite the settlement of Saint-Augustin."},{"n":"Rivière Musquaro","lat":51.2294,"lon":-61.2673,"s":6,"w":"Musquaro River","ty":"river","u":0,"b":"The River Musquaro flows south in the municipality of Côte-Nord-du-Golfe-du-Saint-Laurent, Quebec, in the Le Golfe-du-Saint-Laurent Regional County Municipality, in the administrative region of Côte-Nord (North-Shore), in Quebec, in Canada."},{"n":"St. Lawrence River","lat":49.6667,"lon":-64.5,"s":104,"w":"St. Lawrence River","ty":"river","u":0,"b":"The St. Lawrence River is a large international river in the middle latitudes of North America connecting the Great Lakes with the North Atlantic Ocean. Its waters flow in a northeasterly direction from Lake Ontario to the Gulf of St."},{"n":"Havre-Saint-Pierre","lat":50.245,"lon":-63.5972,"s":18,"w":"Havre-Saint-Pierre","ty":"municipality","u":0,"b":"Havre-Saint-Pierre is a municipality located on the north shore of the Gulf of St. Lawrence, in Côte-Nord region, Minganie RCM, Quebec, Canada."},{"n":"Smallwood Reservoir","lat":54.0964,"lon":-64.0111,"s":18,"w":"Smallwood Reservoir","ty":"reservoir|waterfall","u":0,"b":"The Smallwood Reservoir is the reservoir created for the Churchill Falls Generating Station in the western part of Labrador, Canada. Unlike other reservoirs, water is contained not by a single large dam, but by a series of 88 dikes that total 64 km (40 mi) in length in the drainage area of the Churchill River."},{"n":"Mingan Archipelago National Park Reserve","lat":50.2,"lon":-63.8292,"s":18,"w":"Mingan Archipelago National Park Reserve","ty":"national park of Canada|national park","u":0,"b":"Mingan Archipelago National Park Reserve or Mingan Archipelago Heritage Site bathes in the waters of the Gulf of St. Lawrence, in the administrative region of Côte-Nord, in Minganie RCM, Havre-Saint-Pierre municipality, facing Anticosti Island."},{"n":"Churchill Falls","lat":53.5947,"lon":-64.3083,"s":17,"w":"Churchill Falls","ty":"waterfall","u":0,"b":"Churchill Falls is a 245 ft (74.7 m) high waterfall on the Churchill River in Labrador, Canada. Formerly counted among the most impressive natural features of Canada, the diversion of the river for the Churchill Falls Generating Station has cut off almost all of the falls' former flow, leaving a small stream winding through its old bed and trickling down the rocks."},{"n":"Natashquan","lat":50.1833,"lon":-61.8167,"s":16,"w":"Natashquan","ty":"municipality","u":0,"b":"Natashquan is a municipality located on the north shore of Jacques Cartier Strait, on the Gulf of St. Lawrence, in the Côte-Nord region, Minganie RCM, Quebec, Canada. Natashquan stretches along the coast, on both sides of the Little Natashquan River, about 120 km east of Havre-Saint-Pierre, near Aguanish and the Natashkuan Indian reserve."},{"n":"Côte-Nord-du-Golfe-du-Saint-Laurent","lat":50.4995,"lon":-59.4788,"s":15,"w":"Côte-Nord-du-Golfe-du-Saint-Laurent","ty":"municipality","u":0,"b":"Côte-Nord-du-Golfe-du-Saint-Laurent is a municipality in the regional county municipality of Le Golfe-du-Saint-Laurent in the Côte-Nord region of the province of Quebec, Canada. The municipality consists of two non-contiguous areas, both along the shores of the Gulf of Saint Lawrence."},{"n":"Gros-Mécatina","lat":50.8333,"lon":-58.9667,"s":14,"w":"Gros-Mécatina","ty":"municipality","u":0,"b":"Gros-Mécatina is a municipality on the Lower North Shore of the Gulf of Saint Lawrence, near the border with Labrador in Quebec, Canada. Located near crab, lobster, and scallop fishing grounds, it is dependent on the fishing business, including a fish processing factory that contributes to regional economic activity."},{"n":"Baie-Johan-Beetz","lat":50.2833,"lon":-62.8,"s":13,"w":"Baie-Johan-Beetz","ty":"municipality","u":0,"b":"Baie-Johan-Beetz is a municipality located near the mouth of the Piashti River on the north shore of the Gulf of St. Lawrence, in the Côte-Nord region, Minganie RCM, Quebec, Canada."},{"n":"Minganie Regional County Municipality","lat":50.2333,"lon":-63.6,"s":13,"w":"Minganie Regional County Municipality","ty":"regional county municipality of Quebec","u":0,"b":"Minganie is a regional county municipality on the north shore of the Gulf of St. Lawrence, in the Côte-Nord region of Quebec, Canada. Its territory includes Anticosti Island."},{"n":"Longue-Pointe-de-Mingan","lat":50.2667,"lon":-64.15,"s":13,"w":"Longue-Pointe-de-Mingan","ty":"municipality","u":0,"b":"Longue-Pointe-de-Mingan is a municipality located on the north shore of the Gulf of St. Lawrence, in Minganie Regional County Municipality (RCM), Côte-Nord region, Quebec, Canada."},{"n":"Aguanish","lat":50.2167,"lon":-62.0833,"s":12,"w":"Aguanish, Quebec","ty":"municipality","u":0,"b":"Aguanish is a municipality located in Côte-Nord region on the banks of the Aguanish River, on the north shore of Jacques Cartier Strait, in the Gulf of St. Lawrence, in Minganie Regional County Municipality, Quebec, Canada. In addition to Aguanish itself, the municipality includes the hamlet of L'Île-Michon, 3.5 kilometres (2.2 mi) to the east."},{"n":"Churchill Falls Generating Station","lat":53.5287,"lon":-63.9659,"s":12,"w":"Churchill Falls Generating Station","ty":"hydroelectric power station","u":0,"b":"The Churchill Falls Generating Station is a hydroelectric underground power station in Labrador, Canada. At 5,428 MW, it is the sixteenth largest in the world, and the second-largest in Canada, after the Robert-Bourassa generating station in northwestern Quebec. Rather than a single large dam, the plant's reservoir is contained by 88 dikes, totalling 64 km in length."},{"n":"Rivière-au-Tonnerre","lat":50.2667,"lon":-64.7833,"s":12,"w":"Rivière-au-Tonnerre","ty":"municipality","u":0,"b":"Rivière-au-Tonnerre, municipality located on the North shore of the Gulf of St. Lawrence, in Côte-Nord region, Minganie Regional County Municipality, in the province of Quebec, Canada."},{"n":"Jacques Cartier Strait","lat":49.9667,"lon":-62.7833,"s":11,"w":"Jacques Cartier Strait","ty":"strait","u":0,"b":"The Jacques Cartier Strait is an arm of the sea located in the Gulf of St. Lawrence, between the shore of Côte-Nord region and the North of Anticosti Island, in Quebec, Canada."},{"n":"Romaine River","lat":52.7813,"lon":-63.6764,"s":10,"w":"Romaine River","ty":"river","u":0,"b":"The Romaine River (French: Rivière Romaine), known also as the Kanatuahkuiau, Uanaman Hipu, and Uepatauekat Shipu, is a river in eastern Canada. It flows from north to south, emptying into the Jacques Cartier Strait in the municipality of Havre-Saint-Pierre."},{"n":"Rivière Natashquan","lat":52.5167,"lon":-63.7625,"s":10,"w":"Natashquan River","ty":"watercourse","u":0,"b":"The Natashquan is a river in the Canadian provinces of Quebec and Newfoundland and Labrador. It flows south into the Gulf of Saint Lawrence."},{"n":"Atikonak Lake","lat":52.6667,"lon":-64.5325,"s":10,"w":"Atikonak Lake","ty":"lake","u":0,"b":"Atikonak Lake is a lake in southern Labrador near the border with Quebec, Canada. The flora is population of endemic genus Atikonakia of Volvocaceae."},{"n":"Le Golfe-du-Saint-Laurent Regional County Municipality","lat":50.4833,"lon":-59.6167,"s":9,"w":"Le Golfe-du-Saint-Laurent Regional County Municipality","ty":"regional county municipality of Quebec","u":0,"b":"Le Golfe-du-Saint-Laurent is a regional county municipality in the Côte-Nord region of far-eastern Quebec, Canada. It includes all communities along the Gulf of Saint Lawrence between the Natashquan River and the Newfoundland and Labrador border."},{"n":"Little Mecatina River","lat":50.6567,"lon":-59.4286,"s":9,"w":"Little Mecatina River","ty":"river","u":0,"b":"The Little Mécatina River is a major river in the Côte-Nord region of Quebec, Canada, with tributaries extending into Labrador. Studies have been made to exploit the hydroelectric potential of the river, which could be around 1,200 MW from three dams."},{"n":"Rivière-Saint-Jean","lat":50.3,"lon":-64.3333,"s":9,"w":"Rivière-Saint-Jean, Quebec","ty":"municipality","u":0,"b":"Rivière-Saint-Jean,, \"St. John River\", is a municipality located close to the mouth of the Saint-Jean River and the north shore of the Gulf of St. Lawrence, Côte-Nord region, Minganie RCM, Quebec, Canada."},{"n":"Churchill Falls","lat":53.5317,"lon":-64.0083,"s":9,"w":"Churchill Falls, Newfoundland and Labrador","ty":"locality","u":0,"b":"Churchill Falls is a community in the province of Newfoundland and Labrador, Canada. It is home to the Churchill Falls Generating Station and is a company town."},{"n":"Anticosti Island","lat":49.4777,"lon":-62.5387,"s":48,"w":"Anticosti Island","ty":"island","u":0,"b":"Anticosti Island is a large but sparsely populated island belonging to the Canadian province of Quebec. It lies in the Gulf of St. Lawrence, and is separated from mainland Quebec by the Jacques Cartier and Honguedo straits."},{"n":"Gaspé","lat":48.831,"lon":-64.4844,"s":44,"w":"Gaspé, Quebec","ty":"city or town of Quebec","u":0,"b":"Gaspé is a city at the tip of the Gaspé Peninsula in the Gaspésie–Îles-de-la-Madeleine region of eastern Quebec in Canada. Gaspé is about 650 km (400 mi) northeast of Quebec City and 350 km (220 mi) east of Rimouski. Gaspé has a total population of 15,063, as of the 2021 Canadian Census."},{"n":"Sept-Îles","lat":50.2167,"lon":-66.3833,"s":37,"w":"Sept-Îles","ty":"port city|city or town of Quebec","u":0,"b":"Sept-Îles is a city in the Côte-Nord region of eastern Quebec. Along with Brador and Blanc-Sablon, Sept-Îles is one of the oldest places in the province. The population was 24,569 as of the 2021 Canadian census."},{"n":"British North America","lat":48.6002,"lon":-67.6842,"s":36,"w":"British North America","ty":"historical region","u":0,"b":"British North America comprised the colonial territories of Great Britain and later the United Kingdom in North America from 1783 onwards."},{"n":"Côte-Nord","lat":50.8667,"lon":-65.8167,"s":35,"w":"Côte-Nord","ty":"administrative region of Quebec","u":0,"b":"Côte-Nord (Region 09) is an administrative region of Quebec, on the Quebec-Labrador Peninsula, Canada. The region runs along the St. Lawrence River and then the Gulf of St."},{"n":"Gaspé Peninsula","lat":48.7238,"lon":-65.4511,"s":33,"w":"Gaspé Peninsula","ty":"peninsula","u":0,"b":"The Gaspé Peninsula, also known as Gaspesia (French: Gaspésie,), is a peninsula on the southern side of the St. Lawrence River, in Quebec, Canada. It is separated from New Brunswick to the south by Chaleur Bay."},{"n":"Amqui","lat":48.4624,"lon":-67.4332,"s":32,"w":"Amqui","ty":"city or town of Quebec","u":0,"b":"Amqui is a town in eastern Quebec, Canada, at the base of the Gaspé peninsula in Bas-Saint-Laurent. Located at the confluence of the Humqui and Matapédia Rivers, it is the seat of La Matapédia Regional County Municipality. The main access road is Quebec Route 132."},{"n":"Atikamekw","lat":51.0,"lon":-66.0,"s":31,"w":"Atikamekw language","ty":"modern language|natural language","u":0,"b":"Atikamekw is a variety of the Algonquian language Cree and the language of the Atikamekw people of southwestern Quebec, Canada. It is spoken by nearly all the Atikamekw, and therefore it is among the indigenous languages least threatened with extinction, according to some studies."},{"n":"Gaspésie–Îles-de-la-Madeleine","lat":48.6833,"lon":-65.4,"s":29,"w":"Gaspésie–Îles-de-la-Madeleine","ty":"administrative region of Quebec","u":0,"b":"Gaspésie–Îles-de-la-Madeleine is an administrative region of Quebec consisting of the Gaspé Peninsula (Gaspésie) and the Îles-de-la-Madeleine. It lies in the Gulf of Saint Lawrence at the eastern extreme of southern Quebec. The predominant economic activities are fishing, forestry and tourism."},{"n":"Matane","lat":48.8433,"lon":-67.5306,"s":29,"w":"Matane","ty":"city or town of Quebec","u":0,"b":"Matane is a town on the Gaspé Peninsula in Quebec, Canada, on the south shore of the Saint Lawrence River at the mouth of the Matane River. The town is the seat for the La Matanie Regional County Municipality. In addition to Matane itself, the town's territory also includes the communities of Petit-Matane and Saint-Luc-de-Matane."},{"n":"Percé","lat":48.5333,"lon":-64.2167,"s":29,"w":"Percé, Quebec","ty":"city or town of Quebec|village","u":0,"b":"Percé is a city located on the shores of the Gulf of St. Lawrence, near the tip of the Gaspé Peninsula, in Gaspésie-Îles-de-la-Madeleine, Quebec, Canada. Percé, member of the association of Most Beautiful Villages of Quebec, is mainly a tourist location particularly well known for the attractions of Percé Rock and Bonaventure Island."},{"n":"Port-Cartier","lat":50.0333,"lon":-66.8667,"s":24,"w":"Port-Cartier","ty":"city or town of Quebec","u":0,"b":"Port-Cartier is a city in the Côte-Nord region of Quebec, Canada. It is located on the north shore of the St. Lawrence River at the mouth of the Aux-Rochers River, 63 kilometres (39 mi) southwest of Sept-Îles, Quebec."},{"n":"Causapscal","lat":48.355,"lon":-67.2251,"s":23,"w":"Causapscal","ty":"city or town of Quebec","u":0,"b":"Causapscal is a city in the Canadian province of Quebec, located in La Matapédia Regional County Municipality. It is located at the confluence of the Matapédia and Causapscal Rivers, along Quebec Route 132, approximately halfway between Mont-Joli and Campbellton, New Brunswick. It is served by the Causapscal railway station and the Causapscal Airport."},{"n":"Sayabec","lat":48.5667,"lon":-67.6833,"s":23,"w":"Sayabec","ty":"municipality","u":0,"b":"Sayabec is a municipality located in the La Matapédia Regional County Municipality (RCM) in Bas-Saint-Laurent, Quebec, Canada. It is located in the Matapédia Valley between the Chic-Choc Mountains of the Appalachian near Lake Matapédia. The main activities of the village are agriculture and forestry."},{"n":"Forillon National Park","lat":48.9,"lon":-64.35,"s":22,"w":"Forillon National Park","ty":"national park of Canada|national park","u":0,"b":"Forillon National Park, one of 42 national parks and park reserves across Canada, is located at the outer tip of the Gaspé Peninsula of Quebec and covers 244 km2 (94 sq mi). Created in 1970, Forillon was the first national park in Quebec. The park includes forests, sea coast, salt marshes, sand dunes, cliffs, and the Eastern End of the Appalachians."},{"n":"Chandler","lat":48.35,"lon":-64.6833,"s":22,"w":"Chandler, Quebec","ty":"city or town of Quebec|town","u":0,"b":"Chandler is a town in the Gaspésie–Îles-de-la-Madeleine region of Quebec, Canada. It is the second-most populous town on the Gaspé Peninsula after the Town of Gaspé. It was known as Pabos between June 27, 2001, and May 4, 2002."},{"n":"Sainte-Anne-des-Monts","lat":49.1333,"lon":-66.5,"s":22,"w":"Sainte-Anne-des-Monts","ty":"city or town of Quebec","u":0,"b":"Sainte-Anne-des-Monts, is a city in La-Haute-Gaspésie Regional County Municipality, Gaspésie–Îles-de-la-Madeleine region, Quebec province, in Canada. Sainte-Anne-des-Monts is located close to the Chic-Choc Mountains on the south shore of Gulf of St Lawrence."},{"n":"New Richmond","lat":48.1667,"lon":-65.8667,"s":21,"w":"New Richmond, Quebec","ty":"city or town of Quebec","u":0,"b":"New Richmond (French pronunciation:; Gesgapegiag Mi'kmaq: Qame'g, lit. 'other side (of the river)') is an incorporated municipality in Quebec, Canada, situated on the southern coast of the Gaspé Peninsula between the municipalities of Maria and Caplan. New Richmond is bounded on the west by the Grand Cascapedia River. The Little Cascapedia runs to the east of the town proper."},{"n":"Cap-Chat","lat":49.1,"lon":-66.6833,"s":20,"w":"Cap-Chat","ty":"city or town of Quebec","u":0,"b":"Cap-Chat is a town in the Canadian province of Québec, in the Regional County Municipality of Haute-Gaspésie, and in the administrative region of Gaspésie-Îles-de-la-Madeleine. Cap-Chat is found 16 kilometres (9.9 mi) west of Sainte-Anne-des-Monts. As of 2021, Cap-Chat's population is 2,516."},{"n":"Murdochville","lat":48.9667,"lon":-65.5,"s":19,"w":"Murdochville","ty":"city or town of Quebec","u":0,"b":"Murdochville is a city in Quebec, Canada, one of only a few inland communities on the Gaspé Peninsula. Its population (as of 2021) is 643."},{"n":"Grande-Rivière","lat":48.4,"lon":-64.5,"s":19,"w":"Grande-Rivière, Quebec","ty":"city or town of Quebec","u":0,"b":"Grande-Rivière is a city in the Gaspésie-Îles-de-la-Madeleine region of the province of Québec in Canada. In addition to Grande-Rivière itself at the mouth of the namesake Grand River, the town's territory also includes the communities of Grande-Rivière-Ouest, Petite-Rivière-Ouest, and Petit Pabos. Its economy is based on the fishing industry."},{"n":"Perce Rock","lat":48.5239,"lon":-64.1994,"s":15,"w":"Percé Rock","ty":"natural arch|tidal island|rock","u":0,"b":"Percé Rock is a huge sheer rock formation in the Gulf of Saint Lawrence on the tip of the Gaspé Peninsula in Quebec, Canada, off Percé Bay. Percé Rock appears from a distance like a ship under sail. It is one of the world's largest natural arches located in water and is considered a geologically and historically rich natural icon of Quebec."},{"n":"New Brunswick","lat":46.6,"lon":-66.0,"s":145,"w":"New Brunswick","ty":"province of Canada","u":0,"b":"New Brunswick is a province of Canada, bordering Quebec to the northwest, the Gulf of Saint Lawrence to the northeast, Nova Scotia to the east, the Bay of Fundy to the southeast, and the U.S. state of Maine to the southwest. It is part of Eastern Canada and is one of the three Maritime provinces and one of the four Atlantic provinces."},{"n":"Acadia","lat":47.6653,"lon":-65.7542,"s":55,"w":"Acadia (region)","ty":"ethnic territory","u":0,"b":"Acadia is a North American cultural region in the Maritime provinces of Canada where approximately 300,000 French-speaking Acadians live. The region lacks clear or formal borders; it is usually considered to be the north and east of New Brunswick as well as many localities in Prince Edward Island and Nova Scotia. Some also include a few localities in Quebec and/or Maine."},{"n":"Aroostook County","lat":46.6374,"lon":-68.2617,"s":53,"w":"Aroostook County, Maine","ty":"county of Maine","u":0,"b":"Aroostook County is the northernmost county in the U.S. state of Maine, located along the Canada–United States border. As of the 2020 census, the population was 67,105. The county seat is Houlton, with offices in Caribou and Fort Kent."},{"n":"Rimouski","lat":48.45,"lon":-68.5333,"s":48,"w":"Rimouski","ty":"city or town of Quebec","u":0,"b":"Rimouski is a city in Quebec, Canada. Rimouski is located in the Bas-Saint-Laurent region, at the mouth of the Rimouski River. As of 2021, the city has a population of 48,935."},{"n":"Presque Isle","lat":46.6794,"lon":-68.0022,"s":45,"w":"Presque Isle, Maine","ty":"city in the United States","u":0,"b":"Presque Isle ( PRESK) is the commercial center and largest city in Aroostook County, Maine, United States. The population was 8,797 at the 2020 Census. The city is home to the University of Maine at Presque Isle, Northern Maine Community College, Northern Maine Fairgrounds, the Aroostook Centre Mall, and the Presque Isle International Airport."},{"n":"Edmundston","lat":47.3765,"lon":-68.3253,"s":37,"w":"Edmundston","ty":"municipality|town","u":0,"b":"Edmundston is a city in Madawaska County, New Brunswick, Canada. Established in 1850, it had a population of 16,437 as of 2021. On January 1, 2023, Edmundston amalgamated with the village of Rivière-Verte and parts of two local service districts; revised census figures have not been released."},{"n":"Baie-Comeau","lat":49.2167,"lon":-68.15,"s":36,"w":"Baie-Comeau","ty":"city or town of Quebec","u":0,"b":"Baie-Comeau is a city in the Côte-Nord region of the province of Quebec, Canada. It is located on the shores of the St. Lawrence River, and is the seat of Manicouagan Regional County Municipality."},{"n":"Rivière-du-Loup","lat":47.8333,"lon":-69.5333,"s":35,"w":"Rivière-du-Loup","ty":"city or town of Quebec","u":0,"b":"Rivière-du-Loup is a small city on the south shore of the Saint Lawrence River in Quebec. The city is the seat for the Rivière-du-Loup Regional County Municipality and the judicial district of Kamouraska. It is one of the largest cities in Bas-Saint-Laurent."},{"n":"Miguasha National Park","lat":48.1106,"lon":-66.3694,"s":35,"w":"Miguasha National Park","ty":"paleontological site|national park of Quebec","u":1,"b":"Miguasha Provincial Park (French: Parc national de Miguasha) is a protected area near Carleton-sur-Mer on the Gaspé Peninsula of Quebec in Canada. Created in 1985 by the Government of Quebec, Miguasha was designated a World Heritage Site in 1999 in recognition of its wealth of fossils, which display a crucial time during the evolution of life on Earth."},{"n":"Fort Kent","lat":47.2586,"lon":-68.5894,"s":34,"w":"Fort Kent, Maine","ty":"town in the United States","u":0,"b":"Fort Kent (French: Fort-Kent) is a town in Aroostook County, Maine, United States, surrounding a village of the same name situated at the confluence of the Fish River and the Saint John River, on the border with New Brunswick, Canada. The population was 4,067 in the 2020 census."},{"n":"Lower Canada","lat":50.0,"lon":-69.0,"s":34,"w":"Lower Canada","ty":"crown colony","u":0,"b":"The Province of Lower Canada (French: province du Bas-Canada) was a British colony on the lower Saint Lawrence River and the shores of the Gulf of Saint Lawrence established in 1791 and abolished in 1841. It covered the southern portion of the current Province of Quebec and the Labrador region of the current Province of Newfoundland and Labrador."},{"n":"Madawaska","lat":47.3553,"lon":-68.3217,"s":33,"w":"Madawaska, Maine","ty":"New England town|human settlement","u":0,"b":"Madawaska is a town in Aroostook County, Maine, United States. The population was 3,867 at the 2020 census. Madawaska is opposite Edmundston, Madawaska County in New Brunswick, Canada, to which it is connected by the Edmundston–Madawaska Bridge over the Saint John River."},{"n":"Van Buren","lat":47.1573,"lon":-67.9353,"s":32,"w":"Van Buren, Maine","ty":"town in the United States","u":0,"b":"Van Buren is a town in Aroostook County, Maine, United States, located along the Saint John River across from Saint-Léonard, New Brunswick, Canada. The population was 2,038 at the 2020 United States census. The town is named after Martin Van Buren, the eighth president of the United States."},{"n":"Bas-Saint-Laurent","lat":48.3333,"lon":-68.6667,"s":31,"w":"Bas-Saint-Laurent","ty":"administrative region of Quebec","u":0,"b":"The Bas-Saint-Laurent is an administrative region of Quebec located along the south shore of the lower Saint Lawrence River in Quebec. The river widens at this place, later becoming a bay that discharges into the Atlantic Ocean and is often nicknamed \"Bas-du-Fleuve\" (Lower-River). The region is formed by eight regional county municipalities and 114 municipalities."},{"n":"Bathurst","lat":47.62,"lon":-65.65,"s":30,"w":"Bathurst, New Brunswick","ty":"city","u":0,"b":"Bathurst is a city in northern New Brunswick with a population of 12,157 and the 4th largest metropolitan area in New Brunswick as defined by Census Canada with a population of 31,387 as of 2021. The City of Bathurst overlooks Nepisiguit Bay, which is part of Chaleur Bay, and is at the estuary of the Nepisiguit River."},{"n":"Saint-Louis-du-Ha! Ha!","lat":47.6703,"lon":-68.9817,"s":30,"w":"Saint-Louis-du-Ha! Ha!","ty":"parish municipality","u":0,"b":"Saint-Louis-du-Ha! Ha! is a parish municipality in the Témiscouata Regional County Municipality of the Bas-Saint-Laurent region of Quebec."},{"n":"Eagle Lake","lat":47.04,"lon":-68.5895,"s":30,"w":"Eagle Lake, Maine","ty":"town in the United States","u":0,"b":"Eagle Lake (French: Lac Aigle) is a town in Aroostook County, Maine, United States. The population was 772 at the 2020 census. The town was named by a body of troops heading from Bangor to the Aroostook War for the many eagles that they saw around the lake."},{"n":"Mapleton","lat":46.6819,"lon":-68.1628,"s":29,"w":"Mapleton, Maine","ty":"town in the United States","u":0,"b":"Mapleton is a town in Aroostook County, Maine, United States. The population was 1,886 at the 2020 census."},{"n":"New Sweden","lat":46.9417,"lon":-68.1206,"s":28,"w":"New Sweden, Maine","ty":"town in the United States","u":0,"b":"New Sweden is a town in Aroostook County, Maine, United States. The population was 577 at the 2020 census."},{"n":"Saguenay River","lat":48.1292,"lon":-69.7036,"s":28,"w":"Saguenay River","ty":"river","u":0,"b":"The Saguenay River (French: Rivière Saguenay,) is a major river of Quebec, Canada. Draining Lac Saint-Jean in the Laurentian Highlands, it leaves Alma and runs east. The city of Saguenay is on the river, which drains into the Saint Lawrence River."},{"n":"Grand Isle","lat":47.3053,"lon":-68.1519,"s":27,"w":"Grand Isle, Maine","ty":"town in the United States","u":0,"b":"Grand Isle (French: Grande Île) is a town in Aroostook County, Maine, United States. The population was 366 at the 2020 census. The village of Grand Isle is in the northwestern part of the town."},{"n":"Washburn","lat":46.7825,"lon":-68.1372,"s":27,"w":"Washburn, Maine","ty":"town in the United States","u":0,"b":"Washburn is a town in Aroostook County, Maine, United States. It was incorporated on February 25, 1861, and named after Israel Washburn, the governor of Maine at the time. The population was 1,527 at the 2020 census."},{"n":"Allagash","lat":47.0834,"lon":-69.0412,"s":27,"w":"Allagash, Maine","ty":"town in the United States","u":0,"b":"Allagash is a town in Aroostook County, Maine, United States. It is on the Allagash River in the North Maine Woods region. The population was 237 at the 2020 census."},{"n":"Chapman","lat":46.6481,"lon":-68.1608,"s":26,"w":"Chapman, Maine","ty":"town in the United States","u":0,"b":"Chapman is a town in Aroostook County, Maine, United States. The population was 491 at the 2020 census."},{"n":"Miramichi","lat":47.0225,"lon":-65.5089,"s":26,"w":"Miramichi, New Brunswick","ty":"municipal government in Canada|city","u":0,"b":"Miramichi is the largest city in northern New Brunswick, Canada. It is situated at the mouth of the Miramichi River where it enters Miramichi Bay. The Miramichi Valley is the second longest valley in New Brunswick, after the Saint John River Valley."},{"n":"Perham","lat":46.8442,"lon":-68.1972,"s":26,"w":"Perham, Maine","ty":"town in the United States","u":0,"b":"Perham is a town in Aroostook County, Maine, United States. The population was 371 at the 2020 census. The town was named after Maine's 33rd governor, Sidney Perham."},{"n":"Ashland","lat":46.6311,"lon":-68.4061,"s":26,"w":"Ashland, Maine","ty":"town in the United States","u":0,"b":"Ashland is a town in Aroostook County, Maine, United States. The population was 1,202 at the 2020 census."},{"n":"Easton","lat":46.6411,"lon":-67.9094,"s":25,"w":"Easton, Maine","ty":"town in the United States","u":0,"b":"Easton is a town in Aroostook County, Maine, United States. The population was 1,320 at the 2020 census."},{"n":"Maine","lat":45.5,"lon":-69.0,"s":216,"w":"Maine","ty":"U.S. state","u":0,"b":"Maine ( MAYN) is a state in the New England region of the United States, and the northeasternmost state in the contiguous United States. It borders New Hampshire to the west, the Gulf of Maine to the southeast, and the Canadian provinces of New Brunswick and Quebec to the northeast and northwest, and shares a maritime border with Nova Scotia."},{"n":"Quebec City","lat":46.8161,"lon":-71.2242,"s":149,"w":"Quebec City","ty":"territory outside RCM in Quebec|big city|city or town of Quebec","u":0,"b":"Quebec City (French: Ville de Québec) is the capital city of the Canadian province of Quebec. As of July 2021, the city had a population of 549,459 and the Quebec City census metropolitan area (including surrounding communities) had a population of 839,311. It is the twelfth-largest city and the seventh-largest metropolitan area in Canada."},{"n":"New France","lat":46.8167,"lon":-71.2,"s":77,"w":"New France","ty":"colony|viceroyalty","u":0,"b":"New France was the territory colonized by France in mainland North America, beginning with the exploration of the Gulf of Saint Lawrence by Jacques Cartier in 1534 and ending with the cession of New France to Great Britain and Spain in 1763 under the Treaty of Paris."},{"n":"Saguenay","lat":48.4167,"lon":-71.0667,"s":57,"w":"Saguenay, Quebec","ty":"big city|city or town of Quebec|territory outside RCM in Quebec|equivalent territory","u":0,"b":"Saguenay is a city in the Saguenay–Lac-Saint-Jean region of Quebec, Canada, on the Saguenay River, about 200 kilometres (120 mi) north of Quebec City by overland route. It is about 126 kilometres (78 mi) upriver and northwest of Tadoussac, located at the confluence with the St. Lawrence River."},{"n":"Lévis","lat":46.8,"lon":-71.1833,"s":53,"w":"Lévis","ty":"big city|equivalent territory|territory outside RCM in Quebec|city or town of Quebec","u":0,"b":"Lévis is a city in eastern Quebec, Canada, located on the south shore of the St. Lawrence River, opposite Quebec City. A ferry links Old Quebec with Old Lévis, and two bridges, the Quebec Bridge and the Pierre-Laporte Bridge, connect western Lévis with Quebec City."},{"n":"Washington County","lat":44.94,"lon":-67.5503,"s":53,"w":"Washington County, Maine","ty":"county of Maine","u":0,"b":"Washington County is a county located in the U.S. state of Maine. As of the 2020 census, its population was 31,095, making it the third-least populous county in Maine. Its county seat is Machias."},{"n":"Somerset County","lat":45.1329,"lon":-69.854,"s":51,"w":"Somerset County, Maine","ty":"county of Maine","u":0,"b":"Somerset County is a county in the U.S. state of Maine, United States. As of the 2020 census, its population was 50,477. Its county seat is Skowhegan."},{"n":"Penobscot County","lat":45.1719,"lon":-68.7225,"s":49,"w":"Penobscot County, Maine","ty":"county of Maine","u":0,"b":"Penobscot County is a county in the U.S. state of Maine, named for the Penobscot people in Wabanakik. As of the 2020 census, the population was 152,199, making it the third-most-populous county in Maine. Its county seat is Bangor."},{"n":"Kotava","lat":46.8,"lon":-71.2,"s":46,"w":"Kotava","ty":"international auxiliary language|constructed language","u":0,"b":"Kotava (sometimes also spelled Kodava) is an international auxiliary language (IAL) created by Staren Fetcey in 1978 that focuses on the principle of cultural neutrality. The name means \"the language of one and all\", and the Kotava community has adopted the slogan \"a project humanistic and universal, utopian and realistic\"."},{"n":"Piscataquis County","lat":45.5652,"lon":-69.3337,"s":46,"w":"Piscataquis County, Maine","ty":"county of Maine","u":0,"b":"Piscataquis County is a county located in the U.S. state of Maine. As of the 2020 census, its population was 16,800, making it Maine's least-populous county. Its county seat is Dover-Foxcroft."},{"n":"Connecticut River","lat":45.2375,"lon":-71.2,"s":44,"w":"Connecticut River","ty":"river","u":0,"b":"The Connecticut River is a major river in the New England region of the United States. The region's longest, it flows roughly southward for 406 miles (653 km) through four states. Rising 300 yards (270 m) south of the U.S. border with Quebec, Canada, it discharges into Long Island Sound between Old Saybrook and Old Lyme, Connecticut."},{"n":"Calais","lat":45.1661,"lon":-67.2425,"s":40,"w":"Calais, Maine","ty":"city in the United States","u":0,"b":"Calais is a city in Washington County, Maine, United States. As of the 2020 census, it had a population of 3,079, making Calais the largest municipality by population in Washington County, but the third least-populous city in Maine (after Hallowell and Eastport). The city has three Canada–US border crossings (also known as ports of entry) over the St."},{"n":"Old Town","lat":44.9431,"lon":-68.6764,"s":36,"w":"Old Town, Maine","ty":"city in the United States","u":0,"b":"Old Town is a city in Penobscot County, Maine, United States. The population was 7,431 at the 2020 census. The city's developed area is chiefly located on the relatively large Marsh Island, but its boundaries extend beyond it."},{"n":"Houlton","lat":46.1333,"lon":-67.8394,"s":35,"w":"Houlton, Maine","ty":"county seat|town in the United States","u":0,"b":"Houlton is a town in and the county seat of Aroostook County, Maine, United States, on the Canada–United States border. As of the 2020 census, the town's population was 6,055. It is perhaps best known for being at the northern terminus of Interstate 95 and as the birthplace of Samantha Smith, a goodwill ambassador as a child during the Cold War."},{"n":"Vermont","lat":44.0,"lon":-72.7,"s":219,"w":"Vermont","ty":"U.S. state","u":0,"b":"Vermont is a landlocked state in the New England region of the Northeastern United States. It borders Massachusetts to the south, New Hampshire to the east, New York to the west, and the Canadian province of Quebec to the north."},{"n":"New Hampshire","lat":44.0,"lon":-71.5,"s":216,"w":"New Hampshire","ty":"U.S. state","u":0,"b":"New Hampshire is a state in the New England region of the Northeastern United States. It borders Massachusetts to the south, Vermont to the west, Maine and the Gulf of Maine to the east, and the Canadian province of Quebec to the north."},{"n":"New England","lat":44.2056,"lon":-70.3064,"s":124,"w":"New England","ty":"cultural area|U.S. region","u":0,"b":"New England is a region consisting of six states in the Northeastern United States: Connecticut, Maine, Massachusetts, New Hampshire, Rhode Island, and Vermont. It is bordered by the state of New York to the west and by the Canadian provinces of New Brunswick to the northeast and Quebec to the north."},{"n":"Montpelier","lat":44.2659,"lon":-72.5717,"s":123,"w":"Montpelier, Vermont","ty":"city in the United States|county seat","u":0,"b":"Montpelier is the capital city of the U.S. state of Vermont and the county seat of Washington County. The site of Vermont's state government, it is the least populous state capital in the United States. As of the 2020 census, the population was 8,074, with a daytime population growth of about 21,000 due to the large number of jobs within city limits."},{"n":"Augusta","lat":44.3106,"lon":-69.7794,"s":115,"w":"Augusta, Maine","ty":"county seat|city in the United States","u":0,"b":"Augusta is the capital city of the U.S. state of Maine. The city's population was 18,899 at the 2020 United States census, making it the 12th-most populous city in Maine, and third-least populous state capital in the United States. Augusta is the seat of and most populous city in Kennebec County."},{"n":"Portland","lat":43.66,"lon":-70.255,"s":99,"w":"Portland, Maine","ty":"county seat|city in the United States","u":0,"b":"Portland is the most populous city in the U.S. state of Maine. Its population was 68,408 at the 2020 census and the Greater Portland metropolitan area has a population of approximately 550,000 people, the most populous metropolitan area in Maine. It is the county seat of Cumberland County."},{"n":"Burlington","lat":44.4761,"lon":-73.2131,"s":88,"w":"Burlington, Vermont","ty":"city in the United States|county seat","u":0,"b":"Burlington is the largest city in the U.S. State of Vermont and the county seat of Chittenden County. It is located 45 miles (72 km) south of the Canada–United States border and 95 miles (153 km) south of Montreal."},{"n":"International Civil Aviation Organization","lat":45.5003,"lon":-73.5642,"s":84,"w":"International Civil Aviation Organization","ty":"specialized agency of the United Nations|publishing house","u":0,"b":"The International Civil Aviation Organization (ICAO) is a specialized agency of the United Nations that coordinates the principles and techniques of international air navigation, and fosters the planning and development of international air transport to ensure safe and orderly growth."},{"n":"Bangor","lat":44.8031,"lon":-68.7675,"s":64,"w":"Bangor, Maine","ty":"county seat|city in the United States","u":0,"b":"Bangor is the county seat and largest city of Penobscot County, Maine, United States. The city proper has a population of 31,753, making it the state's third-most populous city, behind Portland (68,408) and Lewiston (37,121). Bangor is known as the \"Queen City\"."},{"n":"Trois-Rivières","lat":46.35,"lon":-72.55,"s":63,"w":"Trois-Rivières","ty":"equivalent territory|big city|city or town of Quebec","u":0,"b":"Trois-Rivières is a city in the Mauricie administrative region of Quebec, Canada. It is located at the confluence of the Saint-Maurice and Saint Lawrence rivers, on the north shore of the Saint Lawrence River across from the city of Bécancour. It is part of the densely populated Quebec City–Windsor Corridor and is approximately halfway between Montreal and Quebec City."},{"n":"Sherbrooke","lat":45.4,"lon":-71.9,"s":60,"w":"Sherbrooke","ty":"city or town of Quebec|equivalent territory|territory outside RCM in Quebec|big city","u":0,"b":"Sherbrooke is a city in southern Quebec, Canada. It is at the confluence of the Saint-François and Magog rivers in the heart of the Estrie administrative region. The city is coextensive with a territory equivalent to a regional county municipality (TE) and census division (CD) of the same name."},{"n":"Longueuil","lat":45.5141,"lon":-73.438,"s":60,"w":"Longueuil","ty":"city or town of Quebec|territory outside RCM in Quebec","u":0,"b":"Longueuil is a city in the province of Quebec, Canada. It is the seat of the Montérégie administrative region and the central city of the urban agglomeration of Longueuil. It sits on the south shore of the Saint Lawrence River directly across from Montreal."},{"n":"Lewiston","lat":44.1006,"lon":-70.2153,"s":58,"w":"Lewiston, Maine","ty":"city in the United States","u":0,"b":"Lewiston is the second-most populous city in the U.S. state of Maine, with a population of 37,121, according to the 2020 United States census. Located in Androscoggin County, the city lies halfway between Augusta, the state capital, and Portland, the state's largest city."},{"n":"Cumberland County","lat":43.7845,"lon":-70.328,"s":54,"w":"Cumberland County, Maine","ty":"county of Maine","u":0,"b":"Cumberland County is a county in the U.S. state of Maine. As of the 2020 census, the population was 303,069, making it the most populous county in Maine. Its county seat is Portland."},{"n":"Washington County","lat":43.3232,"lon":-73.4282,"s":52,"w":"Washington County, New York","ty":"county of New York","u":0,"b":"Washington County is a county in the U.S. state of New York. As of the 2020 census, the population was 61,302. The county seat is Fort Edward."},{"n":"Coös County","lat":44.6138,"lon":-71.3399,"s":51,"w":"Coös County, New Hampshire","ty":"county of New Hampshire","u":0,"b":"Coös County or Coos County is the northernmost county in the U.S. state of New Hampshire. As of the 2020 census, the population was 31,268, making it the least-populated county in the state. The county seat is Lancaster."},{"n":"Androscoggin County","lat":44.1351,"lon":-70.2177,"s":51,"w":"Androscoggin County, Maine","ty":"county of Maine","u":0,"b":"Androscoggin County is a county in the U.S. state of Maine. As of the 2020 census, the county's population was 111,139. Its county seat is Auburn and its most populous city is Lewiston."},{"n":"Auburn","lat":44.0892,"lon":-70.2414,"s":51,"w":"Auburn, Maine","ty":"city in the United States|county seat","u":0,"b":"Auburn is a city in south-central Maine, within the United States. Settled in the foothills of the Western Lakes and Mountains region of the state, the city serves as the county seat of Androscoggin County. The population was 24,061 at the 2020 census."},{"n":"Franklin County","lat":44.8792,"lon":-70.3879,"s":51,"w":"Franklin County, Maine","ty":"county of Maine","u":0,"b":"Franklin County is a county located in the state of Maine, United States. As of the 2020 census, the population was 29,456, making it the second-least populous county in Maine. Its county seat is Farmington."},{"n":"Orange County","lat":43.9958,"lon":-72.3749,"s":51,"w":"Orange County, Vermont","ty":"county of Vermont","u":0,"b":"Orange County is a county located in the U.S. state of Vermont. As of the 2020 census, the population was 29,277. Its shire town (county seat) is the town of Chelsea."},{"n":"Merrimack County","lat":43.3,"lon":-71.68,"s":51,"w":"Merrimack County, New Hampshire","ty":"county of New Hampshire","u":0,"b":"Merrimack County is a county in the U.S. state of New Hampshire. As of the 2020 Census, the population was 153,808, making it the third most populous county in New Hampshire. Its county seat is Concord, the state capital."},{"n":"Lincoln County","lat":44.0135,"lon":-69.5418,"s":51,"w":"Lincoln County, Maine","ty":"county of Maine","u":0,"b":"Lincoln County is a county located in the U.S. state of Maine. As of the 2020 census, the population was 35,237. Its seat is Wiscasset."},{"n":"Kennebec County","lat":44.4,"lon":-69.7846,"s":51,"w":"Kennebec County, Maine","ty":"county of Maine","u":0,"b":"Kennebec County is a county located in the South-central portion of the U.S. state of Maine. At the 2020 census, the population was 123,642. Its county seat is Augusta, the state's capital."},{"n":"Hancock County","lat":44.5127,"lon":-68.4157,"s":50,"w":"Hancock County, Maine","ty":"county of Maine","u":0,"b":"Hancock County is a county located in the U.S. state of Maine. As of the 2020 census, the population was 55,478. Its county seat and largest city is Ellsworth."},{"n":"Washington County","lat":44.2492,"lon":-72.5808,"s":50,"w":"Washington County, Vermont","ty":"county of Vermont","u":0,"b":"Washington County is a county located in the U.S. state of Vermont. Named after George Washington, its county seat is the city of Montpelier (the least populous state capital in the United States) and the most populous city is the city of Barre."},{"n":"Waldo County","lat":44.4747,"lon":-69.118,"s":50,"w":"Waldo County, Maine","ty":"county of Maine","u":0,"b":"Waldo County is a county in the state of Maine, United States. As of the 2020 census, the population was 39,607. Its county seat is Belfast."},{"n":"Carroll County","lat":43.8226,"lon":-71.1816,"s":50,"w":"Carroll County, New Hampshire","ty":"county of New Hampshire","u":0,"b":"Carroll County is a county in the U.S. state of New Hampshire. As of the 2020 census, the population was 50,107, making it the third-least populous county in New Hampshire. Its county seat is Ossipee."},{"n":"Sullivan County","lat":43.3442,"lon":-72.2472,"s":50,"w":"Sullivan County, New Hampshire","ty":"county of New Hampshire","u":0,"b":"Sullivan County is a county in the U.S. state of New Hampshire. As of the 2020 census, the population was 43,063, making it the second-least populous county in New Hampshire. Its county seat is Newport."},{"n":"New York","lat":43.0,"lon":-75.0,"s":247,"w":"New York (state)","ty":"U.S. state","u":0,"b":"New York, also called New York State, is a state located in the Northeastern United States. Bordering New England to its east, Pennsylvania and New Jersey to the south, and Canada to its north, New York extends into both the Atlantic Ocean and the Great Lakes."},{"n":"Massachusetts","lat":42.3,"lon":-71.8,"s":229,"w":"Massachusetts","ty":"U.S. state","u":0,"b":"Massachusetts, officially the Commonwealth of Massachusetts, is a state in the New England region of the Northeastern United States. It borders the Atlantic Ocean and the Gulf of Maine to its east, Connecticut and Rhode Island to its south, New Hampshire and Vermont to its north, and New York to its west. Massachusetts is the seventh-smallest state by land area."},{"n":"Boston","lat":42.3603,"lon":-71.0578,"s":216,"w":"Boston","ty":"city in the United States|big city","u":0,"b":"Boston is the capital and most populous city of the U.S. state of Massachusetts. It serves as a cultural and financial center of New England, a region of the Northeastern United States."},{"n":"Montreal","lat":45.5033,"lon":-73.5868,"s":194,"w":"Montreal","ty":"college town|territory outside RCM in Quebec|city or town of Quebec|metropolis","u":0,"b":"Montreal (French: Montréal) is the largest city in the province of Quebec, the second-largest in Canada, and the eighth-largest in North America. Founded in 1642 as Ville-Marie, or \"City of Mary\", it now takes its name from Mount Royal, the triple-peaked mountain around which the early settlement was built."},{"n":"Albany","lat":42.65,"lon":-73.7667,"s":135,"w":"Albany, New York","ty":"city in the state of New York|big city|county seat","u":0,"b":"Albany is the capital city of the U.S. state of New York. It is also the county seat of, and the most populous city in Albany County. Albany is located on the west bank of the Hudson River, approximately ten miles (16 km) south of its confluence with the Mohawk River."},{"n":"Providence","lat":41.824,"lon":-71.4128,"s":133,"w":"Providence, Rhode Island","ty":"county seat|city in the United States|big city","u":0,"b":"Providence is the capital and most populous city of the U.S. state of Rhode Island. It is the third-most populous city in New England, with a population of 190,934 at the 2020 census. The Providence metropolitan area extends into Massachusetts and has approximately 1.7 million residents, making it the 39th-largest metropolitan area in the U.S."},{"n":"Concord","lat":43.2067,"lon":-71.5381,"s":128,"w":"Concord, New Hampshire","ty":"county seat|state or insular area capital of the United States|city in the United States","u":0,"b":"Concord is the capital city of the U.S. state of New Hampshire and the seat of Merrimack County. As of the 2020 United States census the population was 43,976, making it the 3rd most populous city in New Hampshire after Manchester and Nashua. The area was first settled by Europeans in 1659."},{"n":"Cambridge","lat":42.375,"lon":-71.1061,"s":103,"w":"Cambridge, Massachusetts","ty":"city in the United States|city","u":0,"b":"Cambridge is a city in Middlesex County, Massachusetts, United States. It is located in the Greater Boston metropolitan area directly across the Charles River from Boston."},{"n":"Springfield","lat":42.1124,"lon":-72.5475,"s":91,"w":"Springfield, Massachusetts","ty":"city in the United States|big city|county seat","u":0,"b":"Springfield is the most populous city in Hampden County, Massachusetts, United States, and its county seat. Springfield sits on the eastern bank of the Connecticut River near its confluence with three rivers: the western Westfield River, the eastern Chicopee River, and the eastern Mill River."},{"n":"Worcester","lat":42.2714,"lon":-71.7989,"s":88,"w":"Worcester, Massachusetts","ty":"county seat|city in the United States|big city","u":0,"b":"Worcester is a city in the U.S. state of Massachusetts. The principal city of Central Massachusetts, Worcester is both the second-most populous city in the state, and the 113th most populous city in the United States. Named after Worcester, England, the city had an estimated 213,862 people as of 2025, also making it the second-most populous city in New England, after Boston."},{"n":"Manchester","lat":42.9908,"lon":-71.4636,"s":87,"w":"Manchester, New Hampshire","ty":"big city|city in the United States","u":0,"b":"Manchester is the most populous city in the U.S. state of New Hampshire. Located on the banks of the Merrimack River, it had a population of 115,644 at the 2020 census. Manchester is the tenth-most populous city in New England."},{"n":"Lowell","lat":42.6394,"lon":-71.3147,"s":81,"w":"Lowell, Massachusetts","ty":"county seat|big city|city in the United States","u":0,"b":"Lowell is a city in Massachusetts, United States. Alongside Cambridge, it is one of the two traditional seats of Middlesex County. With an estimated population of 115,554 in 2020, it was the fifth most populous city in Massachusetts as of the last census, and the third most populous in the Boston metropolitan statistical area."},{"n":"Salem","lat":42.5168,"lon":-70.8985,"s":77,"w":"Salem, Massachusetts","ty":"city in the United States|county seat","u":0,"b":"Salem is a historic coastal city in Essex County, Massachusetts, United States, located on the North Shore of Greater Boston. Continuous settlement by Europeans began in 1626 with English colonists. Salem was one of the most significant seaports for trading commodities in early American history."},{"n":"1980 Winter Olympics","lat":44.2613,"lon":-73.9661,"s":74,"w":"1980 Winter Olympics","ty":"Winter Olympic Games edition","u":0,"b":"The 1980 Winter Olympics, officially the XIII Olympic Winter Games and also known as Lake Placid 1980, were an international multi-sport event held from February 13 to 24, 1980, in Lake Placid, New York, United States. Lake Placid was elected as the host city for the 1980 Winter Games at the 75th International Olympic Committee (IOC) Session in Vienna, Austria, in 1974."},{"n":"1932 Winter Olympics","lat":44.2826,"lon":-73.9841,"s":74,"w":"1932 Winter Olympics","ty":"Winter Olympic Games edition","u":0,"b":"The 1932 Winter Olympics, officially known as the III Olympic Winter Games and commonly known as Lake Placid 1932, were a winter multi-sport event in the United States, held in Lake Placid, New York, United States. The games opened on February 4 and closed on February 13."},{"n":"Lake Placid","lat":44.2856,"lon":-73.9853,"s":72,"w":"Lake Placid, New York","ty":"village of New York","u":0,"b":"Lake Placid is a village in Essex County, New York, United States, within the Adirondack Mountains. Its population was 2,205 at the 2020 census. Lake Placid became known internationally for hosting the 1932 and the 1980 Winter Olympics."},{"n":"Nashua","lat":42.7575,"lon":-71.4644,"s":70,"w":"Nashua, New Hampshire","ty":"city in the United States","u":0,"b":"Nashua is a city in southern New Hampshire, United States. As of the 2020 census, it had a population of 91,322, the second-largest in northern New England after nearby Manchester. It is one of two county seats of New Hampshire's most populous county, Hillsborough; the other being Manchester."},{"n":"Delaware River","lat":41.939,"lon":-75.2791,"s":69,"w":"Delaware River","ty":"river","u":0,"b":"The Delaware River is a major river in the Mid-Atlantic region of the United States and is the longest free-flowing (undammed) river in the Eastern United States. From the meeting of its branches in Hancock, New York, the river flows for 282 miles (454 km) along the borders of (north to south): New York, Pennsylvania, New Jersey, and Delaware, before emptying into Delaware Bay."},{"n":"Laval","lat":45.5833,"lon":-73.75,"s":67,"w":"Laval, Quebec","ty":"territory outside RCM in Quebec|administrative region of Quebec|equivalent territory|big c","u":0,"b":"Laval is a city in Quebec, Canada. It is in the southwest of the province, north of Montreal. It is the largest suburb of Greater Montreal, the third-largest city in the province after Montreal and Quebec City, and the thirteenth largest city in Canada, with a population of 443,192 in 2021."},{"n":"Utica","lat":43.1008,"lon":-75.2325,"s":63,"w":"Utica, New York","ty":"county seat|city in the state of New York","u":0,"b":"Utica is a city in the U.S. state of New York, and the county seat of Oneida County. The tenth-most populous city in New York, its population was 65,283 in the 2020 census."},{"n":"Quincy","lat":42.25,"lon":-71.0,"s":62,"w":"Quincy, Massachusetts","ty":"city in the United States","u":0,"b":"Quincy is a city in Norfolk County, Massachusetts, United States. It is the largest city in the county. Quincy is part of the Greater Boston area as one of Boston's immediate southern suburbs."},{"n":"Schenectady","lat":42.8042,"lon":-73.9292,"s":62,"w":"Schenectady, New York","ty":"county seat|city in the state of New York","u":0,"b":"Schenectady is a city in Schenectady County, New York, United States, of which it is the county seat. As of the 2020 census, the city's population of 67,047 made it the state's ninth-most populous city and the 25th-most populous municipality. The city is in eastern New York, near the confluence of the Mohawk and Hudson Rivers."},{"n":"New York City","lat":40.7128,"lon":-74.0061,"s":325,"w":"New York City","ty":"megacity|big city|city in the United States|port city|largest city|metropolis|city in the ","u":0,"b":"New York, often called New York City (NYC), is the most populous city in the United States. It is located at the southern tip of New York State on New York Harbor, one of the world's largest natural harbors. The city comprises five boroughs—Manhattan, Brooklyn, Queens, the Bronx, and Staten Island—each being coextensive with its respective county."},{"n":"Connecticut","lat":41.6,"lon":-72.7,"s":222,"w":"Connecticut","ty":"U.S. state","u":0,"b":"Connecticut is a state in the New England region of the Northeastern United States. It borders Rhode Island to the east, Massachusetts to the north, New York to the west, and Long Island Sound to the south. Its capital is Hartford, and its most populous city is Bridgeport."},{"n":"Rhode Island","lat":41.7,"lon":-71.5,"s":214,"w":"Rhode Island","ty":"U.S. state","u":0,"b":"Rhode Island ( ROHD) is a state in the New England region of the Northeastern United States. It borders Connecticut to its west; Massachusetts to its north and east; and the Atlantic Ocean to its south via Rhode Island Sound and Block Island Sound; and shares a small maritime border with New York, east of Long Island."},{"n":"Statue of Liberty","lat":40.6892,"lon":-74.0444,"s":158,"w":"Statue of Liberty","ty":"observation tower|statue|colossal statue|part of UNESCO World Heritage Site","u":1,"b":"The Statue of Liberty is a colossal neoclassical sculpture of a robed and crowned woman on Liberty Island, part of New York City, in New York Harbor. The copper-clad statue, a gift to the United States from the people of France, was designed by French sculptor Frédéric Auguste Bartholdi, and its metal framework built by Gustave Eiffel."},{"n":"Interlingua","lat":40.75,"lon":-74.0,"s":158,"w":"Interlingua","ty":"constructed language|international auxiliary language","u":0,"b":"Interlingua is an international auxiliary language (IAL) developed between 1937 and 1951 by the American International Auxiliary Language Association (IALA). It is a constructed language of the \"naturalistic\" variety, whose vocabulary, grammar, and other characteristics are derived from natural languages."},{"n":"Hartford","lat":41.7633,"lon":-72.685,"s":140,"w":"Hartford, Connecticut","ty":"state or insular area capital of the United States|municipality seat|big city|county seat|","u":0,"b":"Hartford is the capital city of the U.S. state of Connecticut. The city, located in Hartford County, had a population of 121,054 at the 2020 census and was estimated at 124,006 in 2025. Hartford is the most populous city in the Capitol Planning Region and the core city of the Greater Hartford metropolitan area with 1.17 million residents in total."},{"n":"Manhattan","lat":40.7283,"lon":-73.9942,"s":139,"w":"Manhattan","ty":"consolidated city-county|borough of New York City","u":0,"b":"Manhattan is the most densely populated and geographically smallest of the five boroughs of New York City. Manhattan is coextensive with New York County, which is the smallest county by area in the U.S. state of New York, and one of the smallest in the United States."},{"n":"Harrisburg","lat":40.2646,"lon":-76.8834,"s":132,"w":"Harrisburg, Pennsylvania","ty":"county seat|city of Pennsylvania|optional charter municipality of Pennsylvania","u":0,"b":"Harrisburg is the capital city of the U.S. commonwealth of Pennsylvania. It is the ninth-most populous city in the state, with a population of 50,099 at the 2020 census, while the Harrisburg–Carlisle metropolitan statistical area has an estimated 615,000 residents and is the fourth-most populous metropolitan area in Pennsylvania."},{"n":"Brooklyn","lat":40.6508,"lon":-73.9497,"s":128,"w":"Brooklyn","ty":"borough of New York City","u":0,"b":"Brooklyn, coextensive with Kings County, is the most populous of the five boroughs and counties of New York City, New York. Located at the westernmost end of Long Island and formerly an independent city, Brooklyn shares a land border with the borough and county of Queens."},{"n":"Empire State Building","lat":40.7483,"lon":-73.9856,"s":125,"w":"Empire State Building","ty":"skyscraper|office building","u":0,"b":"The Empire State Building is a 102-story, supertall skyscraper in the Midtown South neighborhood of Manhattan, New York City, United States. The building was designed in the Art Deco style by Shreve, Lamb & Harmon and constructed between 1930 and 1931. Its name is derived from \"Empire State\", the nickname of New York state."},{"n":"Newark","lat":40.7356,"lon":-74.1722,"s":116,"w":"Newark, New Jersey","ty":"largest city|city in New Jersey|big city","u":0,"b":"Newark is the most populous city in the U.S. state of New Jersey, the county seat of Essex County, and a principal city of the New York metropolitan area. As of the 2020 census, the city's population was 311,549. The Population Estimates Program calculated a population of 323,808 for 2025, making it the 61st-most populous municipality in the nation."},{"n":"The Bronx","lat":40.8467,"lon":-73.8733,"s":114,"w":"The Bronx","ty":"borough of New York City|consolidated city-county","u":0,"b":"The Bronx ( BRONKS) is the northernmost of the five boroughs of New York City. The Bronx has a land area of 42 square miles (109 km2) and a population of 1,472,654 at the 2020 census. It has the fourth largest area, fourth largest population, and third highest population density of the boroughs."},{"n":"World Trade Center","lat":40.7114,"lon":-74.0125,"s":108,"w":"World Trade Center (1973–2001)","ty":"building complex|destroyed building or structure","u":0,"b":"The original World Trade Center (WTC) was a complex of seven buildings in the Financial District of Lower Manhattan in New York City. Built primarily between 1966 and 1975, it was dedicated on April 4, 1973, and was destroyed on September 11, 2001, after two hijacked planes were flown into the towers in a coordinated terrorist attack."},{"n":"New Haven","lat":41.3083,"lon":-72.925,"s":108,"w":"New Haven, Connecticut","ty":"big city|city in the United States","u":0,"b":"New Haven is a city in the U.S. state of Connecticut. It is located on New Haven Harbor on the northern shore of Long Island Sound. With a population of 134,023 at the 2020 census, it is the third-most populous city in Connecticut and the largest in the South Central Connecticut Planning Region, with the Greater New Haven metropolitan area having an estimated 577,000 residents."},{"n":"Queens","lat":40.7136,"lon":-73.8281,"s":106,"w":"Queens","ty":"consolidated city-county|borough of New York City","u":0,"b":"Queens is the largest by area of the five boroughs of New York City, and the second most populous, with a population of 2,405,464 as of the 2020 census. Since 1899 the borough is coextensive with Queens County, the second-most populous county in New York state, behind Kings County (Brooklyn)."},{"n":"Bridgeport","lat":41.1833,"lon":-73.2,"s":101,"w":"Bridgeport, Connecticut","ty":"big city|county seat|city in the United States","u":0,"b":"Bridgeport is the most populous city in the U.S. state of Connecticut. The population was 148,654 in 2020, making it the fifth-most populous city in New England. It is a port city in eastern Fairfield County at the mouth of the Pequonnock River on Long Island Sound, 60 miles (97 km) from Manhattan and 40 miles (64 km) from The Bronx."},{"n":"Staten Island","lat":40.5719,"lon":-74.1469,"s":100,"w":"Staten Island","ty":"borough of New York City|consolidated city-county","u":0,"b":"Staten Island is the southernmost of the five boroughs of New York City. It is separated from New Jersey by the Arthur Kill and the Kill Van Kull and from the rest of New York by New York Bay. With a population of 495,747 in the 2020 census, Staten Island is the least populated borough but the third largest in land area at 58.5 sq mi (152 km2)."},{"n":"American Broadcasting Company","lat":40.7733,"lon":-73.9808,"s":100,"w":"American Broadcasting Company","ty":"film production company|television station|radio network|television network","u":0,"b":"American Broadcasting Companies, Inc. is an American commercial broadcasting television network that serves as the flagship property of the Disney Television Group division of the Walt Disney Company."},{"n":"Jersey City","lat":40.71,"lon":-74.06,"s":98,"w":"Jersey City, New Jersey","ty":"county seat|city in New Jersey","u":0,"b":"Jersey City is the second-most populous city in the U.S. state of New Jersey, after Newark. It is the county seat of Hudson County, the county's most populous city and its largest by area. As of the 2020 United States census, the city's population was 292,449, an increase of 44,852 (+18.1%) from the 2010 census count of 247,597."},{"n":"Syracuse","lat":43.0469,"lon":-76.1444,"s":95,"w":"Syracuse, New York","ty":"city in the state of New York","u":0,"b":"Syracuse is a city in New York, United States, and the seat of government of Onondaga County. With 148,620 residents, and a metropolitan area of 662,057 people, it is the most populous city in Central New York, as well as the fifth-most populated city and 13th-most populated municipality in New York."},{"n":"Washington, D.C.","lat":38.895,"lon":-77.0367,"s":299,"w":"Washington, D.C.","ty":"federal capital|political city|big city|human settlement|planned national capital|city in ","u":0,"b":"Washington, D.C., officially the District of Columbia and commonly shortened to Washington, or DC, is the capital city of the United States, and its only federal district. The city stands on the north-east bank of the Potomac River, across from the state of Virginia, surrounded by Maryland to its north, east, and south."},{"n":"Pennsylvania","lat":41.0,"lon":-77.5,"s":235,"w":"Pennsylvania","ty":"U.S. state","u":0,"b":"Pennsylvania, officially the Commonwealth of Pennsylvania, is a state located in the Mid-Atlantic, Northeastern, Appalachian, and Great Lakes regions of the United States."},{"n":"New Jersey","lat":40.0,"lon":-74.5,"s":231,"w":"New Jersey","ty":"U.S. state","u":0,"b":"New Jersey is a state located in both the Mid-Atlantic and Northeastern regions of the United States."},{"n":"Maryland","lat":39.0,"lon":-76.7,"s":229,"w":"Maryland","ty":"U.S. state","u":0,"b":"Maryland is a state in the Mid-Atlantic and Southeastern regions of the United States. It borders Virginia to its south, West Virginia to its west, Pennsylvania to its north, and Delaware to its east, as well as with the Atlantic Ocean to its east, and the national capital and federal district of Washington, D.C. to the southwest."},{"n":"Delaware","lat":39.0,"lon":-75.5,"s":220,"w":"Delaware","ty":"U.S. state","u":0,"b":"Delaware is a state in the Mid-Atlantic and South Atlantic regions of the United States. It borders Maryland to its south and west, Pennsylvania to its north, New Jersey to its northeast, and the Atlantic Ocean to its east."},{"n":"Philadelphia","lat":39.9528,"lon":-75.1636,"s":205,"w":"Philadelphia","ty":"home rule municipality of Pennsylvania|city of Pennsylvania|county seat|consolidated city-","u":0,"b":"Philadelphia, colloquially referred to as Philly, is the most populous city in the U.S. state of Pennsylvania and the sixth-most populous city in the United States. Its population was 1.60 million at the 2020 census and estimated at 1.57 million in 2025."},{"n":"National Aeronautics and Space Administration","lat":38.8831,"lon":-77.0164,"s":184,"w":"NASA","ty":"independent agency of the United States government|space agency","u":0,"b":"The National Aeronautics and Space Administration (NASA; ) is an independent agency of the U.S. federal government responsible for the United States' civil space program, as well as research in aeronautics and space."},{"n":"Baltimore","lat":39.2864,"lon":-76.615,"s":159,"w":"Baltimore","ty":"independent city in the United States","u":0,"b":"Baltimore, also known as Baltimore City and Charm City is the most populous city in the U.S. state of Maryland. It is the 30th-most-populous U.S. city, with a population of 585,708 at the 2020 census and estimated at 569,997 in 2025; the Baltimore metropolitan area, at 2.86 million residents, is the 22nd-largest metropolitan area in the nation."},{"n":"Lingua Franca Nova","lat":40.05,"lon":-77.5167,"s":144,"w":"Lingua Franca Nova","ty":"international auxiliary language|constructed language","u":0,"b":"Lingua Franca Nova, abbreviated as LFN and known colloquially as Elefen, is a constructed international auxiliary language that was created by C. George Boeree of Shippensburg University, Pennsylvania, and further developed by many of its users. Its vocabulary is based primarily on the Romance languages, namely French, Italian, Portuguese, Spanish, and Catalan."},{"n":"White House","lat":38.8978,"lon":-77.0367,"s":143,"w":"White House","ty":"civic building|presidential palace|mansion","u":0,"b":"The White House is the official residence and workplace of the president of the United States. Located at 1600 Pennsylvania Avenue NW in Washington, D.C., it has served as the residence of every U.S. president since John Adams in 1800 when the national capital was moved from Philadelphia. The White House is also a metonym for the Executive Office of the President."},{"n":"Dover","lat":39.1617,"lon":-75.5257,"s":129,"w":"Dover, Delaware","ty":"state or insular area capital of the United States|city in the United States|city|county s","u":0,"b":"Dover is the capital and the second-most populous city of the U.S. state of Delaware, after Wilmington. It is also the county seat of Kent County and the principal city of the Dover metropolitan statistical area, which encompasses all of Kent County and is part of the Philadelphia metropolitan area. It is located on the St."},{"n":"Annapolis","lat":38.9786,"lon":-76.4919,"s":127,"w":"Annapolis, Maryland","ty":"county seat|state or insular area capital of the United States|city in the United States","u":0,"b":"Annapolis is the capital of the U.S. state of Maryland. It is the county seat of Anne Arundel County and its only incorporated city. Situated on the Chesapeake Bay at the mouth of the Severn River, Annapolis is a historic city with a strong maritime culture."},{"n":"Trenton","lat":40.2203,"lon":-74.7658,"s":125,"w":"Trenton, New Jersey","ty":"county seat|city in New Jersey","u":0,"b":"Trenton is the capital city of the U.S. state of New Jersey and the county seat of Mercer County. It was the capital of the United States from November 1 until December 24, 1784."},{"n":"United States Declaration of Independence","lat":39.9489,"lon":-75.15,"s":123,"w":"United States Declaration of Independence","ty":"declaration of independence","u":0,"b":"The Declaration of Independence, headed The unanimous Declaration of the thirteen united States of America on the document directed to be engrossed by Congress on July 19, 1776, is the founding document of the United States."},{"n":"Federal Bureau of Investigation","lat":38.8953,"lon":-77.025,"s":115,"w":"Federal Bureau of Investigation","ty":"federal law enforcement agency of the United States|intelligence agency|United States fede","u":0,"b":"The Federal Bureau of Investigation (FBI) is the domestic intelligence and security service of the United States and its principal federal law enforcement agency. An agency of the United States Department of Justice, the FBI is a member of the U.S. Intelligence Community and reports to both the attorney general and the director of national intelligence."},{"n":"United States Congress","lat":38.8897,"lon":-77.0089,"s":114,"w":"United States Congress","ty":"bicameral legislature","u":0,"b":"The United States Congress is the legislative branch of the federal government of the United States. It is a bicameral legislature, including a lower body, the U.S. House of Representatives, and an upper body, the U.S. Senate. They both meet in the United States Capitol in Washington, D.C."},{"n":"Library of Congress","lat":38.8886,"lon":-77.0047,"s":103,"w":"Library of Congress","ty":"United Nations Depository Library|national library|parliamentary archives|legislative bran","u":0,"b":"The Library of Congress (LOC) is a research library in Washington, D.C., serving as the library and research service for the United States Congress and the de facto national library of the United States. It also administers copyright law through the United States Copyright Office, and it houses the Congressional Research Service."},{"n":"The Pentagon","lat":38.8708,"lon":-77.055,"s":102,"w":"The Pentagon","ty":"headquarters|government building|office building|groundscraper","u":0,"b":"The Pentagon is the headquarters of the United States Department of Defense, in Arlington County, Virginia, across the Potomac River from Washington, D.C. The building was constructed on an accelerated schedule during World War II. As a symbol of the U.S. military, the phrase The Pentagon is often used as a metonym for the Department of Defense and its leadership."},{"n":"Rochester","lat":43.1656,"lon":-77.6114,"s":101,"w":"Rochester, New York","ty":"big city|city in the state of New York|county seat","u":0,"b":"Rochester is a city in and the county seat of Monroe County, New York, United States. It is the fourth-most populous city in New York, with a population of 206,108 as of the 2025 Census estimate. The Rochester metropolitan area in Western New York has an estimated 1.05 million residents and is the 54th-largest metropolitan area in the U.S."},{"n":"Virginia","lat":37.5,"lon":-79.0,"s":234,"w":"Virginia","ty":"U.S. state","u":0,"b":"Virginia, officially the Commonwealth of Virginia, is a state in the Southeastern and Mid-Atlantic regions of the United States between the Atlantic Coast and the Appalachian Mountains. It borders Kentucky to the west, Tennessee to the south-west, North Carolina to the south, West Virginia to the north-west, and Maryland to the north."},{"n":"West Virginia","lat":39.0,"lon":-80.5,"s":215,"w":"West Virginia","ty":"U.S. state","u":0,"b":"West Virginia is a mountainous, landlocked state in the Southern and Mid-Atlantic regions of the United States. It is bordered by Pennsylvania and Maryland to the northeast, Virginia to the southeast, Kentucky to the southwest, and Ohio to the northwest. West Virginia is the 10th-smallest state by area and ranks as the 12th-least populous state, with 1,778,373 residents."},{"n":"Pittsburgh","lat":40.4417,"lon":-80.0,"s":149,"w":"Pittsburgh","ty":"city of Pennsylvania|big city|county seat|home rule municipality of Pennsylvania","u":0,"b":"Pittsburgh is a city in Allegheny County, Pennsylvania, United States, and its county seat. Located in southwestern Pennsylvania where the Allegheny and Monongahela Rivers meet to form the Ohio River, it had a population of 302,971 at the 2020 census, making it the second-most populous city in Pennsylvania after Philadelphia."},{"n":"Richmond","lat":37.5408,"lon":-77.4367,"s":133,"w":"Richmond, Virginia","ty":"independent city in Virginia|city in the United States|independent city in the United Stat","u":0,"b":"Richmond is the capital city of the U.S. state of Virginia. Incorporated in 1742, Richmond has been an independent city since 1871. It is the fourth-most populous city in Virginia, with a population of 226,610 at the 2020 census."},{"n":"Appalachian Mountains","lat":38.0,"lon":-79.0,"s":98,"w":"Appalachian Mountains","ty":"mountain range","u":0,"b":"The Appalachian Mountains are a vast mountain range situated in eastern North America, extending roughly 2,050 miles (3,300 km) from central Alabama to Newfoundland along a generally southwest–northeast axis. Alongside the Appalachian Plateau province—with which they are not entirely synonymous—the mountains form a wider system comprising the region's backbone."},{"n":"Wilmington","lat":39.7483,"lon":-75.5514,"s":95,"w":"Wilmington, Delaware","ty":"city in the United States|county seat","u":0,"b":"Wilmington is the most populous city in the U.S. state of Delaware. It lies at the confluence of the Christina River and Brandywine Creek, near where the Christina flows into the Delaware River. The population was 70,898 at the 2020 census."},{"n":"Ohio River","lat":40.443,"lon":-80.0171,"s":89,"w":"Ohio River","ty":"river","u":0,"b":"The Ohio River (Seneca: Ohi:yo') is a 981-mile-long (1,579 km) river in the United States. It begins in the Northeast and serves as the boundary between the Midwestern and Southern United States, flowing in a southwesterly direction from Pittsburgh, Pennsylvania, to its mouth on the Mississippi River at Cairo, Illinois."},{"n":"Thirteen Colonies","lat":39.284,"lon":-76.61,"s":88,"w":"Thirteen Colonies","ty":"province|crown colony|colony|tridecad","u":0,"b":"The Thirteen Colonies were the British colonies on the Atlantic coast of North America which broke away from the British Crown in the American Revolutionary War (1775–1783), and joined to form the United States of America. The Thirteen Colonies in their traditional groupings were: the New England Colonies; the Middle Colonies; and the Southern Colonies."},{"n":"Supreme Court of the United States","lat":38.8906,"lon":-77.0044,"s":88,"w":"Supreme Court of the United States","ty":"United States article III court|supreme court|Wikimedia portal","u":0,"b":"The Supreme Court of the United States (SCOTUS) is the highest court in the federal judiciary of the United States. It has ultimate appellate jurisdiction over all U.S. federal court cases, and over state court cases that turn on questions of U.S. constitutional or federal law."},{"n":"Scranton","lat":41.409,"lon":-75.6624,"s":85,"w":"Scranton, Pennsylvania","ty":"city of Pennsylvania|home rule municipality of Pennsylvania|county seat","u":0,"b":"Scranton is a second A class city in and the county seat of Lackawanna County, Pennsylvania, United States. With a population of 76,328 at the 2020 census (estimated at 75,514 in 2025), Scranton is the sixth-most populous city in Pennsylvania and the most populous city in Northeastern Pennsylvania."},{"n":"Alexandria","lat":38.8047,"lon":-77.0472,"s":81,"w":"Alexandria, Virginia","ty":"independent city in Virginia|independent city in the United States","u":0,"b":"Alexandria is an independent city in the U.S. state of Virginia. It lies on the western (or southern) bank of the Potomac River in Northern Virginia, bordering Washington, D.C. to the northeast. The city's population of 159,467 at the 2020 census made it the sixth-most populous city in Virginia and 169th-most populous city in the U.S."},{"n":"Allentown","lat":40.6,"lon":-75.4833,"s":81,"w":"Allentown, Pennsylvania","ty":"county seat|home rule municipality of Pennsylvania|city of Pennsylvania","u":0,"b":"Allentown is a city in eastern Pennsylvania, United States. The county seat of Lehigh County, it is the third-most populous city in Pennsylvania, with a population of 125,845 as of the 2020 census. It is also the most populous city in the Lehigh Valley metropolitan area, which had a population of 861,899 and was the 68th-most populous metropolitan area in the nation as of 2020."},{"n":"Lojban","lat":38.9,"lon":-77.0333,"s":79,"w":"Lojban","ty":"logical language|constructed language","u":0,"b":"Lojban is a logical, constructed human language created by the Logical Language Group, which aims to be syntactically unambiguous. It succeeds the Loglan project. The Logical Language Group (LLG) began developing Lojban in 1987."},{"n":"National Security Agency","lat":39.1089,"lon":-76.7714,"s":78,"w":"National Security Agency","ty":"intelligence agency|Combat support agency","u":0,"b":"The National Security Agency (NSA) is an intelligence agency of the United States Department of Defense, under the authority of the director of national intelligence (DNI)."},{"n":"Arlington County","lat":38.8803,"lon":-77.1083,"s":77,"w":"Arlington County, Virginia","ty":"county of Virginia","u":0,"b":"Arlington County, or simply Arlington, is a county in the U.S. state of Virginia. The county, which is located in the Washington metropolitan area and the broader Northern Virginia region, is positioned directly across the Potomac River from Washington, D.C., the national capital, on the river's southwestern bank."},{"n":"Potomac River","lat":38.0,"lon":-76.335,"s":76,"w":"Potomac River","ty":"stream|river","u":0,"b":"The Potomac River is in the Mid-Atlantic region of the United States and flows from the Potomac Highlands in West Virginia to the Chesapeake Bay in Maryland. It is 405 miles (652 km) long, with a drainage area of 14,700 square miles (38,000 km2), and is the fourth-largest river along the East Coast of the United States. More than 6 million people live within its watershed."},{"n":"I Have a Dream","lat":38.8893,"lon":-77.0499,"s":75,"w":"I Have a Dream","ty":"oration","u":0,"b":"\"I Have a Dream\" is a public speech that was delivered by American civil rights activist and Baptist minister Martin Luther King Jr. during the March on Washington for Jobs and Freedom on August 28, 1963. In the speech, King called for civil and economic rights and an end to legalized racism in the United States."},{"n":"North Carolina","lat":35.5,"lon":-80.0,"s":216,"w":"North Carolina","ty":"U.S. state","u":0,"b":"North Carolina is a state in the Southeastern and South Atlantic regions of the United States. It is bordered by Virginia to the north, the Atlantic Ocean to the east, South Carolina to the south, Georgia to the southwest, and Tennessee to the west. The state is the 28th-largest and ninth-most populous of the United States."},{"n":"Raleigh","lat":35.78,"lon":-78.64,"s":135,"w":"Raleigh, North Carolina","ty":"big city|county seat|city of North Carolina","u":0,"b":"Raleigh is the capital city of the U.S. state of North Carolina. It is the second-most populous city in the state (after Charlotte), tenth most populous city in the Southeast, the largest city in the Research Triangle area, and the 39th-most populous city in the U.S."},{"n":"Charleston","lat":38.3472,"lon":-81.6333,"s":117,"w":"Charleston, West Virginia","ty":"county seat|state or insular area capital of the United States|city in the United States","u":0,"b":"Charleston is the capital and most populous city of the U.S. state of West Virginia. Located at the confluence of the Elk and Kanawha rivers, it is the county seat of Kanawha County. The population was 48,864 at the 2020 census, with an estimated population of 46,482 in 2024."},{"n":"Greensboro","lat":36.0725,"lon":-79.7903,"s":84,"w":"Greensboro, North Carolina","ty":"big city|city of North Carolina|city in the United States|county seat","u":0,"b":"Greensboro is a city in Guilford County, North Carolina, United States, and its county seat. The Greensboro–High Point metropolitan area has an estimated 801,000 residents, with the metropolitan area also encompassing the overall center of North Carolina."},{"n":"Durham","lat":35.9942,"lon":-78.8986,"s":79,"w":"Durham, North Carolina","ty":"big city|county seat|city in the United States|city of North Carolina","u":0,"b":"Durham is a city in the U.S. state of North Carolina, being the county seat of Durham County, with outskirts of the city limits also extending into Orange County and Wake County. Durham is the 4th-most populous city in North Carolina and 70th-most populous city in the United States with a population of 283,506 at the 2020 census."},{"n":"Winston-Salem","lat":36.1025,"lon":-80.2606,"s":78,"w":"Winston-Salem, North Carolina","ty":"city in the United States|county seat|big city|city of North Carolina","u":0,"b":"Winston-Salem is a city in and the county seat of Forsyth County, North Carolina, United States. It anchors the Winston-Salem metropolitan statistical area, which is located in the west-to-southwestern area of the Piedmont Triad region. The Winston-Salem Metropolitan Area had an estimated population of 712,206 in 2025."},{"n":"International Union of Pure and Applied Chemistry","lat":35.904,"lon":-78.8777,"s":78,"w":"International Union of Pure and Applied Chemistry","ty":"publishing house|learned society","u":0,"b":"The International Union of Pure and Applied Chemistry (IUPAC ) is an international federation of National Adhering Organizations working for the advancement of the chemical sciences, especially by developing nomenclature and terminology. It is a member of the International Science Council (ISC)."},{"n":"January 6 United States Capitol attack","lat":38.8897,"lon":-77.0092,"s":75,"w":"January 6 United States Capitol attack","ty":"demonstration|storming|rebellion|insurgency|attempted coup d'état|livestreamed crime","u":0,"b":"On January 6, 2021, the United States Capitol in Washington, D.C., was attacked by a mob of supporters of President Donald Trump. Academic debate exists about whether to characterize the event as an attempted coup, an attempted self-coup, or neither. The attack happened two months after Trump's defeat in the 2020 presidential election."},{"n":"Washington Monument","lat":38.8895,"lon":-77.0352,"s":70,"w":"Washington Monument","ty":"obelisk|National Memorial of the United States","u":0,"b":"The Washington Monument is a 555-foot (169 m) tall obelisk on the National Mall in Washington, D.C., built to commemorate George Washington, a Founding Father of the United States and the nation's first president. Standing east of the Reflecting Pool and the Lincoln Memorial, the monument is made of bluestone gneiss for the foundation and of granite for the construction."},{"n":"Smithsonian Institution","lat":38.8889,"lon":-77.026,"s":70,"w":"Smithsonian Institution","ty":"nonprofit organization|institution|museum","u":0,"b":"The Smithsonian Institution is a group of museums, education and research centers, created by the United States federal government \"for the increase and diffusion of knowledge\". Founded on August 10, 1846, it operates as a trust instrumentality and is not formally a part of any of the three branches of the federal government."},{"n":"Gettysburg Address","lat":39.8283,"lon":-77.2322,"s":65,"w":"Gettysburg Address","ty":"oration","u":0,"b":"The Gettysburg Address is a dedication speech delivered by Abraham Lincoln, the 16th U.S. president, following the Battle of Gettysburg during the American Civil War. The speech has come to be viewed as one of the most famous, enduring, and historically significant speeches in American history."},{"n":"Charlottesville","lat":38.0299,"lon":-78.479,"s":65,"w":"Charlottesville, Virginia","ty":"independent city in the United States|independent city in Virginia|county seat","u":0,"b":"Charlottesville, colloquially known as C'ville, is an independent city in Virginia, United States. It is the county seat of Albemarle County, which surrounds the city, though the two are separate legal entities. The former capital of Virginia, it is named after Queen Charlotte."},{"n":"Roanoke","lat":37.2706,"lon":-79.9425,"s":64,"w":"Roanoke, Virginia","ty":"independent city in the United States|railway town|county seat|independent city in Virgini","u":0,"b":"Roanoke is an independent city in Virginia, United States. It lies in Southwest Virginia along the Roanoke River, within the Blue Ridge range of the greater Appalachian Mountains. Roanoke is about 50 miles (80 km) north of the Virginia–North Carolina border and 250 miles (400 km) southwest of Washington, D.C., along Interstate 81."},{"n":"Rockville","lat":39.084,"lon":-77.1528,"s":64,"w":"Rockville, Maryland","ty":"county seat|city in the United States","u":0,"b":"Rockville is a city in and the county seat of Montgomery County, Maryland, United States, and is part of the Washington metropolitan area. The 2020 census tabulated Rockville's population at 67,117, making it the fourth most populous incorporated city in Maryland."},{"n":"Asheville","lat":35.5956,"lon":-82.5519,"s":63,"w":"Asheville, North Carolina","ty":"city in the United States|city of North Carolina|county seat","u":0,"b":"Asheville is a city in Buncombe County, North Carolina, United States. Located at the confluence of the French Broad and Swannanoa rivers, it is the county seat of Buncombe County. It is the most populous city in Western North Carolina and the state's 11th-most populous city with a population of 94,589 at the 2020 census."},{"n":"National Center for Biotechnology Information","lat":38.9958,"lon":-77.0989,"s":62,"w":"National Center for Biotechnology Information","ty":"research institute|data library","u":0,"b":"The National Center for Biotechnology Information (NCBI) is part of the National Library of Medicine (NLM), a branch of the National Institutes of Health (NIH). It is approved and funded by the government of the United States. The NCBI is located in Bethesda, Maryland, and was founded in 1988 through legislation sponsored by US congressman Claude Pepper."},{"n":"Discovery","lat":38.9114,"lon":-77.4452,"s":61,"w":"Space Shuttle Discovery","ty":"Space Shuttle orbiter|exhibit","u":0,"b":"Space Shuttle Discovery (Orbiter Vehicle Designation: OV-103) is a retired American Space Shuttle orbiter. The spaceplane was one of the orbiters from NASA's Space Shuttle program and the third of five fully operational orbiters to be built. Its first mission, STS-41-D, flew from August 30 to September 5, 1984."},{"n":"South Carolina","lat":34.0,"lon":-81.0,"s":217,"w":"South Carolina","ty":"U.S. state","u":0,"b":"South Carolina is a state in the Southeastern, South Atlantic and Deep South regions of the United States. It borders North Carolina to the north and northeast, the Atlantic Ocean to the southeast, and Georgia to the west and south across the Savannah River. Along with North Carolina, it makes up the Carolinas region of the East Coast."},{"n":"Columbia","lat":34.0006,"lon":-81.0442,"s":128,"w":"Columbia, South Carolina","ty":"county seat|city in the United States","u":0,"b":"Columbia is the capital of the U.S. state of South Carolina. It is the second-most populous city in the state, with a population of 136,632 at the 2020 census and estimated at 147,035 in 2025. It is the principal city of the Columbia metropolitan area, the second-largest metropolitan area in South Carolina, with an estimated population of 879,918 in 2025."},{"n":"Charlotte","lat":35.2269,"lon":-80.8433,"s":127,"w":"Charlotte, North Carolina","ty":"city of North Carolina|big city|city in the United States|county seat","u":0,"b":"Charlotte is the most populous city in the U.S. state of North Carolina. With a population of 874,579 at the 2020 census, it is the 14th-most populous city in the U.S., seventh-most populous city in the South, and second-most populous city in the Southeast (after Jacksonville, Florida)."},{"n":"Knoxville","lat":35.9617,"lon":-83.9233,"s":91,"w":"Knoxville, Tennessee","ty":"big city|county seat|city in the United States","u":0,"b":"Knoxville is a city in Knox County, Tennessee, United States, and its county seat. Located on the Tennessee River within the Appalachian Mountains, it is the largest city in the Grand Division of East Tennessee. Knoxville had a population of 190,740 at the 2020 census, making it the third-most-populous city in Tennessee."},{"n":"Cherokee","lat":35.5,"lon":-83.3,"s":85,"w":"Cherokee language","ty":"modern language|sacred language|natural language|indigenous language","u":0,"b":"Cherokee, or Tsalagi, is an endangered-to-moribund Iroquoian language and the native language of the Cherokee people. Ethnologue states that there were 1,520 Cherokee speakers out of 376,000 Cherokees in 2018, while a tally by the three Cherokee tribes in 2019 recorded about 2,100 speakers. The number of speakers is in decline."},{"n":"Athens","lat":33.9553,"lon":-83.3831,"s":80,"w":"Athens, Georgia","ty":"big city|consolidated city-county|city in the United States|municipality of Georgia|county","u":0,"b":"Athens is a consolidated city-county in the U.S. state of Georgia. Downtown Athens lies about 70 miles (110 km) northeast of downtown Atlanta. The University of Georgia, the state's flagship public university and an R1 research institution, is in Athens and contributed to its initial growth."},{"n":"Tennessee River","lat":35.9593,"lon":-83.8502,"s":68,"w":"Tennessee River","ty":"river","u":0,"b":"The Tennessee River is a 652-mile-long (1,049 km) river located in the southeastern United States. Flowing through the Tennessee Valley in the states of Tennessee, Alabama, Mississippi, and Kentucky, it begins at the confluence of French Broad and Holston rivers at Knoxville, and drains into the Ohio River near Paducah, Kentucky."},{"n":"Greenville","lat":34.8444,"lon":-82.3856,"s":62,"w":"Greenville, South Carolina","ty":"city in the United States|county seat","u":0,"b":"Greenville is a city in Greenville County, South Carolina, United States, and its county seat. It is the sixth-most populous city in South Carolina with a population of 70,720 at the 2020 census, while the Greenville metropolitan area has an estimated 997,000 residents and is the largest metropolitan area in the state."},{"n":"Huntington","lat":38.4208,"lon":-82.4236,"s":61,"w":"Huntington, West Virginia","ty":"city in the United States","u":0,"b":"Huntington is a city in Cabell and Wayne counties in the U.S. state of West Virginia. It is the county seat of Cabell County and sits at the confluence of the Ohio and Guyandotte rivers in the southwestern part of the state. With a population of 46,842 at the 2020 census (estimated at 44,942 in 2024), Huntington is the second-most populous city in West Virginia."},{"n":"Chapel Hill","lat":35.9073,"lon":-79.0499,"s":55,"w":"Chapel Hill, North Carolina","ty":"town in the United States|city of North Carolina","u":0,"b":"Chapel Hill is an incorporated municipality in the counties of Orange and Durham, North Carolina, United States. Its population was 61,960 in the 2020 United States census, making Chapel Hill the 17th-most populous municipality in the state."},{"n":"Marietta","lat":33.9533,"lon":-84.5406,"s":55,"w":"Marietta, Georgia","ty":"municipality of Georgia|county seat|city in the United States","u":0,"b":"Marietta is a city in and the county seat of Cobb County, Georgia, United States. At the 2020 census, the city had a population of 60,972, making it one of Atlanta's largest suburbs. Marietta is the fourth largest of the principal cities by population of the Atlanta metropolitan area."},{"n":"Oak Ridge","lat":36.0133,"lon":-84.2625,"s":54,"w":"Oak Ridge, Tennessee","ty":"city in the United States","u":0,"b":"Oak Ridge is a city in Anderson and Roane counties in the eastern part of the U.S. state of Tennessee, about 25 miles (40 km) west of downtown Knoxville. Oak Ridge's population was 31,402 at the 2020 census. It is part of the Knoxville Metropolitan Area."},{"n":"Cary","lat":35.7789,"lon":-78.8003,"s":54,"w":"Cary, North Carolina","ty":"city of North Carolina|town in the United States","u":0,"b":"Cary is a town in Wake, Chatham, and Durham counties in the U.S. state of North Carolina and is part of the Raleigh-Cary, NC Metropolitan Statistical Area. According to the 2020 census, its population was 174,721, making it the seventh-most populous municipality in North Carolina, and the 146th-most populous in the United States."},{"n":"Staunton","lat":38.1581,"lon":-79.0764,"s":54,"w":"Staunton, Virginia","ty":"independent city in the United States|independent city in Virginia","u":0,"b":"Staunton is an independent city in the U.S. Commonwealth of Virginia. As of the 2020 census, the population was 25,750. In Virginia, independent cities are separate jurisdictions from the counties that surround them, so the government offices of Augusta County are in Verona, which is contiguous to Staunton."},{"n":"Sandy Springs","lat":33.9375,"lon":-84.3686,"s":54,"w":"Sandy Springs, Georgia","ty":"municipality of Georgia|city in the United States","u":0,"b":"Sandy Springs is a city in northern Fulton County, Georgia, United States, within the Atlanta metropolitan area. The city's population was 108,080 at the 2020 census, making it the 7th-most populous city in the state."},{"n":"Cherokee County","lat":34.24,"lon":-84.47,"s":53,"w":"Cherokee County, Georgia","ty":"county of Georgia","u":0,"b":"Cherokee County is in the US state of Georgia. As of the 2020 census, the population was 266,620. The county seat is Canton."},{"n":"Barrow County","lat":33.99,"lon":-83.71,"s":52,"w":"Barrow County, Georgia","ty":"county of Georgia","u":0,"b":"Barrow County is a county located in the East Central region of the U.S. state of Georgia. As of the 2020 census, its population was 83,505. Its county seat is Winder."},{"n":"Ashland","lat":38.4639,"lon":-82.6417,"s":52,"w":"Ashland, Kentucky","ty":"city in the United States","u":0,"b":"Ashland is a city in Boyd County, Kentucky, United States. It is located on the southern bank of the Ohio River at the state border with Ohio and near West Virginia. The population was 21,625 at the 2020 census, making it the most populous city in Boyd County."},{"n":"Dawson County","lat":34.44,"lon":-84.17,"s":52,"w":"Dawson County, Georgia","ty":"county of Georgia","u":0,"b":"Dawson County is a county in the Northeast region of the U.S. state of Georgia. As of the 2020 census, the population was 26,798 up from 22,330 in 2010. The county seat is Dawsonville."},{"n":"Forsyth County","lat":34.22,"lon":-84.13,"s":52,"w":"Forsyth County, Georgia","ty":"county of Georgia","u":0,"b":"Forsyth County is a county in the Northeast region of the U.S. state of Georgia. Suburban and exurban in character, Forsyth County lies within the Atlanta metropolitan area. The county's only incorporated city and county seat is Cumming."},{"n":"Gainesville","lat":34.3044,"lon":-83.8339,"s":52,"w":"Gainesville, Georgia","ty":"city in the United States|municipality of Georgia|county seat","u":0,"b":"Gainesville is a city in and the county seat of Hall County, Georgia, United States. As of the 2020 census, the city had a population of 42,296. This city is part of Metro Atlanta."},{"n":"Banks County","lat":34.35,"lon":-83.5,"s":51,"w":"Banks County, Georgia","ty":"county of Georgia","u":0,"b":"Banks County is a county in the Northeast region of the U.S. state of Georgia. As of the 2020 census, the population was 18,035, down from 18,395 in 2010. The county seat is Homer."},{"n":"Gwinnett County","lat":33.96,"lon":-84.03,"s":51,"w":"Gwinnett County, Georgia","ty":"county of Georgia","u":0,"b":"Gwinnett County ( gwih-NET) is located in the north central portion of the U.S. state of Georgia. It is a core county of Metro Atlanta, being located about 9 miles (14 km) northeast of Atlanta city limits. In 2020, the population was 957,062, making it the second-most populous county in Georgia (after Fulton County)."},{"n":"Madison County","lat":34.13,"lon":-83.21,"s":51,"w":"Madison County, Georgia","ty":"county of Georgia","u":0,"b":"Madison County is a county located in the northeastern part of the U.S. state of Georgia. As of the 2020 census, the population was 30,120. The county seat is Danielsville."},{"n":"Great Smoky Mountains National Park","lat":35.6111,"lon":-83.425,"s":51,"w":"Great Smoky Mountains National Park","ty":"National Park of the United States|national park","u":1,"b":"Great Smoky Mountains National Park is a national park of the United States in the southeast, with parts in North Carolina and Tennessee. The park straddles the ridgeline of the Great Smoky Mountains, part of the Blue Ridge Mountains and part of the Appalachian temperate rainforest, which are a division of the larger Appalachian Mountain chain."},{"n":"Kanawha County","lat":38.34,"lon":-81.53,"s":51,"w":"Kanawha County, West Virginia","ty":"county of West Virginia","u":0,"b":"Kanawha County is a county in the U.S. state of West Virginia. As of the 2020 census, the population was 180,745, making it West Virginia's most populous county. The county seat is Charleston, which is also the state capital and most populous city."},{"n":"Knox County","lat":35.99,"lon":-83.94,"s":51,"w":"Knox County, Tennessee","ty":"county of Tennessee","u":0,"b":"Knox County is a county located in the U.S. state of Tennessee. The population was 511,453 as of a 2025 estimate, making it the third-most populous county in Tennessee. Its county seat is Knoxville, which is the third-most populous city in Tennessee."},{"n":"Mecklenburg County","lat":35.25,"lon":-80.83,"s":51,"w":"Mecklenburg County, North Carolina","ty":"county of North Carolina","u":0,"b":"Mecklenburg County is a southwestern county in the U.S. state of North Carolina. As of the 2020 census, the population was 1,115,482, making it the second-most populous county in North Carolina (after Wake County). Its county seat is Charlotte, the state's largest municipality."},{"n":"Georgia","lat":33.0,"lon":-83.5,"s":231,"w":"Georgia (U.S. state)","ty":"U.S. state","u":0,"b":"Georgia is a state in the Southeastern, South Atlantic, and Deep South regions of the United States. It borders Tennessee to the northwest, North Carolina and South Carolina to the northeast, the Atlantic Ocean to the east, Florida to the south, and Alabama to the west. Of the 50 U.S. states, Georgia is the 24th-largest by area and eighth-most populous."},{"n":"Atlanta","lat":33.7544,"lon":-84.3897,"s":209,"w":"Atlanta","ty":"municipality of Georgia|city in the United States|big city|county seat","u":0,"b":"Atlanta is the capital and most populous city of the U.S. state of Georgia. It is the county seat of Fulton County and extends into neighboring DeKalb County. With a population of 498,715 at the 2020 census and an estimated 529,110 in 2025, Atlanta is the eighth-most populous city in the Southeast and the 36th-most populous city in the United States."},{"n":"Augusta","lat":33.47,"lon":-81.975,"s":85,"w":"Augusta, Georgia","ty":"consolidated city-county|municipality of Georgia","u":0,"b":"Augusta is a city on the central eastern border of the U.S. state of Georgia and the county seat of Richmond County. The city lies directly across the Savannah River from North Augusta, South Carolina, at the head of its navigable portion. Augusta, the third-most-populous city in Georgia (following Atlanta and Columbus), is situated in the Fall Line region of the state."},{"n":"Chattanooga","lat":35.0456,"lon":-85.2672,"s":85,"w":"Chattanooga, Tennessee","ty":"county seat|city in the United States|big city","u":0,"b":"Chattanooga is a city in Hamilton County, Tennessee, United States, and its county seat. It is located along the Tennessee River and borders Georgia to the south. The population was 181,099 at the 2020 census, and was estimated at 191,496 in 2024."},{"n":"Columbus","lat":32.4922,"lon":-84.9403,"s":78,"w":"Columbus, Georgia","ty":"municipality of Georgia|big city|county seat|city in the United States|consolidated city-c","u":0,"b":"Columbus is a consolidated city-county located on the west-central border of the U.S. state of Georgia. Columbus lies on the Chattahoochee River directly across from Phenix City, Alabama. It is the county seat of Muscogee County, with which it officially merged in 1970; the original merger excluded Bibb City, which joined in 2000 after dissolving its own city charter."},{"n":"Macon","lat":32.8407,"lon":-83.6324,"s":68,"w":"Macon, Georgia","ty":"municipality of Georgia|county seat|city in the United States|consolidated city-county|big","u":0,"b":"Macon, officially Macon–Bibb County, is a consolidated city-county in Georgia, United States. Situated near the fall line of the Ocmulgee River in Central Georgia, it is 85 miles (137 km) southeast of Atlanta and 165 miles (266 km) northwest of Savannah. Macon's population was 157,346 in the 2020 census."},{"n":"Tuskegee","lat":32.4315,"lon":-85.7068,"s":62,"w":"Tuskegee, Alabama","ty":"city in the United States|county seat","u":0,"b":"Tuskegee is a city in and the county seat of Macon County, Alabama, United States. The population was 9,395 at the 2020 census, and was estimated to be 8,765 in 2023. It is the most populous city in Macon County."},{"n":"Cherokee County","lat":34.1697,"lon":-85.5942,"s":57,"w":"Cherokee County, Alabama","ty":"county of Alabama","u":0,"b":"Cherokee County, Alabama is a county located in the northeastern part of the U.S. state of Alabama. As of the 2020 census, the population was 24,971. Its county seat is Centre."},{"n":"Auburn","lat":32.5977,"lon":-85.4808,"s":57,"w":"Auburn, Alabama","ty":"city in the United States","u":0,"b":"Auburn is a city in Lee County, Alabama, United States. The population was 76,143 at the 2020 census. It is the largest city in eastern Alabama and is the principal city of the Auburn metropolitan area, which had a population of 193,773 in 2020."},{"n":"Anniston","lat":33.663,"lon":-85.8267,"s":56,"w":"Anniston, Alabama","ty":"county seat|city in the United States","u":0,"b":"Anniston is a city and the county seat of Calhoun County in Alabama, United States, and is one of two urban centers/principal cities of and included in the Anniston–Oxford Metropolitan Statistical Area. As of the 2020 census, Anniston had a population of 21,564. Named the \"Model City\" by Atlanta newspaperman Henry W."},{"n":"Calhoun County","lat":33.7694,"lon":-85.8208,"s":55,"w":"Calhoun County, Alabama","ty":"county of Alabama","u":0,"b":"Calhoun County is a county in the east central part of the U.S. state of Alabama. As of the 2020 census, the population was 116,441. Its county seat is Anniston."},{"n":"Fulton County","lat":33.79,"lon":-84.47,"s":55,"w":"Fulton County, Georgia","ty":"county of Georgia","u":0,"b":"Fulton County is in the north-central portion of the U.S. state of Georgia. As of the 2020 United States census, the population was 1,066,710, making it the state's most populous county. Its county seat and most populous city is Atlanta, the state capital."},{"n":"Gadsden","lat":34.0101,"lon":-86.0104,"s":55,"w":"Gadsden, Alabama","ty":"county seat|city in the United States","u":0,"b":"Gadsden is a city in and the county seat of Etowah County, Alabama, United States. The population was 33,945 as of the 2020 census, and was estimated at 33,367 in 2025, making it is the eighteenth-largest city in Alabama."},{"n":"Chambers County","lat":32.9111,"lon":-85.3939,"s":54,"w":"Chambers County, Alabama","ty":"county of Alabama","u":0,"b":"Chambers County is a county located in the east central portion of the U.S. state of Alabama. As of the 2020 census the population was 34,772. Its county seat is LaFayette."},{"n":"DeKalb County","lat":33.77,"lon":-84.23,"s":54,"w":"DeKalb County, Georgia","ty":"county of Georgia","u":0,"b":"DeKalb County is located in the north central portion of the U.S. state of Georgia. As of the 2020 census, the population was 764,382, making it Georgia's fourth-most populous county. Its county seat is Decatur."},{"n":"Fayette County","lat":33.41,"lon":-84.49,"s":54,"w":"Fayette County, Georgia","ty":"county of Georgia","u":0,"b":"Fayette County is a county located in the north central portion of the U.S. state of Georgia. As of the 2020 census, the population was 119,194, an increase from 106,567 in 2010. Fayette County was established in 1821."},{"n":"Clay County","lat":33.2722,"lon":-85.8611,"s":53,"w":"Clay County, Alabama","ty":"county of Alabama","u":0,"b":"Clay County is a county in the east central part of the U.S. state of Alabama. As of the 2020 census the population was 14,236. Its county seat is Ashland."},{"n":"Coosa County","lat":32.9364,"lon":-86.2464,"s":53,"w":"Coosa County, Alabama","ty":"county of Alabama","u":0,"b":"Coosa County is a county located in the east central portion of the U.S. state of Alabama. As of the 2020 census the population was 10,387. Its county seat is Rockford."},{"n":"Phenix City","lat":32.4728,"lon":-85.02,"s":53,"w":"Phenix City, Alabama","ty":"city in the United States","u":0,"b":"Phenix City is a city in Lee and Russell counties in the U.S. state of Alabama, and the county seat of Russell County with northern and western parts crossing over into neighboring Lee County. As of the 2020 census, the population of the city was 38,817."},{"n":"Carroll County","lat":33.58,"lon":-85.08,"s":53,"w":"Carroll County, Georgia","ty":"county of Georgia","u":0,"b":"Carroll County is a county in the West Central region of the State of Georgia. As of the 2020 census, its population was 119,148. Its county seat is the city of Carrollton."},{"n":"Douglas County","lat":33.7,"lon":-84.77,"s":53,"w":"Douglas County, Georgia","ty":"county of Georgia","u":0,"b":"Douglas County is a county located in the north central portion of the U.S. state of Georgia. As of the 2020 U.S. census, the population was 144,237, having more than doubled since 1990. The county seat is Douglasville."},{"n":"Butts County","lat":33.29,"lon":-83.96,"s":53,"w":"Butts County, Georgia","ty":"county of Georgia","u":0,"b":"Butts County is a county in the West Central region of the U.S. state of Georgia. As of the 2020 census, the population was 25,434, up from 23,655 in 2010. The county seat is Jackson."},{"n":"Jackson County","lat":34.7833,"lon":-86.0,"s":52,"w":"Jackson County, Alabama","ty":"county of Alabama","u":0,"b":"Jackson County is the northeasternmost county in the U.S. state of Alabama. As of the 2020 census, the population was 52,579. The county seat is Scottsboro."},{"n":"Etowah County","lat":34.05,"lon":-86.0333,"s":52,"w":"Etowah County, Alabama","ty":"county of Alabama","u":0,"b":"Etowah County is a county located in the northeastern part of the U.S. state of Alabama. As of the 2020 census the population was 103,436. Its county seat is Gadsden."},{"n":"Baldwin County","lat":33.07,"lon":-83.25,"s":52,"w":"Baldwin County, Georgia","ty":"county of Georgia","u":0,"b":"Baldwin County is a county located in the central portion of the U.S. state of Georgia. As of the 2020 census, its population was 43,799. The county seat is Milledgeville, which was developed along the Oconee River."},{"n":"Alabama","lat":32.7,"lon":-86.7,"s":241,"w":"Alabama","ty":"U.S. state","u":0,"b":"Alabama is a state in the Southeastern and Deep Southern regions of the United States. It borders Tennessee to the north, Georgia to the east, Florida and the Gulf of Mexico to the south, and Mississippi to the west. Alabama is the 30th largest by area, and the 24th-most populous of the 50 U.S. states."},{"n":"Montgomery","lat":32.3675,"lon":-86.3,"s":145,"w":"Montgomery, Alabama","ty":"state or insular area capital of the United States|county seat|big city|city in the United","u":0,"b":"Montgomery is the capital city of the U.S. state of Alabama and the county seat of Montgomery County. It was named for Continental Army Major-General Richard Montgomery and stands beside the Alabama River on the Gulf Coastal Plain. The population was 200,603 at the 2020 census."},{"n":"Birmingham","lat":33.5175,"lon":-86.8094,"s":118,"w":"Birmingham, Alabama","ty":"big city|city in the United States","u":0,"b":"Birmingham is a city in the north central region of Alabama, United States. It is the third-most populous city in the state, with an estimated population of 196,357 as of 2024. The Birmingham metropolitan area, with over 1.19 million residents, is the largest metropolitan area in Alabama and 47th-most populous in the US."},{"n":"Huntsville","lat":34.7136,"lon":-86.5861,"s":94,"w":"Huntsville, Alabama","ty":"county seat|big city|city in the United States","u":0,"b":"Huntsville is the most populous city in the U.S. state of Alabama. The population was 215,006 at the 2020 census, making it the 100th-most populous city in the U.S., while the Huntsville metropolitan area has an estimated 542,000 residents and is the second-most populous metropolitan area in the state."},{"n":"Albany","lat":31.5822,"lon":-84.1656,"s":65,"w":"Albany, Georgia","ty":"municipality of Georgia|county seat|city in the United States","u":0,"b":"Albany is a city in the U.S. state of Georgia. Located on the Flint River, it is the county seat of Dougherty County, and is the sole incorporated city in that county. Located in Southwest Georgia, it is the principal city of the Albany metropolitan area."},{"n":"Decatur","lat":34.581,"lon":-86.9834,"s":63,"w":"Decatur, Alabama","ty":"city in the United States","u":0,"b":"Decatur is the largest city in and the county seat of Morgan County (with a portion also in Limestone County) in the U.S. state of Alabama. Nicknamed \"The River City,\" it is located in northern Alabama on the banks of Wheeler Lake along the Tennessee River. The population was 57,938 at the 2020 census."},{"n":"Autauga County","lat":32.5367,"lon":-86.6483,"s":59,"w":"Autauga County, Alabama","ty":"county of Alabama","u":0,"b":"Autauga County is a county located in the central portion of the U.S. state of Alabama. As of the 2020 census the population was 58,805. Its county seat is Prattville."},{"n":"Chilton County","lat":32.8453,"lon":-86.7144,"s":57,"w":"Chilton County, Alabama","ty":"county of Alabama","u":0,"b":"Chilton County is a county located in the central portion of the U.S. state of Alabama. As of the 2020 census, the population was 45,014. The county seat is Clanton."},{"n":"Barbour County","lat":31.8658,"lon":-85.3961,"s":57,"w":"Barbour County, Alabama","ty":"county of Alabama","u":0,"b":"Barbour County is a county in the southeastern part of the U.S. state of Alabama, located in the Alabama Black Belt Region. As of the 2020 census, the population was 25,223. Its county seat is Clayton."},{"n":"Bullock County","lat":32.0978,"lon":-85.7172,"s":56,"w":"Bullock County, Alabama","ty":"county of Alabama","u":0,"b":"Bullock County is a county of the U.S. state of Alabama. As of the 2020 census, the population was 10,357. Union Springs was chosen as the county seat in 1867, and presently is the county's only incorporated city."},{"n":"Blount County","lat":33.9667,"lon":-86.5833,"s":55,"w":"Blount County, Alabama","ty":"county of Alabama","u":0,"b":"Blount County is a county located in the U.S. state of Alabama. As of the 2020 census, the population was 59,134. Its county seat is Oneonta."},{"n":"Jefferson County","lat":33.52,"lon":-86.81,"s":55,"w":"Jefferson County, Alabama","ty":"county of Alabama","u":0,"b":"Jefferson County is the most populous county in the U.S. state of Alabama, located in the central portion of the state. As of the 2020 census, its population was 674,721. Its county seat is Birmingham."},{"n":"Cullman","lat":34.1775,"lon":-86.8447,"s":55,"w":"Cullman, Alabama","ty":"city in the United States","u":0,"b":"Cullman is the largest city in and the county seat of Cullman County, Alabama, United States. As of the 2020 census it had a population of 18,213, with an estimated population of 20,239 in 2024. It is located along Interstate 65, about 50 miles (80 km) north of Birmingham and about 55 miles (89 km) south of Huntsville."},{"n":"Hoover","lat":33.3861,"lon":-86.8056,"s":54,"w":"Hoover, Alabama","ty":"city in the United States","u":0,"b":"Hoover is a city in Jefferson and Shelby Counties in north central Alabama, United States. The sixth-largest city in Alabama, its population was 92,606 at the 2020 census. Hoover is part of the Birmingham metropolitan statistical area and is also included in the Birmingham-Cullman-Talladega combined statistical area."},{"n":"Battle of Austerlitz","lat":49.1281,"lon":16.7625,"s":75,"w":"Battle of Austerlitz","ty":"battle","u":0,"b":"The Battle of Austerlitz was fought on Monday 2 December 1805, near Austerlitz (then in the Austrian Empire, now in the Czech Republic), being the decisive engagement of the War of the Third Coalition. The Grande Armée under the command of Emperor Napoleon I defeated a combined Russo-Austrian army."},{"n":"Battle of Berlin","lat":52.5186,"lon":13.3761,"s":74,"w":"Battle of Berlin","ty":"battle","u":0,"b":"The Battle of Berlin, designated as the Berlin Strategic Offensive Operation by the Soviet Union, and also known as the Fall of Berlin, was one of the last major offensives of the European theatre of World War II. After the Vistula–Oder Offensive of January–February 1945, the Red Army had temporarily halted on a line 60 km (37 mi) east of Berlin."},{"n":"Battle of Mohács","lat":45.9414,"lon":18.6472,"s":67,"w":"Battle of Mohács","ty":"battle","u":0,"b":"The Battle of Mohács took place on 29 August 1526 near Mohács, in the Kingdom of Hungary. It was fought between the forces of Hungary, led by King Louis II, and the invading Ottoman Empire, commanded by Suleiman the Magnificent and his grand vizier, Pargalı Ibrahim Pasha."},{"n":"Battle of Manzikert","lat":39.1,"lon":42.59,"s":65,"w":"Battle of Manzikert","ty":"battle","u":0,"b":"The Battle of Manzikert or Malazgirt was fought between the Byzantine Empire and the Seljuk Empire on 26 August 1071 near Manzikert, Iberia (modern Malazgirt in Muş Province, eastern Turkey)."},{"n":"Battle of Leipzig","lat":51.3122,"lon":12.4133,"s":65,"w":"Battle of Leipzig","ty":"battle","u":0,"b":"The Battle of Leipzig, also known as the Battle of the Nations, was fought from 16 to 19 October 1813 at Leipzig, Saxony. The Coalition armies of Austria, Prussia, Sweden, and Russia, led by Tsar Alexander I, Karl von Schwarzenberg, Gebhard von Blücher and Swedish Crown Prince Charles John, decisively defeated the Grande Armée of French Emperor Napoleon Bonaparte."},{"n":"Battle of Vienna","lat":48.235,"lon":16.335,"s":65,"w":"Battle of Vienna","ty":"battle|relief","u":0,"b":"The Battle of Vienna took place at Kahlenberg Mountain near Vienna on 12 September 1683 after the city had been besieged by the Ottoman Empire for two months."},{"n":"Battle of Gettysburg","lat":39.8114,"lon":-77.2258,"s":58,"w":"Battle of Gettysburg","ty":"battle","u":0,"b":"The Battle of Gettysburg (locally ) (July 1–3, 1863) was fought in the American Civil War between the Union and Confederate armies in and around Gettysburg, Pennsylvania. The battle, won by the Union, is widely considered the Civil War's turning point, leading to an ultimate victory of the Union and the preservation of the nation."},{"n":"Siege of Baghdad","lat":33.3475,"lon":44.335,"s":56,"w":"Siege of Baghdad","ty":"battle|sack|siege","u":0,"b":"The Siege of Baghdad, also known as the Sack of Baghdad, took place in early 1258. A large army commanded by Hulegu, a prince of the Mongol Empire, attacked the historic capital of the Abbasid Caliphate after a series of provocations from its ruler, caliph al-Musta'sim."},{"n":"Battle of Stamford Bridge","lat":53.9925,"lon":-0.9125,"s":55,"w":"Battle of Stamford Bridge","ty":"battle","u":0,"b":"The Battle of Stamford Bridge took place at the village of Stamford Bridge, East Riding of Yorkshire, in England, on 25 September 1066, between an English army under King Harold Godwinson and an invading Norwegian force led by King Harald Hardrada and the English king's brother Tostig Godwinson."},{"n":"Battle of Ankara","lat":40.15,"lon":32.95,"s":55,"w":"Battle of Ankara","ty":"battle","u":0,"b":"The Battle of Ankara or Angora was fought on 28 July 1402, at the Çubuk plain near Ankara, between the forces of Timur and the Ottoman sultan Bayezid I. The battle was a major victory for Timur, leading to the Ottoman Interregnum."},{"n":"Battle of Bannockburn","lat":56.0933,"lon":-3.9378,"s":51,"w":"Battle of Bannockburn","ty":"battle","u":0,"b":"The Battle of Bannockburn was fought on 23–24 June 1314, between the army of Robert the Bruce, King of Scots, and the army of King Edward II of England, during the First War of Scottish Independence."},{"n":"Battle of Adrianople","lat":41.8,"lon":26.6,"s":51,"w":"Battle of Adrianople","ty":"battle","u":0,"b":"The Battle of Adrianople, also known as Battle of Hadrianopolis, was fought between the Eastern Roman army led by the Roman emperor Valens and Gothic rebels, led by Fritigern. The battle took place on 9 August 378 in the vicinity of Adrianople, in the Roman province of Thracia (modern Edirne in European Turkey)."},{"n":"Battle of White Mountain","lat":50.0783,"lon":14.3194,"s":51,"w":"Battle of White Mountain","ty":"battle","u":0,"b":"The Battle of White Mountain was fought on 8 November 1620 outside Prague in the early stages of the Thirty Years' War. An army backing Frederick V led by Christian of Anhalt was defeated by forces supporting his rival Ferdinand II, Holy Roman Emperor, under Bucquoy and Count Tilly. Imperial forces entered Prague on 9 November and Frederick fled into Silesia."},{"n":"Battle of Carrhae","lat":36.8667,"lon":39.0333,"s":49,"w":"Battle of Carrhae","ty":"battle","u":0,"b":"The Battle of Carrhae was fought in 53 BC between the Roman Republic and the Parthian Empire near the ancient town of Carrhae (present-day Harran, Turkey)."},{"n":"Battle of Jena–Auerstedt","lat":50.95,"lon":11.575,"s":49,"w":"Battle of Jena–Auerstedt","ty":"battle","u":0,"b":"The Battle of Jena–Auerstedt was fought on Tuesday 14 October 1806, near Jena and Auerstedt, being the decisive engagement of the War of the Fourth Coalition. The Grande Armée under the command of Emperor Napoleon I defeated a combined Prussian and Saxon army."},{"n":"Battle of Nicopolis","lat":43.7058,"lon":24.8958,"s":48,"w":"Battle of Nicopolis","ty":"battle","u":0,"b":"The Battle of Nicopolis took place on 25 September 1396 and resulted in the rout of an allied Crusader army, assisted by the Venetian navy, at the hands of an Ottoman force, raising the siege of the Danubian fortress of Nicopolis and leading to the end of the Second Bulgarian Empire."},{"n":"Battle of the Granicus","lat":40.2281,"lon":27.2422,"s":48,"w":"Battle of the Granicus","ty":"battle","u":0,"b":"The Battle of the Granicus in May 334 BC was the first of three major battles fought between Alexander the Great of Macedon and the Persian Achaemenid Empire. The battle took place on the road from Abydus to Dascylium, at the crossing of the Granicus in the Troad region, which is now called the Biga River in Turkey."},{"n":"Battle of Varna","lat":43.2167,"lon":27.8833,"s":48,"w":"Battle of Varna","ty":"battle","u":0,"b":"The Battle of Varna took place on 10 November 1444 near Varna in what is today eastern Bulgaria. The Ottoman army under Sultan Murad II (who did not actually rule the sultanate at the time) defeated the Crusaders commanded by King Władysław III of Poland and Hungary, John Hunyadi (acting as commander of the combined Christian forces) and Mircea II of Wallachia."},{"n":"Siege of Constantinople","lat":41.0125,"lon":28.975,"s":47,"w":"Siege of Constantinople (717–718)","ty":"siege|battle","u":0,"b":"In 717–718, Constantinople, the capital of the Byzantine Empire, was besieged by the Muslim Arabs of the Umayyad Caliphate. The campaign marked the culmination of twenty years of attacks and progressive Arab occupation of the Byzantine borderlands, while Byzantine strength was sapped by prolonged internal turmoil."},{"n":"Siege of Belgrade","lat":44.8167,"lon":20.4667,"s":44,"w":"Siege of Belgrade (1456)","ty":"siege|battle","u":0,"b":"The siege of Belgrade, or the siege of Nándorfehérvár was a military blockade of Belgrade that occurred 4–22 July 1456 in the aftermath of the fall of Constantinople in 1453 marking the Ottomans' attempts to expand further into Europe."},{"n":"Battle of Stirling Bridge","lat":56.13,"lon":-3.935,"s":43,"w":"Battle of Stirling Bridge","ty":"battle","u":0,"b":"The Battle of Stirling Bridge (Scottish Gaelic: Blàr Drochaid Shruighlea) was fought during the First War of Scottish Independence. On 11 September 1297, the forces of Andrew Moray and William Wallace defeated the combined English forces of John de Warenne, 6th Earl of Surrey, and Hugh de Cressingham near Stirling, on the River Forth."},{"n":"Battle of Legnica","lat":51.1453,"lon":16.2228,"s":43,"w":"Battle of Legnica","ty":"battle","u":0,"b":"The Battle of Legnica (Polish: bitwa pod Legnicą), also known as the Battle of Liegnitz (German: Schlacht von Liegnitz) or Battle of Wahlstatt (German: Schlacht bei Wahlstatt), was fought between the Mongol Empire and combined European forces at the village of Legnickie Pole (Wahlstatt), approximately 10 kilometres (6 mi) southeast of the city of Legnica in the Duchy of Silesia on 9 April 1241."},{"n":"Battle of Falkirk","lat":55.9875,"lon":-3.76,"s":43,"w":"Battle of Falkirk","ty":"battle","u":0,"b":"The Battle of Falkirk, on 22 July 1298, was one of the major battles in the First War of Scottish Independence. Led by King Edward I of England, the English army defeated the Scots, led by William Wallace. Shortly after the battle Wallace resigned as Guardian of Scotland."},{"n":"Battle of al-Qadisiyyah","lat":31.5833,"lon":44.5,"s":43,"w":"Battle of al-Qadisiyyah","ty":"battle","u":0,"b":"The Battle of al-Qadisiyyah took place between the armies of the Rashidun Caliphate and the Sasanian Empire in November 636. It resulted in a decisive victory for the Rashidun army and is considered to be one of the most significant engagements of the Muslim conquest of Persia, and thereby of the early Muslim conquests as a whole."},{"n":"Battle of Wagram","lat":48.2956,"lon":16.5578,"s":42,"w":"Battle of Wagram","ty":"battle","u":0,"b":"The Battle of Wagram was a military engagement of the Napoleonic Wars that ended in a costly but decisive victory for Emperor Napoleon's French and allied army against the Austrian army under the command of Archduke Charles of Austria-Teschen. The battle led to the breakup of the Fifth Coalition, the Austrian and British-led alliance against France."},{"n":"Battle of Vukovar","lat":45.3742,"lon":18.9625,"s":41,"w":"Battle of Vukovar","ty":"battle","u":0,"b":"The Battle of Vukovar was an 87-day siege of Vukovar in eastern Croatia by the Yugoslav People's Army (JNA), supported by various paramilitary forces from Serbia, between August and November 1991. Before the Croatian War of Independence the Baroque town was a prosperous, mixed community of Croats, Serbs and other ethnic groups."},{"n":"Battle of Antietam","lat":39.4733,"lon":-77.7447,"s":41,"w":"Battle of Antietam","ty":"battle","u":0,"b":"The Battle of Antietam, also called the Battle of Sharpsburg (particularly in the Southern United States) took place during the American Civil War on September 17, 1862, near Antietam Creek and Sharpsburg, Maryland, between the Army of Northern Virginia, led by Confederate General Robert E. Lee, and the Army of the Potomac, led by Union Major General George B. McClellan."},{"n":"Battle of Culloden","lat":57.4772,"lon":-4.0925,"s":41,"w":"Battle of Culloden","ty":"battle","u":0,"b":"The Battle of Culloden took place on 16 April 1746, near Inverness, in the Scottish Highlands. A Jacobite army under Charles Edward Stuart was decisively defeated by a British government force commanded by the Duke of Cumberland, thereby ending the Jacobite rising of 1745."},{"n":"Battle of Philippi","lat":41.0131,"lon":24.2864,"s":39,"w":"Battle of Philippi","ty":"battle","u":0,"b":"The Battle of Philippi was the final battle in the Liberators' civil war between the forces of Mark Antony and Octavian (of the Second Triumvirate) and the leaders of Julius Caesar's assassination, Brutus and Cassius, in 42 BC, at Philippi in Macedonia."},{"n":"Battles of Lexington and Concord","lat":42.4494,"lon":-71.2308,"s":39,"w":"Battles of Lexington and Concord","ty":"battle","u":0,"b":"The Battles of Lexington and Concord on April 19, 1775, were the first major military actions between the British Army and Patriot militias from British America's Thirteen Colonies during the American Revolutionary War."},{"n":"Siege of Budapest","lat":47.4983,"lon":19.0408,"s":39,"w":"Siege of Budapest","ty":"siege|battle","u":0,"b":"The Siege of Budapest or Battle of Budapest, was a major battle fought between Soviet and Romanian forces and Hungarian and German forces for the Hungarian capital of Budapest, near the end of World War II. The Budapest Offensive began on October 29 1944, while the siege lasted from December 26 1944 to February 13, 1945."},{"n":"Battle of Mohi","lat":47.9778,"lon":20.9131,"s":39,"w":"Battle of Mohi","ty":"battle","u":0,"b":"The Battle of Mohi (11 April 1241) was a pivotal conflict between the Mongol Empire and the Kingdom of Hungary during the Mongol invasion of Europe. The battle took place at Muhi (then Mohi), a town located in present-day Hungary, southwest of the Sajó River."},{"n":"Battle of Königgrätz","lat":50.21,"lon":15.83,"s":39,"w":"Battle of Königgrätz","ty":"battle","u":0,"b":"The Battle of Königgrätz (or Battle of Sadová; Czech: Bitva u Hradce Králové) was the decisive battle of the Austro-Prussian War in which the Kingdom of Prussia defeated the Austrian Empire. It took place on 3 July 1866, near the Bohemian city of Hradec Králové (German: Königgrätz) and village of Sadová, now in the Czech Republic."},{"n":"Battle of Bunker Hill","lat":42.3764,"lon":-71.0608,"s":38,"w":"Battle of Bunker Hill","ty":"battle","u":0,"b":"The Battle of Bunker Hill was fought on June 17, 1775, during the siege of Boston in the first stage of the American Revolutionary War. The battle is named after Bunker Hill in Charlestown, Massachusetts, which was peripherally involved."},{"n":"Battle of Lützen","lat":51.2678,"lon":12.1567,"s":38,"w":"Battle of Lützen (1632)","ty":"battle","u":0,"b":"The Battle of Lützen, fought on 16 November 1632, was one of the most important of the Thirty Years' War. A Swedish army under Gustavus Adolphus, supported by troops from Saxony and Hesse-Kassel, narrowly defeated an Imperial force under Albrecht von Wallenstein. Both sides suffered heavy casualties, with Gustavus himself among the dead."},{"n":"Battle of Chancellorsville","lat":38.3105,"lon":-77.6484,"s":38,"w":"Battle of Chancellorsville","ty":"battle","u":0,"b":"The Battle of Chancellorsville, April 30 – May 6, 1863, was a major battle of the American Civil War (1861–1865), and the principal engagement of the Chancellorsville campaign. Confederate General Robert E."},{"n":"First Battle of Bull Run","lat":38.815,"lon":-77.5225,"s":37,"w":"First Battle of Bull Run","ty":"battle","u":0,"b":"The First Battle of Bull Run, called the Battle of First Manassas by Confederate forces, was the first major battle of the American Civil War. The battle was fought on July 21, 1861, in Prince William County, Virginia, just north of what is now the city of Manassas and about thirty miles west-southwest of Washington, D.C."},{"n":"Battles of Saratoga","lat":42.9989,"lon":-73.6375,"s":37,"w":"Battles of Saratoga","ty":"battle","u":0,"b":"The Battles of Saratoga were fought September 19 and October 7, 1777 over the same ground by the American Continental Army and the British Army near Saratoga, New York during the American Revolutionary War. The second battle ended with a decisive American victory, and the surrender of the British army there."},{"n":"Battle of Maritsa","lat":40.7306,"lon":26.035,"s":37,"w":"Battle of Maritsa","ty":"battle","u":0,"b":"The Battle of Maritsa, also known as the Battle of Chernomen, was fought on 26 September 1371 near the Maritsa River, close to the village of Chernomen (present-day Ormenio, Greece)."},{"n":"Battle of Mosul","lat":36.3372,"lon":43.1358,"s":37,"w":"Battle of Mosul (2016–2017)","ty":"battle","u":0,"b":"The Battle of Mosul (Arabic: معركة الموصل, Ma'rakat al-Mawṣil) was a major battle initiated by Iraq and allied forces to retake the city of Mosul from the Islamic State (IS), which had seized the city years prior in June 2014. It was the largest conventional land battle in the world since the capture of Baghdad in 2003."},{"n":"Battle of Zenta","lat":45.9261,"lon":20.0981,"s":36,"w":"Battle of Zenta","ty":"battle","u":0,"b":"The Battle of Zenta, also known as the Battle of Senta, took place on 11 September 1697 near Zenta, in the Kingdom of Hungary, then under Ottoman occupation (present-day Serbia). It was a decisive engagement of the Great Turkish War, fought between the forces of the Ottoman Empire and the Holy League."},{"n":"Battle of Mohács","lat":45.8513,"lon":18.4094,"s":35,"w":"Battle of Mohács (1687)","ty":"battle","u":0,"b":"The Second Battle of Mohács, also known as the Battle of Harsány Mountain, was fought on 12 August 1687 between the forces of Ottoman Sultan Mehmed IV, commanded by the Grand Vizier Sarı Süleyman Pasha, and the forces of Leopold I, Holy Roman Emperor, commanded by Charles of Lorraine. The result was a decisive victory for the Austrians."},{"n":"Battle of Edessa","lat":37.15,"lon":38.8,"s":35,"w":"Battle of Edessa","ty":"battle","u":0,"b":"The Battle of Edessa took place between the armies of the Roman Empire, under the command of Emperor Valerian, and the Sasanian Empire under Shapur I, in Edessa (now the Turkish city of Urfa) in 260. The Roman army was defeated and captured in its entirety by the Sasanian forces; for the first time, a Roman emperor was taken prisoner."},{"n":"Battle of Breitenfeld","lat":51.4,"lon":12.3333,"s":35,"w":"Battle of Breitenfeld (1631)","ty":"battle","u":0,"b":"The Battle of Breitenfeld, 17 September 1631, took place during the Thirty Years' War outside Breitenfeld, Leipzig, in modern Saxony. In one of the most significant battles of the war, a combined Swedish-Saxon force defeated an army made up of Imperial and Catholic League troops."},{"n":"Battle of Nineveh","lat":36.3594,"lon":43.1528,"s":35,"w":"Battle of Nineveh (627)","ty":"battle","u":0,"b":"The Battle of Nineveh was the climactic battle of the Byzantine–Sasanian War of 602–628. In mid-September 627, Heraclius invaded Sasanian Mesopotamia in a surprising, risky winter campaign. Khosrow II appointed Rhahzadh as the commander of an army to confront him."},{"n":"Battle of Dorylaeum","lat":39.7767,"lon":30.5206,"s":35,"w":"Battle of Dorylaeum (1097)","ty":"battle","u":0,"b":"The Battle of Dorylaion or Dorylaeum took place during the First Crusade on 1 July 1097 between the crusader forces and the Seljuk Turks, near the city of Dorylaion in Anatolia. Though the Turkish forces of Kilij Arslan nearly wiped out the Crusader contingent of Bohemond of Taranto, other Crusaders arrived just in time to reverse the course of the battle."},{"n":"Battle of Long Island","lat":40.665,"lon":-73.981,"s":34,"w":"Battle of Long Island","ty":"battle","u":0,"b":"The Battle of Long Island, also known as the Battle of Brooklyn and the Battle of Brooklyn Heights, was an action of the American Revolutionary War fought on August 27, 1776, at and near the western edge of Long Island in present-day Brooklyn."},{"n":"Battle of Fredericksburg","lat":38.295,"lon":-77.47,"s":34,"w":"Battle of Fredericksburg","ty":"battle","u":0,"b":"The Battle of Fredericksburg was fought December 11–15, 1862, in and around Fredericksburg, Virginia, in the eastern theater of the American Civil War. The combat between the Union Army of the Potomac commanded by Maj. Gen."},{"n":"Siege of Szigetvár","lat":46.0508,"lon":17.7969,"s":34,"w":"Siege of Szigetvár","ty":"battle|siege","u":0,"b":"The siege of Szigetvár or the Battle of Szigeth was an Ottoman siege of the fortress of Szigetvár in the Kingdom of Hungary. The fort had blocked Sultan Suleiman's line of advance towards Vienna in 1566."},{"n":"Battle of Sinop","lat":42.02,"lon":35.15,"s":33,"w":"Battle of Sinop","ty":"naval battle","u":0,"b":"The Battle of Sinop, or the Battle of Sinope, was a naval battle that took place on 30 November 1853 between Imperial Russia and the Ottoman Empire during the opening phase of the Crimean War (1853–1856). It took place at Sinop, a sea port on the southern shore of the Black Sea (the northern shore of Anatolian Turkey)."},{"n":"Battle of Aegospotami","lat":40.25,"lon":26.55,"s":33,"w":"Battle of Aegospotami","ty":"naval battle","u":0,"b":"The Battle of Aegospotami (Greek: Μάχη στους Αιγός Ποταμούς) was a naval confrontation that took place in 405 BC and was the last major battle of the Peloponnesian War. In the battle, a Spartan fleet under Lysander destroyed the Athenian navy. This effectively ended the war, since Athens could not import grain or communicate with its empire without control of the sea."},{"n":"Battle of Aspern-Essling","lat":48.2131,"lon":16.5025,"s":33,"w":"Battle of Aspern–Essling","ty":"battle","u":0,"b":"In the Battle of Aspern–Essling (21–22 May 1809), Napoleon crossed the Danube near Vienna, but the French and their allies were attacked and forced back across the river by the Austrians under Archduke Charles."},{"n":"Second Battle of Bull Run","lat":38.8125,"lon":-77.5213,"s":33,"w":"Second Battle of Bull Run","ty":"battle","u":0,"b":"The Second Battle of Bull Run or Battle of Second Manassas was fought August 28–30, 1862, in Prince William County, Virginia, as part of the American Civil War. It was the culmination of the Northern Virginia campaign waged by Confederate Gen. Robert E. Lee's Army of Northern Virginia against Union Maj."},{"n":"Battle of Trenton","lat":40.2258,"lon":-74.7647,"s":33,"w":"Battle of Trenton","ty":"battle","u":0,"b":"The Battle of Trenton was a short but pivotal American Revolutionary War battle on the morning of December 26, 1776, in Trenton, New Jersey. After General George Washington's crossing of the Delaware River north of Trenton the previous night, Washington led the main body of the Continental Army against Hessian auxiliaries garrisoned at Trenton."},{"n":"Battle of Cunaxa","lat":33.325,"lon":44.08,"s":32,"w":"Battle of Cunaxa","ty":"battle","u":0,"b":"The Battle of Cunaxa was fought in the late summer of 401 BC between the Persian king Artaxerxes II and his brother Cyrus the Younger for control of the Achaemenid throne. The great battle of the revolt of Cyrus took place 70 km north of Babylon, at Cunaxa (Greek: Κούναξα), on the left bank of the Euphrates."},{"n":"Battle of Saint Gotthard","lat":46.9417,"lon":16.2167,"s":32,"w":"Battle of Saint Gotthard (1664)","ty":"battle","u":0,"b":"The Battle of Saint Gotthard, of the Austro-Turkish War (1663–1664), took place on 1 August 1664 on the Raab between Mogersdorf and the Cistercian monastery St. Gotthard in West Hungary (today Hungary)."},{"n":"Siege of Constantinople","lat":41.0122,"lon":28.976,"s":32,"w":"Siege of Constantinople (626)","ty":"battle|siege","u":0,"b":"The siege of Constantinople in 626 by the Sassanid Persians and Avars, aided by large numbers of allied Slavs, ended in a strategic victory for the Byzantines. The failure of the siege saved the empire from collapse, and, combined with other victories achieved by Emperor Heraclius (r."},{"n":"Battle of Rossbach","lat":51.2694,"lon":11.8944,"s":31,"w":"Battle of Rossbach","ty":"battle","u":0,"b":"The Battle of Rossbach took place on 5 November 1757 during the Third Silesian War (1756–1763, part of the Seven Years' War) near the village of Rossbach (Roßbach), in the Electorate of Saxony. It is sometimes called the Battle of, or at, Reichardtswerben, after a different nearby town."},{"n":"Battle of Nahāvand","lat":31.583,"lon":44.5,"s":31,"w":"Battle of Nahavand","ty":"battle","u":0,"b":"The Battle of Nahavand, also spelled Nihavand or Nahawand, was fought in 642 between the Rashidun Muslim forces under An-Numan ibn Muqarrin and Sasanian army under King Yazdegerd III. Yazdegerd escaped to the Merv area, but was unable to raise another substantial army."},{"n":"Battle of the Plains of Abraham","lat":46.8017,"lon":-71.22,"s":31,"w":"Battle of the Plains of Abraham","ty":"battle","u":0,"b":"The Battle of the Plains of Abraham, also known as the First Battle of Quebec, was a pivotal battle in the Seven Years' War—whose North American theatre is referred to by Americans as the French and Indian War."},{"n":"Battle of Mons Graupius","lat":56.9167,"lon":-3.0,"s":31,"w":"Battle of Mons Graupius","ty":"battle","u":0,"b":"The Battle of Mons Graupius was, according to Tacitus, a Roman military victory in what is now Scotland, taking place in AD 83 or, less probably, 84. The exact location of the battle is a matter of debate. Historians have long questioned some details of Tacitus's account of the fight, suggesting that he exaggerated Roman success."},{"n":"Battle of Fulford","lat":53.9325,"lon":-1.0708,"s":31,"w":"Battle of Fulford","ty":"battle","u":0,"b":"The Battle of Fulford was fought on the outskirts of the village of Fulford, just south of York in England, on 20 September 1066. King Harald III of Norway, also known as Harald Hardrada, a claimant to the English throne, and Tostig Godwinson, his English ally, fought and defeated the Northern Earls Edwin and Morcar."},{"n":"Siege of Kobanî","lat":36.8897,"lon":38.3556,"s":31,"w":"Siege of Kobanî","ty":"siege|battle","u":0,"b":"The siege of Kobanî was launched by the Islamic State (IS) on 13 September 2014, in order to capture the Kobanî Canton and its main city of Kobanî (also known as Kobanê or Ayn al-Arab) in northern Syria, in the de facto autonomous region of Rojava."},{"n":"Battle of Köse Dağ","lat":40.2825,"lon":39.595,"s":30,"w":"Battle of Köse Dağ","ty":"battle","u":0,"b":"The Battle of Köse Dağ took place in eastern Anatolia on 26 June 1243 when an army of the Sultanate of Rum, led by Sultan Kaykhusraw II, confronted an invading Mongol army under the general Baiju and was decisively defeated."},{"n":"Battle of Pliska","lat":42.9275,"lon":26.6683,"s":30,"w":"Battle of Pliska","ty":"battle","u":0,"b":"The Battle of Pliska or Battle of Vărbitsa Pass was a series of battles between the forces of the Byzantine Empire under Emperor Nicephorus I, and the First Bulgarian Empire under Khan Krum in July 811. The Byzantines plundered and burned the Bulgar capital Pliska which gave time for the Bulgarians to block passes in the Balkan Mountains that served as exits out of Bulgaria."},{"n":"Battle of Nedao","lat":44.9333,"lon":19.0167,"s":30,"w":"Battle of Nedao","ty":"battle","u":0,"b":"The Battle of Nedao was fought in Pannonia in 454 between the Huns and their former vassals or allies. The Nedao is believed to be a tributary of the Sava."},{"n":"Battle of Harran","lat":36.8667,"lon":39.0333,"s":30,"w":"Battle of Harran","ty":"battle","u":0,"b":"The Battle of Harran took place on 7 May 1104 between the Crusader states of the Principality of Antioch and the County of Edessa, and the Seljuk Turks. It was the first major battle against the newfound Crusader states in the aftermath of the First Crusade, marking a key turning point against Frankish expansion."},{"n":"Battle of Lützen","lat":51.2167,"lon":12.1833,"s":30,"w":"Battle of Lützen (1813)","ty":"battle","u":0,"b":"The Battle of Lützen, fought on 2 May 1813 near the town of Lützen in Saxony, was a major engagement during the War of the Sixth Coalition. It pitted Napoleon Bonaparte's French forces against a coalition army of Prussian and Russian troops commanded by Generals Wittgenstein and Blücher."},{"n":"Battle of the Zab","lat":35.9911,"lon":43.3436,"s":29,"w":"Battle of the Zab","ty":"battle","u":0,"b":"The Battle of the Zab (Arabic: معركة الزاب), also referred to in scholarly contexts as Battle of the Great Zāb River, took place on January 25, 750, on the banks of the Great Zab in what is now the modern country of Iraq. It spelled the end of the Umayyad Caliphate and the rise of the Abbasid Caliphate, which would last from 750 to 1258."},{"n":"Battle of Naissus","lat":43.3,"lon":21.9,"s":29,"w":"Battle of Naissus","ty":"battle","u":0,"b":"The Battle of Naissus in 268 or 269 was the defeat of a Gothic coalition by the Roman Empire under Emperor Gallienus (or Emperor Claudius II Gothicus) and the future Emperor Aurelian near Naissus (Niš). The events around the invasion and the battle are an important part of the history of the Crisis of the Third Century."},{"n":"Battle of Cer","lat":44.5544,"lon":19.5281,"s":29,"w":"Battle of Cer","ty":"battle","u":0,"b":"The Battle of Cer was a military campaign fought between Austria-Hungary and Serbia in August 1914, starting three weeks into the Serbian Campaign of 1914, the initial military action of the First World War. It took place around Cer Mountain and several surrounding villages, as well as the town of Šabac."},{"n":"Battle of Kunersdorf","lat":52.3531,"lon":14.6128,"s":29,"w":"Battle of Kunersdorf","ty":"battle","u":0,"b":"The Battle of Kunersdorf occurred on 12 August 1759 near Kunersdorf (now Kunowice, Poland) immediately east of Frankfurt an der Oder. Part of the Third Silesian War and the wider Seven Years' War, the battle involved over 100,000 men."},{"n":"Battle of Dara","lat":37.18,"lon":40.955,"s":29,"w":"Battle of Dara","ty":"battle","u":0,"b":"The Battle of Dara was fought between the Byzantine Empire and the Sasanian Empire in June 530 AD during the Iberian War. Following the collapse of diplomatic efforts between the Byzantine Emperor Justinian I and Shah Kavadh I, a Sasanian army advanced on the fortified city of Dara, where it was met by a smaller Byzantine force commanded by Belisarius."},{"n":"Battle of Cold Harbor","lat":37.59,"lon":-77.285,"s":29,"w":"Battle of Cold Harbor","ty":"battle|siege","u":0,"b":"The Battle of Cold Harbor was fought during the American Civil War near Mechanicsville, Virginia, from May 31 to June 12, 1864, with the most significant fighting occurring on June 3. It was one of the final battles of Union Lt. Gen."},{"n":"Battle of Dresden","lat":51.0333,"lon":13.7333,"s":29,"w":"Battle of Dresden","ty":"battle","u":0,"b":"The Battle of Dresden (26–27 August 1813) was a major engagement of the Napoleonic Wars. The battle took place around the city of Dresden in modern-day Germany, then the capital of the Kingdom of Saxony. With the recent addition of Austria, the Sixth Coalition felt emboldened in their quest to expel the French from Central Europe."},{"n":"Battle of Princeton","lat":40.33,"lon":-74.675,"s":28,"w":"Battle of Princeton","ty":"battle","u":0,"b":"The Battle of Princeton was a battle of the American Revolutionary War, fought near Princeton, New Jersey on January 3, 1777, and ending in a small victory for the Colonials. General Lord Cornwallis had left 1,400 British troops under the command of Lieutenant Colonel Charles Mawhood in Princeton."},{"n":"Battle of Adrianople (324)","lat":41.67,"lon":26.525,"s":28,"w":"Battle of Adrianople (324)","ty":"battle","u":0,"b":"The Battle of Adrianople was fought in Thrace on July 3, 324, during a Roman civil war, the second to be waged between the two emperors Constantine I and Licinius. Licinius was soundly defeated and his army suffered heavy casualties. Constantine built up military momentum, winning further battles on land and sea, eventually leading to the final defeat of Licinius at Chrysopolis."},{"n":"Battle of Chickamauga","lat":34.9178,"lon":-85.2606,"s":28,"w":"Battle of Chickamauga","ty":"battle","u":0,"b":"The Battle of Chickamauga, fought on September 18–20, 1863, between the United States Army, or Union Army, and Confederate forces in the American Civil War, marked the end of a U.S. Army offensive, the Chickamauga Campaign, in southeastern Tennessee and northwestern Georgia."},{"n":"Battle of Karánsebes","lat":45.4214,"lon":22.2219,"s":28,"w":"Battle of Karánsebes","ty":"battle|friendly fire","u":0,"b":"The Battle of Karánsebes was a friendly fire incident in the Austrian army, occurring during the night of 21–22 September 1788, during the Austro-Turkish War of 1788–1791. Some historians have referred to the battle as \"history's worst friendly fire incident\"."},{"n":"Battle of Carchemish","lat":36.8297,"lon":38.015,"s":28,"w":"Battle of Carchemish","ty":"battle","u":0,"b":"The Battle of Carchemish was a battle fought around 605 BCE between the armies of Egypt, allied with the remnants of the Neo-Assyrian Empire, against the armies of Babylonia. The forces would clash at Carchemish, an important military crossing and trade city on the banks of the Euphrates River in modern-day Syria."},{"n":"Siege of Van","lat":38.4942,"lon":43.38,"s":28,"w":"Defense of Van (1915)","ty":"rebellion|siege|battle","u":0,"b":"The defense of Van (Armenian: Վանի հերոսամարտ, romanized: Vani herosamart) and in Russian Van operation (Russian: Ванская операция, romanized: Vanskaya operatsia) was the armed resistance of the Armenian population of Van and Russian army against the Ottoman Empire's attempts to massacre the Ottoman Armenian population of the Van Vilayet in the 1915 Armenian genocide."},{"n":"Siege of Belgrade","lat":44.8167,"lon":20.4667,"s":28,"w":"Siege of Belgrade (1521)","ty":"battle|siege","u":0,"b":"The siege of Belgrade (Hungarian: Nándorfehérvár ostroma) in 1521 is an event that followed as a result of the third major Ottoman attack on this Hungarian stronghold in the Ottoman–Hungarian wars at the time of the greatest expansion of the Ottoman Empire to the west. Ottoman Sultan Suleiman the Magnificent launched his army in mid-May 1521."},{"n":"Battle of Kolín","lat":50.0289,"lon":15.1219,"s":28,"w":"Battle of Kolín","ty":"battle","u":0,"b":"The Battle of Kolín (Kolin) on 18 June 1757 saw 54,000 Austrians under Count von Daun defeat 34,000 Prussians under Frederick the Great during the Third Silesian War (Seven Years' War). Prussian attempts to turn the Austrian right flank turned into piecemeal frontal attacks and were defeated in five and a half hours of combat. The Prussians lost 13,733 men, the Austrians 8,100."},{"n":"Battle of Kolubara","lat":44.3822,"lon":20.2628,"s":28,"w":"Battle of Kolubara","ty":"battle","u":0,"b":"The Battle of Kolubara was fought between Austria-Hungary and Serbia in November and December 1914, during the Serbian Campaign of 1914."},{"n":"Battle of Zorndorf","lat":52.6719,"lon":14.6544,"s":27,"w":"Battle of Zorndorf","ty":"battle","u":0,"b":"The Battle of Zorndorf, during the Seven Years' War, was fought on 25 August 1758 between Russian troops commanded by Count William Fermor and a Prussian army commanded by King Frederick the Great. The battle was tactically inconclusive, with both armies holding their ground and claiming victory."},{"n":"Battle of Mühlberg","lat":51.4331,"lon":13.2167,"s":27,"w":"Battle of Mühlberg","ty":"battle","u":0,"b":"The Battle of Mühlberg took place near Mühlberg in the Electorate of Saxony in 1547, during the Schmalkaldic War. The Catholic princes of the Holy Roman Empire led by the Holy Roman Emperor Charles V decisively defeated the Lutheran Schmalkaldic League of Protestant princes under the command of Elector John Frederick I of Saxony and Landgrave Philip I of Hesse."},{"n":"Battle of Dogger Bank","lat":54.724,"lon":2.769,"s":27,"w":"Battle of Dogger Bank (1915)","ty":"naval battle","u":0,"b":"The Battle of Dogger Bank (24 January 1915) was a naval engagement during the First World War near the Dogger Bank in the North Sea, between squadrons of the British Grand Fleet and the Kaiserliche Marine (High Seas Fleet)."},{"n":"Battle of Zela","lat":40.3,"lon":35.8833,"s":27,"w":"Battle of Zela (47 BC)","ty":"battle","u":0,"b":"The Battle of Zela was fought in 47 BC between Julius Caesar and Pharnaces II of the Kingdom of Pontus. The battle took place near Zela (modern Zile), which is now a small hilltop town in the Tokat province of northern Turkey. The battle ended the ambitions of king Pharnaces who wanted to expand his rule over Asia Minor."},{"n":"Battle of Brandywine","lat":39.872,"lon":-75.5901,"s":27,"w":"Battle of Brandywine","ty":"battle","u":0,"b":"The Battle of Brandywine, also known as the Battle of Brandywine Creek, was fought between the American Continental Army of General George Washington and the British Army of General Sir William Howe on September 11, 1777, as part of the American Revolutionary War (1775–1783). The forces met near Chadds Ford, Pennsylvania."},{"n":"Battle of Leuthen","lat":51.1521,"lon":16.7525,"s":27,"w":"Battle of Leuthen","ty":"battle","u":0,"b":"The Battle of Leuthen was fought on 5 December 1757 between Frederick the Great's Prussian Army and an Austrian army commanded by Prince Charles of Lorraine and Count Leopold Joseph von Daun. Frederick used maneuver warfare and knowledge of the terrain to rout the larger Austrian force completely."},{"n":"Battle of the Seelow Heights","lat":52.5347,"lon":14.3959,"s":27,"w":"Battle of the Seelow Heights","ty":"battle","u":0,"b":"The Battle of the Seelow Heights (German: Schlacht um die Seelower Höhen) was part of the Berlin Strategic Offensive Operation (16 April – 2 May 1945). A pitched battle, it was one of the last assaults on large entrenched defensive positions of the Second World War. It was fought over three days, from 16 to 19 April 1945."},{"n":"Battle of Abritus","lat":43.51,"lon":26.54,"s":27,"w":"Battle of Abritus","ty":"battle","u":0,"b":"The Battle of Abritus also known as the Battle of Forum Terebronii occurred near Abritus (modern Razgrad) in the Roman province of Moesia Inferior in the summer of 251. It was fought between the Romans and a federation of Gothic and Scythian tribesmen under the Gothic king Cniva."},{"n":"Battle of Appomattox Court House","lat":37.3775,"lon":-78.7961,"s":26,"w":"Battle of Appomattox Court House","ty":"battle","u":0,"b":"The Battle of Appomattox Court House, fought in Appomattox County, Virginia, on the morning of April 9, 1865, was one of the last, and ultimately one of the most consequential, battles of the American Civil War (1861–1865). It was the final push of Confederate general in chief Robert E."},{"n":"Battle of Adrianople","lat":41.6667,"lon":26.5667,"s":26,"w":"Battle of Adrianople (1205)","ty":"battle","u":0,"b":"The Battle of Adrianople occurred around Adrianople on April 14, 1205, between Bulgarians, Cumans and Vlachs under the command of Tsar Kaloyan of Bulgaria, and Crusaders under Baldwin I, who only months before had been crowned Emperor of Constantinople, allied with Venetians under Doge Enrico Dandolo. The battle was won by the Bulgarian Empire after a successful ambush."},{"n":"Battle of Tigranocerta","lat":38.1422,"lon":41.0014,"s":26,"w":"Battle of Tigranocerta","ty":"battle","u":0,"b":"The Battle of Tigranocerta was fought on 6 October 69 BC between the forces of the Roman Republic and the army of the Kingdom of Armenia led by King Tigranes the Great. The Roman force, led by Consul Lucius Licinius Lucullus, defeated Tigranes, and as a result, captured Tigranes' capital city of Tigranocerta."},{"n":"Battle of Prague","lat":50.076,"lon":14.557,"s":26,"w":"Battle of Štěrboholy","ty":"battle","u":0,"b":"The Battle of Prague, also known as Battle of Štěrboholy, was fought on 6 May 1757, during the Third Silesian War and the broader Seven Years' War, between the Kingdom of Prussia and Habsburg Austria. Although Frederick the Great's army of 64,000 Prussians forced 60,000 Austrians to retreat, he lost 14,300 men and decided he was not strong enough to attack Prague."},{"n":"Battle of Petrovaradin","lat":45.2525,"lon":19.8625,"s":26,"w":"Battle of Petrovaradin","ty":"battle","u":0,"b":"The Battle of Petrovaradin also known as the Battle of Peterwardein, took place on 5 August 1716 during the Austro-Turkish War when the Ottoman army besieged the Habsburg-controlled fortress of Petrovaradin on the Military Frontier of the Habsburg monarchy (today Novi Sad, Vojvodina, Serbia)."},{"n":"First Battle of Fallujah","lat":33.35,"lon":43.7833,"s":25,"w":"First Battle of Fallujah","ty":"battle|military operation","u":0,"b":"The First Battle of Fallujah, code-named Operation Vigilant Resolve, was an American-led operation of the Iraq War against militants in Fallujah as well as an attempt to apprehend or kill the perpetrators of the killing of four U.S. contractors in March 2004."},{"n":"Battle of Nahrawan","lat":34.5214,"lon":43.7842,"s":25,"w":"Battle of Nahrawan","ty":"battle","u":0,"b":"The Battle of Nahrawan was fought between the Kufan forces of the fourth Rashidun caliph Ali ibn Abi Talib and the Kharijites, who were primarily composed of qurra originating from across Iraq, in July 658 CE (Safar 38 AH). The latter were a group of former allies of Ali during the First Fitna."},{"n":"Battle of Idistaviso","lat":52.19,"lon":9.0207,"s":25,"w":"Battle of Idistaviso","ty":"battle","u":0,"b":"The Battle of the Weser River, sometimes known as the First Battle of Minden or Battle of Idistaviso, was fought in 16 AD between Roman legions commanded by Roman Emperor Tiberius's heir and adopted son, Germanicus, and an alliance of Germanic peoples, commanded by Arminius. The battle marked the end of a three-year series of campaigns by Germanicus in Germania."},{"n":"Battle of Flodden","lat":55.6269,"lon":-2.1753,"s":25,"w":"Battle of Flodden","ty":"battle","u":0,"b":"The Battle of Flodden, Flodden Field, or occasionally Branxton or Brainston Moor was fought on 9 September 1513 between the Kingdom of England and the Kingdom of Scotland as part of the War of the League of Cambrai and resulted in an English victory."},{"n":"Battle of Slankamen","lat":45.1333,"lon":20.2333,"s":25,"w":"Battle of Slankamen","ty":"battle|historic site","u":0,"b":"The Battle of Slankamen was fought on 19 August 1691, near Slankamen in the Ottoman Sanjak of Syrmia (modern-day Vojvodina, Serbia), between the Ottoman Empire, and Habsburg Austrian forces during the Great Turkish War."},{"n":"Battle of the Wilderness","lat":38.3175,"lon":-77.7564,"s":25,"w":"Battle of the Wilderness","ty":"battle","u":0,"b":"The Battle of the Wilderness was fought on May 5–7, 1864, during the American Civil War. It was the first battle of Lieutenant General Ulysses S. Grant's 1864 Virginia Overland Campaign against General Robert E. Lee and the Confederate Army of Northern Virginia. The fighting occurred in a wooded area near Locust Grove, Virginia, about 20 miles (32 km) west of Fredericksburg."},{"n":"Battle of Mollwitz","lat":50.85,"lon":17.41,"s":25,"w":"Battle of Mollwitz","ty":"battle","u":0,"b":"The Battle of Mollwitz was fought by Prussia and Austria on 10 April 1741, during the First Silesian War (in the early stages of the War of the Austrian Succession). It was the first battle of the new Prussian King Frederick II, in which both sides made numerous military blunders. Frederick fled the battlefield, but the Prussian Army managed to attain victory."},{"n":"Battle on the Marchfeld","lat":48.4815,"lon":16.8773,"s":25,"w":"Battle on the Marchfeld","ty":"battle","u":0,"b":"The Battle on the Marchfeld at Dürnkrut and Jedenspeigen took place on 26 August 1278 and was a decisive event for the history of Central Europe for the following centuries. The opponents were a Bohemian (Czech) army led by the Přemyslid king Ottokar II of Bohemia and the German army under the German king Rudolph I of Habsburg in alliance with King Ladislaus IV of Hungary."},{"n":"Second Battle of Fallujah","lat":33.35,"lon":43.7833,"s":25,"w":"Second Battle of Fallujah","ty":"battle","u":0,"b":"The Second Battle of Fallujah, initially codenamed Operation Phantom Fury, Operation al-Fajr (Arabic: الفجر, lit. 'The Dawn') was an American-led offensive of the Iraq War that began on 7 November 2004 and lasted about six weeks."},{"n":"Battle of Bautzen","lat":51.1833,"lon":14.4167,"s":25,"w":"Battle of Bautzen (1813)","ty":"battle","u":0,"b":"In the Battle of Bautzen (20–21 May 1813), a combined Prusso-Russian army, retreating after their defeat at Lützen and massively outnumbered, was pushed back by Napoleon but escaped destruction. Some sources claim that Marshal Michel Ney failed to block their retreat. The Prussians were led by General Gebhard Leberecht von Blücher, and the Russians by General Peter Wittgenstein."},{"n":"Battle of Marston Moor","lat":53.9622,"lon":-1.2542,"s":25,"w":"Battle of Marston Moor","ty":"battle","u":0,"b":"The Battle of Marston Moor was fought on 2 July 1644, during the Wars of the Three Kingdoms of 1639–1653. The combined forces of the English Parliamentarians under Lord Fairfax and the Earl of Manchester and the Scottish Covenanters under the Earl of Leven defeated the Royalists commanded by Prince Rupert of the Rhine and the Marquess of Newcastle."},{"n":"Battle of Chrysopolis","lat":41.015,"lon":29.03,"s":24,"w":"Battle of Chrysopolis","ty":"battle","u":0,"b":"The Battle of Chrysopolis was fought on 18 September 324 between the Roman emperors Constantine I and Licinius near Chrysopolis (modern Üsküdar), opposite Byzantium (modern Istanbul) on the Asiatic shore of the Bosphorus. The battle followed Constantine's victory at the Battle of the Hellespont, where his son Crispus destroyed the Licinian fleet."},{"n":"Battle of Pelekanon","lat":41.01,"lon":29.1503,"s":24,"w":"Battle of Pelekanon","ty":"battle","u":0,"b":"The Battle of Pelekanon, also known by its Latinised form Battle of Pelecanum, occurred on June 10–11, 1329, between an expeditionary force by the Byzantines led by Andronikos IIl and an Ottoman army led by Orhan I. The Byzantine army was defeated, with no further attempt made at relieving the cities in Anatolia under Ottoman siege."},{"n":"Siege of Bursa","lat":40.1833,"lon":29.0667,"s":24,"w":"Siege of Bursa","ty":"siege|battle","u":0,"b":"The Siege of Bursa (Ottoman Turkish: فتحِ بورصه, romanized: Feth-i Bursa) took place from 1317 until the capture of Bursa on 6 April 1326, when the Ottoman Turks deployed a bold plan to seize the city, which was back then known as Prusa."},{"n":"Bombing of Belgrade in 1941","lat":44.8178,"lon":20.4569,"s":24,"w":"German bombing of Belgrade","ty":"battle|aerial bombing of a city","u":0,"b":"Operation Retribution (German: Unternehmen Strafgericht) or Operation Punishment was the April 1941 German bombing of Belgrade, the capital of Yugoslavia, in retaliation for the coup d'état that overthrew the government that had signed the Tripartite Pact. The bombing occurred in the first days of the German-led Axis invasion of Yugoslavia during World War II."},{"n":"Battle of Kulm","lat":50.7128,"lon":13.957,"s":24,"w":"Battle of Kulm","ty":"battle","u":0,"b":"The Battle of Kulm was fought near the town Kulm (Czech: Chlumec) and the village Přestanov (then called Priesten) in northern Bohemia. It was fought on 29–30 August 1813, during the War of the Sixth Coalition. A French corps under General Dominique Vandamme attacked Alexander Osterman-Tolstoy's Russian corps on 29 August."},{"n":"Battle of Achelous","lat":42.6431,"lon":27.6367,"s":24,"w":"Battle of Achelous (917)","ty":"battle","u":0,"b":"The Battle of Achelous or Acheloos (Bulgarian: Битката при Ахелой, Greek: Μάχη του Αχελώου), also known as the Battle of Anchialus, took place on 20 August 917, on the Achelous river near the Bulgarian Black Sea coast, close to the fortress Tuthom (modern Pomorie) between Bulgarian and Byzantine forces."},{"n":"Battle of Monmouth","lat":40.2589,"lon":-74.2753,"s":24,"w":"Battle of Monmouth","ty":"battle","u":0,"b":"The Battle of Monmouth, also known as the Battle of Monmouth Court House, was fought near the Village of Monmouth Court House in modern-day Freehold Borough, New Jersey and Manalapan, on June 28, 1778, during the American Revolutionary War."},{"n":"Battle of Lutter","lat":51.9669,"lon":10.2386,"s":24,"w":"Battle of Lutter","ty":"battle","u":0,"b":"The Battle of Lutter (German: Lutter am Barenberge) took place on 27 August 1626 during the Thirty Years' War, south of Salzgitter, in Lower Saxony. A combined Danish-German force led by Christian IV of Denmark was defeated by Johann Tserclaes, Count of Tilly, commanding an army of the Catholic League loyal to Emperor Ferdinand II."},{"n":"Battle of Quebec","lat":46.815,"lon":-71.2022,"s":24,"w":"Battle of Quebec (1775)","ty":"battle","u":0,"b":"The Battle of Quebec (French: Bataille de Québec) was fought on December 31, 1775, between American Continental Army forces and the British defenders of Quebec City as part of the invasion of Quebec of the American Revolutionary War. The battle was the first major defeat of the war for the Americans, and it came with heavy losses."},{"n":"Battle of Buda","lat":47.4667,"lon":19.05,"s":23,"w":"Siege of Buda (1686)","ty":"battle|siege","u":0,"b":"The siege of Buda (Hungarian: Buda visszafoglalása, lit. 'Recapture of Buda') was a military engagement during the Great Turkish War, in which forces of the Holy League, led by the Habsburg Monarchy, recaptured the fortified city of Buda (now part of modern-day Budapest) from the Ottoman Empire."},{"n":"Siege of Constantinople","lat":41.0167,"lon":28.9769,"s":23,"w":"Siege of Constantinople (1203)","ty":"battle|siege","u":0,"b":"The siege of Constantinople in 1203 was a crucial episode of the Fourth Crusade, marking the beginning of a series of events that would ultimately lead to the fall of the Byzantine capital."},{"n":"Reconquest of Constantinople","lat":41.0167,"lon":28.9769,"s":23,"w":"Reconquest of Constantinople","ty":"battle","u":0,"b":"Constantinople was recaptured in 1261 from the Latin Empire by Nicaean forces led by the general Alexios Strategopoulos."},{"n":"Battle of Breadfield","lat":45.9375,"lon":23.3444,"s":23,"w":"Battle of Breadfield","ty":"battle","u":0,"b":"The Battle of Breadfield was the most tremendous conflict fought in Transylvania up to that time in the Ottoman–Hungarian Wars, taking place on 13 October 1479, on the Breadfield near the Saxon village of Alkenyér (also Zsibód, German: Unterbrodsdorf, Romanian: Șibot) next to the river Maros (Mureș)."},{"n":"Battle of Pteria","lat":39.9167,"lon":35.3333,"s":23,"w":"Battle of Pteria","ty":"battle","u":0,"b":"The Battle of Pteria (Ancient Greek: Πτερία) was fought in 547 BC between the Persian forces of Cyrus the Great and the Lydian forces of Croesus. Both armies suffered heavy casualties in this indecisive battle."},{"n":"Fall of Nineveh","lat":36.3594,"lon":43.1528,"s":23,"w":"Fall of Nineveh","ty":"battle","u":0,"b":"The Fall of Nineveh, also called the Battle of Nineveh, was a major battle that marked the climax of the Conquest of the Assyrian Empire in 612 BC."},{"n":"Sack of Amorium","lat":39.0225,"lon":31.295,"s":23,"w":"Sack of Amorium","ty":"battle|siege","u":0,"b":"The siege of Amorium by the Abbasid Caliphate in mid-August 838 was one of the major events in the long history of the Arab–Byzantine Wars. The Abbasid campaign was led personally by the Caliph al-Mu'tasim (r. 833–842), in retaliation to a virtually unopposed expedition launched by the Byzantine emperor Theophilos (r. 829–842) into the Caliphate's borderlands the previous year."},{"n":"Battle of Anchialus","lat":42.55,"lon":27.65,"s":23,"w":"Battle of Anchialus (708)","ty":"battle","u":0,"b":"The Battle of Anchialus (Bulgarian: Битката при Анхиало) (Medieval Greek: Μάχη του Αγχίαλου) occurred in 708 near the modern-day town of Pomorie, Bulgaria"},{"n":"Göbekli Tepe","lat":37.2231,"lon":38.9225,"s":78,"w":"Göbekli Tepe","ty":"Neolithic settlement|tell","u":1,"b":"Göbekli Tepe is a Neolithic archaeological site in Upper Mesopotamia (al-Jazira) in modern-day Turkey. The settlement was inhabited from around 9500 BCE to at least 8000 BCE, during the Pre-Pottery Neolithic. It is known for its large circular structures that contain large stone pillars – among the world's oldest known megaliths."},{"n":"Mount Nemrut","lat":37.9807,"lon":38.7408,"s":61,"w":"Mount Nemrut","ty":"mountain|archaeological site|sanctuary","u":1,"b":"Mount Nemrut or Nemrud is a 2,150-metre-high (7,054 ft) mountain in southeastern Turkey, notable for the summit where a number of large statues are erected around what is assumed to be a royal tomb from the 1st century BC. It is one of the highest peaks in the east of the Taurus Mountains. It was designated a UNESCO World Heritage Site in 1987."},{"n":"Sozopol","lat":42.4187,"lon":27.6943,"s":56,"w":"Sozopol","ty":"seaside resort|polis|city in Bulgaria|municipality seat|spa town","u":0,"b":"Sozopol is an ancient seaside town located 35 km south of Burgas on the southern Bulgarian Black Sea Coast. One of the major seaside resorts in the country, it is known for the Apollonia art and film festival (which takes place in early September) that is named after one of the town's ancient names."},{"n":"Imbros","lat":40.2331,"lon":25.903,"s":55,"w":"Imbros","ty":"polis|island","u":0,"b":"Imbros, officially Gökçeada (lit. 'Heavenly Island') since 29 July 1970, is the largest island of Turkey, located in Çanakkale Province. It is located in the north-northeastern Aegean Sea, at the entrance of Saros Bay, and has the westernmost point of Turkey (Cape İncirburnu). Imbros has an area of 286.8 km2 (110.7 sq mi), and has some wooded areas."},{"n":"Antonine Wall","lat":55.967,"lon":-4.067,"s":52,"w":"Antonine Wall","ty":"defensive wall|Roman limes|defense line|Roman archaeological site","u":1,"b":"The Antonine Wall (Latin: Vallum Antonini) was a turf fortification on stone foundations, built by the Romans across what is now the Central Belt of Scotland, between the Firth of Clyde and the Firth of Forth. It was built some twenty years after Hadrian's Wall, which was to the south, and was intended to supersede it."},{"n":"Nicaea","lat":40.429,"lon":29.7195,"s":52,"w":"Nicaea","ty":"ancient city","u":0,"b":"Nicaea, also known as Nikaia or Nice ( or ), was an ancient Greek city in the northwestern Anatolian region of Bithynia. It was the site of the First and Second Councils of Nicaea. The Nicene Creed, which was composed at the First Council, takes its name from the city."},{"n":"Philippi","lat":41.0131,"lon":24.2864,"s":51,"w":"Philippi","ty":"archaeological site|polis|ancient city","u":1,"b":"Philippi was a major mainland Greek city northwest of the nearby island, Thasos. Its original name was Crenides (Ancient Greek: Κρηνῖδες, Krēnĩdes \"Fountains\"). The city was renamed by Philip II of Macedon in 356 BC and abandoned in the 14th century after the Ottoman conquest."},{"n":"Independence Hall","lat":39.9489,"lon":-75.15,"s":47,"w":"Independence Hall","ty":"archaeological site|heritage site|legislative building","u":1,"b":"Independence Hall is a historic civic building in Philadelphia, Pennsylvania, where both the Declaration of Independence and the Constitution of the United States were debated and adopted by the Founding Fathers of the United States. The building, which is the centerpiece of Independence National Historical Park, was designated a World Heritage Site in 1979."},{"n":"Dur-Sharrukin","lat":36.5095,"lon":43.2293,"s":47,"w":"Dur-Sharrukin","ty":"archaeological site|human settlement","u":0,"b":"Dur-Sharrukin, present day Khorsabad, was the Assyrian capital in the time of Sargon II of Assyria. Khorsabad is a village in northern Iraq, 15 km northeast of Mosul. The great city was entirely built in the decade preceding 706 BC. After the unexpected death of Sargon in battle, the capital was moved 20 km south to Nineveh."},{"n":"Nicomedia","lat":40.7625,"lon":29.9175,"s":46,"w":"Nicomedia","ty":"archaeological site|ancient city","u":0,"b":"Nicomedia was an ancient Greek city located in what is now Turkey. In 286 AD, Nicomedia became the eastern and most senior capital city of the Roman Empire (chosen by the emperor Diocletian who ruled in the east), a status which the city maintained during the Tetrarchy system (293–324 AD)."},{"n":"Sippar","lat":33.0667,"lon":44.25,"s":45,"w":"Sippar","ty":"archaeological site|human settlement","u":0,"b":"Sippar (Sumerian: 𒌓𒄒𒉣𒆠, Zimbir) (also Sippir or Sippara) was an ancient Near Eastern Sumerian and later Babylonian city on the east bank of the Euphrates river. Its tell is located at the site of modern Tell Abu Habbah near Yusufiyah in Iraq's Baghdad Governorate, some 69 km (43 mi) north of Babylon and 30 km (19 mi) southwest of Baghdad."},{"n":"Sirmium","lat":44.9661,"lon":19.6106,"s":45,"w":"Sirmium","ty":"archaeological site|ancient city","u":0,"b":"Sirmium was a city in the Roman province of Pannonia, located on the Sava river, on the site of modern Sremska Mitrovica in the Vojvodina autonomous province of Serbia."},{"n":"Carchemish","lat":36.8297,"lon":38.015,"s":44,"w":"Carchemish","ty":"historical country|archaeological site","u":0,"b":"Carchemish, also spelled Karkemish (Turkish: Karkamış), was an important ancient capital in the northern part of the region of Syria. At times during its history the city was independent, but it was also part of the Mitanni, Hittite and Neo-Assyrian Empires. In Roman times the city bore the name Europus."},{"n":"Chalcedon","lat":40.9834,"lon":29.0258,"s":44,"w":"Chalcedon","ty":"polis|ancient city","u":0,"b":"Chalcedon was an ancient maritime town of Bithynia, in Asia Minor. It was located to the south of Chrysopolis (later known as Scutari, modern Üsküdar) and almost directly opposite Byzantium across the Bosporus strait, in Europe. At present, it is a district of the city of Istanbul named Kadıköy."},{"n":"Hedeby","lat":54.4911,"lon":9.5653,"s":43,"w":"Hedeby","ty":"ancient city|archaeological site","u":1,"b":"Hedeby was an important Danish Viking Age (8th to the 11th centuries) trading settlement near the southern end of the Jutland Peninsula, now in the Schleswig-Flensburg district of Schleswig-Holstein, Germany."},{"n":"Edessa","lat":37.15,"lon":38.7825,"s":43,"w":"Edessa","ty":"ancient city|polis|archaeological site","u":0,"b":"Edessa was an ancient city (polis) in Upper Mesopotamia, in what is now Urfa or Şanlıurfa, Turkey. It was founded during the Hellenistic period by Macedonian general and self proclaimed king Seleucus I Nicator (r. 305–281 BC), founder of the Seleucid Empire. He named it after an ancient Macedonian capital."},{"n":"Carnuntum","lat":48.1133,"lon":16.8614,"s":43,"w":"Carnuntum","ty":"castrum|open-air museum|archaeological site|municipium","u":0,"b":"Carnuntum (from Ancient Greek Καρνοῦς (Carnous) according to Ptolemy) was a Roman legionary fortress (Latin: castra legionis) and headquarters of the Pannonian fleet from 50 AD. After the 1st century, it was capital of the Pannonia Superior province. It also became a large city of approximately 50,000 inhabitants."},{"n":"Great Mosque of Samarra","lat":34.2062,"lon":43.8798,"s":43,"w":"Great Mosque of Samarra","ty":"archaeological site|mosque|protected area","u":0,"b":"The Great Mosque of Samarra or Al-Malwiya Mosque is a former congregational mosque, now in partial ruins, in Samarra, in the Saladin Governorate of Iraq. The mosque was commissioned in 848 CE and completed in 851 by the Abbasid caliph Al-Mutawakkil. At the time of construction it was the world's largest mosque."},{"n":"Seleucia","lat":33.1372,"lon":44.5172,"s":43,"w":"Seleucia","ty":"archaeological site|ancient city","u":0,"b":"Seleucia, also known as Seleucia-on-Tigris, Seleucia on the Tigris or Seleucia ad Tigrim, was a major Mesopotamian city, located on the west bank of the Tigris River within the present-day Baghdad Governorate in Iraq."},{"n":"Aquincum","lat":47.5641,"lon":19.0495,"s":43,"w":"Aquincum","ty":"archaeological site|ancient Roman structure|castrum","u":0,"b":"Aquincum was an ancient city, situated on the northeastern borders of the province of Pannonia within the Roman Empire. The ruins of the city can be found in the Óbuda district of Budapest, the capital city of Hungary. It is believed that Marcus Aurelius wrote at least part of his book Meditations at Aquincum."},{"n":"Shanidar Cave","lat":36.8006,"lon":44.2433,"s":42,"w":"Shanidar Cave","ty":"cave|archaeological site","u":0,"b":"Shanidar Cave is an archaeological site on Bradost Mountain, within the Zagros Mountains in the Erbil Governorate of Kurdistan Region in northern Iraq."},{"n":"Basilica Cistern","lat":41.0084,"lon":28.9779,"s":41,"w":"Basilica Cistern","ty":"ancient Roman cistern|palace","u":0,"b":"The Basilica Cistern, or Cisterna Basilica, is the largest of several hundred ancient cisterns that lie beneath the city of Istanbul, Turkey. The cistern, located 150 metres (490 ft) southwest of the Hagia Sophia on the historical peninsula of Sarayburnu, was built in the 6th century during the reign of Byzantine emperor Justinian I."},{"n":"Eshnunna","lat":33.75,"lon":44.75,"s":41,"w":"Eshnunna","ty":"archaeological site|city-state|human settlement","u":0,"b":"Eshnunna (modern Tell Asmar in Diyala Governorate, Iraq) was an ancient Sumerian (and later Akkadian) city and city-state in central Mesopotamia 12.6 miles northwest of Tell Agrab and 15 miles northwest of Tell Ishchali. Although situated in the Diyala Valley northwest of Sumer proper, the city nonetheless belonged securely within the Sumerian cultural milieu."},{"n":"Shuruppak","lat":31.7774,"lon":45.5098,"s":40,"w":"Shuruppak","ty":"human settlement|archaeological site","u":0,"b":"Shuruppak, also Šuruppak, modern Tell Fara, was an ancient Sumerian city situated about 55 kilometres (35 mi) south of Nippur and 30 kilometers north of ancient Uruk on the banks of the Euphrates in Iraq's Al-Qādisiyyah Governorate. Shuruppak was dedicated to Ninlil, also called Sud, the goddess of grain and the air."},{"n":"Gordion","lat":39.6505,"lon":31.9785,"s":40,"w":"Gordion","ty":"archaeological site","u":1,"b":"Gordion was the capital city of ancient Phrygia. It was located at the site of modern Yassıhüyük, about 70–80 km (43–50 mi) southwest of Ankara (capital of Turkey), in the immediate vicinity of Polatlı district. Gordion's location at the confluence of the Sakarya and Porsuk rivers gave it a strategic location with control over fertile land."},{"n":"Băile Herculane","lat":44.8772,"lon":22.4175,"s":38,"w":"Băile Herculane","ty":"ancient city|resort|spa town|designated spa town|resort town|town in Romania","u":0,"b":"Băile Herculane is a spa town in Romanian Banat, in Caraș-Severin County, situated in the valley of the Cerna River, between the Mehedinți Mountains to the east and the Cerna Mountains to the west, elevation 168 m (551 ft). Its current population is 3,787. The town administers one village, Pecinișca (Hungarian: Pecsenyeska; from 1912 to 1918 Csernabesenyő)."},{"n":"Jarmo","lat":35.5558,"lon":44.9303,"s":38,"w":"Jarmo","ty":"archaeological site","u":0,"b":"Jarmo is a prehistoric archeological site located in modern Iraqi Kurdistan on the foothills of the Zagros Mountains. It lies at an altitude of 800 m above sea-level in a belt of oak and pistachio woodlands in the Adhaim River watershed. Excavations revealed that Jarmo was an agricultural community dating back to around 7090 BC."},{"n":"Danevirke","lat":54.4775,"lon":9.4867,"s":37,"w":"Danevirke","ty":"archaeological site|defensive wall","u":1,"b":"The Danevirke or Danework is a system of Danish fortifications in Schleswig-Holstein, Germany. This historically important linear defensive earthwork across the neck of the Cimbrian peninsula was initiated by the Danes in the Nordic Iron Age about AD 650. It was later expanded multiple times during Denmark's Viking Age and High Middle Ages."},{"n":"Tigranocerta","lat":38.1422,"lon":41.0014,"s":37,"w":"Tigranocerta","ty":"ancient city|archaeological site","u":0,"b":"Tigranocerta, also called Cholimma or Chlomaron in late antiquity, was a city and the capital of the Armenian Kingdom between 77 and 69 BCE."},{"n":"Göreme National Park","lat":38.6528,"lon":34.8631,"s":37,"w":"Göreme Historical National Park","ty":"national park|park|archaeological site","u":1,"b":"Göreme Historical National Park is a national park in Cappadocia in central Turkey. It occupies an area of nearly 100 km2 (39 sq mi) and is located in Nevşehir Province. It became a UNESCO World Heritage Site in 1985 under the name Göreme National Park and the Rock Sites of Cappadocia."},{"n":"Trajan's Bridge","lat":44.6238,"lon":22.667,"s":36,"w":"Trajan's Bridge","ty":"road bridge|former bridge|Roman bridge|wooden bridge|deck arch bridge|stone bridge","u":0,"b":"Trajan's Bridge, also called Bridge of Apollodorus over the Danube, was a Roman segmental arch bridge, on the modern Serbian–Romanian border, the first bridge to be built over the lower Danube and considered one of the greatest achievements in Roman architecture."},{"n":"Kültepe","lat":38.85,"lon":35.6333,"s":36,"w":"Kültepe","ty":"ancient city|tell|archaeological site","u":0,"b":"Kültepe (Turkish: lit. 'ash-hill'), ancient name Kaneš (Kanesh, also Kaniš/Kanish) or Neša (Nesha), was a Bronze Age (broadly, 3300–1200 BC) settlement and trading center on the Central Anatolian plateau in modern Turkey. It was a major settlement in the early 3rd millennium, and is particularly renowned for its regional importance in the early 2nd millennium."},{"n":"Girsu","lat":31.5653,"lon":46.1896,"s":35,"w":"Girsu","ty":"ancient city|archaeological site|human settlement","u":0,"b":"Girsu (Sumerian Ĝirsu. cuneiform ĝir2-suki 𒄈𒋢𒆠) was a city of ancient Sumer, situated some 25 km (16 mi) northwest of Lagash, at the site of what is now Tell Telloh in Dhi Qar Governorate, Iraq. Because of the initial velar nasal ŋ, the transcription of Ĝirsu is sometimes spelled as Ngirsu (also: G̃irsu, Girsu, Jirsu)."},{"n":"Borsippa","lat":32.392,"lon":44.3417,"s":35,"w":"Borsippa","ty":"human settlement|ancient city|archaeological site","u":0,"b":"Borsippa (Sumerian: BAD.SI.(A).AB.BAKI or Birs Nimrud, having been identified with Nimrod) is an archeological site in Babylon Governorate, Iraq, built on both sides of a lake about 17.7 km (11.0 mi) southwest of Babylon on the east bank of the Euphrates. It lies 15 kilometers from the ancient site of Dilbat."},{"n":"Al-Hirah","lat":31.98,"lon":44.39,"s":35,"w":"Al-Hira","ty":"lost city|archaeological site","u":0,"b":"Al-Hira (Arabic: الحيرة, romanized: al-Ḥīra Middle Persian: Hērt ) was an ancient city and a major metropolis located in Mesopotamia, in what is now south-central Iraq. It was the capital city of the Lakhmid kingdom, the major Arab client kingdom of the Sasanian Empire in pre-Islamic times, between the fourth and the seventh centuries."},{"n":"Citadel of Erbil","lat":36.191,"lon":44.009,"s":34,"w":"Citadel of Erbil","ty":"tell|citadel","u":1,"b":"The Citadel of Erbil, locally called Qellat, is a tell or occupied mound, and the historical city centre of Erbil in the Kurdistan Region of Iraq. The citadel was added to the World Heritage List on 21 June 2014. The earliest evidence for occupation of the citadel mound dates to the 5th millennium BC, and possibly earlier."},{"n":"Etemenanki","lat":32.5364,"lon":44.4208,"s":34,"w":"Etemenanki","ty":"archaeological site|ziggurat","u":0,"b":"Etemenanki was a Babylonian ziggurat dedicated to the Mesopotamian god Marduk. Now in ruins, it is located about 90 kilometres (56 mi) south of Baghdad. Some scholars have proposed Etemenanki as the ziggurat that may have influenced the biblical account of the Tower of Babel."},{"n":"Cyzicus","lat":40.3878,"lon":27.8706,"s":33,"w":"Cyzicus","ty":"ancient city|polis|archaeological site","u":0,"b":"Cyzicus ( SIZ-ik-əs; Ancient Greek: Κύζικος, romanized: Kúzikos; was an ancient Greek town in Mysia in Anatolia in the current Balıkesir Province of Turkey."},{"n":"Adab","lat":31.95,"lon":45.9667,"s":33,"w":"Adab (city)","ty":"tell|ancient city|archaeological site","u":0,"b":"Adab (Sumerian: 𒌓𒉣𒆠 Adabki, spelled UD.NUNKI) was an ancient Sumerian city between Girsu and Nippur, lying about 35 kilometers (22 miles) southeast of the latter. It was located at the site of modern Bismaya or Bismya in the Al-Qādisiyyah Governorate of Iraq."},{"n":"Fountains Abbey","lat":54.1097,"lon":-1.5814,"s":33,"w":"Fountains Abbey","ty":"monastery|building complex|abbey|destroyed building or structure|monastery ruins","u":1,"b":"Fountains Abbey is a ruined Cistercian monastery near Ripon in North Yorkshire, England. It was founded in 1132 under the direction of Thurstan, archbishop of York, and over the next four centuries became one of the wealthiest monasteries in England thanks to its large and diverse landholdings."},{"n":"Abydos","lat":40.1953,"lon":26.405,"s":33,"w":"Abydos (Hellespont)","ty":"archaeological site|former settlement|polis","u":0,"b":"Abydos (Ancient Greek: Ἄβυδος, Latin: Abydus) was an ancient city and bishopric in Mysia. It was located at the Nara Burnu promontory on the Asian coast of the Hellespont (the straits of Dardanelles), opposite the ancient city of Sestos, and near the city of Çanakkale in Turkey. Abydos was founded in c."},{"n":"Vindobona","lat":48.2108,"lon":16.3703,"s":33,"w":"Vindobona","ty":"ancient city|archaeological site","u":0,"b":"Vindobona was a Roman military camp (or castra) in the province of Pannonia, located on the site of the modern city of Vienna in Austria. The settlement area took on a new name in the 13th century, Berghof, now known as Alter Berghof (Old Berghof). Around 1 AD, the kingdom of Noricum was included in the Roman Empire."},{"n":"Derinkuyu underground city","lat":38.3734,"lon":34.735,"s":33,"w":"Derinkuyu underground city","ty":"underground city|archaeological site","u":1,"b":"Derinkuyu, also known as Malakopi, is an ancient multi-level underground city near the modern town of Derinkuyu in Nevşehir Province, Turkey, extending to a depth of approximately 85 metres (280 ft). It is large enough to have sheltered as many as 20,000 people together with their livestock and food stores."},{"n":"Sarmizegetusa Regia","lat":45.6228,"lon":23.3103,"s":32,"w":"Sarmizegetusa Regia","ty":"archaeological site|temple|ancient city|fortress|dava","u":1,"b":"Sarmizegetusa Regia was the capital and the most important military, religious and political centre of the Dacians before the wars with the Roman Empire. Built on top of a 1200 m high mountain, the fortress, consisting of six citadels, was the core of a strategic and defensive system in the Orăștie Mountains (in present-day Romania)."},{"n":"Alacahöyük","lat":40.2339,"lon":34.6956,"s":32,"w":"Alaca Höyük","ty":"tell|archaeological site|park","u":0,"b":"Alacahöyük or Alaca Höyük (sometimes also spelled as Alacahüyük, Euyuk, or Evuk) is the site of a Neolithic and Hittite settlement and is an important archaeological site."},{"n":"Monastery of Stoudios","lat":40.9961,"lon":28.9286,"s":32,"w":"Monastery of Stoudios","ty":"monastery ruins","u":0,"b":"The Monastery of Stoudios, more fully Monastery of Saint John the Forerunner \"at Stoudios\", often shortened to Stoudios, Studion or Stoudion (Latin: Studium), was a Greek Orthodox monastery in Constantinople (modern-day Istanbul), the capital of the Byzantine Empire. The residents of the monastery were referred to as Stoudites or Studites."},{"n":"Taq-i Kisra","lat":33.0937,"lon":44.5807,"s":32,"w":"Taq Kasra","ty":"architectural landmark|royal palace|archaeological site","u":0,"b":"Tāq Kasrā (Arabic: طاق كسرى, romanized: ṭāq kisrā), also transcribed as Taq-i Kisra or Taq-e Kesra (Persian: طاق کسری, romanized: tâğe kasrâ) or Ayvān-e Kesrā are the remains of a Sasanian-era Persian monument, dated to c. the 3rd to 6th centuries, which is sometimes called the Arch of Ctesiphon. It is located near the modern town of Salman Pak, Iraq."},{"n":"Heraclea Pontica","lat":41.2847,"lon":31.4147,"s":31,"w":"Heraclea Pontica","ty":"archaeological site|polis","u":0,"b":"Heraclea Pontica, known in Byzantine and later times as Pontoheraclea (Greek: Ποντοηράκλεια, romanized: Pontohērakleia), was an ancient city on the coast of Bithynia in Asia Minor, at the mouth of the river Lycus. The site is now the location of the modern city Karadeniz Ereğli, in the Zonguldak Province of Turkey."},{"n":"Arslantepe","lat":38.3819,"lon":38.3611,"s":31,"w":"Arslantepe","ty":"archaeological site|human settlement","u":1,"b":"Arslantepe, also known as Melid, was an ancient city on the Tohma River, a tributary of the upper Euphrates rising in the Taurus Mountains. It has been identified with the modern archaeological site of Arslantepe near Malatya, Türkiye. It was named a UNESCO World Heritage Site under the name Arslantepe Mound in 2021."},{"n":"Tell Brak","lat":36.6667,"lon":41.0583,"s":31,"w":"Tell Brak","ty":"tell","u":0,"b":"Tell Brak (Nagar, Nawar) was an ancient city in Syria; it is one of the earliest known cities in the world. Its remains constitute a tell located in the Upper Khabur region, near the modern village of Tell Brak, 50 kilometers north-east of Al-Hasaka city, Al-Hasakah Governorate. The city's original name is unknown."},{"n":"Çayönü","lat":38.216,"lon":39.725,"s":31,"w":"Çayönü","ty":"human settlement|prehistoric archaeological site","u":0,"b":"Çayönü Tepesi is a Pre-Pottery Neolithic B settlement in southeastern Turkey which prospered from around 8630 to 6800 BC. It is located in Diyarbakır 40 kilometres northwest of Diyarbakır, 140 kilometers northeast of Şanlıurfa, at the foot of the Taurus Mountains. It lies near the Boğazçay, a tributary of the upper Tigris River and the Bestakot, an intermittent stream."},{"n":"Malkara","lat":40.8933,"lon":26.9042,"s":30,"w":"Malkara","ty":"ancient city|town","u":0,"b":"Malkara (Greek: Μάλγαρα, Malgara) is a municipality and district of Tekirdağ Province, Turkey. Its area is 1,243 km2 (the largest in Tekirdağ Province), and its population is 50,988 (2022). It is located at 55 km west of Tekirdağ and 190 km from Istanbul."},{"n":"Externsteine","lat":51.8689,"lon":8.9175,"s":30,"w":"Externsteine","ty":"archaeological site|geotope","u":0,"b":"The Externsteine is a distinctive sandstone rock formation located in the Teutoburg Forest, near the town of Horn-Bad Meinberg in the Lippe district of the German state of North Rhine-Westphalia. The formation is a tor consisting of several tall, narrow columns of rock which rise abruptly from the surrounding wooded hills."},{"n":"Perperikon","lat":41.7147,"lon":25.4653,"s":30,"w":"Perperikon","ty":"archaeological site|ancient city","u":0,"b":"Perperikon (Bulgarian: Перперикон), also Perpericum, is an ancient Thracian city located in the Eastern Rhodope Mountains, 15 km northeast of the present-day town of Kardzhali, Bulgaria on a 470 m high rocky hill, which is thought to have been a sacred place."},{"n":"Magura Cave","lat":43.7183,"lon":22.6003,"s":29,"w":"Magura Cave","ty":"cave|cave with prehistoric art|rock art|show cave","u":0,"b":"The Magura Cave (Bulgarian: пещера Магура) is located in north-western Bulgaria close to the village of Rabisha, 25 km (16 mi) from the town of Belogradchik in Vidin Province."},{"n":"Dilmun Burial Mounds","lat":26.1497,"lon":50.5128,"s":29,"w":"Dilmun Burial Mounds","ty":"necropolis","u":1,"b":"The Dilmun Burial Mounds (Arabic: مدافن دلمون, romanized: Madāfin Dilmūn) are a UNESCO World Heritage Site comprising necropolis areas on the main island of Bahrain dating back to the Dilmun and the Umm al-Nar culture."},{"n":"Lepenski Vir","lat":44.5611,"lon":22.0242,"s":29,"w":"Lepenski Vir","ty":"archaeological site","u":0,"b":"Lepenski Vir (Serbian Cyrillic: Лепенски Вир, \"Lepena Whirlpool\"), located in Serbia, is an important archaeological site of the Lepenski Vir culture (also called as Lepenski Vir-Schela Cladovei culture). It includes Mesolithic Iron Gates Hunter-Gatherers period and transition to Early Neolithic Early European Farmers period of Southeastern Europe."},{"n":"Samosata","lat":37.5795,"lon":38.4813,"s":28,"w":"Samosata","ty":"archaeological site|ancient city","u":0,"b":"Samsat (Kurdish: Samîsad, Ottoman Turkish صمصاد Semisat), formerly Samosata (Ancient Greek: Σαμόσατα) is a small town in the Adıyaman Province of Turkey, situated on the upper Euphrates river. It is the seat of Samsat District. The town is populated by Kurds of the Bêzikan tribe."},{"n":"Dur-Kurigalzu","lat":33.3537,"lon":44.2023,"s":28,"w":"Dur-Kurigalzu","ty":"human settlement|archaeological site|region","u":0,"b":"Dur-Kurigalzu (modern `Aqar-Qūf عَقَرْقُوف in Baghdad Governorate, Iraq) was a city in southern Mesopotamia, near the confluence of the Tigris and Diyala rivers, about 30 kilometres (19 mi) west of the center of Baghdad. It was founded by a Kassite king of Babylon, Kurigalzu I (died c. 1375 BC) and was abandoned after the fall of the Kassite dynasty (c."},{"n":"Nuzi","lat":35.3025,"lon":44.2476,"s":27,"w":"Nuzi","ty":"city|archaeological site","u":0,"b":"Nuzi (Hurrian Nuzi/Nuzu; Akkadian Gasur) at modern Yorghan Tepe (also Yorgan Tepa and Jorgan Tepe), Iraq was an ancient Mesopotamian city 12 kilometers southwest of the city of Arrapha (modern Kirkuk) and 70 kilometers southwest of Sātu Qala, located near the Tigris river."},{"n":"Ancient Abdera","lat":40.9337,"lon":24.9733,"s":27,"w":"Abdera, Thrace","ty":"archaeological site|tourist destination|polis","u":0,"b":"Abdera (Greek: Άβδηρα) is a municipality in the Xanthi regional unit of Thrace, Greece. In classical antiquity, it was a major Greek polis on the Thracian coast. The ancient polis is to be distinguished from the municipality, which was named in its honor."},{"n":"Dara","lat":37.1833,"lon":40.9333,"s":26,"w":"Dara (Mesopotamia)","ty":"archaeological site","u":0,"b":"Dara or Daras (Turkish: Dara Antik Kenti; Greek: Δάρας; Syriac: ܕܪܐ) was an important East Roman fortress city in northern Mesopotamia on the border with the Sassanid Empire. Because of its great strategic importance, it featured prominently in the Roman-Persian conflicts (in 530, 540, 544, 573, and 604). The former archbishopric remains a multiple Catholic titular see."},{"n":"Yazılıkaya","lat":40.025,"lon":34.6328,"s":26,"w":"Yazılıkaya","ty":"archaeological site|sculpture","u":1,"b":"Yazılıkaya, Eskişehir, also called Midas City, is a village with Phrygian ruins. Yazılıkaya (Turkish: Inscribed rock) was a sanctuary of Hattusa, the capital city of the Hittite Empire, today in the Çorum Province, Turkey. Rock reliefs are a prominent aspect of Hittite art, and these are generally regarded as the most important group."},{"n":"Viminacium","lat":44.7165,"lon":21.1666,"s":26,"w":"Viminacium","ty":"archaeological site|municipium","u":0,"b":"Viminacium (also Viminatium) was a major city, military camp, and the capital of the Roman province of Moesia (modern Serbia). Following the division of Moesia in 87, following Domitian's Dacian War, it became the capital of Moesia Superior. As of 2018, only 3-4% of the site has been explored."},{"n":"Calanais Stones","lat":58.1976,"lon":-6.7451,"s":25,"w":"Callanish Stones","ty":"archaeological site","u":0,"b":"The Calanais Stones are a prehistoric stone circle and stone alignment on the west coast of the Isle of Lewis in the Outer Hebrides of Scotland. The monument was built during the Neolithic period, around c. 2750 BC."},{"n":"Amorium","lat":39.0265,"lon":31.2666,"s":25,"w":"Amorium","ty":"ancient city|archaeological site","u":0,"b":"Amorium, also known as Amorion (Greek: Ἀμόριον), was a city in Phrygia, Asia Minor which was founded in the Hellenistic period, flourished under the Byzantine Empire, and declined after the Arab sack of 838. It was situated on the Byzantine military road from Constantinople to Cilicia."},{"n":"Bad-tibira","lat":31.3828,"lon":46.0044,"s":25,"w":"Bad-tibira","ty":"human settlement|archaeological site","u":0,"b":"Bad-tibira (also Patibira) (Sumerian: 𒂦𒁾𒉄𒆠, bad3-tibiraki) was an ancient Sumerian city dating back to the Early Dynastic period, which appears among antediluvian cities in the Sumerian King List. In the earliest days of Akkadian language studies its name was mistakenly read as Dûr-gurgurri."},{"n":"Seuthopolis","lat":42.6181,"lon":25.3056,"s":25,"w":"Seuthopolis","ty":"archaeological site|ancient city|polis","u":0,"b":"Seuthopolis was an ancient Hellenistic city founded by the Thracian king Seuthes III between 325–315 BC which was the capital of the Odrysian kingdom. Its ruins are now located at the bottom of the Koprinka Reservoir near Kazanlak, Stara Zagora Province, in central Bulgaria."},{"n":"Tell Leilan","lat":36.9572,"lon":41.5053,"s":25,"w":"Tell Leilan","ty":"village|tell|archaeological site","u":0,"b":"Tell Leilan (Shekhna) is an archaeological site situated near the Wadi Jarrah in the Khabur River basin in Al-Hasakah Governorate, northeastern Syria. The site has been occupied since the 5th millennium BC. During the late third millennium, the site was known as Shekhna. During that time it was under control of the Akkadian Empire and was used as an administrative center."},{"n":"Tell Halaf","lat":36.8268,"lon":40.0397,"s":25,"w":"Tell Halaf","ty":"tell|archaeological site|type site","u":0,"b":"Tell Halaf (Arabic: تل حلف) is an archaeological site in Al-Hasakah in northeastern Syria, a few kilometers from the city of Ras al-Ayn near the Syria–Turkey border. The site, which dates to the sixth millennium BCE, was the first to be excavated from a Neolithic culture, later called the Halaf culture, characterized by glazed pottery painted with geometric and animal designs."},{"n":"Holyrood Abbey","lat":55.9532,"lon":-3.1716,"s":25,"w":"Holyrood Abbey","ty":"ruins|monastery ruins","u":0,"b":"Holyrood Abbey is a ruined abbey of the Canons Regular in Edinburgh, Scotland. The abbey was founded in 1128 by David I of Scotland. During the 15th century, the abbey guesthouse was developed into a royal residence, and after the Scottish Reformation the Palace of Holyroodhouse was expanded further."},{"n":"Justiniana Prima","lat":42.952,"lon":21.67,"s":24,"w":"Justiniana Prima","ty":"ancient city|archaeological site","u":0,"b":"Justiniana Prima was an Eastern Roman city that existed from 535 to 615 CE, near modern Lebane in the Leskovac region, Serbia. It is currently an archaeological site."},{"n":"Dilbat","lat":32.15,"lon":44.5,"s":24,"w":"Dilbat","ty":"human settlement|archaeological site","u":0,"b":"Dilbat (modern Tell ed-Duleim or Tell al-Deylam) was an ancient Near Eastern city located 25 kilometers south of Babylon on the eastern bank of the Western Euphrates in modern-day Babil Governorate, Iraq. It lies 15 kilometers southeast of the ancient city of Borsippa. The site of Tell Muhattat (also Tell Mukhattat), 5 kilometers away, was earlier thought to be Dilbat."},{"n":"Arrapha","lat":35.45,"lon":44.3833,"s":24,"w":"Arrapha","ty":"archaeological site","u":0,"b":"Arrapha or Arrapkha (Akkadian: Arrapḫa; Arabic: أررابخا,عرفة) was an ancient Near Eastern city or kingdom in what today is northeastern Iraq, speculated to be located at city of Kirkuk. In 1948, Arrapha became the name of the residential area in Kirkuk which was built by the North Oil Company as a settlement for its workers."},{"n":"Nevalı Çori","lat":37.5183,"lon":38.6056,"s":24,"w":"Nevalı Çori","ty":"archaeological site","u":0,"b":"Nevalı Çori (Turkish: Nevali Çori, Kurdish: Newala Çorî) was an early Neolithic settlement on the middle Euphrates, in Şanlıurfa Province, Southeastern Anatolia, Turkey. It is dated to the Pre-Pottery Neolithic B period, from 8400 to 8100 BC, and is part of the \"Taş Tepeler\" sites. The site is known for having some of the world's oldest known temples and monumental sculpture."},{"n":"Eanna","lat":31.3222,"lon":45.6361,"s":24,"w":"Eanna","ty":"temple|archaeological site","u":0,"b":"E-anna (Sumerian: 𒂍𒀭𒈾 É-AN.NA, \"House of Heaven\"), also referred to as the Temple of Inanna, was a monumental ancient Sumerian temple complex in Uruk. Considered the \"residence\" of Inanna, it was among the most prominent and influential religious institutions of ancient Mesopotamia."},{"n":"Sestos","lat":40.2167,"lon":26.3833,"s":24,"w":"Sestos","ty":"polis|archaeological site|former settlement|heritage","u":0,"b":"Sestos (Greek: Σηστός, Latin: Sestus) was an ancient city in Thrace. It was located at the Thracian Chersonese peninsula on the European coast of the Hellespont, opposite the ancient city of Abydos, and near the town of Eceabat in Turkey. In Greek mythology, Sestos is presented in the myth of Hero and Leander as the home of Hero."},{"n":"Zeugma","lat":37.0586,"lon":37.8658,"s":24,"w":"Zeugma (Commagene)","ty":"archaeological site|ancient city","u":0,"b":"Zeugma (Ancient Greek: Ζεῦγμα; Syriac: ܙܘܓܡܐ) was an ancient Hellenistic era Greek and then Roman city of Commagene; located in modern Gaziantep Province, Turkey. It was named for the bridge of boats, or zeugma, that crossed the Euphrates at that location. Zeugma Mosaic Museum contains mosaics from the site, and is one of the largest mosaic museums in the world."},{"n":"Lampsacus","lat":40.3439,"lon":26.6836,"s":24,"w":"Lampsacus","ty":"ancient city|polis|archaeological site","u":0,"b":"Lampsacus was an ancient Greek city located in modern day Turkey, situated on the eastern side of the Hellespont in the northern Troad. An inhabitant of Lampsacus was called a Lampsacene. The name has been transmitted in the nearby modern town of Lapseki."},{"n":"Varna Necropolis","lat":43.2131,"lon":27.8644,"s":24,"w":"Varna Necropolis","ty":"archaeological site","u":0,"b":"The Varna Necropolis (Bulgarian: Варненски некропол), or Varna Cemetery, is a burial site in the western industrial zone of Varna, internationally considered one of the key archaeological sites in world prehistory. The oldest gold treasure and jewelry in the world, dating from 4600 BC to 4200 BC, was discovered at the site."},{"n":"Singidunum","lat":44.82,"lon":20.46,"s":23,"w":"Singidunum","ty":"human settlement|archaeological site","u":0,"b":"Singidunum (Serbian: Сингидунум, Singidunum) was an ancient city which later evolved into modern Belgrade, the capital of Serbia. The name is of Celtic origin, going back to the time when the Celtic tribe Scordisci settled the area in the 3rd century BC, following the Gallic invasion of the Balkans."},{"n":"Jemdet Nasr","lat":32.7178,"lon":44.7794,"s":23,"w":"Jemdet Nasr","ty":"tell|type site|archaeological site","u":0,"b":"Jemdet Nasr (Arabic: جمدة نصر) (also Jamdat Nasr and Jemdat Nasr) is a tell or settlement mound in Babil Governorate, Iraq that is best known as the eponymous type site for the Jemdet Nasr period (c. 3100–2900 BC), under an alternate periodization system termed the Uruk III period, and was one of the oldest Sumerian cities."},{"n":"Eboracum","lat":53.9617,"lon":-1.0806,"s":23,"w":"Eboracum","ty":"archaeological site|Roman city|municipium","u":0,"b":"Eboracum was a fort and later a city in the Roman province of Britannia. In its prime it was the largest town in northern Britannia and a provincial capital. The site remained occupied after the decline of the Western Roman Empire and ultimately developed into the present-day city of York, in North Yorkshire, England."},{"n":"Cistern of Philoxenos","lat":41.0075,"lon":28.9744,"s":23,"w":"Cistern of Philoxenos","ty":"ancient Roman cistern","u":0,"b":"The Cistern of Philoxenos (Greek: Κινστέρνα Φιλοξένου), or Binbirdirek Cistern, is a man-made subterranean reservoir in Istanbul, situated between the Forum of Constantine and the Hippodrome of Constantinople in the Sultanahmet district. It has been restored and is now visited as a tourist attraction. The entrance is located at İmran Öktem Sokak 4."},{"n":"Aegospotami","lat":40.3641,"lon":26.6308,"s":22,"w":"Aegospotami","ty":"mythical river|polis|archaeological site","u":0,"b":"Aegospotami (Ancient Greek: Αἰγὸς Ποταμοί, Aigos Potamoi) or Aegospotamos (i.e. Goat Streams) is the ancient Greek name for a small river or rivers issuing into the Hellespont (Modern Turkish Çanakkale Boğazı), northeast of Sestos."},{"n":"Nicopolis ad Istrum","lat":43.2172,"lon":25.6111,"s":22,"w":"Nicopolis ad Istrum","ty":"ancient city|archaeological site","u":0,"b":"Nicopolis ad Istrum (Greek: Νικόπολις ἡ πρὸς Ἴστρον) or Nicopolis ad Iatrum was a Roman and Early Byzantine town. Its ruins are located at the village of Nikyup, 20 km north of Veliko Tarnovo in northern Bulgaria. The town reached its zenith during the reigns of Hadrian, the Antonines and the Severan dynasty."},{"n":"Kussara","lat":39.385,"lon":37.502,"s":22,"w":"Kussara","ty":"Bronze Age settlement|kingdom|city-state|ancient city|historical country","u":0,"b":"Kussara (Kuššar) was a Middle Bronze Age kingdom in Anatolia. The kingdom, though apparently important at one time, is mostly remembered today as the origin of the dynasty that would form the Old Hittite Kingdom."},{"n":"Anah","lat":34.3686,"lon":41.9819,"s":22,"w":"Anah","ty":"human settlement|archaeological site","u":0,"b":"Anah or Ana (Arabic: عانة, romanized: ʿĀna, Syriac: ܐܢܐ), formerly also known as Anna, is an Iraqi town on the Euphrates approximately midway between the Gulf of Alexandretta and the Persian Gulf. Anah lies from west to east on the right bank along a bend of the river just before it turns south towards Hīt."},{"n":"Plovdiv Roman theatre","lat":42.1468,"lon":24.751,"s":22,"w":"Roman theatre of Philippopolis","ty":"Roman theatre","u":0,"b":"The Roman theatre of Philippopolis is one of the world's best-preserved ancient Roman theatres, located in the city center of modern Plovdiv, Bulgaria, once the ancient city of Philippopolis. It was constructed in the 1st century AD, probably during the reign of Domitian. The theatre can host between 5,000 and 7,000 spectators and it is currently in use."},{"n":"Temple of Augustus in Ankara","lat":39.9443,"lon":32.8583,"s":22,"w":"Temple of Augustus and Rome","ty":"temple|archaeological site","u":0,"b":"The Temple of Augustus and Rome is an augusteum located in the Altındağ district of Ankara. It is thought to have been built around 25–20 BC. Besides being one of the most important Roman-period ruins in the city, it is also known for the Monumentum Ancyranum. This is an inscription about the works of Augustus, who was considered the first Roman emperor."},{"n":"Vindolanda","lat":54.9916,"lon":-2.3595,"s":22,"w":"Vindolanda","ty":"castrum|ancient Roman structure|Samian Ware Discovery Site|archaeological site","u":0,"b":"Vindolanda was a Roman auxiliary fort (castrum) just south of Hadrian's Wall in northern England, which it pre-dated. Archaeological excavations of the site show it was under Roman occupation from roughly 85 AD to 370 AD. Located near the modern village of Bardon Mill in Northumberland, it guarded the Stanegate, the Roman road from the River Tyne to the Solway Firth."},{"n":"Opis","lat":33.1815,"lon":44.6991,"s":22,"w":"Opis","ty":"ancient city|archaeological site","u":0,"b":"Opis (Akkadian Upî or Upija/Upiya; Ancient Greek: Ὦπις) was an ancient Near East city near the Tigris, not far from modern Baghdad. The equivalence of Opis and Upi are now usually assumed but not yet proven. Early on it was thought that the ideogram for Upi might refer to Kesh or Akshak."},{"n":"Forum of Constantine","lat":41.009,"lon":28.971,"s":21,"w":"Forum of Constantine","ty":"ancient Roman structure|forum","u":0,"b":"The Forum of Constantine was built at the foundation of Constantinople immediately outside the old city walls of Byzantium. It marked the centre of the new city, and was a central point along the Mese, the main ceremonial road through the city. It was circular and had two monumental gates to the east and west."},{"n":"Bacho Kiro cave","lat":42.9467,"lon":25.4303,"s":21,"w":"Bacho Kiro Cave","ty":"archaeological site|cave|show cave","u":0,"b":"The Bacho Kiro Cave (Bulgarian: пещера \"Бачо Киро\") is situated 5 km (3.1 mi) west of the town Dryanovo, Bulgaria, only 300 m (980 ft) away from the Dryanovo Monastery. It is embedded in the canyons of the Andaka and Dryanovo River."},{"n":"Urkesh","lat":37.0569,"lon":40.9972,"s":21,"w":"Urkesh","ty":"tell","u":0,"b":"Urkesh, also transliterated Urkish (Akkadian: 𒌨𒆧𒆠 UR.KIŠKI, 𒌨𒋙𒀭𒄲𒆠 UR.KEŠ3KI; modern Tell Mozan (also Tall Mozan); Arabic: تل موزان), is a tell, or settlement mound, located in the foothills of the Taurus Mountains in Al-Hasakah Governorate, northeastern Syria."},{"n":"Edirne Palace","lat":41.6911,"lon":26.5557,"s":21,"w":"Edirne Palace","ty":"archaeological site|built structure","u":0,"b":"Edirne Palace (Turkish: Edirne Sarayı), or formerly New Imperial Palace (Ottoman Turkish: Saray-ı Cedid-i Amire), is a former palace of the Ottoman sultans in Edirne (then known in English as Adrianople), built during the era when the city was the capital of the empire. Few of the palace buildings have survived until now, though reconstruction works are underway."},{"n":"Karahan Tepe","lat":37.0916,"lon":39.3027,"s":21,"w":"Karahan Tepe","ty":"tell|archaeological site","u":0,"b":"Karahan Tepe is a Pre-Pottery Neolithic archaeological site in Şanlıurfa, Turkey. The site is in the same geographical region as Göbekli Tepe, and archaeologists have also uncovered T-shaped stelae there and believe that the sites are related."},{"n":"Tarout Island","lat":26.5667,"lon":50.0667,"s":21,"w":"Tarout Island","ty":"island|archaeological site","u":0,"b":"Tarout Island (Arabic: جزيرة تاروت), also spelled Tārūt, is an island in the Persian Gulf in the Qatif Governorate, located in the Eastern Province of Saudi Arabia. Situated about six kilometers off Qatif mainland coast, the island is connected to Qatif City by three causeways."},{"n":"Der","lat":33.1236,"lon":45.9314,"s":21,"w":"Der (Sumer)","ty":"archaeological site|city-state","u":0,"b":"Der or Dēru (Sumerian: 𒌷𒂦𒀭𒆠 uruBAD3.ANki; Akkadian: 𒌷𒂦𒀭𒆠 uruBAD3.ANki or 𒌷𒁲𒂊𒊒(𒆠) urude-e-ru(ki)) was a Sumerian city-state at the site of modern Tell Aqar near al-Badra in Iraq's Wasit Governorate. It was east of the Tigris River on the border between Sumer and Elam."},{"n":"Battle of Torgau","lat":51.5733,"lon":12.9146,"s":20,"w":"Battle of Torgau","ty":"battlefield|battle","u":0,"b":"In the Battle of Torgau on 3 November 1760, King Frederick the Great's Prussian army fought an Austrian army under the command of Field Marshal Leopold Josef Graf Daun. The Prussians won a costly victory in one of the bloodiest battles of the Third Silesian War (part of the Seven Years' War)."},{"n":"Wasit","lat":32.1891,"lon":46.2817,"s":20,"w":"Wasit","ty":"archaeological site","u":0,"b":"Wasit (Arabic: وَاسِط, romanized: Wāsiṭ, Syriac: ‎ܘܐܣܛ) was an early Islamic city in Iraq. It was founded in the 8th century by the Umayyad viceroy of Iraq, al-Hajjaj ibn Yusuf, to serve as the region's seat of power for the Umayyad governor and as the garrison of Umayyad troops to enforce Umayyad rule there."},{"n":"Nova Roma","lat":41.0139,"lon":28.9556,"s":20,"w":"New Rome","ty":"ancient city","u":0,"b":"Constantinople, the modern Istanbul, was the capital of the Roman Empire and Byzantine Empire from 330 until its takeover by the Ottoman Empire in 1453. After this, it continued to function as the Ottoman capital until the abolition of the Ottoman sultanate in 1922."},{"n":"Balawat","lat":36.2167,"lon":43.4167,"s":20,"w":"Balawat","ty":"human settlement|archaeological site","u":0,"b":"Balawat (Classical Syriac: ܒܝܬ ܠܒܬ, beṯ labat) is an archaeological site of the ancient Assyrian city of Imgur-Enlil, and modern village in Nineveh Province (Iraq). It lies 25 kilometres (16 mi) southeast from the city of Mosul and 4 kilometres (2.5 mi) to the south of the modern Assyrian town of Bakhdida."},{"n":"Pessinus","lat":39.3339,"lon":31.5844,"s":20,"w":"Pessinus","ty":"ancient city|archaeological site","u":0,"b":"Pessinus (Greek: Πεσσινούς or Πισσινούς) was an ancient city and archbishopric in Asia Minor, a geographical area roughly covering modern Anatolia (Asian Turkey). The site of the city is now the modern Turkish village of Ballıhisar, in a tributary valley of the Sakarya River on the high Anatolian plateau at ca. 950 m above sea level, 13 km from the small town of Sivrihisar."},{"n":"Kutha","lat":32.76,"lon":44.6129,"s":20,"w":"Kutha","ty":"tell|city|archaeological site","u":0,"b":"Kutha, Cuthah, Cuth,Cutha, or Gudua (Arabic: كُوثَا, Sumerian: 𒄘𒂃𒀀𒆠 Gû.du8.aki, Akkadian: Kûtu), modern Tell Ibrahim (also Tell Habl Ibrahlm) (Arabic: تَلّ إِبْرَاهِيم), is an archaeological site in Babil Governorate, Iraq. The site of Tell Uqair (possibly ancient Urum) is just to the north. The city was occupied from the Akkadian period until the Hellenistic period."},{"n":"Prague Castle","lat":50.09,"lon":14.4,"s":66,"w":"Prague Castle","ty":"castle|hillfort|château","u":0,"b":"Prague Castle (Czech: Pražský hrad;) is a castle complex in Prague, Czech Republic serving as the official residence and workplace of the president of the Czech Republic. Built in the 9th century, the castle has long served as the seat of power for kings of Bohemia, Holy Roman emperors, and presidents of Czechoslovakia."},{"n":"Edinburgh Castle","lat":55.9487,"lon":-3.2007,"s":58,"w":"Edinburgh Castle","ty":"castle|building complex|museum|archaeological site|château","u":0,"b":"Edinburgh Castle (Scottish Gaelic: Caisteal Dhùn Èideann) is a historic castle in Edinburgh, Scotland. It stands on Castle Rock, which has been occupied by humans since at least the Iron Age. There has been a royal castle on the rock since the reign of Malcolm III in the 11th century, and the castle continued to be a royal residence until 1633."},{"n":"Wartburg","lat":50.9661,"lon":10.3064,"s":58,"w":"Wartburg","ty":"castle|building|museum","u":1,"b":"The Wartburg is a castle originally built in the Middle Ages. At an elevation of 410 metres (1,350 ft) in the state of Thuringia, Germany, it is situated on a southwest-facing precipice and overlooks the town of Eisenach to the north. It was the home of St."},{"n":"Hofburg Palace","lat":48.2064,"lon":16.3653,"s":55,"w":"Hofburg","ty":"château|tourist destination|official residence|palace|museum|castle","u":0,"b":"The Hofburg is the former principal imperial palace of the Habsburg dynasty in Austria. Located in the center of Vienna, it was built in the 13th century by Ottokar II of Bohemia and expanded several times afterwards. It also served as the imperial winter residence, as Schönbrunn Palace was the summer residence."},{"n":"Karlštejn Castle","lat":49.9395,"lon":14.1879,"s":50,"w":"Karlštejn","ty":"castle","u":0,"b":"Karlštejn Castle (Czech: hrad Karlštejn; German: Burg Karlstein) is a large Gothic castle in Czechia, founded in 1348 by King Charles IV. It served as a place for safekeeping the Imperial Regalia as well as the Bohemian crown jewels, holy relics, and other royal treasures. Karlštejn is among the most famous and most frequently visited castles in the country."},{"n":"Bran Castle","lat":45.515,"lon":25.3671,"s":50,"w":"Bran Castle","ty":"castle","u":0,"b":"Bran Castle is a castle in Bran, 25 kilometres (16 mi) southwest of Brașov. The castle was built by Saxons in 1377 who were given the privilege by Louis I of Hungary. It is a national monument and landmark in Transylvania."},{"n":"Buda Castle","lat":47.4961,"lon":19.0397,"s":48,"w":"Buda Castle","ty":"castle|palace","u":1,"b":"Buda Castle (Hungarian: Budavári Palota, German: Burgpalast), formerly also called the Royal Palace (Hungarian: Királyi-palota) and the Royal Castle (Hungarian: Királyi Vár, German: Königliche Burg), is the historical castle and palace complex of the Hungarian kings in Budapest."},{"n":"Spiš Castle","lat":49.0006,"lon":20.7683,"s":48,"w":"Spiš Castle","ty":"castle ruin","u":1,"b":"The ruins of Spiš Castle in eastern Slovakia form one of the six largest castle sites in Slovakia. The castle is situated above the town of Spišské Podhradie and the village of Žehra, in the region known as Spiš. It was included in the UNESCO list of World Heritage Sites in 1993."},{"n":"Bratislava Castle","lat":48.1422,"lon":17.1,"s":47,"w":"Bratislava Castle","ty":"building complex|castle","u":0,"b":"Bratislava Castle is the main castle of Bratislava, the capital of Slovakia. The massive rectangular building with four corner towers stands on an isolated rocky hill of the Little Carpathians, directly above the Danube river, in the middle of Bratislava. Because of its size and location, it has been a dominant feature of the city for centuries."},{"n":"Stirling Castle","lat":56.1239,"lon":-3.9478,"s":43,"w":"Stirling Castle","ty":"castle","u":0,"b":"Stirling Castle (Scottish Gaelic: Caisteal Shruighlea), located in Stirling, is one of the largest and most historically and architecturally important castles in Scotland. The castle sits atop an intrusive crag, which forms part of the Stirling Sill geological formation. It is surrounded on three sides by steep cliffs, giving it a strong defensive position."},{"n":"Konopiště Castle","lat":49.7794,"lon":14.6567,"s":35,"w":"Konopiště Castle","ty":"castle|château","u":0,"b":"Konopiště Castle is a four-winged, three-storey castle located in Konopiště, now a part of the town of Benešov in Central Bohemian Region, Czech Republic. It has become famous as the last residence of Archduke Franz Ferdinand of Austria, heir to the Austro-Hungarian throne, whose assassination in Sarajevo triggered World War I."},{"n":"Kroměříž Castle","lat":49.3003,"lon":17.3931,"s":35,"w":"Kroměříž Castle","ty":"castle|château|palace","u":1,"b":"Kroměříž Castle is a castle in Kroměříž in the Czech Republic. It used to be the principal residence of the bishops and (from 1777) archbishops of Olomouc. UNESCO listed the gardens and castle as a World Heritage Site in 1998 because of its exceptionally well-preserved and outstanding Baroque gardens."},{"n":"Corvin Castle","lat":45.7491,"lon":22.8883,"s":35,"w":"Corvin Castle","ty":"castle","u":0,"b":"Corvin Castle, also known as Hunyadi Castle or Hunedoara Castle, is a Gothic-Renaissance castle in Hunedoara, current-day Romania. It is considered one of the largest castles in Europe and is one of the Seven Wonders of Romania."},{"n":"Devín Castle","lat":48.1739,"lon":16.9781,"s":34,"w":"Devín Castle","ty":"castle","u":0,"b":"Devín Castle is a castle in Devín, which is a borough of Bratislava, the capital of Slovakia."},{"n":"Książ Castle and park complex","lat":50.8422,"lon":16.2917,"s":34,"w":"Książ Castle","ty":"castle|architectural heritage monument","u":0,"b":"Książ Castle is a castle in northern Wałbrzych in Lower Silesian Voivodeship, Poland. The largest castle in the region of Silesia, it is the third-largest in Poland behind Malbork Castle and Wawel Castle. It lies within Książ Landscape Park, a protected area located in the Sudeten Mountains and Sudeten Foreland."},{"n":"Rumeli Hisarı","lat":41.0847,"lon":29.0561,"s":34,"w":"Rumelihisarı","ty":"castle|museum","u":0,"b":"Rumelihisarı or Boğazkesen Fortress (literally 'strait-cutter fortress') is a medieval Ottoman fortress located in Istanbul, Turkey, on a series of hills on the European banks of the Bosphorus. The fortress also lends its name to the immediate neighborhood around it in the city's Sarıyer district."},{"n":"Egeskov Castle","lat":55.1764,"lon":10.4894,"s":33,"w":"Egeskov Castle","ty":"castle|museum","u":0,"b":"Egeskov Castle (Danish: Egeskov Slot) is located near Kværndrup, in the south of the island of Funen, Denmark. The castle is Denmark’s best preserved Renaissance water castle."},{"n":"Nuremberg Castle","lat":49.4579,"lon":11.0759,"s":33,"w":"Nuremberg Castle","ty":"castle","u":0,"b":"Nuremberg Castle (German: Nürnberger Burg) is a group of medieval fortified buildings on a sandstone ridge dominating the historical center of Nuremberg in Bavaria, Germany. The castle, together with the city walls, is considered to be one of Europe's most formidable medieval fortifications."},{"n":"Liechtenstein Castle","lat":48.0927,"lon":16.2704,"s":32,"w":"Liechtenstein Castle (Maria Enzersdorf)","ty":"castle|museum","u":0,"b":"Liechtenstein Castle (German: Burg Liechtenstein) is a castle near Maria Enzersdorf in Lower Austria, bordering Vienna. It is on the edge of the Wienerwald (Vienna Woods). Liechtenstein (German for \"bright stone\") Castle is the eponymous ancestral seat and place of origin of the House of Liechtenstein, the ruling family of the Principality of Liechtenstein."},{"n":"Dunnottar Castle","lat":56.9457,"lon":-2.1968,"s":29,"w":"Dunnottar Castle","ty":"promontory fort|rock castle|castle","u":0,"b":"Dunnottar Castle is a ruined medieval fortress located upon a rocky headland on the northeast coast of Scotland, about 2 miles (3 kilometres) south of Stonehaven in Aberdeenshire. The surviving buildings are largely of the 15th and 16th centuries, but the site is believed to have been fortified in the Early Middle Ages."},{"n":"Český Krumlov Castle","lat":48.8125,"lon":14.3153,"s":29,"w":"Český Krumlov Castle","ty":"castle|château","u":0,"b":"Český Krumlov Castle (Czech: Hrad Český Krumlov) is a castle in Český Krumlov in the South Bohemian Region of the Czech Republic. It dates back to 1253 when the first castle was built by the Vítkovci family, the main branch of the powerful Bohemian family Rosenberg."},{"n":"Linlithgow Palace","lat":55.9785,"lon":-3.601,"s":29,"w":"Linlithgow Palace","ty":"castle","u":0,"b":"The ruins of Linlithgow Palace are located in the town of Linlithgow, West Lothian, Scotland, 15 miles (24 km) west of Edinburgh. The palace was one of the principal residences of the monarchs of Scotland in the 15th and 16th centuries. Although maintained after Scotland's monarchs left for England in 1603, the palace was little used, and was burned out in 1746."},{"n":"Moritzburg Castle","lat":51.1676,"lon":13.6796,"s":29,"w":"Moritzburg Castle","ty":"museum|castle|château","u":0,"b":"Moritzburg Castle (German: Schloss Moritzburg) or Moritzburg Palace is a Baroque palace in Moritzburg, in the German state of Saxony, about 13 kilometres (8.1 mi) northwest of the Saxon capital, Dresden. The castle has four round towers and lies on a symmetrical artificial island. It is named after Duke Moritz of Saxony, who had a hunting lodge built there between 1542 and 1546."},{"n":"Bamburgh Castle","lat":55.6094,"lon":-1.711,"s":29,"w":"Bamburgh Castle","ty":"historic house museum|castle","u":0,"b":"Bamburgh Castle, on the northeast coast of England, by the village of Bamburgh in Northumberland, is a Grade I listed building. The site was originally the location of a Celtic Brittonic fort known as Din Guarie and may have been the capital of the kingdom of Bernicia from its foundation c. 420 to 547."},{"n":"Smederevo Fortress","lat":44.6686,"lon":20.9292,"s":28,"w":"Smederevo Fortress","ty":"castle|fortress","u":0,"b":"The Smederevo Fortress (Serbian: Cмeдepeвcκa твpђaвa / Smederevska tvrđava) is a medieval fortified city in Smederevo, Serbia, which was the temporary capital of Serbia in the Middle Ages. It was built between 1427 and 1430 on the order of Despot Đurađ Branković, the ruler of the Serbian Despotate. It was further fortified by the Ottoman Empire, which had taken the city in 1459."},{"n":"Urquhart Castle","lat":57.324,"lon":-4.442,"s":27,"w":"Urquhart Castle","ty":"destroyed building or structure|archaeological site|ruins|castle","u":0,"b":"Urquhart Castle is a ruined castle that sits beside Loch Ness in the Highlands of Scotland. The castle is on the A82 road, 21 kilometres (13 mi) southwest of Inverness and two kilometres (1+1⁄4 miles) east of Drumnadrochit. It is a scheduled monument and is one of the most-visited castles in Scotland, receiving 466,420 visitors in 2025."},{"n":"Glamis Castle","lat":56.6203,"lon":-3.0024,"s":27,"w":"Glamis Castle","ty":"country house|castle|historic house museum","u":0,"b":"Glamis Castle is situated beside the village of Glamis in Angus, Scotland. It is the home of the Earl of Strathmore and Kinghorne, and is open to the public. Glamis Castle has been the home of the Lyon family since the 14th century, though the present building dates largely from the 17th century."},{"n":"Alnwick Castle","lat":55.4158,"lon":-1.7061,"s":27,"w":"Alnwick Castle","ty":"castle|historic house museum","u":0,"b":"Alnwick Castle is a castle and country house in Alnwick in the English county of Northumberland. It is the seat of the 12th Duke of Northumberland, built following the Norman Conquest and renovated and remodelled several times. It is a Grade I listed building now the home of Ralph Percy, 12th Duke of Northumberland and his family."},{"n":"Špilberk Castle","lat":49.1944,"lon":16.5989,"s":27,"w":"Špilberk Castle","ty":"castle|fortress","u":0,"b":"Špilberk Castle (Czech: hrad Špilberk; German: Spielberg, locally Špilas) is a castle on the hilltop in Brno, Southern Moravia. Its construction began as early as the first half of the 13th century by the Přemyslid kings and completed by King Ottokar II of Bohemia."},{"n":"Trenčín Castle","lat":48.8942,"lon":18.0447,"s":27,"w":"Trenčín Castle","ty":"castle","u":0,"b":"The Trenčín Castle is a castle above the town of Trenčín in western Slovakia."},{"n":"Čachtice Castle","lat":48.7247,"lon":17.7608,"s":26,"w":"Čachtice Castle","ty":"castle ruin","u":0,"b":"Čachtice Castle or Castle of Csejte is a castle ruin in Slovakia next to the village of Čachtice. It stands on a hill featuring rare plants, and has been declared a national nature reserve for this reason. The castle was a residence and later the prison of the Countess and alleged serial killer Elizabeth Báthory in the Kingdom of Hungary."},{"n":"Orava Castle","lat":49.2617,"lon":19.3581,"s":26,"w":"Orava Castle","ty":"castle","u":0,"b":"Orava Castle (Slovak: Oravský hrad, Hungarian: Árva vára) is a castle situated on a high rock above Orava river in the village of Oravský Podzámok, Slovakia. The castle was built in the Kingdom of Hungary, with the oldest parts being built in the thirteenth century and the most recent parts in the early seventeenth century."},{"n":"Dumbarton Castle","lat":55.936,"lon":-4.5628,"s":26,"w":"Dumbarton Castle","ty":"contour fort|castle","u":0,"b":"Dumbarton Castle has the longest recorded history of any stronghold in Scotland. It sits on a volcanic plug of basalt known as Dumbarton Rock which is 240 feet (73 m) high and overlooks the Scottish town of Dumbarton."},{"n":"Glücksburg Castle","lat":54.8317,"lon":9.5436,"s":26,"w":"Glücksburg Castle","ty":"museum|château|water castle","u":0,"b":"Glücksburg Castle (German: Schloss Glücksburg, Danish: Lyksborg Slot) is one of the most significant Renaissance castles in Northern Europe. The castle was the headquarters of the ducal lines of the house of Glücksburg and temporarily served as the primary residence of the Danish monarch."},{"n":"Königstein Fortress","lat":50.9191,"lon":14.0581,"s":25,"w":"Königstein Fortress","ty":"rock castle|fortress","u":0,"b":"Königstein Fortress (German: Festung Königstein), the \"Saxon Bastille\", is a hilltop fortress near Dresden, in Saxon Switzerland, Germany, above the town of Königstein on the left bank of the River Elbe. It is one of the largest hilltop fortifications in Europe and sits atop the table hill of the same name."},{"n":"Vajdahunyad Castle","lat":47.5153,"lon":19.0819,"s":25,"w":"Vajdahunyad Castle","ty":"castle","u":0,"b":"Vajdahunyad Castle (Hungarian: Vajdahunyad vára) is a castle in the City Park of Budapest, Hungary."},{"n":"Wewelsburg","lat":51.6068,"lon":8.6514,"s":25,"w":"Wewelsburg","ty":"hill castle|Schloss|fort|military museum","u":0,"b":"Wewelsburg is a Renaissance castle located in the village of Wewelsburg, which is a district of the town of Büren, Westphalia, in the Landkreis of Paderborn in the northeast of North Rhine-Westphalia, Germany. The castle has a triangular layout, with three round towers connected by massive walls."},{"n":"Gaziantep Castle","lat":37.0664,"lon":37.3833,"s":24,"w":"Gaziantep Castle","ty":"archaeological site|castle","u":0,"b":"Gaziantep Castle (Turkish: Gaziantep Kalesi) is a castle on top of a mound in the centre of Gaziantep, Turkey. First used as an observation point during the Hittite Empire, it was expanded into a castle during Roman rule. The castle was severely damaged by earthquakes in February 2023."},{"n":"Schloss Esterházy","lat":47.8465,"lon":16.5193,"s":24,"w":"Schloss Esterházy","ty":"castle|château|museum","u":0,"b":"Schloss Esterházy (Hungarian: Esterházy-kastély) is a palace in Eisenstadt, Austria, the capital of the Burgenland state. It was constructed in the late 13th century, and came under ownership of the Hungarian Esterházy family in 1622."},{"n":"HMS Repulse","lat":55.8978,"lon":-4.4044,"s":29,"w":"HMS Repulse (1916)","ty":"battlecruiser|shipwreck","u":0,"b":"HMS Repulse was one of two Renown-class battlecruisers built for the Royal Navy during the First World War. Originally laid down as an improved version of the Revenge-class battleship, her construction was suspended on the outbreak of war because she would not be ready in time."},{"n":"HMS Nelson","lat":57.8113,"lon":-5.6419,"s":24,"w":"HMS Nelson (28)","ty":"shipwreck|battleship","u":0,"b":"HMS Nelson (pennant number: 28) was the name ship of her class of two battleships built for the Royal Navy in the 1920s. They were the first battleships built to meet the limitations of the Washington Naval Treaty of 1922. Entering service in 1927, the ship spent her peacetime career with the Atlantic and Home Fleets, usually as the fleet flagship."},{"n":"RMS Empress of Ireland","lat":48.625,"lon":-68.4083,"s":23,"w":"RMS Empress of Ireland","ty":"steamship|transatlantic liner|sunken vessel|shipwreck|passenger vessel","u":0,"b":"RMS Empress of Ireland was a British-built ocean liner that sank near the mouth of the Saint Lawrence River in Canada following a collision in thick fog with the Norwegian collier Storstad in the early hours of 29 May 1914, en route to Liverpool."},{"n":"SMS Lützow","lat":56.25,"lon":5.8833,"s":21,"w":"SMS Lützow","ty":"shipwreck|battlecruiser","u":0,"b":"SMS Lützow was the second Derfflinger-class battlecruiser built by the German Kaiserliche Marine (Imperial Navy) before World War I. Ordered as a replacement for the old protected cruiser Kaiserin Augusta, Lützow was launched on 29 November 1913, but not completed until 1916."},{"n":"SMS Pommern","lat":55.737,"lon":6.6156,"s":19,"w":"SMS Pommern","ty":"pre-dreadnought battleship|shipwreck","u":0,"b":"SMS Pommern was one of five Deutschland-class pre-dreadnought battleships built for the German Kaiserliche Marine (Imperial Navy) between 1904 and 1906. Named after the Prussian province of Pomerania, she was built at the AG Vulcan yard at Stettin, Germany (now Szczecin, Poland), where she was laid down on 22 March 1904 and launched on 2 December 1905."},{"n":"U-1","lat":54.2333,"lon":5.1167,"s":18,"w":"German submarine U-1 (1935)","ty":"shipwreck|submarine","u":0,"b":"German submarine U-1 was the first U-boat (or submarine) built for Nazi Germany's Kriegsmarine following Adolf Hitler's abrogation of the terms of the Treaty of Versailles in 1935, which banned Germany possessing a submarine force. A Type IIA U-boat, she was built at the Deutsche Werke shipyards in Kiel, yard number 236, her keel being laid on 11 February 1935 amid celebration."},{"n":"HMS Audacious","lat":55.5378,"lon":-7.4092,"s":17,"w":"HMS Audacious (1912)","ty":"dreadnought|shipwreck","u":0,"b":"HMS Audacious was the fourth and last King George V-class dreadnought battleship built for the Royal Navy in the early 1910s. After completion in 1913, she spent her brief 2-year career assigned to the Home and Grand Fleets. The ship struck a German naval mine off the northern coast of County Donegal in Ulster, Ireland, in the early days of the First World War."},{"n":"HMS Irresistible","lat":40.0333,"lon":26.3166,"s":17,"w":"HMS Irresistible (1898)","ty":"pre-dreadnought battleship|shipwreck","u":0,"b":"HMS Irresistible—the fourth British Royal Navy ship of the name—was a Formidable-class pre-dreadnought battleship."},{"n":"U-1206","lat":57.3041,"lon":-1.6637,"s":17,"w":"German submarine U-1206","ty":"U-boat|shipwreck","u":0,"b":"German submarine U-1206 was a Type VIIC U-boat of Nazi Germany's Kriegsmarine during World War II. She was laid down on 12 June 1943 at F. Schichau GmbH in Danzig and went into service on 16 March 1944. The submarine was scuttled on 14 April 1945 after being attacked by British forces after she was forced to the surface by problems arising from a malfunctioning plumbing system."},{"n":"U-8","lat":53.5167,"lon":8.1667,"s":15,"w":"German submarine U-8 (1935)","ty":"shipwreck|submarine","u":0,"b":"The German submarine U-8 was a Type IIB U-boat of Nazi Germany's Kriegsmarine, based at Kiel during World War II. It was one of the smaller versions, and was first launched on 16 July 1935. Its first commander was Harald Grosse. U-8 would have 18 commanders over the course of its service, the last being Jürgen Kriegshammer."},{"n":"Mount Erciyes","lat":38.5317,"lon":35.45,"s":49,"w":"Mount Erciyes","ty":"volcano|stratovolcano|mountain","u":0,"b":"Mount Erciyes (Turkish: Erciyes Dağı) is an inactive volcano in Kayseri Province, Turkey. It is a large stratovolcano surrounded by many monogenetic vents and lava domes, and one maar. The bulk of the volcano is formed by lava flows of andesitic and dacitic composition."},{"n":"Mount Hasan","lat":38.1265,"lon":34.1651,"s":37,"w":"Mount Hasan","ty":"stratovolcano|mountain|volcano","u":0,"b":"Mount Hasan (Turkish: Hasan Dağı) is a volcano in Anatolia, Turkey. It has two summits, the 3,069 metres (10,069 ft) high eastern Small Hasandağ and the 3,253 metres (10,673 ft) high Big Hasandağ, and rises about 1 kilometre (0.62 mi) above the surrounding terrain."},{"n":"Vogelsberg","lat":50.5333,"lon":9.2333,"s":37,"w":"Vogelsberg","ty":"mountain range|shield volcano|low mountain range","u":0,"b":"The Vogelsberg is a large volcanic mountain range in the German Central Uplands in the state of Hesse, separated from the Rhön Mountains by the Fulda river valley. Emerging approximately 19 million years ago, the Vogelsberg is Central Europe's largest basalt formation, consisting of a multitude of layers that descend from their peak in ring-shaped terraces to the base."},{"n":"Nemrut","lat":38.6226,"lon":42.2467,"s":33,"w":"Nemrut (volcano)","ty":"dormant volcano|mountain","u":0,"b":"Nemrut is a dormant volcano in Tatvan district, Bitlis province, Eastern Turkey, close to Lake Van. The volcano is named after King Nimrod who is said to have ruled this area in about 2100 BC. There is Lake Nemrut in the crater of the mountain. The most powerful eruptions of Nemrut occurred in the Pleistocene."},{"n":"Mount Süphan","lat":38.9298,"lon":42.8296,"s":30,"w":"Mount Süphan","ty":"volcano|mountain|stratovolcano","u":0,"b":"Mount Süphan is a stratovolcano located in eastern Turkey, immediately north of Lake Van. It is the second highest volcano in Turkey, with an elevation of 4,058 metres (13,314 feet), and has the third highest prominence of the Armenian Highlands, after Mount Ararat (5,137 m) and Mount Aragats (4,090 m)."},{"n":"Říp Mountain","lat":50.3865,"lon":14.2896,"s":22,"w":"Říp","ty":"mountain|extinct volcano","u":0,"b":"Říp (IPA:; German: Georgsberg) is a 461 metres (1,512 ft) high solitary hill in the Lower Ohře Table in the Czech Republic. It is located 20 km (12 mi) southeast of Litoměřice. According to national legend, it is the place where the first Czechs settled."},{"n":"Karaca Dağ","lat":37.7114,"lon":39.829,"s":21,"w":"Karaca Dağ","ty":"shield volcano","u":0,"b":"Karaca Dağ Qerejdax is a shield volcano located in southeastern Turkey, near amed (Diyarbakır.) It was also known as \"Mount Masia\", which in turn was used to give the title of an iris found on the mountain, as Iris masia."},{"n":"Milešovka","lat":50.5549,"lon":13.9311,"s":11,"w":"Milešovka","ty":"mountain|extinct volcano","u":0,"b":"Milešovka is the highest mountain of the Central Bohemian Uplands in the Czech Republic. It has an altitude of 837 m (2,746 ft). The height difference between the foot and summit is 300 metres."},{"n":"Hoher Hagen","lat":51.4752,"lon":9.7646,"s":11,"w":"Hoher Hagen (Dransfeld)","ty":"mountain|volcano","u":0,"b":"The Hoher Hagen is a volcanic hill that is still 480 m high today, in the Dransfeld Municipal Forest, in the German district of Göttingen in South Lower Saxony."},{"n":"Bořeň","lat":50.5277,"lon":13.7639,"s":10,"w":"Bořeň","ty":"extinct volcano|mountain","u":0,"b":"Bořeň (German: Borschen) is a phonolite hill in the Central Bohemian Uplands in the Czech Republic. It has an elevation of 539 m (1,768 ft) and is located in the territory of Bílina in the Ústí nad Labem Region. When seen from the northwest side, the hill has the shape of a lying lion."},{"n":"Červená hora","lat":49.7767,"lon":17.5411,"s":8,"w":"Červená hora (Nízký Jeseník)","ty":"mountain|extinct volcano","u":0,"b":"Červená hora (meaning 'red mountain') is a mountain in the Nízký Jeseník range in the Moravian-Silesian Region of the Czech Republic. It is located in the territory of Budišov nad Budišovkou. With 749 metres (2,457 ft) above sea level it is the highest hill of the Domašov Highlands, which are a part of the Nízký Jeseník, and the highest point in the Opava District."},{"n":"Zuidwal volcano","lat":53.2126,"lon":5.1776,"s":8,"w":"Zuidwal volcano","ty":"stratovolcano","u":0,"b":"The Zuidwal volcano is an extinct volcano in the Netherlands at more than 2 km (6,600 ft) below ground under the Wadden Sea, between Harlingen and Vlieland, just south west of the island Griend."},{"n":"Tatra National Park","lat":49.1803,"lon":19.9194,"s":43,"w":"Tatra National Park, Slovakia","ty":"national park|protected area","u":0,"b":"Tatra(s) National Park (Slovak: Tatranský národný park; abbr. TANAP) is one of the nine national parks in Slovakia. It is situated in North Central Slovakia in the Tatra Mountains."},{"n":"Slovak Paradise National Park","lat":48.9083,"lon":20.4,"s":36,"w":"Slovak Paradise National Park","ty":"protected area|national park","u":0,"b":"Slovak Paradise National Park (Slovak: Národný park Slovenský raj) is one of the nine national parks in Slovakia, situated in East Slovakia. The National Park protects the area of the Slovak Paradise mountain range, which is located in the north of the Slovenské rudohorie Mountains (Slovak Ore Mountains)."},{"n":"Retezat National Park","lat":45.3333,"lon":22.8333,"s":34,"w":"Retezat National Park","ty":"biosphere reserve|national park|protected area","u":0,"b":"The Retezat National Park (Romanian: Parcul Național Retezat) is a protected area located in the Retezat Mountains in Hunedoara County, Romania. Founded in 1935, it is the oldest national park in the country and categorized as a category II IUCN national park. Retezat is particularly notable for its biodiverse flora, with over 1,000 species of plants present within the park."},{"n":"Shenandoah National Park","lat":38.5333,"lon":-78.35,"s":34,"w":"Shenandoah National Park","ty":"National Park of the United States|national park","u":0,"b":"Shenandoah National Park is a national park of the United States that encompasses part of the Blue Ridge Mountains in Virginia. The park is long and narrow, with the Shenandoah River and its broad valley to the west, and the rolling hills of the Virginia Piedmont to the east. Skyline Drive is the main park road, generally traversing along the ridgeline of the mountains."},{"n":"Đerdap National Park","lat":44.6667,"lon":22.5167,"s":32,"w":"Đerdap National Park","ty":"riverscape|national park|geopark","u":0,"b":"Đerdap National Park (Serbian: Национални парк Ђердап / Nacionalni park Đerdap) stretches along the right bank of the Danube River from the Golubac Fortress (Serbian: Голубачки град / Golubački grad) to the dam near Novi Sip, Serbia. It was established in 1974 and spreads on 63,786.5 ha (157,620 acres). The park management office is in the town of Donji Milanovac on the Danube."},{"n":"Cairngorms National Park","lat":57.0833,"lon":-3.6667,"s":32,"w":"Cairngorms National Park","ty":"national park","u":0,"b":"Cairngorms National Park (Scottish Gaelic: Pàirc Nàiseanta a' Mhonaidh Ruaidh) is a national park in northeast Scotland, established in 2003. It was the second of two national parks established by the Scottish Parliament, after Loch Lomond and The Trossachs National Park, which was set up in 2002. The park covers the Cairngorms range of mountains, and surrounding hills."},{"n":"Low Tatras National Park","lat":48.9256,"lon":19.6325,"s":31,"w":"Low Tatras National Park","ty":"national park|protected area","u":0,"b":"Low Tatras National Park (Slovak: Národný park Nízke Tatry; abbr. NAPANT) is a national park in Central Slovakia, between the Váh River and the Hron River valleys. The park and its buffer zone cover the whole Low Tatras mountain range."},{"n":"Šumava National Park","lat":49.0606,"lon":13.4825,"s":31,"w":"Šumava National Park","ty":"national park|protected area","u":0,"b":"The Šumava National Park, or Bohemian Forest National Park, is a national park in the South Bohemian regions of the Czech Republic along the border with Germany and Austria. They protect a little-inhabited area of the mountain range of the same name, the Šumava or Bohemian Forest."},{"n":"Podyjí National Park","lat":48.8478,"lon":15.8972,"s":28,"w":"Podyjí National Park","ty":"national park|protected area","u":0,"b":"Podyjí National Park (Czech: Národní park Podyjí) is a national park in the South Moravian Region of the Czech Republic. Adjacent to Austria's Thayatal National Park on the border, together they are referred to as the Inter-National park. Podyjí is one of the Czech Republic's four national parks."},{"n":"Gesäuse National Park","lat":47.5922,"lon":14.6489,"s":27,"w":"Gesäuse National Park","ty":"national park","u":0,"b":"Gesäuse National Park is a national park in the Austrian state of Styria. Located in the mountainous Upper Styrian region, it covers large parts of the Gesäuse range within the Ennstal Alps and the steep water gap of the Enns river between Admont and Hieflau. The area also covers parts of the municipal areas of Johnsbach, Weng, Landl, and Sankt Gallen."},{"n":"Saxon Switzerland National Park","lat":50.9142,"lon":14.2784,"s":27,"w":"Saxon Switzerland National Park","ty":"national park|Nationalpark|protected area","u":0,"b":"Saxon Switzerland National Park (German: Nationalpark Sächsische Schweiz), is a national park in the German Free State of Saxony, near the Saxon capital Dresden. It covers two areas of 93.5 km2 (36.1 sq mi) in the heart of the German part of the Elbe Sandstone Mountains, which is often called (the) Saxon Switzerland (German: Sächsische Schweiz)."},{"n":"Slovak Karst National Park","lat":48.579,"lon":20.544,"s":26,"w":"Slovak Karst National Park","ty":"protected area|national park","u":0,"b":"Slovak Karst National Park (Národný park Slovenský kras) is a national park in the Slovak Karst (Slovenský kras) mountain range in South East Slovakia. It lies in the Gelnica, Rožňava and Košice–okolie districts in the Košice region. The National Park covers an area of 346.11 km² (133.64 mi²) and its buffer zone covers 117.41 km² (45.33 mi²)."},{"n":"Krkonoše National Park","lat":50.7361,"lon":15.7403,"s":25,"w":"Krkonoše National Park","ty":"protected area|national park","u":0,"b":"Krkonoše National Park (Czech: Krkonošský národní park, abbreviated as KRNAP) is a national park in the Liberec and Hradec Králové regions of the Czech Republic. It covers most of the Giant Mountains (Czech: Krkonoše), which is the highest range of the country. The park has also been listed as a UNESCO Biosphere Reserve site."},{"n":"National Park Thayatal","lat":48.8522,"lon":15.8633,"s":22,"w":"Thayatal National Park","ty":"national park|protected area","u":0,"b":"Thayatal National Park (German: Nationalpark Thayatal) is a 13.3 km2 Austrian national park located in the Lower Austrian border area with the Czech Republic. It connects to the Czech Podyjí National Park. The Thayatal with its steep hillside forests is one of the most beautiful breakthrough valleys in Austria."},{"n":"Cheile Nerei-Beușnița National Park","lat":44.9512,"lon":21.8882,"s":22,"w":"Nera Gorge-Beușnița National Park","ty":"national park|protected area","u":0,"b":"The Nera Gorge-Beușnița National Park (Romanian: Parcul Național Cheile Nerei-Beușnița) (national park category II IUCN) is a protected area situated in Romania, in Caraș-Severin County."},{"n":"Muránska planina National Park","lat":48.7833,"lon":20.0333,"s":22,"w":"Muránska planina National Park","ty":"protected area|national park","u":0,"b":"Muránska planina National Park (Slovak: Národný park Muránska planina) is one of the youngest national parks in Slovakia. The core area measures 21,318 ha and the protective belt 21,698 ha. It includes 14 smaller protected territories."},{"n":"Malá Fatra National Park","lat":49.2139,"lon":19.0808,"s":21,"w":"Malá Fatra National Park","ty":"national park|protected area","u":0,"b":"The Malá Fatra National Park (Slovak: Národný park Malá Fatra) is a national park in the northern part of the Malá Fatra mountains called Krivánska Malá Fatra. It has an area of 226.3 km2 (87.37 mi2) and a 232.62 km2 (89.81 mi2) buffer zone. The park was declared in 1988."},{"n":"Wadden Sea National Park","lat":55.25,"lon":8.4833,"s":19,"w":"Wadden Sea National Park, Denmark","ty":"national park","u":0,"b":"Wadden Sea National Park (Nationalpark Vadehavet) was designated a Danish national park on 17 January 2008, effective 2010."},{"n":"Veľká Fatra National Park","lat":49.0167,"lon":19.1167,"s":19,"w":"Veľká Fatra National Park","ty":"national park|protected area","u":0,"b":"Veľká Fatra National Park (Slovak: Národný park Veľká Fatra) is a National Park in Slovakia. Most of it lies in the southern part of the Žilina Region and a small part in the northern part of Banská Bystrica Region. The national park and its protective zone comprise most of the Greater Fatra Range (Slovak: Veľká Fatra) which belongs to the Outer Western Carpathians."},{"n":"Kouchibouguac National Park","lat":46.8497,"lon":-64.9669,"s":18,"w":"Kouchibouguac National Park","ty":"national park|national park of Canada","u":0,"b":"Kouchibouguac National Park is a national park located on the east coast of New Brunswick in Kouchibouguac and was established in 1969 to preserve a section of the Canadian Maritime Plain region. The park includes barrier islands, sand dunes, lagoons, salt marshes, and forests."},{"n":"Buila-Vânturarița National Park","lat":45.24,"lon":24.096,"s":17,"w":"Buila-Vânturarița National Park","ty":"national park|protected area","u":0,"b":"The Buila-Vânturarița National Park (Romanian: Parcul Național Buila-Vânturarița) (national park category II IUCN) is a protected area situated in Romania, in the central-northern part of Vâlcea County, in the administrative territory of the localities Costești, Bărbătești, and Băile Olănești."},{"n":"Semenic-Cheile Carașului National Park","lat":45.142,"lon":21.977,"s":17,"w":"Semenic-Caraș Gorge National Park","ty":"national park|protected area","u":0,"b":"The Semenic-Caraș Gorge National Park (Romanian: Parcul Național Semenic-Cheile Carașului) is a protected area (national park category II IUCN) situated in southwest Romania, in Caraș-Severin County."},{"n":"Dadia-Lefkimi-Soufli Forest National Park","lat":41.13,"lon":26.2169,"s":16,"w":"Dadia-Lefkimi-Soufli Forest National Park","ty":"national park","u":0,"b":"Dadia-Lefkimi-Soufli Forest National Park is a national park in the region of Eastern Macedonia and Thrace, Greece. The park covers an area of 428 km2 (165 sq mi), of which 72.9 km2 (28.1 sq mi) are under strict protection, and is considered one of the most important protected areas in Europe for biodiversity conservation, particularly for birds of prey."},{"n":"Domogled-Valea Cernei National Park","lat":45.093,"lon":22.624,"s":16,"w":"Domogled-Valea Cernei National Park","ty":"protected area|national park","u":0,"b":"The Domogled-Valea Cernei National Park (Romanian: Parcul Național Domogled-Valea Cernei) is a protected area (national park category II IUCN) situated in Romania, on the administrative territory of counties Caraș-Severin, Gorj, and Mehedinți."},{"n":"Cozia National Park","lat":45.367,"lon":24.265,"s":15,"w":"Cozia National Park","ty":"national park|protected area","u":0,"b":"The Cozia National Park (Romanian: Parcul Național Cozia) (national park category II IUCN) is located in south-central Romania, in the northeast part of Vâlcea County, in the administrative territory of localities Brezoi, Călimănești, Racoviţa, Perișani, Sălătrucel and Berislăvești."},{"n":"Fruška Gora National Park","lat":45.1667,"lon":19.6667,"s":13,"w":"Fruška Gora National Park","ty":"national park","u":0,"b":"Fruška Gora (Serbian Cyrillic: Фрушка гора) is a low mountain range region in Syrmia, with most of the mountain range being part of Serbia and its westernmost edge extending into eastern Croatia. The Serbian part of the mountain range forms the country's oldest national park."},{"n":"Defileul Jiului National Park","lat":45.272,"lon":23.368,"s":12,"w":"Defileul Jiului National Park","ty":"national park|protected area","u":0,"b":"The Defileul Jiului National Park (Romanian: Parcul Național Defileul Jiului) is a protected area (national park category II IUCN) situated in Romania on the administrative territory of counties Gorj (92%) and Hunedoara (8%)."},{"n":"Rodopi Mountain Range National Park","lat":41.477,"lon":24.46,"s":11,"w":"Rodopi Mountain Range National Park","ty":"national park","u":0,"b":"The Rodopi Mountain Range National Park is a national park in Greece, situated in the central-west massif of the Greek section of the Rhodope Mountains. It covers an area of approximately 170,000 hectares and includes the largest and most productive forest ecosystems in Greece."},{"n":"Piatra Craiului National Park","lat":45.5269,"lon":25.2117,"s":11,"w":"Piatra Craiului National Park","ty":"national park|protected area","u":0,"b":"Piatra Craiului National Park is a protected area of national interest in Romania corresponding to IUCN category II (national park), located on the territories of Argeș (6,967 ha.) and Brașov (7,806 ha) counties. Located on the Piatra Craiului Massif, it is largely karstic."},{"n":"Sharjah National Park","lat":25.3128,"lon":55.5364,"s":11,"w":"Sharjah National Park","ty":"national park","u":0,"b":"Sharjah National Park is a park in Sharjah, the United Arab Emirates. The park is the largest in Sharjah, covering approximately 630,000 m2. The park includes many recreational facilities, such as a children's play area, an electronic games area, and sports fields including a football field, a handball court, and a basketball court."},{"n":"Dessau","lat":51.8342,"lon":12.2461,"s":71,"w":"Dessau","ty":"former municipality|Ortsteil|municipality in Germany|world heritage site","u":1,"b":"Dessau is a district of the independent city of Dessau-Roßlau in Saxony-Anhalt at the confluence of the rivers Mulde and Elbe, in the Bundesland (Federal State) of Saxony-Anhalt. Until 1 July 2007, it was an independent city. The population of Dessau is 67,747 (Dec."},{"n":"Selimiye Mosque","lat":41.6781,"lon":26.5594,"s":67,"w":"Selimiye Mosque, Edirne","ty":"historic building|mosque|world heritage site","u":1,"b":"The Selimiye Mosque (Turkish: Selimiye Camii) is an Ottoman imperial mosque, located in the city of Edirne (formerly Adrianople), Turkey. It was commissioned by Sultan Selim II and was built by the imperial architect Mimar Sinan between 1568 and 1575."},{"n":"Neusiedl Lake","lat":47.8333,"lon":16.75,"s":63,"w":"Lake Neusiedl","ty":"endorheic lake|steppe lake|Natura 2000 site|world heritage site","u":1,"b":"Lake Neusiedl or Lake Fertő (Hungarian: Fertő tó), is the largest endorheic lake in Central and Western Europe, as well as the second largest in Europe after The Caspian Sea, straddling Austria and Hungary. The lake is saline and covers 315 km2 (122 sq mi), of which 240 km2 (93 sq mi) is on the Austrian side and 75 km2 (29 sq mi) on the Hungarian side."},{"n":"Nesebar","lat":42.6595,"lon":27.7247,"s":62,"w":"Nesebar","ty":"seaside resort|municipality seat|city in Bulgaria|spa town|world heritage site","u":1,"b":"Nesebar is an ancient city and one of the major seaside resorts on the Bulgarian Black Sea Coast, located in Burgas Province. It is the administrative centre of the homonymous Nesebar Municipality. Often referred to as the \"Pearl of the Black Sea\", Nesebar is a rich city-museum defined by more than three millennia of ever-changing history."},{"n":"Fallingwater","lat":39.9064,"lon":-79.4681,"s":61,"w":"Fallingwater","ty":"single-family detached home|historic house museum|world heritage site","u":1,"b":"Fallingwater is a house museum in Stewart Township in the Laurel Highlands of southwestern Pennsylvania, United States. Designed by the architect Frank Lloyd Wright, it is built partly over a waterfall on the Bear Run stream. The three-story residence was developed as a weekend retreat for Edgar J."},{"n":"Solomon R. Guggenheim Museum","lat":40.7831,"lon":-73.9589,"s":60,"w":"Solomon R. Guggenheim Museum","ty":"museum building|art museum|world heritage site","u":1,"b":"The Solomon R. Guggenheim Museum, often referred to as The Guggenheim, is an art museum at 1071 Fifth Avenue between 88th and 89th Streets on the Upper East Side of Manhattan in New York City. It hosts a permanent collection of Impressionist, Post-Impressionist, early Modern and contemporary art and also features special exhibitions throughout the year."},{"n":"Museum Island","lat":52.5214,"lon":13.3956,"s":58,"w":"Museum Island","ty":"neighborhood|world heritage site","u":1,"b":"The Museum Island is a museum complex on the northern part of Spree Island in the historic heart of Berlin, Germany. It is one of the capital's most visited sights and one of the most important museum sites in Europe."},{"n":"Beemster","lat":52.55,"lon":4.9278,"s":57,"w":"Beemster","ty":"municipality of the Netherlands|polder|world heritage site","u":1,"b":"Beemster is a former municipality in the Netherlands, in the province of North Holland. The Beemster is the first polder in the Netherlands reclaimed from a lake, the water extracted by windmills between 1609 and 1612. The original well-ordered landscape of fields, roads, canals, and dykes has been preserved intact."},{"n":"Liberty Island","lat":40.69,"lon":-74.045,"s":57,"w":"Liberty Island","ty":"island|heritage site|world heritage site","u":1,"b":"Liberty Island is a federally owned island in Upper New York Bay in the northeastern United States. Its most notable feature is the Statue of Liberty (Liberty Enlightening the World), a large statue by Frédéric Auguste Bartholdi that was dedicated in 1886."},{"n":"Wachau","lat":48.3644,"lon":15.4342,"s":57,"w":"Wachau","ty":"valley|world heritage site","u":1,"b":"The Wachau is an Austrian valley formed by the Danube River. It is one of the most prominent tourist destinations of Lower Austria, located between the towns of Melk and Krems that attracts epicureans for its high-quality wines. It is 36 kilometres (22 mi) in length and has been settled since prehistoric times."},{"n":"Ancient and Primeval Beech Forests of the Carpathians and Other Regions of Europe","lat":49.0,"lon":15.0,"s":56,"w":"Ancient and Primeval Beech Forests of the Carpathians and Other Regions of Europe","ty":"group|group of protected areas|World Heritage Site|world heritage site","u":1,"b":"Ancient and Primeval Beech Forests of the Carpathians and Other Regions of Europe is a transnational serial nature UNESCO World Heritage Site, encompassing 93 component parts (forests of European beech, Fagus sylvatica) in 18 European countries. Together, the sites protect the largest and least disturbed forests dominated by the beech tree."},{"n":"Forth Bridge","lat":55.9984,"lon":-3.3876,"s":55,"w":"Forth Bridge","ty":"truss bridge|railway bridge|steel bridge|cantilever bridge|world heritage site","u":1,"b":"The Forth Bridge is a cantilever railway bridge across the Firth of Forth in the east of Scotland, 9 miles (14 kilometres) west of central Edinburgh. Completed in 1890, it is considered a symbol of Scotland, and is a UNESCO World Heritage Site. It was designed by English engineers Sir John Fowler and Sir Benjamin Baker."},{"n":"Hortobágy National Park","lat":47.5946,"lon":21.1568,"s":54,"w":"Hortobágy National Park","ty":"national parkin Hungary|Natura 2000 site|biosphere reserve|world heritage site","u":1,"b":"Hortobágy is an 800 km2 national park in eastern Hungary. The park, a part of the Alföld (Great Plain), was designated as a national park in 1973 (the first in Hungary), and elected among the World Heritage Sites in 1999. The Hortobágy is Hungary's largest protected area, and the largest semi-natural grassland in Europe."},{"n":"Hollókő","lat":47.9961,"lon":19.5917,"s":52,"w":"Hollókő","ty":"municipality of Hungary|world heritage site","u":1,"b":"Hollókő is a village in northern Hungary, located in Nógrád County. The village, which was constructed in the 13th century and developed in the 18th and 19th centuries, is a well-preserved ethnographic village of the Palóc people, with traditional wooden architecture and layout of buildings, farms, and orchards."},{"n":"Pirin National Park","lat":41.6722,"lon":23.4878,"s":52,"w":"Pirin National Park","ty":"national park|world heritage site","u":1,"b":"Pirin National Park (Bulgarian: Национален парк \"Пирин\"), originally named Vihren National Park, covering the larger part of the Pirin Mountains in southwestern Bulgaria, spanning an area of 403.56 square kilometers (155.82 mi2). It is one of the three national parks in the country, the others being Rila National Park and Central Balkan National Park."},{"n":"Monastery of Saint John of Rila","lat":42.1344,"lon":23.3396,"s":51,"w":"Rila Monastery","ty":"Stauropegic monastery|Eastern Orthodox church building|monastery|world heritage site","u":1,"b":"The Monastery of Saint John of Rila, also known as Rila Monastery (\"Sveti Ivan Rilski\" (Bulgarian: Рилски манастир „Свети Иван Рилски“), is the largest and most famous Eastern Orthodox monastery in Bulgaria."},{"n":"Vlkolínec","lat":49.0397,"lon":19.2784,"s":50,"w":"Vlkolínec","ty":"village|world heritage site","u":1,"b":"Vlkolínec is a village under the administration of the town of Ružomberok in Slovakia. Historically, however, it was a separate village. The first written mention of the village came from 1376 and after 1882 it became part of Ružomberok."},{"n":"Old Town","lat":50.0847,"lon":14.4203,"s":50,"w":"Old Town (Prague)","ty":"municipal part of the Czech Republic|urban area|city center|cadastral area in the Czech Re","u":1,"b":"The Old Town of Prague (Czech: Staré Město pražské, German: Prager Altstadt) is a medieval settlement of Prague, Czech Republic. It was separated from the outside by a semi-circular moat and wall, connected to the Vltava river at both of its ends."},{"n":"Boyana Church","lat":42.6447,"lon":23.2662,"s":50,"w":"Boyana Church","ty":"museum|Eastern Orthodox church building|world heritage site","u":1,"b":"The Boyana Church (Bulgarian: Боянска църква, romanized: Boyanska tsărkva) is a medieval Bulgarian Orthodox church situated on the outskirts of Sofia, the capital of Bulgaria, in the Boyana quarter. In 1979, the building was added to the UNESCO World Heritage List."},{"n":"Semmering railway","lat":47.643,"lon":15.831,"s":49,"w":"Semmering Railway","ty":"railway line|world heritage site","u":1,"b":"The Semmering Railway (German: Semmeringbahn) in Austria, which starts at Gloggnitz and leads over the Semmering to Mürzzuschlag, was the first mountain railway in Europe built with a standard gauge track."},{"n":"Madara Rider","lat":43.2774,"lon":27.1189,"s":49,"w":"Madara Rider","ty":"|world heritage site","u":1,"b":"The Madara Rider or Madara Horseman (Bulgarian: Мадарски конник, Madarski konnik) is a large early medieval rock relief carved on the Madara Plateau east of Shumen in northeastern Bulgaria, near the village of Madara. The monument is dated to the very late 7th or more often the very early 8th century, during the reign of the Bulgar Khan Tervel."},{"n":"Žatec","lat":50.3273,"lon":13.5459,"s":49,"w":"Žatec","ty":"royal city|municipality of the Czech Republic|municipality with authorized municipal offic","u":1,"b":"Žatec is a town in Louny District in the Ústí nad Labem Region of the Czech Republic. It has about 19,000 inhabitants. The town lies on the Ohře River in the Most Basin."},{"n":"Centennial Hall","lat":51.1069,"lon":17.0772,"s":48,"w":"Centennial Hall (Wrocław)","ty":"multi-purpose hall|architectural heritage monument|hall|world heritage site","u":1,"b":"The Centennial Hall (Polish: Hala Stulecia); German: Jahrhunderthalle), formerly named People's Hall (Hala Ludowa), is a historic building in Wrocław, Poland. It was constructed according to the plans of architect Max Berg in 1911–1913."},{"n":"Srebarna Nature Reserve","lat":44.1111,"lon":27.0722,"s":47,"w":"Srebarna Nature Reserve","ty":"biosphere reserve|world heritage site","u":1,"b":"The Srebarna Nature Reserve is a nature reserve in northeastern Bulgaria (Southern Dobruja), near the village of the same name, 18 kilometers (11 mi) west of Silistra and two kilometers (1.2 mi) south of the Danube. It comprises Lake Srebarna and its surroundings, and is an important wetland located on the Via Pontica, a bird migration route between Europe and Africa."},{"n":"Villa Tugendhat","lat":49.2072,"lon":16.6158,"s":47,"w":"Villa Tugendhat","ty":"museum building|villa|world heritage site","u":1,"b":"Villa Tugendhat (Czech: Vila Tugendhat) is an architecturally significant building in Brno, Czech Republic. It is one of the pioneering prototypes of modern architecture in Europe, and was designed by the German architects Ludwig Mies van der Rohe and Lilly Reich."},{"n":"Monticello","lat":38.0103,"lon":-78.4523,"s":47,"w":"Monticello","ty":"plantation|world heritage site","u":1,"b":"Monticello was the primary residence and plantation of Thomas Jefferson, a Founding Father, author of the Declaration of Independence, and the third president of the United States. Jefferson began designing Monticello after inheriting land from his father at the age of 14."},{"n":"Holašovice","lat":48.9667,"lon":14.2667,"s":46,"w":"Holašovice","ty":"cadastral area in the Czech Republic|municipal part of the Czech Republic|world heritage s","u":1,"b":"Holašovice is a small historic village located in the south of the Czech Republic, 16 kilometres west of České Budějovice. Village belongs to the municipality Jankov. To the south lies the protected landscape area of Blanský Forest."},{"n":"Muskau Park","lat":51.5476,"lon":14.7232,"s":45,"w":"Muskau Park","ty":"park|English garden|world heritage site","u":1,"b":"Muskau Park is a landscape park in the Upper Lusatia region of Germany and Poland. It is the largest and one of the most famous English gardens in Central Europe, stretching along both sides of the German–Polish border on the Lusatian Neisse."},{"n":"Altes Museum","lat":52.5194,"lon":13.3989,"s":44,"w":"Altes Museum","ty":"art museum|history museum|world heritage site","u":1,"b":"The Altes Museum (English: Old Museum) is a listed building on the Museum Island in the historic centre of Berlin, Germany. Built between 1825 and 1830 by order of King Frederick William III of Prussia according to plans by Karl Friedrich Schinkel, it is considered a major work of German Neoclassical architecture."},{"n":"Rock-hewn Churches of Ivanovo","lat":43.6956,"lon":25.9881,"s":44,"w":"Rock-hewn Churches of Ivanovo","ty":"museum|group|world heritage site","u":1,"b":"The Rock-hewn Churches of Ivanovo are a group of monolithic churches, chapels and monasteries hewn out of solid rock and completely different from other monastery complexes in Bulgaria, located near the village of Ivanovo, 20 kilometers (12 mi) south of Rousse, on the high rocky banks of the Rusenski Lom, 32 meters (105 ft) above the river."},{"n":"Horezu monastery","lat":45.1686,"lon":24.0069,"s":43,"w":"Horezu Monastery","ty":"monastery|world heritage site","u":1,"b":"The Horezu Monastery or Hurezi Monastery was founded in 1690 by Prince Constantin Brâncoveanu in the town of Horezu, Wallachia, Romania. It is considered to be a masterpiece of \"Brâncovenesc style\", known for its architectural purity and balance, the richness of its sculpted detail, its treatment of religious compositions, its votive portraits, and its painted decorative works."},{"n":"Schwerin Castle","lat":53.6242,"lon":11.4189,"s":43,"w":"Schwerin Castle","ty":"Schloss|museum|parliament building|architectural landmark|world heritage site","u":1,"b":"Schwerin Castle (German: Schweriner Schloss, German pronunciation: also known as Schwerin Palace, is a 19th-century Schloss built in the historicist style located in the city of Schwerin, the capital of Mecklenburg-Vorpommern state, Germany. It is situated on an island in the city's main lake, Lake Schwerin."},{"n":"Thracian Tomb of Kazanlak","lat":42.6256,"lon":25.3992,"s":43,"w":"Thracian Tomb of Kazanlak","ty":"tomb|museum|world heritage site","u":1,"b":"The Thracian Tomb of Kazanlak (Bulgarian: Казанлъшка гробница, Kazanlǎška grobnica) is a vaulted-brickwork \"beehive\" (tholos) tomb that is located near the town of Kazanlak in central Bulgaria."},{"n":"Thracian Tomb of Sveshtari","lat":43.745,"lon":26.7663,"s":43,"w":"Thracian Tomb of Sveshtari","ty":"tomb|world heritage site","u":1,"b":"The Thracian Tomb of Svestari (Свещарска гробница, Sveshtarska grobnitsa) is 2.5 kilometers (1.6 mi) southwest of the village of Sveshtari, Razgrad Province, which is 42 kilometers (26 mi) northeast of Razgrad, in northeast Bulgaria. The tomb is probably the grave of Dromichaetes (Ancient Greek: Δρομιχαίτης, romanized: Dromichaites; c. 300 – c."},{"n":"New Lanark","lat":55.6636,"lon":-3.7814,"s":42,"w":"New Lanark","ty":"village|world heritage site","u":1,"b":"New Lanark is a village on the River Clyde, approximately 1.4 miles (2.3 kilometres) from Lanark, in Lanarkshire, and some 25 miles (40 km) southeast of Glasgow, Scotland. It was founded in 1785 and opened in 1786 by David Dale, who built cotton mills and housing for the mill workers."},{"n":"Marienberg","lat":50.6508,"lon":13.1647,"s":42,"w":"Marienberg","ty":"urban municipality in Germany|Greater district town|mining community|world heritage site","u":1,"b":"Marienberg is a town in Germany. It was the district capital of the Mittlerer Erzgebirgskreis (Central Ore Mountains district) in the southern part of Saxony, and since August 2008 it has been part of the new district of Erzgebirgskreis. As of 2020, the town had 16,716 inhabitants."},{"n":"Tokaj wine region","lat":48.15,"lon":21.35,"s":41,"w":"Tokaj wine region","ty":"wine-producing region|geographical small region of Hungary|world heritage site","u":1,"b":"Tokaj wine region or Tokaj-Hegyalja wine region (short Tokaj-Hegyalja or Hegyalja) is a historical wine region located in northeastern Hungary and southeastern Slovakia. It is also one of the seven larger wine regions of Hungary (Hungarian: Tokaji borrégió). Hegyalja means \"foothills\" in Hungarian, and this was the original name of the region."},{"n":"wooden churches of the Slovak Carpathians","lat":49.3361,"lon":19.5583,"s":41,"w":"Wooden churches of the Slovak Carpathians","ty":"|world heritage site","u":1,"b":"Carpathian Wooden Churches is the name of a UNESCO World Heritage Site that consists of nine wooden religious buildings constructed between the 16th and 18th centuries in eight different locations in Slovakia. They include two Roman Catholic (Hervartov, Tvrdošín), three Protestant and three Greek Catholic churches (Bodružal, Ruská Bystrá, Ladomirová) plus one belfry in Hronsek."},{"n":"Pannonhalma Archabbey","lat":47.5528,"lon":17.7611,"s":40,"w":"Pannonhalma Archabbey","ty":"cathedral|Catholic church building|abbey|minor basilica|archabbey|parish church|world heri","u":1,"b":"The Benedictine Pannonhalma Archabbey or Territorial Abbey of Saint Martin on Mount Pannonhalma is a medieval building in Pannonhalma and one of the oldest historical monuments in Hungary. Founded in 996, it is located near the town, on top of a hill (282 m)."},{"n":"Churches of Peace","lat":51.0539,"lon":16.189,"s":40,"w":"Churches of Peace","ty":"architectural ensemble|world heritage site","u":1,"b":"The Churches of Peace (Polish: Kościoły Pokoju, German: Friedenskirchen) in Jawor and Świdnica in Lower Silesia. Poland, are 17th-century churches, named after the Peace of Westphalia of 1648. The treaty granted the Lutherans of Silesia to build three churches from wood, loam and straw outside the city walls, without steeples and church bells."},{"n":"Holy Trinity Column in Olomouc","lat":49.594,"lon":17.2505,"s":40,"w":"Holy Trinity Column, Olomouc","ty":"plague column|Holy Trinity column|world heritage site","u":1,"b":"The Holy Trinity Column (Czech: Sloup Nejsvětější Trojice) in Olomouc, in the Czech Republic is a Baroque monument (Trinity column) that was built between 1716 and 1754. The main purpose was to celebrate the Catholic Church and faith, partly caused by feeling of gratitude for ending a plague, which struck Moravia (now in the Czech Republic) between 1713 and 1715."},{"n":"Divriği Great Mosque and Hospital","lat":39.3712,"lon":38.1216,"s":40,"w":"Divriği Great Mosque and Hospital","ty":"community health center|historic site|mosque|former hospital|group of structures or buildi","u":1,"b":"Divriği Great Mosque and Hospital (Turkish: Divriği Ulu Cami ve Darüşşifası) was built in 1228–1229 by the local dynasty of the Mengujekids in the small Anatolian town of Divriği, now in Sivas Province, Turkey. The complex is in the upper town, below the citadel."},{"n":"Gamzigrad","lat":43.8993,"lon":22.1862,"s":40,"w":"Gamzigrad","ty":"human settlement|world heritage site","u":1,"b":"Gamzigrad is an archaeological site, spa resort, and UNESCO World Heritage Site of Serbia, located south of the Danube river, in the city of Zaječar. It is the location of the ancient Roman complex of palaces and temples Felix Romuliana (Serbian: Феликс Ромулијана / Feliks Romulijana), built by Emperor Galerius in Dacia Ripensis. The main area covers 10 acres (40,000 m2)."},{"n":"Defence Line of Amsterdam","lat":52.3744,"lon":4.8931,"s":39,"w":"Stelling van Amsterdam","ty":"Nationaal Landschap|waterline|fortification|world heritage site","u":1,"b":"The Stelling van Amsterdam is a 135-kilometre (84 mi) fortification line around Amsterdam, which would function as a national redoubt. It comprises 45 forts, as well as dams, dikes, locks, pumping stations, batteries and casemates. The forts are 10–15 kilometres (6.2–9.3 mi) from the centre and lowlands, which can easily be inundated in time of war."},{"n":"Eggenberg Castle, Graz","lat":47.0739,"lon":15.3913,"s":39,"w":"Eggenberg Palace, Graz","ty":"museum|palace|world heritage site","u":1,"b":"Eggenberg Palace (German: Schloss Eggenberg) in Graz, is the most significant Baroque palace complex in the Austrian state of Styria."},{"n":"Princely Abbey of Corvey","lat":51.7778,"lon":9.41,"s":39,"w":"Princely Abbey of Corvey","ty":"abbey|religious community|monastery|royal palace|world heritage site","u":1,"b":"The Princely Abbey of Corvey (German: Fürststift Corvey or German: Fürstabtei Corvey) is a former Benedictine abbey and ecclesiastical principality now in North Rhine-Westphalia, Germany. It was one of the half-dozen self-ruling princely abbeys of the Holy Roman Empire from the Late Middle Ages until 1792 when Corvey was elevated to a prince-bishopric."},{"n":"Pilgrimage Church of Saint John of Nepomuk","lat":49.58,"lon":15.9419,"s":38,"w":"Pilgrimage Church of Saint John of Nepomuk","ty":"church building|Catholic pilgrimage church|world heritage site","u":1,"b":"The Pilgrimage Church of Saint John of Nepomuk (Czech: Poutní kostel svatého Jana Nepomuckého) at Zelená hora (meaning \"Green Hill\", German: Grünberg) is a religious building at the edge of Žďár nad Sázavou, Czech Republic, near the historical border between Moravia and Bohemia."},{"n":"Berlin Modernism Housing Estates","lat":52.4483,"lon":13.45,"s":38,"w":"Berlin Modernism Housing Estates","ty":"architectural ensemble|heritage site|world heritage site","u":1,"b":"The Berlin Modernism Housing Estates (German: Siedlungen der Berliner Moderne) is a World Heritage Site designated in 2008, comprising seven separate subsidized housing estates in Berlin."},{"n":"Town Hall of Bremen","lat":53.0759,"lon":8.8076,"s":37,"w":"Bremen City Hall","ty":"Rathaus|world heritage site","u":1,"b":"Bremen City Hall (German: Bremer Rathaus) is the seat of the President of the Senate and Mayor of Bremen, Germany. It is one of the most important examples of Brick Gothic and Weser Renaissance architecture in Europe. Since 1973, it has been a protected historical building."},{"n":"St. Michael's Church","lat":52.1529,"lon":9.9435,"s":36,"w":"St. Michael's Church, Hildesheim","ty":"Simultaneum|abbey|church building|world heritage site","u":1,"b":"The Church of St. Michael (German: Michaeliskirche) is an early-Romanesque church located in Hildesheim, Germany. It has been on the UNESCO World Cultural Heritage list since 1985 due to the before mentioned early-Romanesque architecture and art found within such as the Tree of Jesse and the now relocated Bernward Doors."},{"n":"Hildesheim Cathedral","lat":52.1489,"lon":9.9472,"s":36,"w":"Hildesheim Cathedral","ty":"Catholic cathedral|world heritage site","u":1,"b":"Hildesheim Cathedral (German: Hildesheimer Dom), officially the Cathedral of the Assumption of Mary (German: Hohe Domkirche St. Mariä Himmelfahrt) or simply St. Mary's Cathedral (German: Mariendom), is a medieval Roman Catholic cathedral in the city centre of Hildesheim in Lower Saxony, Germany, that serves as the seat of the Diocese of Hildesheim."},{"n":"Naumburg Cathedral","lat":51.1547,"lon":11.8039,"s":36,"w":"Naumburg Cathedral","ty":"church building|Lutheran cathedral|world heritage site","u":1,"b":"Naumburg Cathedral, located in Naumburg, Germany, is the former cathedral of the Bishopric of Naumburg-Zeitz."},{"n":"Dessau-Wörlitz Garden Realm","lat":51.8636,"lon":12.2814,"s":36,"w":"Dessau-Wörlitz Garden Realm","ty":"cultural landscape|World Heritage Site|park|world heritage site","u":1,"b":"The Dessau-Wörlitz Garden Realm (German: Dessau-Wörlitzer Gartenreich) is a cultural landscape and World Heritage Site in Germany, located between the city of Dessau and the town of Wörlitz in Central Germany."},{"n":"Bergpark Wilhelmshöhe","lat":51.3167,"lon":9.4,"s":35,"w":"Bergpark Wilhelmshöhe","ty":"museum|English garden|mountain park|heritage site|world heritage site","u":1,"b":"Bergpark Wilhelmshöhe is a landscape park in Kassel, Germany. The area of the park is 2.4 square kilometres (590 acres), making it the largest European hillside park, and second largest park on a hill slope in the world. Construction of the Bergpark, or \"mountain park\", began in 1689 at the behest of the Landgraves of Hesse-Kassel and took about 150 years."},{"n":"Caves of Aggtelek Karst and Slovak Karst","lat":48.4718,"lon":20.4953,"s":35,"w":"Caves of Aggtelek Karst and Slovak Karst","ty":"cave system|world heritage site","u":1,"b":"The Caves of Aggtelek Karst and Slovak Karst are a series of over 1000 karst caves spread out over a total area of 55,800 ha (138,000 acres) along the border of Hungary and Slovakia."},{"n":"Palaces and Parks of Potsdam and Berlin","lat":52.4,"lon":13.0333,"s":34,"w":"Palaces and Parks of Potsdam and Berlin","ty":"cultural landscape|world heritage site","u":1,"b":"Palaces and Parks of Potsdam and Berlin (German: Schlösser und Gärten von Potsdam und Berlin) are a group of palace complexes and extended landscaped gardens located in the Havelland region around Potsdam and the German capital of Berlin. The term was used upon the designation of the cultural ensemble as a World Heritage Site by UNESCO in 1990."},{"n":"Margravial Opera House","lat":49.9443,"lon":11.5787,"s":34,"w":"Margravial Opera House","ty":"museum|opera house|world heritage site","u":1,"b":"The Margravial Opera House (German: Markgräfliches Opernhaus) is a Baroque opera house in the town of Bayreuth, Germany. Built between 1745 and 1750, it is one of Europe's few surviving theatres of the period and has been extensively restored. On 30 June 2012, the opera house was added to the UNESCO World Heritage List because of its exceptional Baroque architecture."},{"n":"Fagus Factory","lat":51.9837,"lon":9.8126,"s":34,"w":"Fagus Factory","ty":"factory|world heritage site","u":1,"b":"The Fagus Factory (German: Fagus-Werk) is a shoe last factory in Alfeld on the Leine, Lower Saxony, Germany, and serves as an important example of early modern architecture. Commissioned by owner Carl Benscheidt who wanted a radical structure to express the company's break from the past, the factory was designed by Walter Gropius and Adolf Meyer."},{"n":"Bremen Roland","lat":53.0759,"lon":8.8073,"s":34,"w":"Bremen Roland","ty":"colossal statue|Roland statue|world heritage site","u":1,"b":"The Bremen Roland is a statue of Roland, erected in 1404. It stands in the market square (Rathausplatz) of Bremen, Germany, facing the cathedral, and shows Roland, paladin of the first Holy Roman Emperor Charlemagne and hero of the Battle of Roncevaux Pass. Statues of Roland appear in numerous cities of the former Holy Roman Empire, as emblems of city liberties, Stadtrechte."},{"n":"Christiansfeld","lat":55.3567,"lon":9.4831,"s":33,"w":"Christiansfeld","ty":"town|world heritage site","u":1,"b":"Christiansfeld, with a population of 3,105 (1 January 2026), is a town in Kolding Municipality in Southern Jutland in Region of Southern Denmark. The town was founded in 1773 by the Moravian Church and named after the Danish king Christian VII."},{"n":"Lednice-Valtice Cultural Landscape","lat":48.7758,"lon":16.775,"s":32,"w":"Lednice–Valtice Cultural Landscape","ty":"landscape heritage zone|cultural landscape|world heritage site","u":1,"b":"The Lednice–Valtice Cultural Landscape is a cultural-natural landscape complex of 283.09 square kilometres (109.30 sq mi) in the South Moravian Region of the Czech Republic. It comprises the municipalities of Lednice, Valtice and Hlohovec, and the rural area of Břeclav."},{"n":"Dacian Fortresses of the Orăștie Mountains","lat":45.6231,"lon":23.3119,"s":32,"w":"Dacian Fortresses of the Orăștie Mountains","ty":"fortification system|architectural ensemble|world heritage site","u":1,"b":"Built in murus dacicus style, the six Dacian Fortresses of the Orăștie Mountains (Romanian: Cetăți dacice din Munții Orăștiei), in Romania, were created in the 1st centuries BC and AD as protection against Roman conquest, and played an important role during the Roman–Dacian wars."},{"n":"Hevsel Gardens","lat":37.9075,"lon":40.2475,"s":32,"w":"Hevsel Gardens","ty":"field|world heritage site","u":1,"b":"The Hevsel Gardens (Turkish: Hevsel Bahçeleri, Kurdish: Baxçeyên Hewselê), are the seven hundred hectares of cultivated, fertile lands near the Tigris in eastern Turkey, between the Diyarbakır Fortress and the river."},{"n":"Hainich National Park","lat":51.0967,"lon":10.3908,"s":30,"w":"Hainich National Park","ty":"Nationalpark|world heritage site","u":1,"b":"Hainich National Park (German: Nationalpark Hainich), founded on December 31, 1997, is the 13th national park in Germany and the only one in Thuringia. One of the main objectives of the park is the protection of an ancient native beech forest."},{"n":"Old Quebec","lat":46.8094,"lon":-71.2106,"s":30,"w":"Old Quebec","ty":"old town|world heritage site","u":1,"b":"Old Quebec is a historic neighbourhood of Quebec City, Quebec, Canada. Comprising the Upper Town (French: Haute-Ville) and Lower Town (French: Basse-Ville), the area is a UNESCO World Heritage Site. Administratively, Old Quebec is part of the Vieux-Québec–Cap-Blanc–colline Parlementaire district in the borough of La Cité-Limoilou."},{"n":"Diyarbakır Fortress","lat":37.9109,"lon":40.2273,"s":29,"w":"Fortifications of Diyarbakır","ty":"city walls|fortress|world heritage site","u":1,"b":"The Fortifications of Diyarbakır are a set of fortifications enclosing the historical district of Sur in Diyarbakır, Turkey. They consist of an inner fortress, the citadel, and an outer ring of city walls. The main gates of the city are: Dağ (Mountain) Gate, Urfa Gate, Mardin Gate, and Yeni (New) Gate."},{"n":"Studley Royal Park","lat":54.1161,"lon":-1.5731,"s":29,"w":"Studley Royal Park","ty":"French formal garden|English garden|world heritage site","u":1,"b":"Studley Royal Park is an estate in North Yorkshire, England. The site has an area of 800 acres (323 ha) and includes an 18th-century landscaped garden; the ruins of Fountains Abbey; Fountains Hall, a Jacobean mansion; and the Victorian St Mary's church, designed by William Burges. Studley Royal House, around which the park and gardens were designed, burned down in 1946."},{"n":"Dobšinská Ice Cave","lat":48.8683,"lon":20.3044,"s":28,"w":"Dobšiná Ice Cave","ty":"show cave|ice cave|national nature monument|protected area|world heritage site","u":1,"b":"Dobšiná Ice Cave is an ice cave in Slovakia, near the mining town of Dobšiná in the Slovak Paradise. Since 2000 it has been included on the UNESCO World Heritage list as a part of the Caves of Aggtelek Karst and Slovak Karst site, because of its unique cave formations and its natural beauty."},{"n":"Litomyšl Chateau","lat":49.8734,"lon":16.3126,"s":28,"w":"Litomyšl Castle","ty":"event venue|château|world heritage site","u":1,"b":"Litomyšl Castle is one of the largest Renaissance castles in the Czech Republic. It is owned by the Czech state. It is located in the centre of the town of Litomyšl and was declared a UNESCO World Heritage Site in 1999."},{"n":"Bahrain Pearling Trail","lat":26.25,"lon":50.61,"s":28,"w":"Bahrain Pearling Trail","ty":"group of structures or buildings|world heritage site","u":1,"b":"The Bahrain Pearling Path (Arabic: مسار اللؤلؤ, romanized: Masār al-Luʼluʼ) is a serial cultural heritage site inscribed on the UNESCO World Heritage List on June 30, 2012."},{"n":"Eise Eisinga Planetarium","lat":53.1874,"lon":5.5438,"s":28,"w":"Eise Eisinga Planetarium","ty":"museum|world heritage site","u":1,"b":"The Royal Eise Eisinga Planetarium (Dutch: Koninklijk Eise Eisinga Planetarium) is an 18th-century orrery in Franeker, Friesland, Netherlands. It is currently a museum and open to the public. The orrery has been on the top 100 Dutch heritage sites list since 1990."},{"n":"Ir.D.F. Woudagemaal","lat":52.8458,"lon":5.6789,"s":28,"w":"Wouda pumping station","ty":"steamdriven pumping station|museum|world heritage site","u":1,"b":"The ir. D.F. Wouda Steam Pumping Station (ir. D.F. Woudagemaal) is a pumping station in the Netherlands, and the largest still operational steam-powered pumping station in the world."},{"n":"Castle Church, Wittenberg","lat":51.8664,"lon":12.6378,"s":27,"w":"All Saints' Church, Wittenberg","ty":"castle church|world heritage site","u":1,"b":"All Saints' Church, commonly referred to as Schlosskirche (Castle Church) to distinguish it from the Stadtkirche (Town Church) of St. Mary's, sometimes known as the Reformation Memorial Church, is a Lutheran church in Wittenberg, Saxony-Anhalt, Germany."},{"n":"Dresden Elbe Valley","lat":51.0498,"lon":13.8132,"s":26,"w":"Dresden Elbe Valley","ty":"cultural landscape|world heritage site","u":1,"b":"The Dresden Elbe Valley is a cultural landscape and former World Heritage Site stretching along the Elbe river in Dresden, the state capital of Saxony, Germany."},{"n":"St. Procopius Basilica in Třebíč","lat":49.217,"lon":15.8736,"s":25,"w":"St. Procopius Basilica in Třebíč","ty":"church building|basilica|world heritage site","u":1,"b":"St. Procopius Basilica (Czech: Bazilika svatého Prokopa) is a Romanesque-Gothic Christian church in Třebíč, Czech Republic. It was built on the site of the original Virgin Mary's Chapel of the Benedictine monastery in 1240–1260."},{"n":"Historic Areas of Istanbul","lat":41.0085,"lon":28.9799,"s":24,"w":"Historic Areas of Istanbul","ty":"urban area|group of protected areas|world heritage site","u":1,"b":"The Historic Areas of Istanbul are a group of sites in the capital district of Fatih in the city of Istanbul, Turkey, that were added to the UNESCO World Heritage List in 1985."},{"n":"Spišská Kapitula","lat":49.0006,"lon":20.7411,"s":24,"w":"Spišská Kapitula","ty":"human settlement|quarter|world heritage site","u":1,"b":"Spišská Kapitula (both meaning the \"Spiš Chapter house\") is an exceptionally well-preserved ecclesiastical town on the outskirts of Spišské Podhradie, Slovakia, and overlooking Spiš Castle. It is part of the UNESCO World Heritage Site \"Levoča, Spiš Castle and the associated cultural monuments\". The town consists of St."},{"n":"Ahwar of Southern Iraq","lat":31.5622,"lon":47.6578,"s":24,"w":"Ahwar of Southern Iraq","ty":"cultural landscape|world heritage site","u":1,"b":"The Ahwar of Southern Iraq: Refuge of Biodiversity and the Relict Landscape of the Mesopotamian Cities is a UNESCO World Heritage Site in Southern Iraq sometimes called the \"Garden of Eden\" by Biblical scholars. It consists of marshlands and ancient cities sustained by the Tigris and Euphrates rivers."},{"n":"Kellerwald-Edersee National Park","lat":51.1667,"lon":9.0,"s":24,"w":"Kellerwald-Edersee National Park","ty":"Nationalpark|world heritage site","u":1,"b":"Kellerwald-Edersee National Park (German: Nationalpark Kellerwald-Edersee), CDDA-No. 318077) in the North Hessian county of Waldeck-Frankenberg is a national park, 57.38 km² in area, that lies south of the Edersee lake in the northern part of the Kellerwald low mountain range in the German state of Hesse."},{"n":"Auschwitz-Birkenau State Museum","lat":50.0358,"lon":19.1783,"s":23,"w":"Auschwitz-Birkenau State Museum","ty":"museum|world heritage site","u":1,"b":"The Auschwitz-Birkenau State Museum (Polish: Państwowe Muzeum Auschwitz-Birkenau) is a museum on the site of the Auschwitz concentration camp in Oświęcim, Poland, which was operated by Nazi Germany. The site includes the main concentration camp at Auschwitz I and the remains of the concentration and extermination camp at Auschwitz II-Birkenau."},{"n":"Cumalıkızık","lat":40.1752,"lon":29.1727,"s":23,"w":"Cumalıkızık","ty":"mahalle|world heritage site","u":1,"b":"Cumalıkızık is a neighbourhood in the municipality and district of Yıldırım, Bursa Province in Turkey. Its population is 707 (2022). It is 10 kilometers east of the city of Bursa, at the foot of Mount Uludağ."},{"n":"Historic Centre of Sighișoara","lat":46.2178,"lon":24.7922,"s":22,"w":"Historic Centre of Sighișoara","ty":"old town|urban area|world heritage site","u":1,"b":"The Historic Centre of Sighișoara (Sighișoara Citadel) is the old historic center of the town of Sighișoara (German: Schäßburg, Hungarian: Segesvár), Romania, built in the 12th century by Saxon settlers."},{"n":"The 20th-Century Architecture of Frank Lloyd Wright","lat":39.9056,"lon":-79.4665,"s":22,"w":"20th-Century Architecture of Frank Lloyd Wright","ty":"group of structures or buildings|world heritage site","u":1,"b":"The 20th-Century Architecture of Frank Lloyd Wright is a UNESCO World Heritage Site consisting of eight buildings across the United States designed by the American architect Frank Lloyd Wright (1867–1959). These sites are designated because they exemplify his philosophy of organic architecture, in which he designed structures that harmonized with humanity and their environment."},{"n":"Old Synagogue (Erfurt)","lat":50.9786,"lon":11.0293,"s":21,"w":"Old Synagogue (Erfurt)","ty":"synagogue|world heritage site","u":1,"b":"The Old Synagogue (German: Alte Synagoge; Yiddish: אלטע שול, ערפורט; Hebrew: בית הכנסת הישן (ארפורט)) is a former Jewish synagogue, located in Erfurt, Thuringia, Germany. Dating from the late 11th century, the synagogue is one of the best preserved Medieval synagogues in Europe. Most parts of the building date from around 1250–1320."},{"n":"Jewish Quarter of Třebíč","lat":49.2168,"lon":15.8734,"s":21,"w":"Jewish Quarter of Třebíč","ty":"Jewish quarter|world heritage site","u":1,"b":"The Jewish Quarter of Třebíč (Czech: Židovská čtvrť v Třebíči) is a neighborhood and former ghetto in the town of Třebíč, located in western Moravia, Czech Republic. The Jewish Quarter is situated on the north bank of the River Jihlava and is one of the best preserved Jewish quarters in Europe. In 2003, together with the nearby Jewish Cemetery and the St."},{"n":"Peace Church in Świdnica","lat":50.8462,"lon":16.4916,"s":20,"w":"Holy Trinity Church of Peace in Świdnica","ty":"timber-framed church|architectural heritage monument|church building|world heritage site","u":1,"b":"The Holy Trinity Church of Peace in Świdnica is the largest wooden Baroque temple in Europe and a historic religious building built under the agreements of the Treaty of Westphalia signed in 1648, which ended the Thirty Years' War. It belongs to the Świdnica parish of the Evangelical-Augsburg Church in Poland. The building has been on the UNESCO World Heritage List since 2001."},{"n":"Duchess Anna Amalia Library","lat":50.9786,"lon":11.3322,"s":20,"w":"Duchess Anna Amalia Library","ty":"research library|world heritage site","u":1,"b":"The Duchess Anna Amalia Library (German: Herzogin Anna Amalia Bibliothek) in Weimar, Germany, houses a major collection of German literature and historical documents. In 1991, the tricentennial of its opening to the public, the Ducal Library was renamed for Duchess Anna Amalia. Today, the library is a public research library for literature and art history."},{"n":"Early Christian Necropolis of Pécs","lat":46.0744,"lon":18.2278,"s":20,"w":"Early Christian Necropolis of Pécs","ty":"World Heritage Site|necropolis|archaeological site|world heritage site","u":1,"b":"The Early Christian Necropolis of Pécs is a Roman cemetery and archeological site in Pécs, Hungary. Dating from the 4th century AD, the necropolis contains many decorated tombs, mausoleums, and burial chapels from the Early Christian period. It is one of the most significant Roman cemeteries outside of Italy."},{"n":"Babelsberg Palace","lat":52.4076,"lon":13.0933,"s":20,"w":"Babelsberg Palace","ty":"château|world heritage site","u":1,"b":"Babelsberg Palace (German: Schloss Babelsberg) lies in the eponymous park and quarter of Potsdam, the capital of the German state of Brandenburg, near Berlin. For over 50 years it was the summer residence of Prince William, later German Emperor William I and King of Prussia and his wife, Augusta of the House of Saxe-Weimar-Eisenach, German Empress and Queen of Prussia."},{"n":"Glienicke Palace","lat":52.4142,"lon":13.0953,"s":19,"w":"Glienicke Palace","ty":"palace|château|world heritage site","u":1,"b":"Glienicke Palace (German: Schloss Glienicke) is a historic palace located on the peninsula of Berlin-Wannsee in Germany. It was designed by Karl Friedrich Schinkel around 1825 for Prince Carl of Prussia."},{"n":"Auschwitz II-Birkenau concentration camp","lat":50.0371,"lon":19.1752,"s":19,"w":"Auschwitz II","ty":"concentration camp|open-air museum|cultural heritage|extermination camp|world heritage sit","u":1,"b":"Auschwitz, also known as Oświęcim, was a complex of over 40 concentration and extermination camps operated by Nazi Germany in occupied Poland (in a portion annexed into Germany in 1939) during World War II and the Holocaust."},{"n":"Jabal Al Fayah","lat":25.1114,"lon":55.839,"s":19,"w":"Jebel Faya","ty":"hill|archaeological site|world heritage site","u":1,"b":"Jebel Faya (Arabic: جَبَل ٱلْفَايَة, romanized: Jabal Al-Fāyah) is an archaeological site and limestone hill or escarpment near Mleiha, located in the central region of the Emirate of Sharjah in the UAE."},{"n":"Upper Harz Water Regale","lat":51.82,"lon":10.34,"s":19,"w":"Upper Harz Water Regale","ty":"reservoir|world heritage site","u":1,"b":"The Upper Harz Water Regale is a system of dams, reservoirs, ditches and other structures, much of which was built from the 16th to 19th centuries to divert and store the water that drove the water wheels of the mines in the Upper Harz region of Germany."},{"n":"Church of the Assumption of Our Lady and Saint John the Baptist","lat":49.9598,"lon":15.2899,"s":19,"w":"Church of the Assumption of Our Lady and Saint John the Baptist","ty":"church building|abbey church|world heritage site","u":1,"b":"The Church of the Assumption of Our Lady and Saint John the Baptist is a Gothic and Baroque Gothic church north-east of Kutná Hora in the Czech Republic and is listed in the UNESCO World Heritage List together with the Church of St. Barbara and other monuments in Kutná Hora."},{"n":"Kaymakli Underground City","lat":38.46,"lon":34.7523,"s":18,"w":"Kaymakli underground city","ty":"archaeological site|underground city|world heritage site","u":1,"b":"Kaymakli underground city (Turkish: Kaymaklı; Cappadocian Greek: Ανακού) is contained within the citadel of Kaymakli in Nevşehir Province, in the Central Anatolia Region of Turkey. First opened to tourists in 1964, the village is about 19 km from Nevşehir, on the Nevşehir-Niğde road."},{"n":"Classical Weimar","lat":50.9833,"lon":11.3167,"s":18,"w":"Classical Weimar (World Heritage Site)","ty":"architectural ensemble|world heritage site","u":1,"b":"Classical Weimar (German: Klassisches Weimar) is a UNESCO World Heritage Site consisting of 11 sites located in and around the city of Weimar, Germany. The site was inscribed on 2 December 1998. The properties all bear testimony to the influence of Weimar as a cultural centre of the Enlightenment during the eighteenth and early nineteenth centuries."},{"n":"Innere Stadt","lat":47.0719,"lon":15.4408,"s":18,"w":"Innere Stadt (Graz)","ty":"old town|district of Graz|human settlement|world heritage site","u":1,"b":"Innere Stadt is the 1st city-district of the Austrian city of Graz, capital of the state of Styria. It is the part of the Old Town (in German: Altstadt) containing the Schloßberg and the city park (Stadtpark). The district borders are formed by the river Mur between Radetzkybrücke and Keplerbrücke, the Wickenburggasse, the Glacis, Jakominiplatz and the Radetzkystraße."},{"n":"Stara Reka","lat":42.6435,"lon":24.8072,"s":17,"w":"Stara Reka Reserve","ty":"nature reserve|world heritage site","u":1,"b":"Stara Reka (Bulgarian: Стара река, meaning Old river) is one of the nine nature reserves in the Central Balkan National Park in central Bulgaria. Stara Reka was established on 19 March 1981 to protect the unique ecosystems of the Balkan Mountains. It spans an area of 1974.7 hectares, or 19.747km2."},{"n":"Wadi Wurayah","lat":25.4226,"lon":56.3635,"s":17,"w":"Wadi Wurayah","ty":"wadi|world heritage site","u":1,"b":"Wadi Wurayah (Arabic: وَادِي ٱلْوُرَيْعَة, romanized: Wādī Al-Wurayʿah) is a 12,700-hectare (31,000-acre) wadi between the towns of Masafi, Khor Fakkan, and Bidiyah in the United Arab Emirates. It has been designated as Ramsar Wetland of International Importance."},{"n":"Pfaueninsel","lat":52.4344,"lon":13.1308,"s":17,"w":"Pfaueninsel","ty":"island|world heritage site","u":1,"b":"Pfaueninsel is an island in the River Havel situated in Berlin-Wannsee, in the district of Steglitz-Zehlendorf in southwestern Berlin, near the border with Potsdam in Brandenburg. The island is part of the Palaces and Parks of Potsdam and Berlin UNESCO World Heritage Site because of its outstanding Prussian architecture and is a popular destination for day-trippers."},{"n":"Grachtengordel","lat":52.3664,"lon":4.8858,"s":17,"w":"Grachtengordel","ty":"neighborhood|world heritage site","u":1,"b":"The Grachtengordel, known in English as the Canal District, is a neighborhood in Amsterdam, Netherlands located in the Centrum district. The seventeenth-century canals of Amsterdam, located in the center of Amsterdam, were added to the UNESCO World Heritage List in August 2010."},{"n":"Wooden articular church of Hronsek","lat":48.6489,"lon":19.1549,"s":16,"w":"Wooden articular church of Hronsek","ty":"Lutheran church|church building|world heritage site","u":1,"b":"Wooden articular church of Hronsek is a Lutheran church situated in the village of Hronsek, in Slovakia."},{"n":"Muradiye Complex","lat":40.1908,"lon":29.0461,"s":16,"w":"Muradiye Complex","ty":"külliye|world heritage site","u":1,"b":"The Muradiye Complex (Turkish: Muradiye Külliyesi) or the Complex of Sultan Murad II, the Ottoman sultan (reigned 1421–1451, with interruption 1444–46), is located in Bursa, Turkey. It is part of the historic UNESCO World Heritage Site."},{"n":"Sculptural Ensemble of Constantin Brâncuși at Târgu Jiu","lat":45.0374,"lon":23.2854,"s":16,"w":"Sculptural Ensemble of Constantin Brâncuși at Târgu Jiu","ty":"group of sculptures|world heritage site","u":1,"b":"The Sculptural Ensemble of Constantin Brâncuși at Târgu Jiu is an homage to the Romanian heroes of the First World War. The ensemble comprises three sculptures: The Table of Silence (Masa tăcerii), The Gate of the Kiss (Poarta sărutului), and the Endless Column (Coloana fără Sfârșit) on an axis 1.3 km (3⁄4 mile) long, oriented west to east."},{"n":"Arbeia","lat":55.0044,"lon":-1.4311,"s":15,"w":"Arbeia","ty":"archaeological site|local authority museum|military museum|castrum|world heritage site","u":1,"b":"Arbeia was a large Roman fort in South Shields, Tyne & Wear, England, now ruined and partially reconstructed. It was first excavated in the 1870s. All modern buildings on the site were cleared in the 1970s."},{"n":"Hufeisensiedlung","lat":52.4475,"lon":13.4486,"s":15,"w":"Hufeisensiedlung","ty":"housing estate|world heritage site","u":1,"b":"The Hufeisensiedlung (\"Horseshoe Estate\") is a housing estate in Berlin, built in 1925–33. It was designed by architect Bruno Taut, municipal planning head and co-architect Martin Wagner, garden architect Leberecht Migge and Neukölln gardens director Ottokar Wagler. In 1986 the ensemble was placed under German heritage protection."},{"n":"Pampus","lat":52.3647,"lon":5.0689,"s":15,"w":"Pampus","ty":"island|artificial island|sea fort|fort|museum|world heritage site","u":1,"b":"Pampus is an artificial island and late 19th-century sea fort located in the IJmeer near Amsterdam. Pampus now belongs to the municipality of Gooise Meren and is open to visitors. Together with the artillery battery on the lighthouse island near Durgerdam and the battery at the Diemer seawall, Pampus protected the entrance to IJ Bay and the harbour of Amsterdam."},{"n":"Ore Mountain Mining Region","lat":50.4065,"lon":12.8373,"s":15,"w":"Ore Mountain Mining Region","ty":"public service company|mining region|world heritage site","u":1,"b":"The Ore Mountain Mining Region is an industrial heritage landscape, over 800 years old, in the border region of the Ore Mountains between the German state of Saxony and North Bohemia in the Czech Republic."},{"n":"Church of the Holy Trinity","lat":49.1333,"lon":20.4283,"s":14,"w":"Articular church, Kežmarok","ty":"Lutheran church|church building|world heritage site","u":1,"b":"The Articular church in Kežmarok (Slovak: Artikulárny kostol v Kežmarku) is a wooden church in Kežmarok, Slovakia."},{"n":"borders of the Roman Empire","lat":54.9926,"lon":-2.601,"s":14,"w":"Borders of the Roman Empire","ty":"architectural ensemble|political border|world heritage site","u":1,"b":"The borders of the Roman Empire, which fluctuated throughout the empire's history, were realised as a combination of military roads and linked forts, natural frontiers (most notably the Rhine and Danube rivers) and man-made fortifications which separated the lands of the empire from the countries beyond."},{"n":"Bauhaus and its Sites in Weimar, Dessau and Bernau","lat":50.9748,"lon":11.3295,"s":14,"w":"Bauhaus and its Sites in Weimar, Dessau and Bernau","ty":"group of structures or buildings|world heritage site","u":1,"b":"Bauhaus and its Sites in Weimar, Dessau and Bernau are World Heritage Sites in Germany, comprising six separate sites which are associated with the Bauhaus art school. It was designated in 1996 with four initial sites, and in 2017 two further sites were added."},{"n":"Church of the Redeemer","lat":52.4246,"lon":13.0965,"s":14,"w":"Church of the Redeemer, Sacrow","ty":"church building|world heritage site","u":1,"b":"The Protestant Church of the Redeemer is located to the south of the village of Sacrow, which since 1939 has been incorporated to Potsdam, the capital of the German Bundesland of Brandenburg. It is famous for its Italian Romanesque Revival architecture with a separate campanile (bell tower) and for its scenic location. It was built in 1844."},{"n":"Levoča, Spiš Castle and the associated cultural monuments","lat":48.9994,"lon":20.7675,"s":14,"w":"Levoča, Spiš Castle and the associated cultural monuments","ty":"group|world heritage site","u":1,"b":"The ruins of Spiš Castle is one of the largest castle sites in Central Europe. The castle is situated above the town of Spišské Podhradie and the village of Žehra that with adjacent ecclesiastical town Spišská Kapitula form components of the UNESCO World Heritage Site."},{"n":"Lutherhaus Wittenberg","lat":51.8642,"lon":12.6525,"s":14,"w":"Lutherhaus","ty":"museum|world heritage site","u":1,"b":"The Lutherhaus is a writer's house museum in Lutherstadt Wittenberg, Germany. Originally built in 1504 as part of the University of Wittenberg, the building was the home of Martin Luther for most of his adult life and a significant location in the history of the Protestant Reformation. Luther was living here when he wrote his 95 Theses."},{"n":"Snezhnika","lat":41.7692,"lon":23.4028,"s":3,"w":"Snezhnika","ty":"glacier","u":0,"b":"Snezhnika (Bulgarian: Снежника 'the snow patch') is a glacieret in the Pirin Mountains of Bulgaria, a remnant of the former Vihren Glacier. The glacieret lies at an elevation between 2,425 m (7,956 ft) and 2,480 m (8,140 ft) in the deep Golemiya Kazan cirque at the steep northern foot of Vihren (2,914 m (9,560 ft)), Pirin's highest summit."},{"n":"Yalova","lat":40.6556,"lon":29.275,"s":76,"w":"Yalova","ty":"big city|municipality|city","u":0,"b":"Yalova is a city located in northwestern Turkey on the eastern coast of the Sea of Marmara. It is the seat of Yalova Province and Yalova District. The city has a population of over 250,000 with adjacent conurbation districts."},{"n":"İznik","lat":40.4289,"lon":29.7194,"s":75,"w":"İznik","ty":"town|city","u":0,"b":"İznik is a municipality and district of Bursa Province, Turkey. Its area is 753 km2, and its population 44,236 (2022). The town is at the site of the ancient city of Nicaea, from which the modern name derives."},{"n":"Constanța","lat":44.1767,"lon":28.6508,"s":109,"w":"Constanța","ty":"city|port city|county seat in Romania|big city|border area|border city|college town|munici","u":0,"b":"Constanța is a city in the Northern Dobruja historical region of Romania. A port city, it is the capital of Constanța County and the country's fourth largest city and principal port on the Black Sea coast. It is the oldest continuously inhabited city in Romania, founded around 600 BC, and among the oldest in Europe."},{"n":"Dobrich","lat":43.5833,"lon":28.0,"s":74,"w":"Dobrich Province","ty":"oblast of Bulgaria","u":0,"b":"Dobrich Province is a province in northeastern Bulgaria, part of Southern Dobruja geographical region. It is bounded on the east by the Black Sea, on the south by Varna Province, on the west by Shumen and Silistra provinces, and on the north by Romania. It is divided into eight municipalities."},{"n":"Danube","lat":45.2219,"lon":29.7433,"s":200,"w":"Danube","ty":"transboundary river|river","u":0,"b":"The Danube is a river in Europe, the second-longest after the Volga. It flows through Central and Southeastern Europe, from the Black Forest of Germany south through the Danube Delta in Romania into the Black Sea. A large and historically important river, it was once a frontier of the Roman Empire."},{"n":"Gagauz","lat":46.0,"lon":28.6,"s":100,"w":"Gagauz language","ty":"natural language|modern language","u":0,"b":"Gagauz is a Turkic language spoken by the Gagauz people of Moldova, Ukraine, Russia and Turkey and is an official language of the Autonomous Region of Gagauzia in Moldova. Gagauz belongs to the Oghuz branch of Turkic languages, alongside Azerbaijani, Turkmen, and Turkish. Gagauz is a distinct language from Balkan Gagauz Turkish to some degree."},{"n":"Galați","lat":45.4336,"lon":28.0553,"s":89,"w":"Galați","ty":"big city|county seat in Romania|border area|cross-border region|border city|port city|muni","u":0,"b":"Galați (UK: gal-ATS, US: gah-LAHTS(-ee), Romanian:; also known by alternative names) is the capital city of Galați County in the historical region of Western Moldavia, in eastern Romania. Galați is a port town on the river Danube. and the sixth-largest of all cities on the river Danube."},{"n":"Brăila","lat":45.2692,"lon":27.9575,"s":78,"w":"Brăila","ty":"port city|municipality of Romania|big city|county seat in Romania","u":0,"b":"Brăila is a city in Muntenia, eastern Romania, a port on the Danube and the capital of Brăila County. The Sud-Est Regional Development Agency is headquartered in the city. According to the 2021 Romanian census, Brăila had a population of 154,686 inhabitants, making it the 11th most populous city in Romania and the 9th largest on the Danube."},{"n":"Prut","lat":45.4688,"lon":28.2072,"s":73,"w":"Prut","ty":"river","u":0,"b":"The Prut is a river in Eastern Europe. It is a left tributary of the Danube and is 953 km (592 mi) long. Part of its course forms Romania's border with Moldova and Ukraine."},{"n":"Tulcea","lat":45.1775,"lon":28.8036,"s":73,"w":"Tulcea","ty":"county seat in Romania|port city|border city|municipality of Romania","u":0,"b":"Tulcea is a city in Northern Dobruja, Romania. It is the administrative center of Tulcea County, and had a population of 65,624 as of 2021. One village, Tudor Vladimirescu, is administered by the city."},{"n":"Silistra","lat":43.9167,"lon":27.1667,"s":70,"w":"Silistra Province","ty":"oblast of Bulgaria","u":0,"b":"Silistra Province (Bulgarian: Област Силистра, Oblast Silistra) is a province of Bulgaria. Formerly known as the Silistra okrug, it is located on the northeast corner of Bulgaria. The province is part of the Southern Dobrudja region, with its largest and major city being Silistra."},{"n":"Kırklareli","lat":41.7347,"lon":27.2253,"s":70,"w":"Kırklareli","ty":"city|municipality","u":0,"b":"Kırklareli is a city in the European part of Turkey. It is the seat of Kırklareli Province and Kırklareli District. Its population is 85,493 (2022)."},{"n":"Izmail","lat":45.3418,"lon":28.8346,"s":70,"w":"Izmail","ty":"border city|port city|city in Ukraine","u":0,"b":"Izmail is a city and municipality on the Danube river in Odesa Oblast in south-western Ukraine. It serves as the administrative center of Izmail Raion, one of seven districts of Odesa Oblast, and is the only locality which constitutes Izmail urban hromada, one of the hromadas of Ukraine."},{"n":"Veliko Tarnovo","lat":43.3167,"lon":25.55,"s":70,"w":"Veliko Tarnovo Province","ty":"oblast of Bulgaria","u":0,"b":"Veliko Tarnovo is a province in the middle of the northern part of Bulgaria. Its capital city, Veliko Tarnovo, is of historical significance as it was the capital of the Second Bulgarian Empire. The province is divided into ten municipalities with a total population, as of December 2009, of 275,395."},{"n":"First Bulgarian Empire","lat":43.3667,"lon":27.1167,"s":70,"w":"First Bulgarian Empire","ty":"historical country","u":0,"b":"The First Bulgarian Empire was a medieval state that existed in Southeastern and southeastern Central Europe between the 7th and 11th centuries AD."},{"n":"Silistra","lat":44.1092,"lon":27.2654,"s":70,"w":"Silistra","ty":"municipality seat|city in Bulgaria|border city|oblast seat","u":0,"b":"Silistra is a town in Northeastern Bulgaria. The town lies on the southern bank of the lower Danube river, and is also the part of the Romanian border where it stops following the Danube. Silistra is the administrative center of the Silistra Province and one of the important towns of the historical region of Dobruja."},{"n":"Shumen","lat":43.25,"lon":27.0,"s":70,"w":"Shumen Province","ty":"oblast of Bulgaria","u":0,"b":"Shumen Province is a province in northeastern Bulgaria named after its main city Shumen. It is divided into ten municipalities with a total population, as of December 2009, of 194,090 inhabitants."},{"n":"Carpathians","lat":47.0,"lon":25.5,"s":128,"w":"Carpathian Mountains","ty":"mountain range|non-geologically related mountain range","u":0,"b":"The Carpathian Mountains or Carpathians are a range of mountains forming an arc across Central and Southeast Europe. Roughly 1,500 km (930 mi) long, it is the third-longest European mountain range after the Urals at 2,500 km (1,600 mi) and the Scandinavian Mountains at 1,700 km (1,100 mi)."},{"n":"Iași","lat":47.1622,"lon":27.5889,"s":108,"w":"Iași","ty":"county seat in Romania|municipality of Romania|big city","u":0,"b":"Iași (UK: YASH(-ee), US: YAHSH(-ee), Romanian:; also known by other alternative names), also sometimes referred to historically as Jassy, is the third most-populous city in Romania and the seat of Iași County. Located in the historical region of Moldavia, it has traditionally been one of the leading centres of Romanian social, cultural, academic and artistic life."},{"n":"Gagauzia","lat":46.3164,"lon":28.6664,"s":92,"w":"Gagauzia","ty":"autonomous territorial unit","u":0,"b":"Gagauzia or Gagauz-Yeri, officially the Autonomous Territorial Unit of Gagauzia (ATUG), is an autonomous territorial unit of Moldova. Its autonomy is intended for the local Gagauz people, a Turkic primarily Orthodox Christian ethnic group. Bessarabia, previously the eastern half of the Principality of Moldavia, was annexed by the Russian Empire in 1812."},{"n":"Bacău","lat":46.5833,"lon":26.9167,"s":76,"w":"Bacău","ty":"municipality of Romania|county seat in Romania|big city","u":0,"b":"Bacău is the main city in Bacău County, Romania. With a population of 136,087 (as of 2021 census), Bacău is the 14th largest city in Romania. The city is situated in the historical region of Moldavia, at the foothills of the Carpathian Mountains, and on the Bistrița River (which meets the Siret River about 8 kilometres (5.0 mi) to the south of Bacău)."},{"n":"Alba County","lat":46.1333,"lon":23.5333,"s":73,"w":"Alba County","ty":"county of Romania","u":0,"b":"Alba County is a county (județ) of Romania located in the historic region of Transylvania. Its capital is Alba Iulia, a city with a population of 63,536."},{"n":"Chernivtsi","lat":48.2908,"lon":25.9344,"s":106,"w":"Chernivtsi","ty":"big city|city of regional significance of Ukraine","u":0,"b":"Chernivtsi is a city in southwestern Ukraine on the upper course of the Prut River. Formerly the capital of the historic region of Bukovina, which is now divided between Romania and Ukraine, Chernivtsi serves as the administrative center for the Chernivtsi urban hromada, the Chernivtsi Raion, and the oblast itself."},{"n":"Zakarpattia Oblast","lat":48.41,"lon":23.29,"s":105,"w":"Zakarpattia Oblast","ty":"oblast of Ukraine","u":0,"b":"Zakarpattia Oblast, also referred to as simply Zakarpattia (Ukrainian: Закарпаття; Hungarian: Kárpátalja), Subcarpathia, or Transcarpathia in English, is an oblast located in the Carpathian Mountains in western Ukraine, mostly coterminous with the historical region of Carpathian Ruthenia. Its administrative centre is the city of Uzhhorod."},{"n":"Chernivtsi Oblast","lat":48.28,"lon":26.01,"s":102,"w":"Chernivtsi Oblast","ty":"oblast of Ukraine","u":0,"b":"Chernivtsi Oblast, also referred to as Chernivechchyna (Чернівеччина), is an oblast (province) in western Ukraine, consisting of the northern parts of the historical regions of Bukovina and Bessarabia. It has an international border with Romania and Moldova. The region spans 8,100 square kilometres (3,100 sq mi)."},{"n":"Uzhhorod","lat":48.6239,"lon":22.295,"s":102,"w":"Uzhhorod","ty":"big city|border city|city of regional significance of Ukraine","u":0,"b":"Uzhhorod is a city on the Uzh River in western Ukraine, on the border with Slovakia and near the border with Hungary. The city is approximately equidistant from the Baltic, the Adriatic and the Black Sea (650–690km) making it the most inland city in this part of Europe."},{"n":"Ivano-Frankivsk Oblast","lat":48.6582,"lon":24.5048,"s":99,"w":"Ivano-Frankivsk Oblast","ty":"oblast of Ukraine","u":0,"b":"Ivano-Frankivsk Oblast, also referred to as Ivano-Frankivshchyna (Івано-Франківщина) or simply Frankivshchyna, is an oblast (region) in western Ukraine. Its administrative center is the city of Ivano-Frankivsk. It has a population of 1,351,822 (2022 estimate)."},{"n":"Baia Mare","lat":47.6567,"lon":23.5719,"s":76,"w":"Baia Mare","ty":"county seat in Romania|big city|municipality of Romania|city","u":0,"b":"Baia Mare is a city in northwestern Romania, the capital and largest municipality of Maramureș County. It lies on the Săsar River and serves as an important economic, cultural, and educational centre of the historical region of Maramureș, a subregion of Transylvania."},{"n":"Satu Mare","lat":47.79,"lon":22.89,"s":75,"w":"Satu Mare","ty":"municipality of Romania|big city|county seat in Romania","u":0,"b":"Satu Mare is a city in Romania with a population of 91,520 (2021). It is the capital of Satu Mare County as well as the centre of the Satu Mare metropolitan area. It lies in the region of Maramureș, broadly part of Transylvania."},{"n":"Bukovina","lat":48.0,"lon":26.0,"s":73,"w":"Bukovina","ty":"region|Historical regions of Romania|Ukrainian historical regions","u":0,"b":"Bukovina is a historical region at the crossroads of Central and Eastern Europe. It is located on the northern slopes of the central Eastern Carpathians and the adjoining plains, today divided between Romania and Ukraine. It is inhabited mainly by Romanians (in southern regions) and Ukrainians (in northern regions)."},{"n":"Arad County","lat":46.36,"lon":21.8,"s":72,"w":"Arad County","ty":"county of Romania","u":0,"b":"Arad County is an administrative division (județ) of Romania roughly translated into county in the western part of the country on the border with Hungary, mostly in the region of Crișana and a few villages in Banat. The administrative center of the county lies in the city of Arad. The Arad County is part of the Danube–Criș–Mureș–Tisa Euroregion."},{"n":"Suceava County","lat":47.58,"lon":25.76,"s":72,"w":"Suceava County","ty":"county of Romania","u":0,"b":"Suceava County is a county (Romanian: județ) of Romania. Most of its territory lies in the southern part of the historical region of Bukovina, while the remainder forms part of Western Moldavia proper. The county seat and the most populous urban settlement of the county is Suceava."},{"n":"Bistrița-Năsăud County","lat":47.1389,"lon":24.5003,"s":71,"w":"Bistrița-Năsăud County","ty":"county of Romania","u":0,"b":"Bistrița-Năsăud is a county (județ) of Romania, in Transylvania, with its capital city at Bistrița."},{"n":"Botoșani","lat":47.7486,"lon":26.6694,"s":71,"w":"Botoșani","ty":"municipality of Romania|county seat in Romania","u":0,"b":"Botoșani is the capital city of Botoșani County, in the northern part of Moldavia, Romania. Today, it is best known as the birthplace of many celebrated Romanians, including Mihai Eminescu, Nicolae Iorga and Grigore Antipa."},{"n":"Lesser Poland Voivodeship","lat":49.85,"lon":20.2667,"s":111,"w":"Lesser Poland Voivodeship","ty":"voivodeship of Poland","u":0,"b":"Lesser Poland Voivodeship is a voivodeship in southern Poland. It has an area of 15,108 square kilometres (5,833 sq mi), and a population of 3,404,863 (2019). Its capital and largest city is Kraków."},{"n":"Dniester","lat":49.1755,"lon":22.8883,"s":105,"w":"Dniester","ty":"river","u":0,"b":"The Dniester is a transboundary river in Eastern Europe. It runs first through Ukraine and then through Moldova, finally discharging into the Black Sea on Ukrainian territory again."},{"n":"Ivano-Frankivsk","lat":48.9228,"lon":24.7106,"s":98,"w":"Ivano-Frankivsk","ty":"city or town|big city|city of regional significance of Ukraine","u":0,"b":"Ivano-Frankivsk, formerly Stanyslaviv, Stanislav and Stanisławów, is a city in western Ukraine. It serves as the administrative centre of Ivano-Frankivsk Oblast as well as Ivano-Frankivsk Raion within the oblast. Ivano-Frankivsk also hosts the administration of the Ivano-Frankivsk urban hromada."},{"n":"Rusyn","lat":49.0,"lon":22.0,"s":94,"w":"Rusyn language","ty":"natural language|modern language","u":0,"b":"Rusyn is an East Slavic language spoken by Rusyns in parts of Central and Eastern Europe, and written in the Cyrillic script. The majority of speakers live in Carpathian Ruthenia, which includes Transcarpathia and parts of eastern Slovakia and south-eastern Poland. There is also a sizeable Pannonian Rusyn linguistic island in Serbia, and a Rusyn diaspora worldwide."},{"n":"Bielsko-Biała","lat":49.8225,"lon":19.0444,"s":80,"w":"Bielsko-Biała","ty":"city with powiat rights in Poland|big city|city","u":0,"b":"Bielsko-Biała is a city in the Silesian Voivodeship, southern Poland, with a population of approximately 166,765 as of December 2022, making it the 22nd largest city in Poland, and an area of 124.51 km2 (48.07 sq mi). It is the core of the broader metropolitan area with around 335,000 inhabitants."},{"n":"Zakopane","lat":49.2994,"lon":19.9519,"s":78,"w":"Zakopane","ty":"urban municipality of Poland","u":0,"b":"Zakopane (Podhale Goral: Zokopane) is a town in the south of Poland, in the southern part of the Podhale region at the foot of the Tatra Mountains. From 1975 to 1998, it was part of Nowy Sącz Voivodeship; since 1999, it has been part of Lesser Poland Voivodeship. As of 2017, its population was 27,266."},{"n":"Przemyśl","lat":49.7835,"lon":22.7842,"s":78,"w":"Przemyśl","ty":"city|city with powiat rights in Poland","u":0,"b":"Przemyśl is a city in southeastern Poland with 56,466 inhabitants, as of December 2023. In 1999, it became part of the Subcarpathian Voivodeship. It was previously the capital of Przemyśl Voivodeship."},{"n":"Poprad","lat":49.05,"lon":20.3,"s":77,"w":"Poprad","ty":"city|municipality of Slovakia","u":0,"b":"Poprad is a city in northern Slovakia at the foot of the High Tatra Mountains, famous for its picturesque historic centre and as a holiday resort. The largest town of the Spiš region and the largest of all towns in the vicinity of the High Tatra Mountains in both Slovakia and Poland, Poprad is the tenth largest city in Slovakia, with a population of approximately 50,000."},{"n":"Kraków","lat":50.0614,"lon":19.9372,"s":185,"w":"Kraków","ty":"city with powiat rights in Poland|city or town|tourist destination|place with town rights ","u":0,"b":"Kraków, officially the Royal Capital City of Kraków, is the second-largest and one of the oldest cities in Poland. Situated on the Vistula River in Lesser Poland Voivodeship, the city has a population of 816,614 (2025), with 1,428,363 people living in the Kraków metropolitan area."},{"n":"Podkarpackie Voivodeship","lat":49.95,"lon":22.1667,"s":102,"w":"Podkarpackie Voivodeship","ty":"voivodeship of Poland","u":0,"b":"Podkarpackie Voivodeship is a voivodeship, or province, in the southeastern corner of Poland. Its administrative capital and largest city is Rzeszów. It is governed by the Subcarpathian Regional Assembly and the voivodeship marshal."},{"n":"Rzeszów","lat":50.0411,"lon":21.9989,"s":100,"w":"Rzeszów","ty":"term|city with powiat rights in Poland|big city|city","u":0,"b":"Rzeszów is the largest city in southeastern Poland. It is located on both sides of the Wisłok River in the heartland of the Sandomierz Basin. Rzeszów is the capital of the Subcarpathian Voivodeship and the seat of Rzeszów County."}]};
